class BrowserRuntime:
    def __init__(
        self,
        session_id: str,
        work_item_id: str,
        exploration_run_id: str | None,
        target_url: str,
        process: Any | None,
        interactive: bool = True,
        created_by_user_id: str = "",
    ) -> None:
        self.session_id = session_id
        self.work_item_id = work_item_id
        self.exploration_run_id = exploration_run_id
        self.target_url = target_url
        self.process = process
        self.interactive = interactive
        self.created_by_user_id = created_by_user_id
        self.controller_user_id = created_by_user_id if interactive else ""
        self.websockets: set[WebSocket] = set()
        self.socket_states: dict[WebSocket, BrowserSocketState] = {}
        self.ready = asyncio.Event()
        self.closed = asyncio.Event()
        self.last_frame: dict[str, Any] | None = None
        self.status = "starting"
        self.last_error = ""
        self.last_worker_event_type = ""
        self.last_worker_event_at = ""
        self.last_worker_url = ""
        self.step_events: dict[int, asyncio.Event] = {}
        self.step_results: dict[int, dict[str, Any]] = {}
        self.command_events: dict[str, asyncio.Event] = {}
        self.command_results: dict[str, dict[str, Any]] = {}
        self.slot_ready = asyncio.Event()
        self.capacity_acquired = False
        self.queue_position = 0
        self.activation_task: asyncio.Task[None] | None = None
        self.dropped_frames = 0


class ExplorationPlanBuildError(RuntimeError):
    def __init__(self, code: str, message: str, technical_message: str = "", details: dict[str, Any] | None = None) -> None:
        super().__init__(message)
        self.code = code
        self.public_message = message
        self.technical_message = technical_message or message
        self.details = details or {}


class BrowserSocketState:
    def __init__(self, runtime: BrowserRuntime, websocket: WebSocket) -> None:
        self.runtime = runtime
        self.websocket = websocket
        self.reliable: asyncio.Queue[tuple[dict[str, Any], asyncio.Future[None] | None]] = asyncio.Queue()
        self.latest_frame: dict[str, Any] | None = None
        self.wakeup = asyncio.Event()
        self.consecutive_timeouts = 0
        self.closed = False
        self.task = asyncio.create_task(self._sender())

    def enqueue(self, payload: dict[str, Any]) -> None:
        if self.closed:
            return
        if payload.get("type") == "frame":
            if self.latest_frame is not None:
                self.runtime.dropped_frames += 1
            self.latest_frame = payload
        else:
            self.reliable.put_nowait((payload, None))
        self.wakeup.set()

    async def send_reliable(self, payload: dict[str, Any]) -> None:
        if self.closed:
            raise RuntimeError("WebSocket connection closed")
        delivered = asyncio.get_running_loop().create_future()
        self.reliable.put_nowait((payload, delivered))
        self.wakeup.set()
        await delivered

    async def _sender(self) -> None:
        try:
            while not self.closed:
                payload: dict[str, Any] | None = None
                delivered: asyncio.Future[None] | None = None
                if not self.reliable.empty():
                    payload, delivered = self.reliable.get_nowait()
                elif self.latest_frame is not None:
                    payload = self.latest_frame
                    self.latest_frame = None
                else:
                    self.wakeup.clear()
                    await self.wakeup.wait()
                    continue
                timeout = BROWSER_FRAME_SEND_TIMEOUT_SECONDS if payload.get("type") == "frame" else BROWSER_EVENT_SEND_TIMEOUT_SECONDS
                attempts = 1 if payload.get("type") == "frame" else 3
                last_error: Exception | None = None
                for _ in range(attempts):
                    try:
                        await asyncio.wait_for(self.websocket.send_json(payload), timeout=timeout)
                        self.consecutive_timeouts = 0
                        last_error = None
                        break
                    except asyncio.TimeoutError as exc:
                        last_error = exc
                        self.consecutive_timeouts += 1
                        if payload.get("type") == "frame":
                            self.runtime.dropped_frames += 1
                    except Exception as exc:
                        last_error = exc
                        break
                if delivered and not delivered.done():
                    if last_error is None:
                        delivered.set_result(None)
                    else:
                        delivered.set_exception(last_error)
                if last_error is not None and (not isinstance(last_error, asyncio.TimeoutError) or self.consecutive_timeouts >= 3):
                    break
        finally:
            self.closed = True
            self.runtime.websockets.discard(self.websocket)
            self.runtime.socket_states.pop(self.websocket, None)
            while not self.reliable.empty():
                _, delivered = self.reliable.get_nowait()
                if delivered and not delivered.done():
                    delivered.set_exception(RuntimeError("WebSocket connection closed"))
            with contextlib.suppress(Exception):
                await self.websocket.close()

    async def stop(self) -> None:
        if self.closed:
            return
        self.closed = True
        self.wakeup.set()
        self.task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await self.task


def configured_browser_session_limit() -> int:
    try:
        return max(1, min(50, int(os.environ.get("QA_MAX_ACTIVE_BROWSER_SESSIONS", DEFAULT_BROWSER_SESSION_LIMIT))))
    except (TypeError, ValueError):
        return DEFAULT_BROWSER_SESSION_LIMIT


def system_memory_percent() -> float | None:
    """Return host memory use without adding a production dependency."""
    try:
        meminfo = Path("/proc/meminfo")
        if meminfo.exists():
            values = {}
            for line in meminfo.read_text(encoding="utf-8").splitlines():
                key, value = line.split(":", 1)
                values[key] = int(value.strip().split()[0])
            total = values.get("MemTotal", 0)
            available = values.get("MemAvailable", 0)
            return round((total - available) * 100 / total, 1) if total else None
        if os.uname().sysname == "Darwin":
            total = int(subprocess.check_output(["sysctl", "-n", "hw.memsize"], text=True).strip())
            output = subprocess.check_output(["vm_stat"], text=True)
            page_size_match = re.search(r"page size of (\d+) bytes", output)
            page_size = int(page_size_match.group(1)) if page_size_match else 4096
            pages = {}
            for line in output.splitlines():
                match = re.match(r"([^:]+):\s+(\d+)\.", line)
                if match:
                    pages[match.group(1)] = int(match.group(2))
            available_pages = sum(pages.get(key, 0) for key in ("Pages free", "Pages inactive", "Pages speculative"))
            return round((total - available_pages * page_size) * 100 / total, 1) if total else None
    except Exception:
        return None
    return None


class BrowserCapacityManager:
    def __init__(self) -> None:
        self.active: set[str] = set()
        self.waiting: list[tuple[str, asyncio.Future[bool]]] = []
        self._lock: asyncio.Lock | None = None

    def _get_lock(self) -> asyncio.Lock:
        if self._lock is None:
            self._lock = asyncio.Lock()
        return self._lock

    @property
    def limit(self) -> int:
        return configured_browser_session_limit()

    def snapshot(self) -> dict[str, Any]:
        return {
            "activeBrowserCount": len(self.active),
            "queuedBrowserCount": len(self.waiting),
            "browserLimit": self.limit,
        }

    def queue_position(self, session_id: str) -> int:
        for index, (queued_id, _) in enumerate(self.waiting, start=1):
            if queued_id == session_id:
                return index
        return 0

    def memory_allows_start(self) -> bool:
        percent = system_memory_percent()
        return percent is None or percent < MEMORY_PRESSURE_PERCENT

    async def reserve(self, runtime: "BrowserRuntime") -> bool:
        future: asyncio.Future[bool] | None = None
        async with self._get_lock():
            if len(self.active) < self.limit and not self.waiting and self.memory_allows_start():
                self.active.add(runtime.session_id)
                runtime.capacity_acquired = True
            else:
                future = asyncio.get_running_loop().create_future()
                self.waiting.append((runtime.session_id, future))
                runtime.status = "queued"
        await publish_browser_capacity_state()
        if future is None:
            return True
        try:
            return await future
        except asyncio.CancelledError:
            await self.release(runtime.session_id)
            raise

    async def release(self, session_id: str) -> None:
        async with self._get_lock():
            self.active.discard(session_id)
            remaining = []
            for queued_id, future in self.waiting:
                if queued_id == session_id:
                    if not future.done():
                        future.set_result(False)
                else:
                    remaining.append((queued_id, future))
            self.waiting = remaining
            self._promote_locked()
        await publish_browser_capacity_state()

    async def promote(self) -> None:
        async with self._get_lock():
            self._promote_locked()
        await publish_browser_capacity_state()

    def _promote_locked(self) -> None:
        if not self.memory_allows_start():
            return
        while self.waiting and len(self.active) < self.limit:
            session_id, future = self.waiting.pop(0)
            runtime = BROWSER_RUNTIMES.get(session_id)
            if runtime is None or runtime.closed.is_set() or future.cancelled():
                if not future.done():
                    future.set_result(False)
                continue
            self.active.add(session_id)
            runtime.capacity_acquired = True
            if not future.done():
                future.set_result(True)


