def auth_disabled() -> bool:
    return os.environ.get("QA_AUTH_DISABLED") == "1"


def json_auth_response(request: Request, payload: dict[str, Any], status_code: int) -> JSONResponse:
    response = JSONResponse(payload, status_code=status_code)
    origin = request.headers.get("origin")
    if origin in CORS_ALLOWED_ORIGINS:
        response.headers["Access-Control-Allow-Origin"] = origin
        response.headers["Access-Control-Allow-Credentials"] = "true"
        response.headers.add_vary_header("Origin")
    return response


def normalize_username(value: str) -> str:
    return re.sub(r"\s+", "", value.strip().lower())


def validate_username(value: str) -> str:
    username = normalize_username(value)
    if not re.fullmatch(r"[a-zA-Z0-9_.-]{3,32}", username):
        raise HTTPException(status_code=400, detail="账号需为 3-32 位字母、数字、点、下划线或短横线")
    return username


def validate_password(value: str) -> str:
    password = value or ""
    if len(password) < 8 or not re.search(r"[A-Za-z]", password) or not re.search(r"\d", password):
        raise HTTPException(status_code=400, detail="密码至少 8 位，并包含字母和数字")
    return password


def credential_field_label(field: str) -> str:
    normalized = str(field)
    if normalized == "username":
        return "用户名"
    if normalized == "password":
        return "密码"
    return normalized


PLAYWRIGHT_REQUIRED_CREDENTIAL_HELPER = """function requiredCredential(name: 'QA_USERNAME' | 'QA_PASSWORD'): string {
  const value = process.env[name];
  if (!value) throw new Error(`缺少运行环境变量 ${name}`);
  return value;
}
"""


def work_item_login_credentials(item: sqlite3.Row | dict[str, Any] | None) -> dict[str, str]:
    if item is None:
        return {}
    keys = item.keys() if hasattr(item, "keys") else item
    source = " ".join(
        str(item[key] or "")
        for key in ("test_data", "requirement")
        if key in keys
    )
    credentials = parse_test_data(source)
    return {
        env_name: str(credentials.get(field) or "")
        for field, env_name in (("username", "QA_USERNAME"), ("password", "QA_PASSWORD"))
        if credentials.get(field)
    }


def secure_generated_script_credentials(
    content: str,
    item: sqlite3.Row | dict[str, Any] | None,
) -> str:
    if "requiredCredential('QA_PASSWORD')" in content:
        return content
    runtime_credentials = work_item_login_credentials(item)
    username = runtime_credentials.get("QA_USERNAME", "")
    password = runtime_credentials.get("QA_PASSWORD", "")
    if not username or not password:
        return content

    replacements: list[tuple[str, str]] = []
    if "function sauce(page: Page, testId: string)" in content:
        replacements = [
            (f"const username = {json.dumps(username, ensure_ascii=False)};", "const username = requiredCredential('QA_USERNAME');"),
            (f"const password = {json.dumps(password, ensure_ascii=False)};", "const password = requiredCredential('QA_PASSWORD');"),
        ]
    elif "function passwordInput(page: Page)" in content or "function openSauceLogin(page: Page)" in content:
        escaped_username = username.replace("'", "\\'")
        escaped_password = password.replace("'", "\\'")
        replacements = [
            (f"const validUsername = '{escaped_username}';", "const validUsername = requiredCredential('QA_USERNAME');"),
            (f"const validPassword = '{escaped_password}';", "const validPassword = requiredCredential('QA_PASSWORD');"),
        ]
    if not replacements or any(source not in content for source, _ in replacements):
        return content

    secured = content
    for source, target in replacements:
        secured = secured.replace(source, target, 1)
    first_assignment = min(secured.index(target) for _, target in replacements)
    return secured[:first_assignment] + PLAYWRIGHT_REQUIRED_CREDENTIAL_HELPER + "\n" + secured[first_assignment:]


def migrate_generated_script_credentials(conn: sqlite3.Connection) -> int:
    rows = conn.execute(
        """
        SELECT v.*, w.test_data, w.requirement
        FROM test_script_versions v
        JOIN work_items w ON w.id = v.work_item_id
        WHERE v.source = 'generated'
        """
    ).fetchall()
    migrated = 0
    for row in rows:
        current = str(row["content"] or "")
        secured = secure_generated_script_credentials(current, row)
        if secured == current:
            continue
        timestamp = now_iso()
        next_hash = content_hash(secured)
        conn.execute(
            "UPDATE test_script_versions SET content = ?, content_hash = ?, updated_at = ? WHERE id = ?",
            (secured, next_hash, timestamp, row["id"]),
        )
        conn.execute(
            "UPDATE generated_scripts SET content = ? WHERE script_version_id = ?",
            (secured, row["id"]),
        )
        if row["source_generated_script_id"]:
            conn.execute(
                "UPDATE generated_scripts SET content = ? WHERE id = ?",
                (secured, row["source_generated_script_id"]),
            )
        if row["spec_path"]:
            path = resolve_workspace_path(row["spec_path"])
            if path.exists() and path.read_text(encoding="utf-8") == current:
                path.write_text(secured, encoding="utf-8")
        migrated += 1
    if migrated:
        log_event(
            logging.INFO,
            "generated_script_credentials_migrated",
            component="startup",
            migrated_count=migrated,
        )
    return migrated


def hash_password(password: str, salt: str | None = None) -> str:
    active_salt = salt or secrets.token_hex(16)
    digest = hashlib.pbkdf2_hmac(
        "sha256",
        password.encode("utf-8"),
        active_salt.encode("utf-8"),
        PASSWORD_HASH_ITERATIONS,
    ).hex()
    return f"pbkdf2_sha256${PASSWORD_HASH_ITERATIONS}${active_salt}${digest}"


def verify_password(password: str, stored_hash: str) -> bool:
    try:
        algorithm, iterations, salt, expected = stored_hash.split("$", 3)
        if algorithm != "pbkdf2_sha256":
            return False
        digest = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt.encode("utf-8"), int(iterations)).hex()
        return hmac.compare_digest(digest, expected)
    except (ValueError, TypeError):
        return False


def hash_session_token(token: str) -> str:
    return hashlib.sha256(token.encode("utf-8")).hexdigest()


def row_to_user(row: sqlite3.Row | dict[str, Any]) -> dict[str, Any]:
    return {
        "id": row["id"],
        "username": row["username"],
        "displayName": row["display_name"],
        "role": row["role"],
        "status": row["status"],
        "createdAt": row["created_at"],
        "updatedAt": row["updated_at"],
        "lastLoginAt": row["last_login_at"] if "last_login_at" in row.keys() else "",
    }


