def normalized_navigation_url(value: Any) -> str:
    """Normalize only the URL representation; never infer or append a route."""
    raw = str(value or "").strip()
    if not raw:
        return ""
    try:
        parsed = urllib.parse.urlsplit(raw)
    except ValueError:
        return raw
    return urllib.parse.urlunsplit((parsed.scheme, parsed.netloc, parsed.path, parsed.query, parsed.fragment))


def infer_access_mode(item: sqlite3.Row | dict[str, Any]) -> str:
    keys = item.keys() if hasattr(item, "keys") else item
    text = " ".join(str(item[key] or "") for key in ("requirement", "acceptance", "role") if key in keys)
    if explicitly_anonymous_item(item):
        return "anonymous"
    if re.search(r"登录|账号|密码|认证|登录态", text):
        return "authentication-required"
    return "unknown"


def explored_access_mode(
    result: dict[str, Any],
    steps: list[dict[str, Any]],
    state_evidence: list[dict[str, Any]],
    required_mode: str,
) -> str:
    nested_target = result.get("navigationTarget") if isinstance(result.get("navigationTarget"), dict) else {}
    explicit = str(result.get("accessMode") or nested_target.get("accessMode") or "").strip()
    if required_mode == "anonymous":
        initial_evidence = next((
            evidence for evidence in state_evidence
            if str(evidence.get("stateKey") or "initial") == "initial"
            and not re.search(r"(?:^|[/#?])login(?:[/#?=&]|$)|sign[-_]?in", str(evidence.get("url") or ""), re.IGNORECASE)
        ), None)
        if initial_evidence:
            return "anonymous"
    if explicit in {"anonymous", "authentication-required"}:
        return explicit
    auth_step = any(
        step.get("action") in {"click", "fill", "select"}
        and re.search(
            r"登录|登陆|账号|用户名|密码|认证|sign[ -]?in|log[ -]?in|username|password",
            " ".join(
                str(step.get(key) or "")
                for key in ("target", "description", "value")
            ),
            re.IGNORECASE,
        )
        for step in steps
    )
    if auth_step:
        return "authentication-required"
    if state_evidence and required_mode == "anonymous":
        return "anonymous"
    return "unknown"


def navigation_target_from_result(
    item: sqlite3.Row | dict[str, Any],
    result: dict[str, Any] | None,
    steps: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """Build a replayable navigation contract from real exploration evidence."""
    result = result if isinstance(result, dict) else {}
    nested_target = result.get("navigationTarget") if isinstance(result.get("navigationTarget"), dict) else {}
    raw_steps = steps if isinstance(steps, list) else result.get("steps") or nested_target.get("navigationSteps") or []
    passed_steps: list[dict[str, Any]] = []
    for index, step in enumerate(raw_steps):
        if not isinstance(step, dict) or step.get("status") not in {None, "passed"}:
            continue
        target = step.get("resolvedTarget") or step.get("resolved_target") or {}
        passed_steps.append({
            "action": str(step.get("action") or ""),
            "value": str(step.get("value") or ""),
            "target": str(step.get("target") or ""),
            "description": str(step.get("description") or ""),
            "caseId": str(step.get("caseId") or step.get("case_id") or ""),
            "scenarioIndex": str(step.get("scenarioIndex") or step.get("scenario_index") or ""),
            "stateKey": str(step.get("stateKey") or step.get("state_key") or ""),
            "sequence": index,
            "urlBefore": normalized_navigation_url(step.get("urlBefore") or step.get("url_before") or ""),
            "urlAfter": normalized_navigation_url(step.get("urlAfter") or step.get("url_after") or ""),
            "resolvedTarget": target if isinstance(target, dict) else {},
        })
    requested_url = normalized_navigation_url(
        result.get("requestedUrl")
        or result.get("requested_url")
        or nested_target.get("requestedUrl")
        or (item["target_url"] if "target_url" in item.keys() else "")
    )
    state_evidence = result.get("stateEvidence") if isinstance(result.get("stateEvidence"), list) else []
    state_evidence = [item for item in state_evidence if isinstance(item, dict)]
    direct_initial_evidence = next((
        evidence for evidence in state_evidence
        if str(evidence.get("stateKey") or "initial") == "initial"
        and navigation_urls_equivalent(requested_url, normalized_navigation_url(evidence.get("url") or ""))
    ), None)
    resolved_url = requested_url if direct_initial_evidence else normalized_navigation_url(
        result.get("resolvedUrl") or result.get("resolved_url") or nested_target.get("resolvedUrl") or ""
    )
    if not resolved_url:
        for evidence in reversed(state_evidence):
            resolved_url = normalized_navigation_url(evidence.get("url") or "")
            if resolved_url:
                break
    if not resolved_url:
        for step in reversed(passed_steps):
            resolved_url = step["urlAfter"] or step["urlBefore"]
            if resolved_url:
                break
    resolved_url = resolved_url or requested_url
    readiness_signals: list[dict[str, Any]] = []
    for evidence in state_evidence:
        signal = {
            "url": normalized_navigation_url(evidence.get("url") or ""),
            "title": str(evidence.get("title") or ""),
            "headings": [str(value) for value in evidence.get("headings") or [] if str(value)],
            "texts": [str(value) for value in evidence.get("texts") or [] if str(value)],
            "stateKey": str(evidence.get("stateKey") or ""),
            "caseIds": [str(value) for value in evidence.get("caseIds") or [] if str(value)],
        }
        if signal["url"] or signal["title"] or signal["headings"] or signal["texts"]:
            readiness_signals.append(signal)
    matching_readiness = [
        signal for signal in readiness_signals
        if signal["url"] and navigation_urls_equivalent(resolved_url, signal["url"])
    ]
    if matching_readiness:
        readiness_signals = matching_readiness
    supported_actions = {"click", "fill", "select", "locate"}
    replayable_steps = [step for step in passed_steps if step["action"] in supported_actions]
    grouped_steps: dict[str, list[dict[str, Any]]] = {}
    for step in replayable_steps:
        group_key = step["scenarioIndex"] or step["caseId"] or "default"
        grouped_steps.setdefault(group_key, []).append(step)
    target_case_ids = {
        case_id
        for signal in readiness_signals
        for case_id in signal.get("caseIds") or []
    }
    candidate_groups = [
        group for group in grouped_steps.values()
        if not target_case_ids or any(step["caseId"] in target_case_ids for step in group)
    ] or list(grouped_steps.values())
    def replay_prefix(group: list[dict[str, Any]]) -> list[dict[str, Any]]:
        if requested_url != resolved_url:
            for index, step in enumerate(group):
                if step["urlAfter"] == resolved_url:
                    return group[: index + 1]
        return group

    candidate_paths = [replay_prefix(group) for group in candidate_groups]
    navigation_steps = [] if requested_url == resolved_url else min(candidate_paths, key=len) if candidate_paths else []
    navigation_steps = [
        {key: value for key, value in step.items() if key != "sequence"}
        for step in navigation_steps
    ]
    direct_navigation_allowed = bool(
        requested_url == resolved_url
        or direct_initial_evidence
        or result.get("directNavigationAllowed")
        or nested_target.get("directNavigationAllowed")
    )
    required_access_mode = infer_access_mode(item)
    access_mode = explored_access_mode(result, passed_steps, state_evidence, required_access_mode)
    evidence_confirmed = bool(state_evidence) or bool(result.get("evidenceConfirmed")) or bool(nested_target.get("evidenceConfirmed"))
    return {
        "requestedUrl": requested_url,
        "resolvedUrl": resolved_url,
        "navigationSteps": navigation_steps,
        "readinessSignals": readiness_signals,
        "accessMode": access_mode,
        "requiredAccessMode": required_access_mode,
        "directNavigationAllowed": direct_navigation_allowed,
        "navigationPathConfirmed": bool(requested_url and resolved_url and (requested_url == resolved_url or navigation_steps or direct_navigation_allowed)),
        "evidenceConfirmed": evidence_confirmed,
    }


def navigation_target_for_work_item(work_item_id: str, item: sqlite3.Row | None = None) -> dict[str, Any]:
    item = item or get_work_item_row(work_item_id)
    with get_db() as conn:
        run = conn.execute(
            "SELECT * FROM exploration_runs WHERE work_item_id = ? ORDER BY started_at DESC LIMIT 1",
            (work_item_id,),
        ).fetchone()
        exploration = conn.execute(
            "SELECT state_evidence_json FROM explorations WHERE work_item_id = ? ORDER BY id DESC LIMIT 1",
            (work_item_id,),
        ).fetchone()
    result = safe_json_loads(run["result_json"] if run is not None and "result_json" in run.keys() else None, {})
    if not isinstance(result, dict):
        result = {}
    if exploration is not None and not result.get("stateEvidence"):
        result["stateEvidence"] = safe_json_loads(exploration["state_evidence_json"], [])
    target = navigation_target_from_result(item, result)
    if run is not None and run["status"] == "passed":
        target["evidenceConfirmed"] = True
    return target


def default_fixture_content(item: sqlite3.Row, navigation_target: dict[str, Any] | None = None) -> str:
    target = navigation_target or navigation_target_from_result(item, {})
    target_url = json.dumps(target.get("requestedUrl") or item["target_url"] or "/", ensure_ascii=False)
    navigation_json = json.dumps(target, ensure_ascii=False)
    return f"""import {{ test, type Page }} from '@playwright/test';

const SOURCE_TARGET_URL = {target_url};
export const TARGET_URL = process.env.QA_TARGET_URL || SOURCE_TARGET_URL;
export const NAVIGATION_TARGET = {navigation_json} as const;

export function runtimeUrl(value: string) {{
  if (!value || TARGET_URL === SOURCE_TARGET_URL) return value;
  const source = new URL(SOURCE_TARGET_URL);
  const target = new URL(TARGET_URL);
  const current = new URL(value, SOURCE_TARGET_URL);
  if (current.origin !== source.origin) return value;
  const sourceRoot = source.pathname.replace(/\\/$/, '') || '/';
  if (sourceRoot !== '/' && current.pathname !== sourceRoot && !current.pathname.startsWith(`${{sourceRoot}}/`)) return value;
  const suffix = sourceRoot === '/' ? current.pathname : current.pathname.slice(sourceRoot.length) || '/';
  const targetRoot = target.pathname.replace(/\\/$/, '') || '/';
  target.pathname = targetRoot === '/' ? suffix : `${{targetRoot}}${{suffix.startsWith('/') ? suffix : `/${{suffix}}`}}`;
  target.search = target.search || current.search;
  target.hash = target.hash || current.hash;
  return target.href;
}}

function normalizedNavigationPath(value: string) {{
  return value.replace(/\\/+$/, '') || '/';
}}

function defaultSpaRootHash(value: string) {{
  return ['', '#', '#/', '#!/'].includes(value);
}}

export function navigationUrlsEquivalent(expected: string, actual: string) {{
  const expectedUrl = new URL(expected);
  const actualUrl = new URL(actual);
  if (expectedUrl.origin !== actualUrl.origin) return false;
  if (normalizedNavigationPath(expectedUrl.pathname) !== normalizedNavigationPath(actualUrl.pathname)) return false;
  if (expectedUrl.search !== actualUrl.search) return false;
  if (expectedUrl.hash === actualUrl.hash) return true;
  return defaultSpaRootHash(expectedUrl.hash) && defaultSpaRootHash(actualUrl.hash);
}}

function locatorFor(page: Page, target: any) {{
  const type = String(target?.locatorType || '').toLowerCase();
  const value = String(target?.locatorValue || target?.name || '');
  const role = String(target?.locatorRole || target?.role || '');
  if (!value) return null;
  if (type === 'testid' || type === 'data-test' || type === 'data-testid') return page.locator(`[data-test=\\"${{value}}\\"], [data-testid=\\"${{value}}\\"]`).first();
  if (type === 'placeholder') return page.getByPlaceholder(value).first();
  if (type === 'label') return page.getByLabel(value).first();
  if (type === 'role' && role) return page.getByRole(role as any, {{ name: value, exact: true }}).first();
  if (type === 'css') return page.locator(value).first();
  return page.getByText(value, {{ exact: true }}).first();
}}

export async function openTargetPage(page: Page) {{
  const requested = runtimeUrl(NAVIGATION_TARGET.requestedUrl || SOURCE_TARGET_URL) || TARGET_URL;
  await page.goto(requested, {{ waitUntil: 'commit', timeout: 20_000 }});
  for (const step of NAVIGATION_TARGET.navigationSteps || []) {{
    const action = String(step.action || '');
    const locator = locatorFor(page, step.resolvedTarget || {{}});
    if (action === 'click' && locator) await locator.click();
    else if (action === 'fill' && locator) await locator.fill(String(step.value || ''));
    else if (action === 'select' && locator) await locator.selectOption(String(step.value || ''));
    else if (action === 'locate' && locator) await locator.waitFor({{ state: 'visible', timeout: 10_000 }});
  }}
  const resolved = runtimeUrl(NAVIGATION_TARGET.resolvedUrl || requested) || requested;
  if (!(NAVIGATION_TARGET.navigationSteps || []).length && resolved && resolved !== requested) {{
    if (!NAVIGATION_TARGET.directNavigationAllowed) {{
      throw new Error(`navigation-precondition: no replayable path or confirmed direct navigation; requested=${{requested}}; resolved=${{resolved}}`);
    }}
    await page.goto(resolved, {{ waitUntil: 'commit', timeout: 20_000 }});
  }}
  if (resolved) {{
    try {{
      await page.waitForURL(url => navigationUrlsEquivalent(resolved, url.toString()), {{ timeout: 10_000 }});
    }} catch (error) {{
      throw new Error(`navigation-precondition: resolved URL mismatch; expected=${{resolved}}; actual=${{page.url()}}`, {{ cause: error as Error }});
    }}
  }}
  return page.url();
}}

export async function runStep(title: string, action: () => Promise<void>) {{
  console.log(`[步骤开始] ${{title}}`);
  try {{
    await test.step(title, action);
    console.log(`[步骤通过] ${{title}}`);
  }} catch (error) {{
    console.log(`[步骤失败] ${{title}}`);
    throw error;
  }}
}}
"""


def validate_fixture_content(content: str) -> None:
    normalized = content.strip()
    if not basic_typescript_shape_valid(normalized):
        raise HTTPException(status_code=400, detail="共享 Fixture 未通过 TypeScript 基础结构校验")
    if extract_playwright_test_titles(normalized):
        raise HTTPException(status_code=400, detail="共享 Fixture 不能声明具体测试用例")
    required_exports = ("TARGET_URL", "NAVIGATION_TARGET", "openTargetPage", "runStep")
    missing_exports = [name for name in required_exports if name not in normalized]
    if missing_exports:
        raise HTTPException(status_code=400, detail=f"共享 Fixture 缺少导航契约导出：{', '.join(missing_exports)}")
    if re.search(r"from\s+['\"][^'\"]+\.spec(?:\.ts)?['\"]", normalized):
        raise HTTPException(status_code=400, detail="共享 Fixture 不能导入 spec 文件")


def create_fixture_version(
    conn: sqlite3.Connection,
    item: sqlite3.Row,
    batch_id: str,
    content: str,
) -> sqlite3.Row:
    content = parameterize_typescript_source(content, str(item["target_url"] or ""), generated=True)
    validate_fixture_content(content)
    fixture_id = uuid.uuid4().hex[:12]
    version = next_fixture_version_number(conn, item["id"])
    file_path = fixture_version_path(item, batch_id, fixture_id)
    normalized = content.strip() + "\n"
    resolve_workspace_path(file_path).write_text(normalized, encoding="utf-8")
    timestamp = now_iso()
    conn.execute(
        """
        INSERT INTO test_fixture_versions (
            id, project_id, work_item_id, version, status, file_path,
            content, content_hash, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            fixture_id,
            item["project_id"] or "",
            item["id"],
            version,
            "draft",
            file_path,
            normalized,
            content_hash(normalized),
            timestamp,
            timestamp,
        ),
    )
    return conn.execute("SELECT * FROM test_fixture_versions WHERE id = ?", (fixture_id,)).fetchone()


def fixture_supports_navigation_contract(row: sqlite3.Row | None) -> bool:
    if row is None:
        return False
    try:
        validate_fixture_content(str(row["content"] or ""))
    except HTTPException:
        return False
    return True


def fixture_import_for_paths(spec_path: str, fixture_path: str) -> str:
    spec_file = resolve_workspace_path(spec_path)
    fixture_file = resolve_workspace_path(fixture_path).with_suffix("")
    relative = os.path.relpath(fixture_file, spec_file.parent).replace(os.sep, "/")
    return relative if relative.startswith(".") else f"./{relative}"


def current_navigation_fixture(
    conn: sqlite3.Connection,
    item: sqlite3.Row,
    batch_id: str,
    navigation_target: dict[str, Any],
) -> sqlite3.Row:
    content = parameterize_typescript_source(
        default_fixture_content(item, navigation_target),
        str(item["target_url"] or ""),
        generated=True,
    ).strip() + "\n"
    expected_hash = content_hash(content)
    existing = conn.execute(
        """
        SELECT * FROM test_fixture_versions
        WHERE work_item_id = ? AND content_hash = ?
        ORDER BY version DESC LIMIT 1
        """,
        (item["id"], expected_hash),
    ).fetchone()
    if existing is not None:
        fixture_file = resolve_workspace_path(existing["file_path"])
        if not fixture_file.exists():
            fixture_file.parent.mkdir(parents=True, exist_ok=True)
            fixture_file.write_text(existing["content"], encoding="utf-8")
        return existing
    return create_fixture_version(conn, item, batch_id, content)


def script_version_path(
    item: sqlite3.Row,
    script_version_id: str,
    status: str = "draft",
    *,
    batch_id: str = "",
    case_external_id: str = "",
) -> str:
    WORK_ITEM_DRAFT_DIR.mkdir(parents=True, exist_ok=True)
    suffix = "active" if status == "active" else "draft"
    if batch_id and case_external_id:
        case_slug = slugify(case_external_id)
        spec_path = WORK_ITEM_DRAFT_DIR / item["slug"] / batch_id / "cases" / f"{case_slug}.{script_version_id}.{suffix}.spec.ts"
    else:
        spec_path = WORK_ITEM_DRAFT_DIR / item["slug"] / f"{script_version_id}.{suffix}.spec.ts"
    spec_path.parent.mkdir(parents=True, exist_ok=True)
    return relative_or_absolute(spec_path)


def create_script_version(
    conn: sqlite3.Connection,
    item: sqlite3.Row,
    content: str,
    *,
    asset_mode: str,
    case_ids: list[str],
    case_id: str = "",
    generation_batch_id: str = "",
    fixture_version_id: str = "",
    case_external_id: str = "",
    source_generated_script_id: int | None = None,
    exploration_run_id: str = "",
    case_definition_hash: str = "",
    source: str = "generated",
    script_layout: str = "single-case",
    dependency_analysis: dict[str, Any] | None = None,
    parameterize_content: bool = True,
) -> str:
    if parameterize_content:
        content = parameterize_typescript_source(content, str(item["target_url"] or ""), generated=True)
    version_id = uuid.uuid4().hex[:12]
    version = next_script_version_number(conn, item["id"], case_id)
    relative_spec = script_version_path(
        item,
        version_id,
        batch_id=generation_batch_id,
        case_external_id=case_external_id,
    )
    resolve_workspace_path(relative_spec).write_text(content, encoding="utf-8")
    timestamp = now_iso()
    if not case_definition_hash and case_id:
        case_row = conn.execute("SELECT * FROM test_cases WHERE id = ?", (case_id,)).fetchone()
        case_definition_hash = test_case_definition_hash(case_row) if case_row is not None else ""
    conn.execute(
        """
        INSERT INTO test_script_versions (
            id, project_id, work_item_id, case_id, generation_batch_id, fixture_version_id,
            exploration_run_id, source_generated_script_id,
            version, status, spec_path, content, content_hash, asset_mode,
            case_ids_json, verified_run_id, case_definition_hash, source, script_layout,
            dependency_analysis_json, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            version_id,
            item["project_id"] or "",
            item["id"],
            case_id,
            generation_batch_id,
            fixture_version_id,
            exploration_run_id,
            source_generated_script_id,
            version,
            "draft",
            relative_spec,
            content,
            content_hash(content),
            normalize_asset_mode(asset_mode),
            json_case_ids(case_ids),
            "",
            case_definition_hash,
            source,
            script_layout,
            json.dumps(dependency_analysis or {}, ensure_ascii=False),
            timestamp,
            timestamp,
        ),
    )
    return version_id


def script_set_payload(conn: sqlite3.Connection, work_item_id: str) -> dict[str, Any]:
    batch = latest_script_batch_for_work_item(conn, work_item_id)
    if batch is None:
        return {
            "generationBatchId": "",
            "status": "empty",
            "fixtureVersion": None,
            "scriptVersions": [],
        }
    fixture = None
    if batch["fixture_version_id"]:
        fixture_row = conn.execute(
            "SELECT * FROM test_fixture_versions WHERE id = ?",
            (batch["fixture_version_id"],),
        ).fetchone()
        fixture = row_to_fixture_version(fixture_row) if fixture_row is not None else None
    versions = [row_to_script_version_detail(conn, row) for row in script_versions_for_batch(conn, batch["id"])]
    return {
        "generationBatchId": batch["id"],
        "casesRevisionId": batch["cases_revision_id"] if "cases_revision_id" in batch.keys() else None,
        "status": batch["status"],
        "source": batch["source"],
        "assetMode": batch["asset_mode"],
        "fixtureVersion": fixture,
        "scriptVersions": versions,
        "createdAt": batch["created_at"],
        "updatedAt": batch["updated_at"],
    }


def latest_case_script_versions(conn: sqlite3.Connection, work_item_id: str) -> list[sqlite3.Row]:
    batch = latest_script_batch_for_work_item(conn, work_item_id)
    if batch is None:
        legacy = latest_script_version_for_work_item(conn, work_item_id)
        return [legacy] if legacy is not None else []
    return script_versions_for_batch(conn, batch["id"])


def update_script_version_run(conn: sqlite3.Connection, script_version_id: str, run_id: str, status: str) -> None:
    # Navigation blocking is a precondition outcome, not evidence that the script is bad.
    # Preserve the current version until a later run proves the target page is reachable.
    if status == "blocked":
        return
    next_status = "verified" if status == "passed" else "failed"
    conn.execute(
        """
        UPDATE test_script_versions
        SET status = ?, verified_run_id = ?, updated_at = ?
        WHERE id = ? AND status != 'active'
        """,
        (next_status, run_id, now_iso(), script_version_id),
    )


def case_title_mapping_for_script(cases_markdown: str, script: str) -> dict[str, str]:
    titles = extract_playwright_test_titles(script)
    mapping: dict[str, str] = {}
    for item in parse_cases_markdown(cases_markdown):
        external_id = item["external_id"]
        mapping[external_id] = next((title for title in titles if external_id in title), external_id)
    return mapping


def publish_script_version(
    conn: sqlite3.Connection,
    item: sqlite3.Row,
    script_version_id: str,
    case_ids: list[str],
    cases_markdown: str,
    script: str,
    run: sqlite3.Row,
    *,
    source: str = "published",
    case_result_status: str = "",
) -> str:
    version_row = conn.execute("SELECT * FROM test_script_versions WHERE id = ?", (script_version_id,)).fetchone()
    if version_row is None:
        raise HTTPException(status_code=404, detail="脚本版本不存在")
    if version_row["work_item_id"] != item["id"]:
        raise HTTPException(status_code=400, detail="脚本版本不属于当前工单")
    verified_status = case_result_status or run["status"]
    if verified_status != "passed":
        raise HTTPException(status_code=400, detail="草稿脚本验证失败，不能发布替换绑定")
    project_id = item["project_id"] or ""
    if not project_id:
        raise HTTPException(status_code=400, detail="工单未绑定项目，请先选择项目")
    normalized_case_ids = validate_case_ids_for_project(conn, project_id, normalize_case_ids(case_ids))
    if not normalized_case_ids:
        normalized_case_ids = sync_test_cases_from_markdown(
            conn,
            project_id,
            item["id"],
            cases_markdown,
            "",
            default_feature_id=item["feature_id"] if "feature_id" in item.keys() else "",
            asset_mode=version_row["asset_mode"] or "create",
            case_ids=[],
        )
    title_mapping = case_title_mapping_for_script(cases_markdown, script)
    relative_spec = version_row["spec_path"]
    timestamp = now_iso()
    placeholders = ",".join("?" for _ in normalized_case_ids)
    previous_version_ids = [
        row["script_version_id"]
        for row in conn.execute(
            f"SELECT DISTINCT script_version_id FROM test_case_script_bindings WHERE case_id IN ({placeholders}) AND is_active = 1",
            normalized_case_ids,
        ).fetchall()
    ]
    conn.execute(
        f"UPDATE test_case_script_bindings SET is_active = 0 WHERE case_id IN ({placeholders}) AND is_active = 1",
        normalized_case_ids,
    )
    for previous_version_id in previous_version_ids:
        still_active = conn.execute(
            "SELECT 1 FROM test_case_script_bindings WHERE script_version_id = ? AND is_active = 1 LIMIT 1",
            (previous_version_id,),
        ).fetchone()
        if still_active is None:
            conn.execute(
                "UPDATE test_script_versions SET status = 'archived', updated_at = ? WHERE id = ?",
                (timestamp, previous_version_id),
            )
    conn.execute(
        """
        UPDATE test_script_versions
        SET status = 'active', verified_run_id = ?, updated_at = ?
        WHERE id = ?
        """,
        (run["id"], timestamp, script_version_id),
    )
    for case_id in normalized_case_ids:
        case_row = conn.execute("SELECT * FROM test_cases WHERE id = ?", (case_id,)).fetchone()
        if case_row is None:
            continue
        test_title = title_mapping.get(case_row["external_id"], case_row["external_id"])
        conn.execute(
            """
            INSERT INTO test_case_script_bindings (
                id, case_id, script_version_id, external_id, test_title,
                grep_pattern, is_active, bound_by_source, bound_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                uuid.uuid4().hex[:12],
                case_id,
                script_version_id,
                case_row["external_id"],
                test_title,
                re.escape(case_row["external_id"]),
                1,
                source,
                timestamp,
            ),
        )
        conn.execute(
            """
            UPDATE test_cases
            SET automation_status = 'automated', spec_path = ?, latest_run_id = ?,
                latest_status = ?, updated_at = ?
            WHERE id = ?
            """,
            (relative_spec, run["id"], verified_status, timestamp, case_id),
        )
    return relative_spec


def row_to_test_case(row: sqlite3.Row) -> dict[str, Any]:
    with get_db() as conn:
        feature = feature_summary(conn, row["feature_id"])
        active_binding = active_script_binding_for_case(conn, row["id"])
        candidate_binding = {} if active_binding else candidate_script_binding_for_case(conn, row["id"])
    return {
        "id": row["id"],
        "projectId": row["project_id"],
        "workItemId": row["work_item_id"],
        **feature,
        "externalId": row["external_id"],
        "title": row["title"],
        "titleSource": row["title_source"] if "title_source" in row.keys() and row["title_source"] in TITLE_SOURCE_VALUES else "manual",
        "canRestoreAutoTitle": bool(row["suggested_title"]) if "suggested_title" in row.keys() else False,
        "priority": row["priority"],
        "requirement": row["requirement"],
        "preconditions": row["preconditions"],
        "steps": row["steps"],
        "expected": row["expected"],
        "automationNotes": row["automation_notes"],
        "automationStatus": row["automation_status"],
        "specPath": row["spec_path"],
        "scriptVersionId": active_binding.get("scriptVersionId", ""),
        "scriptVersion": active_binding.get("version"),
        "scriptStatus": active_binding.get("status", ""),
        "testTitle": active_binding.get("testTitle", ""),
        "grepPattern": active_binding.get("grepPattern", ""),
        "candidateScriptVersionId": candidate_binding.get("scriptVersionId", ""),
        "candidateScriptVersion": candidate_binding.get("version"),
        "candidateScriptStatus": candidate_binding.get("status", ""),
        "candidateSpecPath": candidate_binding.get("specPath", ""),
        "candidateScriptLayout": candidate_binding.get("scriptLayout", ""),
        "candidateTestTitle": candidate_binding.get("testTitle", ""),
        "latestRunId": row["latest_run_id"],
        "latestStatus": row["latest_status"],
        "libraryStatus": test_case_library_status(row),
        "publishedAt": row["published_at"] or "" if "published_at" in row.keys() else "",
        "publishedRunId": row["published_run_id"] or "" if "published_run_id" in row.keys() else "",
        "createdAt": row["created_at"],
        "updatedAt": row["updated_at"],
    }


def delete_test_case_rows(conn: sqlite3.Connection, case_ids: list[str]) -> int:
    unique_case_ids = list(dict.fromkeys(case_id.strip() for case_id in case_ids if case_id.strip()))
    if not unique_case_ids:
        raise HTTPException(status_code=400, detail="请选择至少一个用例删除")
    placeholders = ",".join("?" for _ in unique_case_ids)
    existing_rows = conn.execute(
        f"SELECT id, project_id, external_id, title FROM test_cases WHERE id IN ({placeholders})",
        unique_case_ids,
    ).fetchall()
    existing_case_ids = {row["id"] for row in existing_rows}
    missing_case_ids = [case_id for case_id in unique_case_ids if case_id not in existing_case_ids]
    if missing_case_ids:
        raise HTTPException(status_code=404, detail=f"存在无效用例：{', '.join(missing_case_ids)}")
    record_deleted_test_case_tombstones(conn, existing_rows)
    conn.execute(f"DELETE FROM test_suite_cases WHERE case_id IN ({placeholders})", unique_case_ids)
    conn.execute(f"DELETE FROM test_case_script_bindings WHERE case_id IN ({placeholders})", unique_case_ids)
    conn.execute(f"DELETE FROM test_cases WHERE id IN ({placeholders})", unique_case_ids)
    return len(unique_case_ids)


def summarize_content(content: str, fallback: str = "") -> str:
    text = re.sub(r"\s+", " ", content).strip()
    if not text:
        return fallback
    return text[:180]


def render_inline_markdown(value: str) -> str:
    escaped = html.escape(value)
    escaped = re.sub(r"`([^`]+)`", r"<code>\1</code>", escaped)
    escaped = re.sub(r"\*\*([^*]+)\*\*", r"<strong>\1</strong>", escaped)
    return escaped


def markdown_table_to_html(lines: list[str]) -> str:
    rows = []
    for line in lines:
        cells = [render_inline_markdown(cell.strip()) for cell in line.strip().strip("|").split("|")]
        rows.append(cells)
    if len(rows) <= 2:
        return ""
    header = "".join(f"<th>{cell}</th>" for cell in rows[0])
    body = "".join(
        "<tr>" + "".join(f"<td>{cell}</td>" for cell in row) + "</tr>"
        for row in rows[2:]
    )
    return f"<table><thead><tr>{header}</tr></thead><tbody>{body}</tbody></table>"


def render_markdown_report(markdown: str) -> str:
    html_parts: list[str] = []
    paragraph: list[str] = []
    table_lines: list[str] = []
    list_open = False
    code_open = False

    def flush_paragraph() -> None:
        nonlocal paragraph
        if paragraph:
            html_parts.append(f"<p>{render_inline_markdown(' '.join(paragraph))}</p>")
            paragraph = []

    def flush_table() -> None:
        nonlocal table_lines
        if table_lines:
            rendered = markdown_table_to_html(table_lines)
            if rendered:
                html_parts.append(rendered)
            else:
                html_parts.extend(f"<p>{render_inline_markdown(line)}</p>" for line in table_lines)
            table_lines = []

    def close_list() -> None:
        nonlocal list_open
        if list_open:
            html_parts.append("</ul>")
            list_open = False

    for raw_line in markdown.splitlines():
        line = raw_line.rstrip()
        if line.strip().startswith("```"):
            flush_paragraph()
            flush_table()
            close_list()
            if code_open:
                html_parts.append("</code></pre>")
            else:
                html_parts.append("<pre><code>")
            code_open = not code_open
            continue
        if code_open:
            html_parts.append(html.escape(raw_line) + "\n")
            continue
        if line.startswith("|") and line.endswith("|"):
            flush_paragraph()
            close_list()
            table_lines.append(line)
            continue
        flush_table()
        stripped = line.strip()
        if not stripped:
            flush_paragraph()
            close_list()
            continue
        heading = re.match(r"^(#{1,4})\s+(.+)$", stripped)
        if heading:
            flush_paragraph()
            close_list()
            level = min(len(heading.group(1)) + 1, 5)
            html_parts.append(f"<h{level}>{render_inline_markdown(heading.group(2))}</h{level}>")
            continue
        bullet = re.match(r"^[-*]\s+(.+)$", stripped)
        if bullet:
            flush_paragraph()
            if not list_open:
                html_parts.append("<ul>")
                list_open = True
            html_parts.append(f"<li>{render_inline_markdown(bullet.group(1))}</li>")
            continue
        paragraph.append(stripped)

    flush_paragraph()
    flush_table()
    close_list()
    if code_open:
        html_parts.append("</code></pre>")
    return "\n".join(html_parts)


def rendered_report_page(title: str, body: str) -> str:
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>{html.escape(title)}</title>
  <style>
    :root {{ color-scheme: light; font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }}
    body {{ margin: 0; background: #f6f8fb; color: #172033; }}
    main {{ width: min(1080px, calc(100vw - 40px)); margin: 32px auto; background: #fff; border: 1px solid #d9e2ef; border-radius: 8px; padding: 32px; box-shadow: 0 18px 50px rgba(22, 34, 51, 0.08); }}
    h1 {{ margin: 0 0 20px; font-size: 26px; }}
    h2, h3, h4, h5 {{ margin: 28px 0 12px; color: #0f172a; }}
    p, li {{ line-height: 1.72; }}
    p code, li code {{ background: #eef3f9; border-radius: 4px; padding: 2px 5px; color: #172033; }}
    pre {{ overflow: auto; background: #0f172a; color: #e5edf7; border: 1px solid #1e293b; border-radius: 8px; padding: 16px; font: 14px/1.65 Menlo, Consolas, "Liberation Mono", monospace; white-space: pre-wrap; overflow-wrap: anywhere; }}
    pre code {{ background: transparent; border-radius: 0; padding: 0; color: inherit; font: inherit; }}
    table {{ width: 100%; border-collapse: collapse; margin: 16px 0 24px; font-size: 14px; }}
    th, td {{ border: 1px solid #d9e2ef; padding: 10px 12px; text-align: left; vertical-align: top; }}
    th {{ background: #f1f5f9; }}
    .meta {{ margin-bottom: 24px; color: #64748b; }}
  </style>
</head>
<body>
  <main>
    <h1>{html.escape(title)}</h1>
    <div class="meta">由 QA 自动化测试平台渲染</div>
    {body}
  </main>
</body>
</html>"""


def register_deliverable(
    conn: sqlite3.Connection,
    project_id: str,
    deliverable_type: str,
    name: str,
    file_path: str | Path,
    *,
    work_item_id: str = "",
    case_id: str = "",
    run_id: str = "",
    feature_id: str = "",
    status: str = "ready",
    summary: str = "",
    bump_version: bool = True,
) -> str:
    normalized_path = relative_or_absolute(file_path)
    normalized_feature_id = validate_project_feature(conn, project_id, feature_id) if feature_id else ""
    existing = conn.execute(
        """
        SELECT id, version FROM deliverables
        WHERE project_id = ? AND type = ? AND file_path = ?
        """,
        (project_id, deliverable_type, normalized_path),
    ).fetchone()
    deliverable_id = existing["id"] if existing else uuid.uuid4().hex[:12]
    version = (existing["version"] + 1) if existing and bump_version else existing["version"] if existing else 1
    timestamp = now_iso()
    conn.execute(
        """
        INSERT INTO deliverables (
            id, project_id, work_item_id, case_id, run_id, feature_id, type, name, status,
            version, file_path, summary, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
            work_item_id = excluded.work_item_id,
            case_id = excluded.case_id,
            run_id = excluded.run_id,
            feature_id = excluded.feature_id,
            name = excluded.name,
            status = excluded.status,
            version = excluded.version,
            summary = excluded.summary,
            updated_at = excluded.updated_at
        """,
        (
            deliverable_id,
            project_id,
            work_item_id,
            case_id,
            run_id,
            normalized_feature_id,
            deliverable_type,
            name,
            status,
            version,
            normalized_path,
            summary,
            timestamp,
            timestamp,
        ),
    )
    return deliverable_id


def project_deliverable_dir(project_slug: str, work_item_slug: str) -> Path:
    return PROJECT_ARTIFACT_DIR / project_slug / "deliverables" / work_item_slug


def spec_path_for_case_doc(case_path: Path) -> Path:
    suffix = "-test-cases.md"
    if case_path.name.endswith(suffix):
        return case_path.with_name(f"{case_path.name[:-len(suffix)]}.spec.ts")
    return case_path.with_suffix(".spec.ts")


def row_to_deliverable(row: sqlite3.Row, include_content: bool = False) -> dict[str, Any]:
    with get_db() as conn:
        feature = feature_summary(conn, row["feature_id"] if "feature_id" in row.keys() else "")
    payload = {
        "id": row["id"],
        "projectId": row["project_id"],
        "workItemId": row["work_item_id"],
        "caseId": row["case_id"],
        "runId": row["run_id"],
        **feature,
        "type": row["type"],
        "name": row["name"],
        "status": row["status"],
        "version": row["version"],
        "filePath": row["file_path"],
        "summary": row["summary"],
        "createdAt": row["created_at"],
        "updatedAt": row["updated_at"],
        "content": "",
    }
    if include_content:
        path = resolve_workspace_path(row["file_path"])
        if path.exists() and path.is_file() and path.stat().st_size <= 512_000:
            with contextlib.suppress(UnicodeDecodeError, OSError):
                payload["content"] = path.read_text(encoding="utf-8")
    return payload


def row_to_work_item_summary(row: sqlite3.Row | None) -> dict[str, Any] | None:
    if row is None:
        return None
    with get_db() as conn:
        feature = feature_summary(conn, row["feature_id"] if "feature_id" in row.keys() else "")
    return {
        "id": row["id"],
        "projectId": row["project_id"] if "project_id" in row.keys() else "",
        **feature,
        "slug": row["slug"],
        "title": row["title"],
        "titleSource": row["title_source"] if "title_source" in row.keys() and row["title_source"] in TITLE_SOURCE_VALUES else "manual",
        "requirement": row["requirement"],
        "stage": row["stage"],
        "status": row["status"],
        "systemImport": bool(row["is_system_import"]) if "is_system_import" in row.keys() else False,
        "importId": row["import_id"] if "import_id" in row.keys() and row["import_id"] else "",
        "createdAt": row["created_at"],
        "updatedAt": row["updated_at"],
    }


def deliverable_case_match_sql(alias: str = "d") -> str:
    return f"""
        {alias}.project_id = tc.project_id
        AND (
            ({alias}.case_id IS NOT NULL AND {alias}.case_id != '' AND {alias}.case_id = tc.id)
            OR (
                ({alias}.case_id IS NULL OR {alias}.case_id = '')
                AND tc.work_item_id IS NOT NULL AND tc.work_item_id != ''
                AND {alias}.work_item_id IS NOT NULL AND {alias}.work_item_id != ''
                AND {alias}.work_item_id = tc.work_item_id
            )
            OR (
                ({alias}.case_id IS NULL OR {alias}.case_id = '')
                AND ({alias}.work_item_id IS NULL OR {alias}.work_item_id = '')
                AND tc.spec_path IS NOT NULL AND tc.spec_path != ''
                AND {alias}.file_path = tc.spec_path
            )
            OR (
                ({alias}.case_id IS NULL OR {alias}.case_id = '')
                AND ({alias}.work_item_id IS NULL OR {alias}.work_item_id = '')
                AND tc.spec_path IS NOT NULL AND tc.spec_path != ''
                AND {alias}.type = 'test-cases'
                AND {alias}.file_path = replace(tc.spec_path, '.spec.ts', '-test-cases.md')
            )
        )
    """


def row_to_delivery_report_item(conn: sqlite3.Connection, case_row: sqlite3.Row) -> dict[str, Any]:
    project_row = conn.execute("SELECT * FROM projects WHERE id = ?", (case_row["project_id"],)).fetchone()
    work_item_row = conn.execute("SELECT * FROM work_items WHERE id = ?", (case_row["work_item_id"] or "",)).fetchone()
    run_row = None
    if case_row["latest_run_id"]:
        run_row = conn.execute("SELECT * FROM runs WHERE id = ?", (case_row["latest_run_id"],)).fetchone()
    if run_row is None and case_row["work_item_id"]:
        run_row = conn.execute(
            "SELECT * FROM runs WHERE work_item_id = ? ORDER BY started_at DESC LIMIT 1",
            (case_row["work_item_id"],),
        ).fetchone()
    deliverable_rows = conn.execute(
        """
        SELECT DISTINCT d.*
        FROM deliverables d
        WHERE d.project_id = ?
          AND (
              (d.case_id IS NOT NULL AND d.case_id != '' AND d.case_id = ?)
              OR (
                  (d.case_id IS NULL OR d.case_id = '')
                  AND ? != ''
                  AND d.work_item_id IS NOT NULL AND d.work_item_id != ''
                  AND d.work_item_id = ?
              )
              OR (
                  (d.case_id IS NULL OR d.case_id = '')
                  AND (d.work_item_id IS NULL OR d.work_item_id = '')
                  AND ? != ''
                  AND d.file_path = ?
              )
              OR (
                  (d.case_id IS NULL OR d.case_id = '')
                  AND (d.work_item_id IS NULL OR d.work_item_id = '')
                  AND ? != ''
                  AND d.type = 'test-cases'
                  AND d.file_path = ?
              )
          )
        ORDER BY d.updated_at DESC, d.version DESC
        """,
        (
            case_row["project_id"],
            case_row["id"],
            case_row["work_item_id"] or "",
            case_row["work_item_id"] or "",
            case_row["spec_path"] or "",
            case_row["spec_path"] or "",
            case_row["spec_path"] or "",
            (case_row["spec_path"] or "").replace(".spec.ts", "-test-cases.md"),
        ),
    ).fetchall()
    deliverables_payload = [row_to_deliverable(row, include_content=False) for row in deliverable_rows]
    deliverable_summary: dict[str, Any] = {}
    for deliverable in deliverables_payload:
        deliverable_summary.setdefault(deliverable["type"], deliverable)
    missing_types = [deliverable_type for deliverable_type in REQUIRED_DELIVERY_TYPES if deliverable_type not in deliverable_summary]
    latest_status = case_row["latest_status"] or (run_row["status"] if run_row is not None else "")
    readiness = "missing" if missing_types else "ready"
    if latest_status == "failed":
        readiness = "risk"
    updated_candidates = [case_row["updated_at"]]
    updated_candidates.extend(row["updated_at"] for row in deliverable_rows if row["updated_at"])
    updated_at = max(updated_candidates) if updated_candidates else case_row["updated_at"]
    return {
        "case": row_to_test_case(case_row),
        "project": row_to_project(project_row) if project_row else None,
        "workItem": row_to_work_item_summary(work_item_row),
        "latestRun": row_to_run(run_row) if run_row else None,
        "deliverables": deliverables_payload,
        "deliverableSummary": deliverable_summary,
        "readiness": readiness,
        "missingTypes": missing_types,
        "updatedAt": updated_at,
    }


def delivery_report_readiness_sql() -> tuple[str, str, str]:
    missing_checks = [
        f"""
        NOT EXISTS (
            SELECT 1 FROM deliverables d_{deliverable_type.replace("-", "_")}
            WHERE {deliverable_case_match_sql(f"d_{deliverable_type.replace('-', '_')}")}
              AND d_{deliverable_type.replace("-", "_")}.type = '{deliverable_type}'
        )
        """
        for deliverable_type in REQUIRED_DELIVERY_TYPES
    ]
    missing_sql = " OR ".join(missing_checks)
    failed_sql = """
        COALESCE(
            tc.latest_status,
            (
                SELECT r.status
                FROM runs r
                WHERE r.id = tc.latest_run_id
                LIMIT 1
            ),
            (
                SELECT wr.status
                FROM runs wr
                WHERE wr.work_item_id = tc.work_item_id
                ORDER BY wr.started_at DESC
                LIMIT 1
            ),
            ''
        ) = 'failed'
    """
    readiness_sql = f"""
        CASE
            WHEN {failed_sql} THEN 'risk'
            WHEN {missing_sql} THEN 'missing'
            ELSE 'ready'
        END
    """
    return readiness_sql, missing_sql, failed_sql


def delivery_report_summary(conn: sqlite3.Connection, where_sql: str, params: list[Any]) -> dict[str, Any]:
    readiness_sql, missing_sql, failed_sql = delivery_report_readiness_sql()
    row = conn.execute(
        f"""
        SELECT
            COUNT(*) AS total,
            SUM(CASE WHEN ({readiness_sql}) = 'ready' THEN 1 ELSE 0 END) AS ready,
            SUM(CASE WHEN ({missing_sql}) THEN 1 ELSE 0 END) AS missing,
            SUM(CASE WHEN ({failed_sql}) THEN 1 ELSE 0 END) AS failed_risk
        FROM test_cases tc
        {where_sql}
        """,
        params,
    ).fetchone()
    missing_by_type: dict[str, int] = {}
    for deliverable_type in REQUIRED_DELIVERY_TYPES:
        alias = "dm"
        missing_by_type[deliverable_type] = conn.execute(
            f"""
            SELECT COUNT(*) AS total
            FROM test_cases tc
            {where_sql}
            AND NOT EXISTS (
                SELECT 1 FROM deliverables {alias}
                WHERE {deliverable_case_match_sql(alias)}
                  AND {alias}.type = ?
            )
            """ if where_sql else f"""
            SELECT COUNT(*) AS total
            FROM test_cases tc
            WHERE NOT EXISTS (
                SELECT 1 FROM deliverables {alias}
                WHERE {deliverable_case_match_sql(alias)}
                  AND {alias}.type = ?
            )
            """,
            [*params, deliverable_type],
        ).fetchone()["total"]
    return {
        "total": row["total"] or 0,
        "ready": row["ready"] or 0,
        "missing": row["missing"] or 0,
        "failedRisk": row["failed_risk"] or 0,
        "missingByType": missing_by_type,
    }


def migrate_project_case_deliverable_data(conn: sqlite3.Connection) -> None:
    default_project = conn.execute("SELECT id FROM projects WHERE id = ?", (DEFAULT_PROJECT_ID,)).fetchone()
    if default_project is None:
        return
    legacy_project_id = default_project["id"]
    conn.execute("UPDATE work_items SET project_id = ? WHERE project_id IS NULL OR project_id = ''", (legacy_project_id,))
    rows = conn.execute("SELECT * FROM work_items").fetchall()
    for row in rows:
        project_id = row["project_id"] if "project_id" in row.keys() and row["project_id"] else legacy_project_id
        cases_path = row["cases_path"] if "cases_path" in row.keys() else ""
        spec_path = row["spec_path"] if "spec_path" in row.keys() else ""
        report_path = row["report_path"] if "report_path" in row.keys() else ""
        cases_content = ""
        if cases_path and resolve_workspace_path(cases_path).exists():
            with contextlib.suppress(OSError, UnicodeDecodeError):
                cases_content = resolve_workspace_path(cases_path).read_text(encoding="utf-8")
        if not cases_content:
            latest = conn.execute(
                "SELECT content FROM generated_cases WHERE work_item_id = ? ORDER BY id DESC LIMIT 1",
                (row["id"],),
            ).fetchone()
            cases_content = latest["content"] if latest else ""
        case_ids = sync_test_cases_from_markdown(
            conn,
            project_id,
            row["id"],
            cases_content,
            relative_or_absolute(spec_path) if spec_path else "",
            asset_mode="append",
        ) if cases_content else []
        for deliverable_type, path_value, name in [
            ("test-cases", cases_path, f"{row['title']} 测试用例"),
            ("spec", spec_path, f"{row['title']} 自动化脚本"),
            ("manual-report", report_path, f"{row['title']} 人工测试报告"),
        ]:
            if path_value and resolve_workspace_path(path_value).exists():
                register_deliverable(
                    conn,
                    project_id,
                    deliverable_type,
                    name,
                    path_value,
                    work_item_id=row["id"],
                    case_id=case_ids[0] if len(case_ids) == 1 else "",
                    run_id=row["latest_run_id"] or "",
                    summary=f"从历史工单 {row['title']} 迁移登记。",
                    bump_version=False,
                )

    test_dir = ROOT_DIR / project_context().get("testDir", "tests/e2e")
    if test_dir.exists():
        for case_path in test_dir.glob("*-test-cases.md"):
            with contextlib.suppress(OSError, UnicodeDecodeError):
                content = case_path.read_text(encoding="utf-8")
                sibling_spec_path = spec_path_for_case_doc(case_path)
                sibling_spec = relative_or_absolute(sibling_spec_path) if sibling_spec_path.exists() else ""
                case_ids = sync_test_cases_from_markdown(conn, legacy_project_id, "", content, sibling_spec, asset_mode="append")
                register_deliverable(
                    conn,
                    legacy_project_id,
                    "test-cases",
                    case_path.name,
                    case_path,
                    case_id=case_ids[0] if len(case_ids) == 1 else "",
                    summary="从仓库测试用例文档扫描登记。",
                    bump_version=False,
                )
                if sibling_spec_path.exists():
                    for case_id in case_ids:
                        register_deliverable(
                            conn,
                            legacy_project_id,
                            "spec",
                            sibling_spec_path.name,
                            sibling_spec_path,
                            case_id=case_id,
                            summary="从同名用例文档关联 Playwright spec。",
                            bump_version=False,
                        )
        for spec_path in test_dir.glob("*.spec.ts"):
            register_deliverable(
                conn,
                legacy_project_id,
                "spec",
                spec_path.name,
                spec_path,
                summary="从仓库 Playwright spec 扫描登记。",
                bump_version=False,
            )
    for report_path in ROOT_DIR.glob("*-test-report.md"):
        register_deliverable(
            conn,
            legacy_project_id,
            "manual-report",
            report_path.name,
            report_path,
            summary="从仓库人工测试报告扫描登记。",
            bump_version=False,
        )
    if REPORT_INDEX.exists():
        register_deliverable(
            conn,
            legacy_project_id,
            "html-report",
            "Playwright HTML Report",
            REPORT_INDEX,
            summary="从已有 Playwright HTML Report 扫描登记。",
            bump_version=False,
        )


def get_setting(key: str) -> str:
    with get_db() as conn:
        row = conn.execute("SELECT value FROM app_settings WHERE key = ?", (key,)).fetchone()
    return row["value"] if row else ""


def set_setting(key: str, value: str) -> None:
    with get_db() as conn:
        conn.execute(
            """
            INSERT INTO app_settings (key, value, updated_at)
            VALUES (?, ?, ?)
            ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at
            """,
            (key, value, now_iso()),
        )


DEFAULT_OPENAI_BASE_URL = "https://api.openai.com/v1"
DEFAULT_OPENAI_MODEL = "gpt-4.1-mini"
AI_PROFILES_SETTING_KEY = "ai_profiles"
AI_ACTIVE_PROFILE_SETTING_KEY = "ai_active_profile_id"
AI_PROVIDER_VALUES = {"openai", "gpt", "anthropic", "deepseek", "custom"}
AI_API_PROTOCOL_VALUES = {"responses", "chat_completions"}
AI_STRUCTURED_OUTPUT_MODE_VALUES = {"json_schema", "json_object"}
AI_CAPABILITY_CACHE: dict[str, dict[str, str]] = {}


def mask_secret(value: str) -> str:
    secret = (value or "").strip()
    if not secret:
        return ""
    return f"{secret[:7]}...{secret[-4:]}" if len(secret) > 12 else "已配置"


def normalize_openai_base_url(value: str) -> str:
    base_url = (value or DEFAULT_OPENAI_BASE_URL).strip()
    if not base_url:
        return DEFAULT_OPENAI_BASE_URL
    base_url = base_url.rstrip("/")
    if base_url.endswith("/responses"):
        base_url = base_url[: -len("/responses")].rstrip("/")
    if base_url.endswith("/chat/completions"):
        base_url = base_url[: -len("/chat/completions")].rstrip("/")
    return base_url or DEFAULT_OPENAI_BASE_URL


def validate_openai_base_url(base_url: str) -> None:
    if not re.match(r"^https?://", base_url):
        raise HTTPException(status_code=400, detail="Base URL 必须以 http:// 或 https:// 开头")


def normalize_ai_provider(value: str) -> str:
    provider = (value or "openai").strip().lower()
    return provider if provider in AI_PROVIDER_VALUES else "custom"


def normalize_ai_api_protocol(value: str) -> str:
    protocol = (value or "").strip().lower()
    return protocol if protocol in AI_API_PROTOCOL_VALUES else ""


def normalize_ai_structured_output_mode(value: str) -> str:
    mode = (value or "").strip().lower()
    return mode if mode in AI_STRUCTURED_OUTPUT_MODE_VALUES else ""


def default_ai_profile_name(provider: str) -> str:
    return {
        "openai": "OpenAI 默认配置",
        "gpt": "GPT 网关配置",
        "anthropic": "Anthropic 兼容配置",
        "deepseek": "DeepSeek 配置",
        "custom": "自定义 AI 配置",
    }.get(provider, "AI 配置")


def normalize_ai_profile(raw: dict[str, Any] | None, *, fallback_id: str = "") -> dict[str, str]:
    payload = raw or {}
    provider = normalize_ai_provider(str(payload.get("provider") or "openai"))
    profile_id = str(payload.get("id") or fallback_id or uuid.uuid4().hex[:12]).strip()
    name = str(payload.get("name") or default_ai_profile_name(provider)).strip() or default_ai_profile_name(provider)
    model = str(payload.get("model") or DEFAULT_OPENAI_MODEL).strip() or DEFAULT_OPENAI_MODEL
    base_url = normalize_openai_base_url(str(payload.get("base_url") or payload.get("baseUrl") or DEFAULT_OPENAI_BASE_URL))
    return {
        "id": profile_id,
        "name": name,
        "provider": provider,
        "api_key": str(payload.get("api_key") or payload.get("apiKey") or "").strip(),
        "model": model,
        "base_url": base_url,
        "api_protocol": normalize_ai_api_protocol(str(payload.get("api_protocol") or payload.get("apiProtocol") or "")),
        "structured_output_mode": normalize_ai_structured_output_mode(str(payload.get("structured_output_mode") or payload.get("structuredOutputMode") or "")),
        "capability_verified_at": str(payload.get("capability_verified_at") or payload.get("capabilityVerifiedAt") or "").strip(),
        "updated_at": str(payload.get("updated_at") or payload.get("updatedAt") or now_iso()),
    }


def public_ai_profile(profile: dict[str, str]) -> dict[str, Any]:
    return {
        "id": profile["id"],
        "name": profile["name"],
        "provider": profile["provider"],
        "model": profile["model"],
        "baseUrl": profile["base_url"],
        "apiProtocol": profile.get("api_protocol", ""),
        "structuredOutputMode": profile.get("structured_output_mode", ""),
        "capabilityVerifiedAt": profile.get("capability_verified_at", ""),
        "maskedKey": mask_secret(profile.get("api_key", "")),
        "updatedAt": profile.get("updated_at", ""),
    }


def save_ai_profiles(profiles: list[dict[str, str]], active_profile_id: str = "") -> None:
    normalized = [normalize_ai_profile(profile) for profile in profiles]
    set_setting(AI_PROFILES_SETTING_KEY, json.dumps(normalized, ensure_ascii=False))
    if active_profile_id:
        set_setting(AI_ACTIVE_PROFILE_SETTING_KEY, active_profile_id)


def legacy_ai_profile() -> dict[str, str] | None:
    legacy_key = get_setting("openai_api_key")
    legacy_model = get_setting("openai_model")
    legacy_base_url = get_setting("openai_base_url")
    if not any([legacy_key, legacy_model, legacy_base_url]):
        return None
    return normalize_ai_profile(
        {
            "id": "openai-default",
            "name": "OpenAI 默认配置",
            "provider": "openai",
            "api_key": legacy_key,
            "model": legacy_model or DEFAULT_OPENAI_MODEL,
            "base_url": legacy_base_url or DEFAULT_OPENAI_BASE_URL,
        }
    )


def get_ai_profiles(*, migrate_legacy: bool = True) -> list[dict[str, str]]:
    stored = get_setting(AI_PROFILES_SETTING_KEY)
    profiles: list[dict[str, str]] = []
    if stored:
        try:
            decoded = json.loads(stored)
        except json.JSONDecodeError:
            decoded = []
        if isinstance(decoded, list):
            profiles = [normalize_ai_profile(item) for item in decoded if isinstance(item, dict)]
    if not profiles and migrate_legacy:
        legacy = legacy_ai_profile()
        if legacy:
            profiles = [legacy]
            save_ai_profiles(profiles, legacy["id"])
    return profiles


def get_active_ai_profile(profiles: list[dict[str, str]] | None = None) -> dict[str, str] | None:
    items = profiles if profiles is not None else get_ai_profiles()
    if not items:
        return None
    active_id = get_setting(AI_ACTIVE_PROFILE_SETTING_KEY)
    return next((profile for profile in items if profile["id"] == active_id), None) or items[0]


def ai_runtime_config() -> dict[str, str]:
    profile = get_active_ai_profile()
    env_key = os.environ.get("OPENAI_API_KEY", "")
    env_base_url = os.environ.get("OPENAI_BASE_URL", "")
    base_url = env_base_url or (profile["base_url"] if profile else DEFAULT_OPENAI_BASE_URL)
    use_profile_capability = bool(profile and not env_base_url and normalize_openai_base_url(base_url) == profile["base_url"])
    return {
        "profile_id": profile["id"] if profile else "",
        "provider": profile["provider"] if profile else "not-configured",
        "api_key": env_key or (profile["api_key"] if profile else ""),
        "model": profile["model"] if profile else DEFAULT_OPENAI_MODEL,
        "base_url": normalize_openai_base_url(base_url),
        "api_protocol": profile.get("api_protocol", "") if use_profile_capability else "",
        "structured_output_mode": profile.get("structured_output_mode", "") if use_profile_capability else "",
        "capability_verified_at": profile.get("capability_verified_at", "") if use_profile_capability else "",
        "source": "env" if env_key else "local" if profile and profile.get("api_key") else "none",
        "base_url_source": "env" if env_base_url else "local" if profile and profile.get("base_url") else "default",
    }


def get_openai_api_key() -> str:
    if os.environ.get("QA_DISABLE_AI") == "1":
        return ""
    return ai_runtime_config()["api_key"]


def get_openai_model() -> str:
    return ai_runtime_config()["model"]


def get_openai_base_url() -> str:
    return ai_runtime_config()["base_url"]


def build_openai_url(path: str, base_url: str | None = None) -> str:
    normalized_base = normalize_openai_base_url(base_url or get_openai_base_url())
    return f"{normalized_base}/{path.lstrip('/')}"


def infer_ai_provider(provider: str = "", base_url: str = "") -> str:
    if provider:
        normalized = normalize_ai_provider(provider)
    else:
        runtime = ai_runtime_config()
        inherited_provider = runtime["provider"] if not base_url or normalize_openai_base_url(base_url) == runtime["base_url"] else "custom"
        normalized = normalize_ai_provider(inherited_provider)
    hostname = urllib.parse.urlparse(base_url or "").hostname or ""
    if normalized == "custom" and "deepseek.com" in hostname:
        return "deepseek"
    return normalized


def build_chat_completions_url(base_url: str) -> str:
    normalized_base = normalize_openai_base_url(base_url)
    parsed = urllib.parse.urlparse(normalized_base)
    if parsed.hostname == "api.deepseek.com" and parsed.path.rstrip("/") == "/v1":
        normalized_base = normalized_base[: -len("/v1")]
    return f"{normalized_base}/chat/completions"


def parse_openai_text_response(body: dict[str, Any]) -> str:
    if body.get("choices"):
        text_chunks: list[str] = []
        for choice in body.get("choices", []):
            message = choice.get("message") or {}
            if message.get("content"):
                text_chunks.append(str(message["content"]))
            elif choice.get("text"):
                text_chunks.append(str(choice["text"]))
        if text_chunks:
            return "\n".join(text_chunks)
    text_chunks: list[str] = []
    for item_payload in body.get("output", []):
        for content in item_payload.get("content", []):
            if content.get("type") in {"output_text", "text"} and content.get("text"):
                text_chunks.append(content["text"])
    if not text_chunks and body.get("output_text"):
        text_chunks.append(body["output_text"])
    return "\n".join(text_chunks)


class AIRequestError(RuntimeError):
    def __init__(
        self,
        message: str,
        *,
        status_code: int | None = None,
        provider_code: str = "",
        compatibility_error: bool = False,
        retryable: bool = False,
    ) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.provider_code = provider_code
        self.technical_message = message
        self.compatibility_error = compatibility_error
        self.retryable = retryable


def ai_error_details(exc: Exception) -> dict[str, Any]:
    if isinstance(exc, AIRequestError):
        return {
            "httpStatus": exc.status_code,
            "providerCode": exc.provider_code,
            "technicalReason": exc.technical_message,
            "compatibilityError": exc.compatibility_error,
            "retryable": exc.retryable,
        }
    return {
        "httpStatus": None,
        "providerCode": "",
        "technicalReason": openai_error_message(exc),
        "compatibilityError": False,
        "retryable": isinstance(exc, (TimeoutError, urllib.error.URLError)),
    }


def ai_http_error(exc: urllib.error.HTTPError) -> AIRequestError:
    raw_body = ""
    with contextlib.suppress(Exception):
        raw_body = exc.read().decode("utf-8", errors="replace")
    detail = ""
    provider_code = ""
    if raw_body:
        try:
            body = json.loads(raw_body)
        except json.JSONDecodeError:
            body = {}
        if isinstance(body, dict):
            error = body.get("error") if isinstance(body.get("error"), dict) else {}
            detail = str(error.get("message") or body.get("detail") or "").strip()
            provider_code = str(error.get("code") or "").strip()
    normalized_detail = " ".join(detail.split())
    compatibility_error = exc.code in {404, 405} or bool(
        exc.code == 400
        and re.search(
            r"(?:unknown|unsupported|unavailable|not supported|does not support|invalid).{0,80}(?:response_format|json_schema|responses)|"
            r"(?:response_format|json_schema|responses).{0,80}(?:unknown|unsupported|unavailable|not supported|does not support|invalid)",
            normalized_detail,
            re.IGNORECASE,
        )
    )
    status_messages = {
        401: "鉴权失败，请检查 API Key",
        403: "请求被拒绝，请检查 API Key 权限或网关访问策略",
        404: "接口不存在，请确认 Base URL 支持当前厂商的生成接口",
        405: "接口不接受当前请求方式",
        429: "请求被限流，请稍后重试或检查额度",
    }
    prefix = status_messages.get(exc.code, f"服务返回 HTTP {exc.code}")
    message = f"{prefix}{f'：{normalized_detail}' if normalized_detail else ''}"
    return AIRequestError(
        message,
        status_code=exc.code,
        provider_code=provider_code,
        compatibility_error=compatibility_error,
        retryable=exc.code == 429 or exc.code >= 500,
    )


def openai_error_message(exc: Exception) -> str:
    if isinstance(exc, AIRequestError):
        return exc.technical_message
    if isinstance(exc, urllib.error.HTTPError):
        return ai_http_error(exc).technical_message
    if isinstance(exc, TimeoutError):
        return "连接超时，请检查 Base URL、网络或网关响应速度"
    if isinstance(exc, urllib.error.URLError):
        reason = getattr(exc, "reason", exc)
        return f"连接失败，请检查 Base URL：{reason}"
    if isinstance(exc, json.JSONDecodeError):
        return "服务返回内容不是有效 JSON，请确认网关兼容 OpenAI Responses API"
    return str(exc) or "连接测试失败"


def structured_format_from_payload(payload: dict[str, Any]) -> dict[str, Any]:
    text_config = payload.get("text") if isinstance(payload.get("text"), dict) else {}
    return text_config.get("format") if isinstance(text_config.get("format"), dict) else {}


def schema_json_instruction(text_format: dict[str, Any]) -> str:
    schema = text_format.get("schema") if isinstance(text_format.get("schema"), dict) else {}
    schema_text = json.dumps(schema, ensure_ascii=False, separators=(",", ":"))
    return (
        "Return exactly one valid JSON object. Do not use Markdown code fences or explanatory text. "
        f"The JSON object must satisfy this JSON Schema: {schema_text}"
    )


def prepend_chat_instruction(messages: list[dict[str, Any]], instruction: str) -> list[dict[str, Any]]:
    if not instruction:
        return messages
    return [{"role": "system", "content": instruction}, *messages]


def chat_payload_from_responses_payload(
    model: str,
    payload: dict[str, Any],
    *,
    stream: bool = False,
    structured_output_mode: str = "json_object",
) -> dict[str, Any]:
    input_value = payload.get("input", "")
    if isinstance(input_value, list):
        messages = input_value
    else:
        messages = [{"role": "user", "content": str(input_value)}]
    text_format = structured_format_from_payload(payload)
    mode = normalize_ai_structured_output_mode(structured_output_mode) or "json_object"
    if text_format and mode == "json_object":
        messages = prepend_chat_instruction(messages, schema_json_instruction(text_format))
    chat_payload: dict[str, Any] = {
        "model": model,
        "messages": messages,
        "stream": stream,
    }
    if payload.get("max_output_tokens") is not None:
        chat_payload["max_tokens"] = payload["max_output_tokens"]
    if text_format:
        if mode == "json_schema":
            chat_payload["response_format"] = {
                "type": "json_schema",
                "json_schema": {
                    "name": str(text_format.get("name") or "structured_output"),
                    "strict": bool(text_format.get("strict", True)),
                    "schema": text_format.get("schema") or {},
                },
            }
        else:
            chat_payload["response_format"] = {"type": "json_object"}
    return chat_payload


def ai_operation_from_payload(payload: dict[str, Any]) -> str:
    text_config = payload.get("text") if isinstance(payload.get("text"), dict) else {}
    format_config = text_config.get("format") if isinstance(text_config.get("format"), dict) else {}
    return str(format_config.get("name") or "text_generation")


def ai_capability_cache_key(provider: str, model: str, base_url: str) -> str:
    return "|".join((normalize_ai_provider(provider), model.strip(), normalize_openai_base_url(base_url)))


def official_ai_host(base_url: str, hostname: str) -> bool:
    return (urllib.parse.urlparse(normalize_openai_base_url(base_url)).hostname or "").lower() == hostname


def default_ai_capability(provider: str, base_url: str) -> dict[str, str]:
    resolved_provider = infer_ai_provider(provider, base_url)
    if resolved_provider == "deepseek" or official_ai_host(base_url, "api.deepseek.com"):
        return {"api_protocol": "chat_completions", "structured_output_mode": "json_object"}
    if official_ai_host(base_url, "api.openai.com"):
        return {"api_protocol": "responses", "structured_output_mode": "json_schema"}
    return {"api_protocol": "", "structured_output_mode": ""}


def persist_ai_capability(provider: str, model: str, base_url: str, capability: dict[str, str]) -> None:
    resolved_provider = infer_ai_provider(provider, base_url)
    normalized = {
        "api_protocol": normalize_ai_api_protocol(capability.get("api_protocol", "")),
        "structured_output_mode": normalize_ai_structured_output_mode(capability.get("structured_output_mode", "")),
        "capability_verified_at": capability.get("capability_verified_at") or now_iso(),
    }
    AI_CAPABILITY_CACHE[ai_capability_cache_key(provider, model, base_url)] = normalized
    profiles = get_ai_profiles()
    changed = False
    for profile in profiles:
        if infer_ai_provider(profile["provider"], profile["base_url"]) != resolved_provider:
            continue
        if profile["model"] != model or profile["base_url"] != normalize_openai_base_url(base_url):
            continue
        profile.update(normalized)
        changed = True
    if changed:
        save_ai_profiles(profiles, get_setting(AI_ACTIVE_PROFILE_SETTING_KEY))


def clear_ai_capability(provider: str, model: str, base_url: str) -> None:
    resolved_provider = infer_ai_provider(provider, base_url)
    AI_CAPABILITY_CACHE.pop(ai_capability_cache_key(provider, model, base_url), None)
    profiles = get_ai_profiles()
    changed = False
    for profile in profiles:
        if infer_ai_provider(profile["provider"], profile["base_url"]) == resolved_provider and profile["model"] == model and profile["base_url"] == normalize_openai_base_url(base_url):
            profile.update(api_protocol="", structured_output_mode="", capability_verified_at="")
            changed = True
    if changed:
        save_ai_profiles(profiles, get_setting(AI_ACTIVE_PROFILE_SETTING_KEY))


def stored_ai_capability(provider: str, model: str, base_url: str) -> dict[str, str]:
    runtime = ai_runtime_config()
    if (
        runtime["provider"] == normalize_ai_provider(provider)
        and runtime["model"] == model
        and runtime["base_url"] == normalize_openai_base_url(base_url)
        and runtime.get("api_protocol")
    ):
        return {
            "api_protocol": runtime["api_protocol"],
            "structured_output_mode": runtime.get("structured_output_mode") or "json_schema",
            "capability_verified_at": runtime.get("capability_verified_at", ""),
        }
    return AI_CAPABILITY_CACHE.get(ai_capability_cache_key(provider, model, base_url), {})


def open_ai_request(request: urllib.request.Request, timeout: int) -> dict[str, Any]:
    hostname = urllib.parse.urlparse(request.full_url).hostname or ""
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({})) if hostname in {"localhost", "127.0.0.1", "::1"} else urllib.request.build_opener()
    try:
        with opener.open(request, timeout=timeout) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        raise ai_http_error(exc) from exc


def call_ai_protocol(
    api_key: str,
    model: str,
    base_url: str,
    payload: dict[str, Any],
    *,
    api_protocol: str,
    structured_output_mode: str,
    timeout: int,
) -> dict[str, Any]:
    if api_protocol == "chat_completions":
        url = build_chat_completions_url(base_url)
        request_payload = chat_payload_from_responses_payload(
            model,
            payload,
            structured_output_mode=structured_output_mode,
        )
    else:
        url = build_openai_url("/responses", base_url)
        request_payload = {**payload, "model": model}
    request = urllib.request.Request(
        url,
        data=json.dumps(request_payload).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )
    return open_ai_request(request, timeout)


def capability_probe_candidates(provider: str, base_url: str) -> list[tuple[str, str]]:
    candidates = [
        ("responses", "json_schema"),
        ("chat_completions", "json_schema"),
        ("chat_completions", "json_object"),
    ]
    if infer_ai_provider(provider, base_url) == "deepseek" or official_ai_host(base_url, "api.deepseek.com"):
        return [candidates[2], candidates[1], candidates[0]]
    return candidates


def probe_ai_capability(
    api_key: str,
    model: str,
    base_url: str,
    provider: str,
    timeout: int = 12,
    *,
    persist_result: bool = True,
) -> dict[str, str]:
    schema = {
        "type": "object",
        "additionalProperties": False,
        "properties": {"ok": {"type": "boolean"}},
        "required": ["ok"],
    }
    payload = {
        "model": model,
        "input": "Return only valid JSON matching the schema, exactly as {\"ok\": true}.",
        "max_output_tokens": 256,
        "text": {"format": {"type": "json_schema", "name": "capability_probe", "schema": schema, "strict": True}},
    }
    last_error: Exception | None = None
    for api_protocol, structured_output_mode in capability_probe_candidates(provider, base_url):
        for content_attempt in range(2):
            try:
                body = call_ai_protocol(
                    api_key,
                    model,
                    base_url,
                    payload,
                    api_protocol=api_protocol,
                    structured_output_mode=structured_output_mode,
                    timeout=timeout,
                )
                raw_text = parse_openai_text_response(body).strip()
                parsed = json.loads(raw_text)
                if not isinstance(parsed, dict) or parsed.get("ok") is not True or not isinstance(parsed.get("ok"), bool):
                    raise AIRequestError("AI 结构化输出探针未返回预期 JSON 对象")
                capability = {
                    "api_protocol": api_protocol,
                    "structured_output_mode": structured_output_mode,
                    "capability_verified_at": now_iso(),
                }
                if persist_result:
                    persist_ai_capability(provider, model, base_url, capability)
                return capability
            except (json.JSONDecodeError, TypeError):
                last_error = AIRequestError("AI 结构化输出探针返回内容不是有效 JSON")
                if content_attempt == 0:
                    continue
                raise last_error
            except AIRequestError as exc:
                last_error = exc
                if exc.compatibility_error:
                    break
                if exc.status_code is None and content_attempt == 0:
                    continue
                raise
    if last_error:
        raise last_error
    raise AIRequestError("未找到兼容的 AI 结构化输出接口", compatibility_error=True)


def resolve_ai_capability(api_key: str, model: str, base_url: str, provider: str, *, probe_unknown: bool = True) -> dict[str, str]:
    capability = stored_ai_capability(provider, model, base_url)
    if capability.get("api_protocol"):
        return capability
    default = default_ai_capability(provider, base_url)
    if default.get("api_protocol"):
        return default
    if not probe_unknown:
        return {"api_protocol": "responses", "structured_output_mode": "json_schema", "capability_verified_at": ""}
    return probe_ai_capability(api_key, model, base_url, provider)


def call_openai_chat_completions(api_key: str, model: str, base_url: str, payload: dict[str, Any], timeout: int = 6) -> dict[str, Any]:
    return call_ai_protocol(
        api_key,
        model,
        base_url,
        payload,
        api_protocol="chat_completions",
        structured_output_mode="json_object",
        timeout=timeout,
    )


def call_openai_responses(api_key: str, model: str, base_url: str, payload: dict[str, Any], timeout: int = 6, provider: str = "") -> dict[str, Any]:
    resolved_provider = infer_ai_provider(provider, base_url)
    capability = resolve_ai_capability(
        api_key,
        model,
        base_url,
        resolved_provider,
        probe_unknown=bool(structured_format_from_payload(payload)),
    )
    operation = ai_operation_from_payload(payload)
    started = time.monotonic()
    log_event(
        logging.INFO,
        "ai_call_started",
        component="ai",
        provider=resolved_provider,
        model=model,
        operation=operation,
        base_url=base_url,
        timeout_seconds=timeout,
        api_protocol=capability["api_protocol"],
        structured_output_mode=capability["structured_output_mode"],
        stream=False,
    )
    try:
        try:
            body = call_ai_protocol(
                api_key,
                model,
                base_url,
                payload,
                api_protocol=capability["api_protocol"],
                structured_output_mode=capability["structured_output_mode"],
                timeout=timeout,
            )
        except AIRequestError as exc:
            if not exc.compatibility_error:
                raise
            clear_ai_capability(resolved_provider, model, base_url)
            capability = probe_ai_capability(api_key, model, base_url, resolved_provider, timeout=min(timeout, 12))
            body = call_ai_protocol(
                api_key,
                model,
                base_url,
                payload,
                api_protocol=capability["api_protocol"],
                structured_output_mode=capability["structured_output_mode"],
                timeout=timeout,
            )
    except Exception:
        log_event(
            logging.ERROR,
            "ai_call_failed",
            component="ai",
            exc_info=True,
            provider=resolved_provider,
            model=model,
            operation=operation,
            base_url=base_url,
            elapsed_ms=int((time.monotonic() - started) * 1000),
            stream=False,
        )
        raise
    log_event(
        logging.INFO,
        "ai_call_completed",
        component="ai",
        provider=resolved_provider,
        model=model,
        operation=operation,
        elapsed_ms=int((time.monotonic() - started) * 1000),
        output_length=len(parse_openai_text_response(body)),
        stream=False,
    )
    return body


def extract_openai_stream_delta(event: dict[str, Any]) -> str:
    if event.get("choices"):
        chunks: list[str] = []
        for choice in event.get("choices", []):
            delta = choice.get("delta") or {}
            if delta.get("content"):
                chunks.append(str(delta["content"]))
            elif choice.get("message", {}).get("content"):
                chunks.append(str(choice["message"]["content"]))
        if chunks:
            return "".join(chunks)
    event_type = str(event.get("type") or "")
    if event_type in {"response.output_text.delta", "response.refusal.delta"}:
        return str(event.get("delta") or "")
    if event_type in {"response.text.delta", "output_text.delta", "text.delta"}:
        return str(event.get("delta") or event.get("text") or "")
    if event_type == "response.output_item.done":
        item = event.get("item") or {}
        text_chunks: list[str] = []
        for content in item.get("content", []):
            if content.get("type") in {"output_text", "text"} and content.get("text"):
                text_chunks.append(content["text"])
        return "\n".join(text_chunks)
    return ""


def iter_openai_sse_events(response: Any) -> Iterator[dict[str, Any]]:
    def decode_event(lines: list[str]) -> tuple[dict[str, Any] | None, bool]:
        data_lines = [item[5:].strip() for item in lines if item.startswith("data:")]
        if not data_lines:
            return None, False
        data = "\n".join(data_lines)
        if data == "[DONE]":
            return None, True
        try:
            event = json.loads(data)
        except json.JSONDecodeError:
            return None, False
        return (event if isinstance(event, dict) else None), False

    event_lines: list[str] = []
    while True:
        raw = response.readline()
        if not raw:
            event, done = decode_event(event_lines)
            if event is not None:
                yield event
            break
        line = raw.decode("utf-8", errors="replace").rstrip("\r\n")
        if line:
            event_lines.append(line)
            continue
        event, done = decode_event(event_lines)
        event_lines = []
        if done:
            break
        if event is not None:
            yield event


def iter_openai_stream_deltas(
    api_key: str,
    model: str,
    base_url: str,
    payload: dict[str, Any],
    timeout: int = 60,
    provider: str = "",
) -> Iterator[str]:
    resolved_provider = infer_ai_provider(provider, base_url)
    capability = resolve_ai_capability(
        api_key,
        model,
        base_url,
        resolved_provider,
        probe_unknown=bool(structured_format_from_payload(payload)),
    )
    operation = ai_operation_from_payload(payload)
    started = time.monotonic()
    output_length = 0
    log_event(
        logging.INFO,
        "ai_call_started",
        component="ai",
        provider=resolved_provider,
        model=model,
        operation=operation,
        base_url=base_url,
        timeout_seconds=timeout,
        api_protocol=capability["api_protocol"],
        structured_output_mode=capability["structured_output_mode"],
        stream=True,
    )
    emitted_output = False
    try:
        for protocol_attempt in range(2):
            is_chat_completions = capability["api_protocol"] == "chat_completions"
            if is_chat_completions:
                url = build_chat_completions_url(base_url)
                request_payload = chat_payload_from_responses_payload(
                    model,
                    payload,
                    stream=True,
                    structured_output_mode=capability["structured_output_mode"],
                )
            else:
                url = build_openai_url("/responses", base_url)
                request_payload = {**payload, "model": model, "stream": True}
            request = urllib.request.Request(
                url,
                data=json.dumps(request_payload).encode("utf-8"),
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "Content-Type": "application/json",
                    "Accept": "text/event-stream",
                },
                method="POST",
            )
            hostname = urllib.parse.urlparse(url).hostname or ""
            opener = urllib.request.build_opener(urllib.request.ProxyHandler({})) if hostname in {"localhost", "127.0.0.1", "::1"} else urllib.request.build_opener()
            try:
                with opener.open(request, timeout=timeout) as response:
                    for event in iter_openai_sse_events(response):
                        delta = extract_openai_stream_delta(event)
                        if not delta:
                            continue
                        if not is_chat_completions and event.get("type") == "response.output_item.done" and emitted_output:
                            continue
                        emitted_output = True
                        output_length += len(delta)
                        yield delta
                break
            except urllib.error.HTTPError as exc:
                request_error = ai_http_error(exc)
                if emitted_output or protocol_attempt or not request_error.compatibility_error:
                    raise request_error from exc
                clear_ai_capability(resolved_provider, model, base_url)
                capability = probe_ai_capability(api_key, model, base_url, resolved_provider, timeout=min(timeout, 12))
    except Exception:
        log_event(
            logging.ERROR,
            "ai_call_failed",
            component="ai",
            exc_info=True,
            provider=resolved_provider,
            model=model,
            operation=operation,
            base_url=base_url,
            elapsed_ms=int((time.monotonic() - started) * 1000),
            stream=True,
        )
        raise
    log_event(
        logging.INFO,
        "ai_call_completed",
        component="ai",
        provider=resolved_provider,
        model=model,
        operation=operation,
        elapsed_ms=int((time.monotonic() - started) * 1000),
        output_length=output_length,
        stream=True,
    )


def call_openai_responses_stream(
    api_key: str,
    model: str,
    base_url: str,
    payload: dict[str, Any],
    artifact_id: str,
    timeout: int = 24,
    provider: str = "",
) -> str:
    chunks: list[str] = []
    for delta in iter_openai_stream_deltas(api_key, model, base_url, payload, timeout=timeout, provider=provider):
        chunks.append(delta)
        if artifact_id:
            append_flow_artifact_content(artifact_id, delta)
    return "".join(chunks).strip()


def call_openai_chat_completions_stream(
    api_key: str,
    model: str,
    base_url: str,
    payload: dict[str, Any],
    artifact_id: str,
    timeout: int = 24,
) -> str:
    chunks: list[str] = []
    for delta in iter_openai_stream_deltas(api_key, model, base_url, payload, timeout=timeout, provider="deepseek"):
        chunks.append(delta)
        append_flow_artifact_content(artifact_id, delta)
    return "".join(chunks).strip()


