SENSITIVE_LOG_PATTERNS = [
    re.compile(r"(?i)(bearer\s+)[a-z0-9._~+/=-]+"),
    re.compile(r"(?i)\b(authorization|cookie|set-cookie|token|access[_-]?token|refresh[_-]?token|api[_-]?key|password|passwd|pwd|secret)\b\s*([:：=]\s*|\s+)([^\s,;，；]+)"),
    re.compile(r"(密码|口令|令牌|密钥)\s*(?:为|是|[:：=])?\s*([^\s,;，；。]+)"),
    re.compile(r"(?i)([?&](?:token|access_token|refresh_token|api_key|password|passwd|pwd|secret)=)[^&#\s]+"),
]


def redact_sensitive_log_text(value: Any) -> str:
    text = str(value or "")
    text = SENSITIVE_LOG_PATTERNS[0].sub(r"\1***", text)
    text = SENSITIVE_LOG_PATTERNS[1].sub(lambda match: f"{match.group(1)}{match.group(2)}***", text)
    text = SENSITIVE_LOG_PATTERNS[2].sub(lambda match: f"{match.group(1)}：***", text)
    return SENSITIVE_LOG_PATTERNS[3].sub(r"\1***", text)


def sanitize_flow_log_details(value: Any) -> Any:
    if isinstance(value, dict):
        sanitized: dict[str, Any] = {}
        for key, item in value.items():
            normalized_key = str(key)
            if re.search(r"(?i)(authorization|cookie|token|api[_-]?key|password|passwd|pwd|secret)", normalized_key):
                sanitized[normalized_key] = "***"
            else:
                sanitized[normalized_key] = sanitize_flow_log_details(item)
        return sanitized
    if isinstance(value, list):
        return [sanitize_flow_log_details(item) for item in value]
    if isinstance(value, tuple):
        return [sanitize_flow_log_details(item) for item in value]
    if isinstance(value, str):
        return redact_sensitive_log_text(value)
    return value


def automation_flow_log_payload(row: sqlite3.Row) -> dict[str, Any]:
    details: Any = {}
    if "details_json" in row.keys() and row["details_json"]:
        with contextlib.suppress(json.JSONDecodeError, TypeError):
            details = json.loads(row["details_json"])
    return {
        "id": row["id"],
        "createdAt": row["created_at"],
        "stage": row["stage"],
        "level": row["level"],
        "message": redact_sensitive_log_text(row["message"]),
        "evidenceType": row["evidence_type"],
        "evidencePath": redact_sensitive_log_text(row["evidence_path"]),
        "linkedRunId": row["linked_run_id"],
        "stepKey": (row["step_key"] or "") if "step_key" in row.keys() else "",
        "stepLabel": (row["step_label"] or "") if "step_label" in row.keys() else "",
        "stepStatus": (row["step_status"] or "") if "step_status" in row.keys() else "",
        "durationMs": row["duration_ms"] if "duration_ms" in row.keys() else None,
        "details": sanitize_flow_log_details(details),
    }


def automation_flow_log_row(flow_run_id: str, log_id: int) -> dict[str, Any] | None:
    with get_db() as conn:
        row = conn.execute(
            "SELECT * FROM automation_flow_logs WHERE flow_run_id = ? AND id = ?",
            (flow_run_id, log_id),
        ).fetchone()
    if row is None:
        return None
    return automation_flow_log_payload(row)


def write_automation_flow_log(
    flow_run_id: str,
    stage: str,
    level: str,
    message: str,
    evidence_type: str = "",
    evidence_path: str = "",
    linked_run_id: str = "",
    *,
    step_key: str = "",
    step_label: str = "",
    step_status: str = "",
    duration_ms: int | None = None,
    details: dict[str, Any] | None = None,
) -> None:
    log_id = 0
    safe_message = redact_sensitive_log_text(message)
    safe_evidence_path = redact_sensitive_log_text(evidence_path)
    safe_details = sanitize_flow_log_details(details or {})
    with get_db() as conn:
        cursor = conn.execute(
            """
            INSERT INTO automation_flow_logs (
                flow_run_id, created_at, stage, level, message,
                evidence_type, evidence_path, linked_run_id, step_key,
                step_label, step_status, duration_ms, details_json
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                flow_run_id,
                now_iso(),
                stage,
                level,
                safe_message,
                evidence_type,
                safe_evidence_path,
                linked_run_id,
                step_key,
                step_label,
                step_status,
                duration_ms,
                json.dumps(safe_details, ensure_ascii=False) if safe_details else "",
            ),
        )
        log_id = cursor.lastrowid
    log = automation_flow_log_row(flow_run_id, log_id)
    if log:
        schedule_automation_flow_event(flow_run_id, {"type": "log", "flowRunId": flow_run_id, "log": log})


