PLAYWRIGHT_FLOW_STEP_PATTERN = re.compile(r"\[(步骤开始|步骤通过|步骤失败)\]\s*(.+)")


def parse_playwright_flow_step(line: str) -> dict[str, str] | None:
    match = PLAYWRIGHT_FLOW_STEP_PATTERN.search(line)
    if not match:
        return None
    marker, content = match.groups()
    status_map = {"步骤开始": "started", "步骤通过": "passed", "步骤失败": "failed"}
    level_map = {"步骤开始": "info", "步骤通过": "success", "步骤失败": "error"}
    label = content.strip()
    detail = ""
    if marker == "步骤失败":
        if label.startswith("测试用例:") and "，状态" in label:
            label, detail = label.split("，状态", maxsplit=1)
            detail = f"状态{detail.strip()}"
        else:
            parts = re.split(r"[:：]\s+", label, maxsplit=1)
            label = parts[0].strip()
            detail = parts[1].strip() if len(parts) > 1 else ""
    return {
        "stepStatus": status_map[marker],
        "level": level_map[marker],
        "stepLabel": label,
        "message": detail or f"{marker}：{label}",
    }


def duplicate_playwright_flow_step(
    previous_marker: tuple[str, str] | None,
    previous_at: float,
    step_event: dict[str, str],
    current_at: float,
) -> bool:
    marker = (step_event["stepLabel"], step_event["stepStatus"])
    return marker == previous_marker and current_at - previous_at <= 0.1


