def create_flow_artifact(
    flow_run_id: str,
    work_item_id: str,
    stage: str,
    artifact_type: str,
    title: str,
    content: str = "",
    status: str = "streaming",
    source: str = "system",
    path: str = "",
    metadata: dict[str, Any] | None = None,
) -> str:
    artifact_id = uuid.uuid4().hex[:12]
    timestamp = now_iso()
    with get_db() as conn:
        conn.execute(
            """
            INSERT INTO automation_flow_artifacts (
                id, flow_run_id, work_item_id, stage, artifact_type, title,
                content, status, source, path, metadata_json, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                artifact_id,
                flow_run_id,
                work_item_id,
                stage,
                artifact_type,
                title,
                content,
                status,
                source,
                path,
                json.dumps(metadata or {}, ensure_ascii=False),
                timestamp,
                timestamp,
            ),
        )
    artifact = flow_artifact_by_id(artifact_id)
    if artifact:
        schedule_automation_flow_event(flow_run_id, {"type": "artifact_created", "flowRunId": flow_run_id, "artifact": artifact})
    return artifact_id


def update_flow_artifact(artifact_id: str, **fields: Any) -> None:
    if not fields:
        return
    if "metadata" in fields:
        fields["metadata_json"] = json.dumps(fields.pop("metadata") or {}, ensure_ascii=False)
    fields["updated_at"] = now_iso()
    keys = ", ".join(f"{key} = ?" for key in fields)
    with get_db() as conn:
        conn.execute(f"UPDATE automation_flow_artifacts SET {keys} WHERE id = ?", [*fields.values(), artifact_id])
    artifact = flow_artifact_by_id(artifact_id)
    if artifact:
        schedule_automation_flow_event(
            artifact["flowRunId"],
            {"type": "artifact_updated", "flowRunId": artifact["flowRunId"], "artifact": artifact},
        )


def append_flow_artifact_content(artifact_id: str, delta: str) -> None:
    if not delta:
        return
    flow_run_id = ""
    with get_db() as conn:
        conn.execute(
            """
            UPDATE automation_flow_artifacts
            SET content = COALESCE(content, '') || ?,
                updated_at = ?
            WHERE id = ?
            """,
            (delta, now_iso(), artifact_id),
        )
        row = conn.execute("SELECT flow_run_id FROM automation_flow_artifacts WHERE id = ?", (artifact_id,)).fetchone()
        flow_run_id = row["flow_run_id"] if row is not None else ""
    if flow_run_id:
        schedule_automation_flow_event(
            flow_run_id,
            {"type": "artifact_delta", "flowRunId": flow_run_id, "artifactId": artifact_id, "delta": delta},
        )


def format_requirement_analysis_artifact(item: sqlite3.Row, analysis: dict[str, Any]) -> str:
    missing = analysis.get("missing") or []
    missing_text = "、".join(str(value) for value in missing) if missing else "无"
    source = "AI 自动提取" if analysis.get("source") == "ai" else "规则兜底提取"
    return f"""## 需求结构化结果

- 来源：{source}
- 标题：{item['title']}
- 功能目标：{analysis.get('goal', item['requirement'])}
- 用户路径：{analysis.get('userPath', item['requirement'])}
- 验收标准：{analysis.get('acceptance', item['acceptance'] or '未提供')}
- 角色：{analysis.get('role', item['role'] or '未提供')}
- 测试数据：{analysis.get('testData', item['test_data'] or '未提供')}
- 环境/目标 URL：{analysis.get('environment', item['target_url'] or '未提供')}
- 排除项：{analysis.get('exclusions', item['exclusions'] or '未提供')}
- 仍需澄清：{missing_text}
"""


def format_data_context_artifact(resolution: dict[str, Any], data_context: dict[str, Any]) -> str:
    sources = data_context.get("sources") or []
    datasets = data_context.get("datasets") or []
    lines = [
        "## 测试数据上下文",
        "",
        f"- 数据需求：{resolution.get('label') or resolution.get('category') or '-'}",
        f"- 解析状态：{resolution.get('status') or '-'}",
        f"- 数据来源：{resolution.get('source') or '-'}",
        f"- 访问方式：{data_context.get('accessMode') or 'unknown'}",
        f"- 解析说明：{resolution.get('reason') or '-'}",
        f"- 页面标题：{(data_context.get('page') or {}).get('title') or '-'}",
        f"- 证据来源：{len(sources)} 个",
        f"- 可用数据集：{len(datasets)} 个",
        "",
    ]
    missing_fields = resolution.get("missingFields") or []
    if missing_fields:
        lines.extend([
            f"- 缺少凭据：{'、'.join(credential_field_label(field) for field in missing_fields)}",
            f"- 需要操作：{resolution.get('actionRequired') or '补充登录凭据后重新运行'}",
            "- 未执行范围：登录及其后的业务场景",
            "",
        ])
    invalid_fields = resolution.get("invalidFields") or []
    if invalid_fields:
        lines.extend([
            f"- 无效凭据：{'、'.join(credential_field_label(field) for field in invalid_fields)}",
            f"- 需要操作：{resolution.get('actionRequired') or '修正登录凭据后重新运行'}",
            "- 未执行范围：登录及其后的业务场景",
            "",
        ])
    if datasets:
        lines.extend(["| 数据集 | 状态 | 记录数 | 字段 |", "| --- | --- | ---: | --- |"]) 
        for dataset in datasets:
            lines.append(
                f"| {str(dataset.get('name') or '-').replace('|', '\\|')} | "
                f"{dataset.get('status') or '-'} | {dataset.get('itemCount') or 0} | "
                f"{', '.join(dataset.get('fields') or []) or '-'} |"
            )
        lines.append("")
    hints = data_context.get("assertionHints") or []
    if hints:
        lines.append("### 可用断言依据")
        lines.extend(f"- {hint}" for hint in hints)
        lines.append("")
    if resolution.get("requiresProvisioning"):
        provisioning = data_context.get("provisioning") if isinstance(data_context.get("provisioning"), dict) else {}
        lines.extend([
            "### 数据准备限制",
            "- 当前未配置可执行任意站点写入的测试数据 Provider。",
            "- 只生成带唯一标记的数据准备建议，不会自动调用页面发现到的写接口。",
            f"- 目标环境：{provisioning.get('targetOrigin') or '-'}",
            f"- 唯一标记：`{provisioning.get('marker') or '-'}`",
            f"- Provider 状态：{provisioning.get('status') or 'provider-unavailable'}",
            f"- 清理规则：{provisioning.get('cleanupPolicy') or '-'}",
        ])
    if data_context.get("preflightError"):
        lines.append(f"- 预探索警告：{data_context['preflightError']}")
    return "\n".join(lines).strip() + "\n"


def format_exploration_plan_artifact(plan: list[dict[str, Any]]) -> str:
    lines = ["| 关联用例 | 状态路径 | 步骤 | 动作 | 交互目标 | 说明 |", "| --- | --- | --- | --- | --- | --- |"]
    for step in plan:
        target_meta = step.get("targetMeta") if isinstance(step.get("targetMeta"), dict) else {}
        aliases = " / ".join(str(value) for value in target_meta.get("aliases", []) if value)
        semantic_target = str(target_meta.get("name") or step.get("target") or "")
        if aliases:
            semantic_target = f"{semantic_target}（{aliases}）"
        lines.append(
            "| {case_id} | {scenario} | {step_index} | {action} | {target} | {description} |".format(
                case_id=", ".join(step.get("caseIds") or [step.get("caseId") or "legacy"]).replace("|", "\\|"),
                scenario=str(step.get("journeyId") or int(step.get("scenarioIndex", 0)) + 1).replace("|", "\\|"),
                step_index=int(step.get("scenarioStepIndex", step.get("index", 0))) + 1,
                action=str(step.get("action", "")),
                target=semantic_target.replace("|", "\\|"),
                description=str(step.get("description", "")).replace("|", "\\|"),
            )
        )
    return "\n".join(lines)


def format_exploration_result_artifact(exploration_payload: dict[str, Any]) -> str:
    result = exploration_payload.get("result") or {}
    steps = exploration_payload.get("steps") or []
    lines = [
        "## 探索执行结果",
        "",
        f"- 状态：{exploration_payload.get('status', '-')}",
        f"- 截图路径：{result.get('screenshot_path') or exploration_payload.get('screenshotPath') or '-'}",
        f"- 候选元素：{len(result.get('elements') or [])} 个",
        f"- 必需控件覆盖：{(result.get('targetCoverage') or {}).get('covered', 0)}/{(result.get('targetCoverage') or {}).get('total', 0)}（{(result.get('targetCoverage') or {}).get('percent', 0)}%）",
        f"- 浏览器会话：{result.get('browser_session_id') or exploration_payload.get('browserSessionId') or '-'}",
    ]
    root_cause = result.get("rootCause") if isinstance(result.get("rootCause"), dict) else {}
    if root_cause:
        lines.extend([
            f"- 根因分类：{root_cause.get('code') or '-'}",
            f"- 根因说明：{root_cause.get('message') or '-'}",
        ])
    lines.extend([
        "",
        "| 用例 | 场景/步骤 | 动作 | 执行状态 | URL 变化 | 截图 | 错误 |",
        "| --- | --- | --- | --- | --- | --- | --- |",
    ])
    for step in steps:
        before = step.get("urlBefore") or "-"
        after = step.get("urlAfter") or "-"
        url_change = before if before == after else f"{before} -> {after}"
        lines.append(
            "| {case_id} | {scenario}/{step_index} | {action} | {status} | {url_change} | {screenshot} | {error} |".format(
                case_id=str(step.get("caseId") or "legacy").replace("|", "\\|"),
                scenario=int(step.get("scenarioIndex", 0)) + 1,
                step_index=int(step.get("scenarioStepIndex", step.get("stepIndex", 0))) + 1,
                action=str(step.get("action", "")),
                status=str(step.get("status", "")),
                url_change=str(url_change).replace("|", "\\|"),
                screenshot=str(step.get("screenshotPath") or "-").replace("|", "\\|"),
                error=str(step.get("error") or "-").replace("|", "\\|"),
            )
        )
    structure = result.get("page_structure") or ""
    if structure:
        lines.extend(["", "## 页面结构摘要", "", structure])
    if result.get("missingTargets"):
        lines.extend(["", "## 缺失交互控件", ""])
        for target in result["missingTargets"]:
            lines.append(f"- {target.get('name') or target.get('targetId')}：{', '.join(target.get('caseIds') or [])}")
    if result.get("behaviorFindings"):
        lines.extend(["", "## 业务行为差异", ""])
        for finding in result["behaviorFindings"]:
            lines.append(
                f"- {finding.get('priority') or 'P1'} · {finding.get('caseId') or '-'} · "
                f"{finding.get('target') or finding.get('action') or '交互'}：{finding.get('message') or '实际行为与需求预期不符'}；"
                f"实际 URL：`{finding.get('actualUrl') or '-'}`"
            )
    return "\n".join(lines)


def format_confirmed_elements_artifact(elements: list[dict[str, Any]], confirmed_count: int) -> str:
    lines = [
        f"## 已确认 selector：{confirmed_count} 个",
        "",
        "| # | 状态 | 元素 | Locator | 关联用例 | 备用 Locator | 来源 |",
        "| --- | --- | --- | --- | --- | --- | --- |",
    ]
    confirmed = [element for element in elements if element.get("confirmed")]
    for index, element in enumerate(confirmed, start=1):
        locator_type = element.get("locatorType") or element.get("locator_type")
        locator_role = element.get("locatorRole") or element.get("locator_role")
        locator = f"{locator_type}{f'({locator_role})' if locator_role else ''}={element.get('locatorValue') or element.get('locator_value')}"
        lines.append(
            "| {index} | {state} | {name} | {locator} | {cases} | {fallbacks} | {source} |".format(
                index=index,
                state=str(element.get("stateKey") or element.get("state_key") or element.get("area", "")).replace("|", "\\|"),
                name=str(element.get("name", "")).replace("|", "\\|"),
                locator=str(locator).replace("|", "\\|"),
                cases=", ".join(element.get("caseIds") or element.get("case_ids") or []).replace("|", "\\|"),
                fallbacks=json.dumps(element.get("fallbacks") or [], ensure_ascii=False).replace("|", "\\|"),
                source=str(element.get("source", "")).replace("|", "\\|"),
            )
        )
    if not confirmed:
        lines.append("| - | - | - | 未自动确认高置信 selector | - | - | 需要人工确认元素后再生成最终脚本 |")
    return "\n".join(lines)


def format_run_summary_artifact(run: sqlite3.Row, command: str = "") -> str:
    status = run["status"] if run is not None else "未运行"
    exit_code = run["exit_code"] if run is not None else "无"
    spec = run["spec"] if run is not None else "-"
    report = run["report_path"] if run is not None else str(REPORT_INDEX)
    screenshot = run["screenshot_path"] if run is not None else str(SCREENSHOT_PATH)
    command_text = command or (f"npx playwright test {spec} --project=chromium --reporter=list,html" if spec != "-" else "-")
    failure = "无" if status == "passed" else "详见 Playwright HTML report、运行日志、截图/trace/video 证据"
    return f"""## Playwright 运行验证

- 执行命令：`{command_text}`
- Spec 路径：`{spec}`
- 状态：{status}
- 退出码：{exit_code}
- 失败摘要：{failure}
- HTML report：`{report or REPORT_INDEX}`
- 截图/预览：`{screenshot or SCREENSHOT_PATH}`
"""


