def failure_script_versions_for_run(conn: sqlite3.Connection, run_id: str) -> list[sqlite3.Row]:
    rows = conn.execute(
        """
        SELECT v.*
        FROM run_script_versions rv
        JOIN test_script_versions v ON v.id = rv.script_version_id
        WHERE rv.run_id = ?
        ORDER BY rv.created_at ASC
        """,
        (run_id,),
    ).fetchall()
    if not rows:
        run = conn.execute("SELECT script_version_id FROM runs WHERE id = ?", (run_id,)).fetchone()
        if run is not None and run["script_version_id"]:
            row = conn.execute("SELECT * FROM test_script_versions WHERE id = ?", (run["script_version_id"],)).fetchone()
            return [row] if row is not None else []
        return []

    persisted_failed_rows = conn.execute(
        """
        SELECT v.*
        FROM run_script_versions rv
        JOIN test_script_versions v ON v.id = rv.script_version_id
        WHERE rv.run_id = ? AND rv.result_status = 'failed'
        ORDER BY rv.created_at ASC
        """,
        (run_id,),
    ).fetchall()
    if persisted_failed_rows:
        return persisted_failed_rows

    failure_log = run_log_text(run_id)
    failed_rows = [
        row
        for row in rows
        if row["status"] == "failed" and row["verified_run_id"] == run_id
    ]
    if failed_rows:
        return failed_rows

    candidates = rows
    failure_lines = []
    for raw_line in failure_log.splitlines():
        line = re.sub(r"\x1b\[[0-9;]*m", "", raw_line)
        if "已归档本轮执行 spec 快照" in line or "执行命令:" in line:
            continue
        if "✘" in line or "×" in line or re.search(r"(?:^|\]\s+)\d+\)\s+\[[^]]+\]\s+›", line) or re.search(r"\bat\s+\S+\.spec\.ts:\d+", line):
            failure_lines.append(line)

    matched_rows: list[sqlite3.Row] = []
    matched_ids: set[str] = set()
    for line in failure_lines:
        for row in candidates:
            filename = Path(row["spec_path"] or "").name
            if filename and filename in line and row["id"] not in matched_ids:
                matched_rows.append(row)
                matched_ids.add(row["id"])

    if matched_rows:
        return matched_rows
    run_row = conn.execute(
        "SELECT status, failure_category FROM runs WHERE id = ?",
        (run_id,),
    ).fetchone()
    if run_row is not None and str(run_row["failure_category"] or "") == "script-structure":
        return rows
    if len(rows) == 1:
        return rows
    return []


def failure_script_version_for_run(conn: sqlite3.Connection, run_id: str) -> sqlite3.Row | None:
    rows = failure_script_versions_for_run(conn, run_id)
    return rows[0] if len(rows) == 1 else None


EXPLORATION_ACTIONS = {"navigate", "fill", "click", "select", "locate", "snapshot"}
EXPLORATION_TARGET_KINDS = {
    "textbox", "password", "button", "link", "checkbox", "radio", "combobox",
    "option", "switch", "tab", "menuitem", "selector",
}
EXPLORATION_DANGEROUS_TERMS = {
    "删除", "支付", "付款", "下单", "提交订单", "生产提交", "发布", "delete", "pay",
    "purchase", "place order", "finish order", "publish", "remove",
}
EXPLORATION_IRREVERSIBLE_PATTERN = re.compile(
    r"(?:删除|移除|支付|付款|下单|提交订单|确认发布|提交发布|立即发布|"
    r"delete|remove|pay|purchase|place\s+order|confirm\s+publish|submit\s+publish)",
    re.IGNORECASE,
)
EXPLORATION_PLANNER_VERSION = 10
EXPLORATION_MAX_EXPANDED_STATES = 5
EXPLORATION_PRIORITY_RANK = {"P0": 0, "P1": 1, "P2": 2}
EXPLORATION_SAFE_NAVIGATION_PATTERN = re.compile(
    r"(?:入口|页面|详情|查看|打开|进入|跳转|导航|link|page|detail|view|open|go\s+to)",
    re.IGNORECASE,
)
EXPLORATION_COMMIT_ACTION_PATTERN = re.compile(
    r"(?:确认|立即|提交|完成|执行|确定|保存|创建|confirm|submit|complete|execute|save|create)",
    re.IGNORECASE,
)
EXPLORATION_ABSTRACT_ASSERTIONS = {
    "系统可用页面", "登录后页面", "页面正常", "正常页面", "操作成功", "符合预期", "登录成功",
    "system usable page", "post-login page", "page works", "operation succeeded", "expected result",
}
EXPLORATION_LOGIN_ENTRY_PATTERN = re.compile(
    r"^(?:登录|用户登录|登录系统|立即登录|去登录|sign\s*in|log\s*in)$",
    re.IGNORECASE,
)
EXPLORATION_LOGIN_CONTROL_PATTERN = re.compile(
    r"(?:账号|用户名|username|account|密码|password|登录按钮|sign\s*in|log\s*in)",
    re.IGNORECASE,
)
EXPLORATION_NEGATIVE_LOGIN_PATTERN = re.compile(
    r"(?:不(?:需要|用|必)?登录|无需登录|免登录|不登录|未登录(?:状态|浏览器会话)?|"
    r"(?:不需要|无需).{0,8}(?:账号|用户名|密码|认证)|匿名(?:访问|访客|用户)?|游客(?:访问|访客|用户)?|"
    r"无登录(?:访问|拦截|要求|限制)|排除登录(?:/注册)?(?:流程|页面|页)?|"
    r"(?:不|未)(?:会)?跳转(?:到)?登录(?:/注册)?页(?:面)?|"
    r"without\s+(?:a\s+)?login|no\s+login|not\s+logged\s+in|logged\s+out)",
    re.IGNORECASE,
)
EXPLORATION_POSITIVE_LOGIN_PATTERN = re.compile(
    r"(?:验证登录|登录功能|登录页面|登录页|登录表单|登录成功|点击登录|提交登录|"
    r"填写(?:账号|用户名|密码)|输入(?:账号|用户名|密码)|账号|用户名|密码|username|account|password|pwd|"
    r"sign\s*in|log\s*in)",
    re.IGNORECASE,
)
EXPLORATION_SEARCH_INTENT_PATTERN = re.compile(r"(?:搜索|查询|检索|search)", re.IGNORECASE)
EXPLORATION_TRANSITION_INTENT_PATTERN = re.compile(
    r"(?:点击|进入|跳转|打开.+(?:页|菜单|入口)|输入|填写|选择|切换|搜索|查询|提交|登录成功|"
    r"click|open|navigate|enter|fill|select|switch|search|submit|sign\s*in|log\s*in)",
    re.IGNORECASE,
)
EXPLORATION_ACTIONABILITY_INTENT_PATTERN = re.compile(
    r"(?:可|可以|能够|能)(?:正常)?(?:点击|操作|使用)|(?:clickable|enabled|actionable)",
    re.IGNORECASE,
)
EXPLORATION_ABSTRACT_TARGET_PATTERN = re.compile(
    r"(?:查看|观察|确认|验证|记录).*(?:结果|状态|页面)|"
    r"(?:结果|页面|系统).*(?:正常|刷新|更新|成功|符合预期)|"
    r"(?:实际页面\s*DOM|以实际.*为准|控件需以)",
    re.IGNORECASE,
)


def exploration_case_value(case: sqlite3.Row | dict[str, Any], key: str) -> Any:
    if hasattr(case, "keys") and key in case.keys():
        return case[key]
    return case.get(key) if isinstance(case, dict) else ""


def exploration_case_source(case: sqlite3.Row | dict[str, Any]) -> str:
    return "\n".join(
        str(exploration_case_value(case, key) or "")
        for key in ("external_id", "title", "requirement", "preconditions", "steps", "expected", "automation_notes")
    )


def exploration_case_step_fragments(case: sqlite3.Row | dict[str, Any]) -> list[str]:
    text = html.unescape(str(exploration_case_value(case, "steps") or ""))
    text = re.sub(r"<br\s*/?>", "\n", text, flags=re.IGNORECASE)
    text = re.sub(r"</?(?:p|div|li|ul|ol)>\s*", "\n", text, flags=re.IGNORECASE)
    text = re.sub(r"<[^>]+>", " ", text)
    text = re.sub(r"\s+(?=\d+\s*[.、．)]\s*)", "\n", text)
    fragments = []
    for value in re.split(r"[\n；;]+", text):
        value = re.sub(r"^\s*(?:\d+\s*[.、．)]|[-*])\s*", "", value)
        value = re.sub(r"\s+", " ", value).strip()
        if value:
            fragments.append(value)
    return fragments


def sanitize_exploration_phrase(value: Any, *, max_length: int = 120) -> str:
    text = html.unescape(str(value or ""))
    text = re.sub(r"<br\s*/?>", "\n", text, flags=re.IGNORECASE)
    text = re.sub(r"</?(?:p|div|li|ul|ol)>\s*", "\n", text, flags=re.IGNORECASE)
    text = re.sub(r"<[^>]+>", " ", text)
    text = re.sub(r"\s+", " ", text).strip(" \t\r\n-'\"“”")
    return text[:max_length]


def exploration_target_quality_error(name: str) -> str:
    raw = str(name or "")
    clean = sanitize_exploration_phrase(raw, max_length=240)
    if not clean:
        return "目标名称为空"
    if re.search(r"<[^>]+>|&lt;|&gt;", raw, re.IGNORECASE):
        return "目标名称包含 HTML 标签"
    if len(clean) > 80:
        return "目标名称过长"
    if re.search(r"(?:^|\s)\d+\s*[.、．)]\s*", clean) or "\n" in raw or "\r" in raw:
        return "目标名称包含复合步骤"
    if EXPLORATION_ABSTRACT_TARGET_PATTERN.search(clean):
        return "目标名称是抽象结果描述"
    return ""


def exploration_case_requires_transition(case: sqlite3.Row | dict[str, Any]) -> bool:
    if exploration_case_is_actionability_only(case):
        return False
    source = "\n".join([
        str(exploration_case_value(case, "title") or ""),
        *exploration_case_step_fragments(case),
    ])
    source = EXPLORATION_ACTIONABILITY_INTENT_PATTERN.sub("", source)
    return bool(EXPLORATION_TRANSITION_INTENT_PATTERN.search(source))


def exploration_case_requires_interaction(case: sqlite3.Row | dict[str, Any]) -> bool:
    source = "\n".join(exploration_case_step_fragments(case))
    source = EXPLORATION_ACTIONABILITY_INTENT_PATTERN.sub("", source)
    if exploration_case_is_actionability_only(case):
        source = re.sub(
            r"(?:点击|单击|click)|(?:进入|打开).{0,24}(?:页面|页|网站|URL)",
            "",
            source,
            flags=re.IGNORECASE,
        )
    return bool(re.search(
        r"(?:点击|进入|输入|填写|选择|切换|搜索|查询|提交|登录成功|"
        r"click|enter|fill|select|switch|search|submit|sign\s*in|log\s*in)",
        source,
        re.IGNORECASE,
    ))


def exploration_case_required_actions(case: sqlite3.Row | dict[str, Any]) -> set[str]:
    source = "\n".join(exploration_case_step_fragments(case))
    source = EXPLORATION_ACTIONABILITY_INTENT_PATTERN.sub("", source)
    if exploration_case_is_actionability_only(case):
        source = re.sub(r"(?:点击|单击|click)", "", source, flags=re.IGNORECASE)
    required: set[str] = set()
    if re.search(r"(?:输入(?!框|区域)|填写|fill|type)", source, re.IGNORECASE):
        required.add("fill")
    if EXPLORATION_SEARCH_INTENT_PATTERN.search(source) and exploration_case_input_values(case):
        required.add("fill")
    if re.search(r"(?:选择(?!或输入)|切换|select|switch)", source, re.IGNORECASE):
        required.add("select")
    if re.search(r"(?:点击|提交|执行搜索|执行查询|登录成功|click|submit|sign\s*in|log\s*in)", source, re.IGNORECASE):
        required.add("click")
    return required


def exploration_step_is_dangerous(
    action: str,
    description: str,
    target: str,
    value: str,
    target_meta: dict[str, Any],
) -> bool:
    if action in {"navigate", "locate", "snapshot", "fill"}:
        return False
    safety = target_meta.get("safety") if isinstance(target_meta.get("safety"), dict) else {}
    safety_class = str(safety.get("class") or "").strip().lower()
    if safety_class == "irreversible":
        return True
    if safety_class in {"read-only", "same-origin-navigation", "reversible-state-change"}:
        return False
    kind = str(target_meta.get("kind") or "").strip().lower()
    if action == "click" and kind in {"link", "menuitem", "tab"} and safety.get("sameOrigin") is not False:
        return False
    target_text = f"{target_meta.get('name') or target} {value}".strip()
    return bool(EXPLORATION_IRREVERSIBLE_PATTERN.search(target_text))


def exploration_case_requires_actionability(case: sqlite3.Row | dict[str, Any]) -> bool:
    return bool(EXPLORATION_ACTIONABILITY_INTENT_PATTERN.search(exploration_case_source(case)))


def exploration_case_is_actionability_only(case: sqlite3.Row | dict[str, Any]) -> bool:
    if not exploration_case_requires_actionability(case):
        return False
    outcome_source = "\n".join(
        str(exploration_case_value(case, key) or "")
        for key in ("title", "requirement", "expected")
    )
    outcome_source = EXPLORATION_ACTIONABILITY_INTENT_PATTERN.sub("", outcome_source)
    return not bool(re.search(
        r"(?:点击|单击).{0,20}(?:后|进入|跳转|打开|展示|显示|更新|刷新|成功)|"
        r"(?:进入|跳转|打开).{0,20}(?:页面|详情|结果)|"
        r"(?:URL|地址).{0,12}(?:变化|包含)|"
        r"(?:click).{0,20}(?:navigate|open|show|display|update|refresh)",
        outcome_source,
        re.IGNORECASE,
    ))


def exploration_case_requires_link_href(case: sqlite3.Row | dict[str, Any]) -> bool:
    source = exploration_case_source(case)
    return exploration_case_requires_actionability(case) and bool(re.search(r"(?:链接|link)", source, re.IGNORECASE))


def exploration_case_input_values(case: sqlite3.Row | dict[str, Any]) -> list[str]:
    source = "\n".join([
        str(exploration_case_value(case, "preconditions") or ""),
        *exploration_case_step_fragments(case),
    ])
    values: list[str] = []
    patterns = [
        r"(?:技能|作者|标签|关键词|账号|用户名|密码)\s*[=:：]\s*([^；;，,。\n]{1,50})",
        r"(?:输入|填写)\s+([^；;，,。\n]{1,50}?)(?=\s*(?:并|后|然后|执行|点击|提交|$))",
        r"(?:按|为)\s*(?:技能|作者|标签)?\s*([^；;，,。\n]{1,40}?)\s*(?:搜索|查询)",
    ]
    for pattern in patterns:
        for match in re.finditer(pattern, source, re.IGNORECASE):
            value = sanitize_exploration_phrase(match.group(1), max_length=50).strip("'\"“”")
            if not value or re.fullmatch(r"(?:关键词|查询词|作者|标签|技能|账号|用户名|密码|条件)", value, re.IGNORECASE):
                continue
            if value not in values:
                values.append(value)
    return values[:6]


def normalize_exploration_expected(raw_expected: Any, action: str, value: str = "") -> dict[str, Any]:
    source = raw_expected if isinstance(raw_expected, dict) else {}
    expected: dict[str, Any] = {}
    for key in ("urlContains", "urlNotContains"):
        clean = sanitize_exploration_phrase(source.get(key), max_length=500)
        if clean:
            expected[key] = clean
    for key in ("textAny", "textAbsent"):
        values = source.get(key) if isinstance(source.get(key), list) else []
        cleaned = [sanitize_exploration_phrase(item, max_length=160) for item in values]
        cleaned = [item for item in cleaned if item and item not in EXPLORATION_ABSTRACT_ASSERTIONS]
        if cleaned:
            expected[key] = list(dict.fromkeys(cleaned))[:8]
    target_visible = source.get("targetVisible") if isinstance(source.get("targetVisible"), list) else []
    normalized_hints = []
    for hint in target_visible:
        if not isinstance(hint, dict):
            continue
        locator_type = str(hint.get("locatorType") or "").strip().lower()
        locator_value = sanitize_exploration_phrase(hint.get("locatorValue"), max_length=160)
        locator_role = str(hint.get("locatorRole") or "").strip().lower()
        if locator_type and locator_value:
            normalized_hints.append({
                "locatorType": locator_type,
                "locatorValue": locator_value,
                "locatorRole": locator_role,
            })
    if normalized_hints:
        expected["targetVisible"] = normalized_hints[:6]
    if bool(source.get("stateChanged")):
        expected["stateChanged"] = True
    behavior_policy = str(source.get("behaviorPolicy") or "").strip().lower()
    if behavior_policy in {"enforce", "record"}:
        expected["behaviorPolicy"] = behavior_policy
    if action == "fill":
        expected["valueEquals"] = str(source.get("valueEquals", value))
    elif "valueEquals" in source:
        expected["valueEquals"] = str(source.get("valueEquals") or "")
    return expected


def exploration_case_intent_source(case: dict[str, str]) -> str:
    return "\n".join([
        str(case.get("title") or ""),
        str(case.get("requirement") or ""),
        str(case.get("preconditions") or ""),
        *exploration_case_step_fragments(case),
    ])


def exploration_positive_login_source(value: str) -> str:
    return EXPLORATION_NEGATIVE_LOGIN_PATTERN.sub(" ", str(value or ""))


def exploration_case_requires_login(case: dict[str, str], item_requirement: str = "") -> bool:
    source = exploration_positive_login_source(
        "\n".join([str(item_requirement or ""), exploration_case_intent_source(case)])
    )
    return bool(EXPLORATION_POSITIVE_LOGIN_PATTERN.search(source))


def exploration_preflight_candidate_kind(candidate: dict[str, Any]) -> str:
    role = str(candidate.get("locatorRole") or "").strip().lower()
    tag = str(candidate.get("tag") or "").strip().lower()
    input_type = str(candidate.get("type") or "").strip().lower()
    if input_type == "password":
        return "password"
    if tag in {"input", "textarea"} or role == "textbox":
        return "textbox"
    if tag == "select":
        return "combobox"
    return role if role in EXPLORATION_TARGET_KINDS else ""


def exploration_candidate_locator_hints(candidate: dict[str, Any]) -> list[dict[str, str]]:
    hints: list[dict[str, str]] = []

    def add_hint(locator_type: Any, locator_value: Any, locator_role: Any = "") -> None:
        normalized_type = str(locator_type or "").strip().lower()
        normalized_value = str(locator_value or "").strip()
        normalized_role = str(locator_role or "").strip().lower()
        if not normalized_type or not normalized_value:
            return
        hint = {
            "locatorType": normalized_type,
            "locatorValue": normalized_value,
            "locatorRole": normalized_role,
        }
        if hint not in hints:
            hints.append(hint)

    for raw_hint in candidate.get("locatorHints") or []:
        if isinstance(raw_hint, dict):
            add_hint(raw_hint.get("locatorType"), raw_hint.get("locatorValue"), raw_hint.get("locatorRole"))
    add_hint(candidate.get("locatorType"), candidate.get("locatorValue"), candidate.get("locatorRole"))
    priority = {"testid": 0, "label": 1, "placeholder": 2, "css": 3, "role": 4, "selector": 5, "text": 6}
    return sorted(hints, key=lambda hint: priority.get(str(hint.get("locatorType") or "").lower(), 9))[:6]


def exploration_preflight_target_candidate(
    kind: str,
    name: str,
    aliases: list[str],
    preflight: dict[str, Any] | None,
) -> dict[str, Any] | None:
    expected_names = {str(value or "").strip().lower() for value in [name, *aliases] if str(value or "").strip()}
    if not expected_names:
        return None
    for candidate in (preflight or {}).get("elements") or []:
        if not isinstance(candidate, dict) or exploration_preflight_candidate_kind(candidate) != kind:
            continue
        candidate_names = {
            str(candidate.get(key) or "").strip().lower()
            for key in ("name", "locatorValue")
            if str(candidate.get(key) or "").strip()
        }
        if expected_names & candidate_names:
            return candidate
    return None


def exploration_preflight_candidate_case_ids(
    candidate: dict[str, Any],
    parsed_cases: list[dict[str, str]],
    item_requirement: str = "",
) -> list[str]:
    names = list(dict.fromkeys(
        str(candidate.get(key) or "").strip()
        for key in ("name", "locatorValue")
        if str(candidate.get(key) or "").strip()
    ))
    kind = exploration_preflight_candidate_kind(candidate)
    input_type = str(candidate.get("type") or "").strip().lower()
    is_login_entry = (
        kind in {"button", "link"}
        and any(EXPLORATION_LOGIN_ENTRY_PATTERN.fullmatch(name) for name in names)
    )
    candidate_text = " ".join(names)
    is_search_control = kind == "textbox" and (
        input_type == "search" or bool(EXPLORATION_SEARCH_INTENT_PATTERN.search(candidate_text))
    )
    matched_case_ids = []
    for case in parsed_cases:
        if is_login_entry:
            if exploration_case_requires_login(case, item_requirement):
                matched_case_ids.append(case["external_id"])
            continue
        source = exploration_positive_login_source(
            "\n".join([str(item_requirement or ""), exploration_case_intent_source(case)])
        )
        normalized_source = source.lower()
        directly_referenced = any(name.lower() in normalized_source for name in names)
        search_referenced = is_search_control and bool(EXPLORATION_SEARCH_INTENT_PATTERN.search(source))
        password_referenced = kind == "password" and bool(re.search(r"密码|password|pwd", source, re.IGNORECASE))
        if directly_referenced or search_referenced or password_referenced:
            matched_case_ids.append(case["external_id"])
    return matched_case_ids


def exploration_login_entry(preflight: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(preflight, dict):
        return None
    matches = []
    for candidate in preflight.get("elements") or []:
        if not isinstance(candidate, dict):
            continue
        role = str(candidate.get("locatorRole") or "").strip().lower()
        name = str(candidate.get("name") or candidate.get("locatorValue") or "").strip()
        if role not in {"link", "button"} or not EXPLORATION_LOGIN_ENTRY_PATTERN.fullmatch(name):
            continue
        matches.append(candidate)
    return matches[0] if len(matches) == 1 else None


def exploration_preflight_requires_entry(preflight: dict[str, Any] | None) -> bool:
    structure = preflight.get("structure") if isinstance(preflight, dict) else {}
    has_login_control = any(
        isinstance(candidate, dict)
        and (
            str(candidate.get("type") or "").strip().lower() == "password"
            or bool(re.search(
                r"(?:账号|用户名|username|account|密码|password)",
                " ".join([
                    str(candidate.get("name") or ""),
                    str(candidate.get("locatorValue") or ""),
                ]),
                re.IGNORECASE,
            ))
        )
        for candidate in ((preflight or {}).get("elements") or [])
    )
    return bool(
        exploration_login_entry(preflight)
        and not has_login_control
    )


def exploration_recovery_policy(preflight: dict[str, Any] | None) -> dict[str, Any]:
    entry = exploration_login_entry(preflight)
    if not entry:
        return {}
    return {
        "type": "unique_login_entry",
        "maxAttempts": 1,
        "entry": {
            "locatorType": "role",
            "locatorRole": str(entry.get("locatorRole") or "").strip().lower(),
            "locatorValue": str(entry.get("locatorValue") or entry.get("name") or "").strip(),
            "name": str(entry.get("name") or entry.get("locatorValue") or "").strip(),
        },
    }


def preflight_prompt_payload(preflight: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(preflight, dict):
        return {}
    structure = preflight.get("structure") if isinstance(preflight.get("structure"), dict) else {}
    elements = []
    for candidate in (preflight.get("elements") or [])[:40]:
        if not isinstance(candidate, dict):
            continue
        elements.append({
            "tag": str(candidate.get("tag") or "")[:24],
            "type": str(candidate.get("type") or "")[:24],
            "name": redact_sensitive_log_text(candidate.get("name") or "")[:120],
            "locatorType": str(candidate.get("locatorType") or "")[:32],
            "locatorValue": redact_sensitive_log_text(candidate.get("locatorValue") or "")[:120],
            "locatorRole": str(candidate.get("locatorRole") or "")[:24],
            "href": redact_sensitive_log_text(candidate.get("href") or "")[:500],
            "buttonType": str(candidate.get("buttonType") or "")[:24],
            "formMethod": str(candidate.get("formMethod") or "")[:16],
            "formAction": redact_sensitive_log_text(candidate.get("formAction") or "")[:500],
            "options": [
                {
                    "label": redact_sensitive_log_text(option.get("label") or option.get("text") or "")[:120],
                    "value": redact_sensitive_log_text(option.get("value") or "")[:120],
                }
                for option in (candidate.get("options") or [])[:20]
                if isinstance(option, dict)
            ],
        })
    responses = []
    for response in (preflight.get("responses") or [])[:20]:
        if not isinstance(response, dict):
            continue
        dataset = response_dataset(response, len(responses))
        responses.append({
            "method": "GET",
            "url": redact_sensitive_log_text(response.get("url") or "")[:500],
            "status": int(response.get("status") or 0),
            "itemCount": dataset.get("itemCount") or 0,
            "fields": dataset.get("fields") or [],
        })
    return {
        "finalUrl": redact_sensitive_log_text(preflight.get("final_url") or preflight.get("finalUrl") or ""),
        "title": redact_sensitive_log_text(preflight.get("title") or "")[:160],
        "headings": [redact_sensitive_log_text(value)[:160] for value in (structure.get("headings") or [])[:8]],
        "counts": {
            key: int(structure.get(key) or 0)
            for key in ("forms", "inputs", "buttons", "links")
        },
        "elements": elements,
        "readOnlyResponses": responses,
        "states": [
            {
                "stateKey": str(state.get("stateKey") or "")[:80],
                "requestedUrl": redact_sensitive_log_text(state.get("requested_url") or state.get("requestedUrl") or "")[:500],
                "finalUrl": redact_sensitive_log_text(state.get("final_url") or state.get("finalUrl") or "")[:500],
                "accessGate": sanitize_flow_log_details(state.get("accessGate") or {}),
                "candidateCount": len(state.get("elements") or []),
                "elements": [
                    {
                        "tag": str(candidate.get("tag") or "")[:24],
                        "type": str(candidate.get("type") or "")[:24],
                        "name": redact_sensitive_log_text(candidate.get("name") or "")[:120],
                        "locatorType": str(candidate.get("locatorType") or "")[:32],
                        "locatorValue": redact_sensitive_log_text(candidate.get("locatorValue") or "")[:120],
                        "locatorRole": str(candidate.get("locatorRole") or "")[:24],
                        "href": redact_sensitive_log_text(candidate.get("href") or "")[:500],
                        "options": [
                            {
                                "label": redact_sensitive_log_text(option.get("label") or option.get("text") or "")[:120],
                                "value": redact_sensitive_log_text(option.get("value") or "")[:120],
                            }
                            for option in (candidate.get("options") or [])[:20]
                            if isinstance(option, dict)
                        ],
                    }
                    for candidate in (state.get("elements") or [])[:40]
                    if isinstance(candidate, dict)
                ],
                "readOnlyResponses": [
                    {
                        "method": "GET",
                        "url": redact_sensitive_log_text(response.get("url") or "")[:500],
                        "status": int(response.get("status") or 0),
                        "itemCount": response_dataset(response, index).get("itemCount") or 0,
                        "fields": response_dataset(response, index).get("fields") or [],
                    }
                    for index, response in enumerate((state.get("responses") or [])[:20])
                    if isinstance(response, dict)
                ],
            }
            for state in (preflight.get("states") or [])[:EXPLORATION_MAX_EXPANDED_STATES]
            if isinstance(state, dict)
        ],
    }


def preflight_run_payload(preflight: dict[str, Any] | None) -> dict[str, Any]:
    prompt_payload = preflight_prompt_payload(preflight)
    if not prompt_payload:
        return {}
    return {
        **prompt_payload,
        "candidateCount": len((preflight or {}).get("elements") or []),
        "screenshotPath": str((preflight or {}).get("screenshot_path") or ""),
    }


def normalize_semantic_target(raw_target: Any, action: str) -> dict[str, Any]:
    if action in {"navigate", "snapshot"}:
        return {"kind": "url" if action == "navigate" else "text", "name": "", "aliases": [], "exact": True}
    if not isinstance(raw_target, dict):
        raise ExplorationPlanBuildError("invalid_target", f"{action} 步骤缺少结构化语义目标")
    kind = str(raw_target.get("kind") or "").strip().lower()
    name = str(raw_target.get("name") or "").strip()
    aliases = [str(value).strip() for value in raw_target.get("aliases", []) if str(value).strip()]
    if kind not in EXPLORATION_TARGET_KINDS:
        raise ExplorationPlanBuildError("invalid_target_kind", f"不支持的语义目标类型：{kind or '空'}")
    if not name and not aliases:
        raise ExplorationPlanBuildError("empty_target", f"{action} 步骤缺少目标名称")
    return {"kind": kind, "name": name, "aliases": aliases[:8], "exact": bool(raw_target.get("exact", True))}


def legacy_scenarios_to_asset_plan(raw_payload: dict[str, Any]) -> dict[str, Any]:
    raw_scenarios = raw_payload.get("scenarios") if isinstance(raw_payload.get("scenarios"), list) else []
    targets: list[dict[str, Any]] = []
    target_by_key: dict[tuple[str, str, str], str] = {}
    journeys: list[dict[str, Any]] = []
    for scenario_index, scenario in enumerate(raw_scenarios):
        if not isinstance(scenario, dict):
            continue
        case_id = str(scenario.get("caseId") or "").strip()
        journey_steps: list[dict[str, Any]] = []
        current_state = "initial"
        for raw_step in scenario.get("steps", []):
            if not isinstance(raw_step, dict):
                continue
            action = str(raw_step.get("action") or "").strip().lower()
            raw_target = raw_step.get("target") if isinstance(raw_step.get("target"), dict) else {}
            kind = str(raw_target.get("kind") or "").strip().lower()
            name = str(raw_target.get("name") or "").strip()
            aliases = [str(value).strip() for value in raw_target.get("aliases", []) if str(value).strip()]
            if action in {"navigate", "snapshot"}:
                journey_steps.append({
                    "action": action,
                    "targetId": "",
                    "value": "",
                    "description": str(raw_step.get("description") or action),
                    "expected": raw_step.get("expected") if isinstance(raw_step.get("expected"), dict) else {},
                })
                continue
            if kind not in EXPLORATION_TARGET_KINDS or (not name and not aliases):
                continue
            target_state = current_state
            key = (target_state, kind, (name or aliases[0]).lower())
            target_id = target_by_key.get(key)
            if not target_id:
                target_id = f"target-{len(targets) + 1}"
                target_by_key[key] = target_id
                targets.append({
                    "targetId": target_id,
                    "kind": kind,
                    "name": name or aliases[0],
                    "aliases": aliases,
                    "caseIds": [case_id] if case_id else [],
                    "stateKey": target_state,
                    "required": True,
                })
            elif case_id:
                target = next(item for item in targets if item["targetId"] == target_id)
                target["caseIds"] = list(dict.fromkeys([*target["caseIds"], case_id]))
            normalized_action = "locate" if action == "assert" else action
            if normalized_action not in EXPLORATION_ACTIONS:
                continue
            journey_steps.append({
                "action": normalized_action,
                "targetId": target_id,
                "value": str(raw_step.get("value") or ""),
                "description": str(raw_step.get("description") or normalized_action),
                "expected": raw_step.get("expected") if isinstance(raw_step.get("expected"), dict) else {},
            })
            if (
                normalized_action == "click"
                and kind in {"link", "button"}
                and EXPLORATION_LOGIN_ENTRY_PATTERN.fullmatch(name or (aliases[0] if aliases else ""))
            ):
                current_state = "login"
        journeys.append({
            "journeyId": f"legacy-journey-{scenario_index + 1}",
            "title": str(scenario.get("title") or case_id or "历史状态路径"),
            "stateKey": "initial",
            "caseIds": [case_id] if case_id else [],
            "steps": journey_steps,
        })
    return {"targets": targets, "journeys": journeys}


def deterministic_exploration_asset_plan(
    item: sqlite3.Row | dict[str, Any],
    parsed_cases: list[dict[str, str]],
    preflight: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    targets: list[dict[str, Any]] = []
    target_by_key: dict[tuple[str, str, str], dict[str, Any]] = {}

    def add_target(
        kind: str,
        name: str,
        aliases: list[str],
        case_ids: list[str],
        state_key: str = "initial",
        locator_hints: list[dict[str, str]] | None = None,
        evidence_source: str = "",
    ) -> dict[str, Any] | None:
        clean_name = sanitize_exploration_phrase(name, max_length=120)
        clean_name = re.sub(r"^(?:按钮|链接|入口)\s*|\s*(?:按钮|链接|入口)$", "", clean_name, flags=re.IGNORECASE)
        clean_name = clean_name.strip(" “\"'：:")[:60]
        if kind not in EXPLORATION_TARGET_KINDS or not clean_name or not case_ids:
            return None
        if exploration_target_quality_error(clean_name):
            return None
        if any(term in clean_name.lower() for term in EXPLORATION_DANGEROUS_TERMS):
            return None
        key = (state_key.lower(), kind, clean_name.lower())
        existing = target_by_key.get(key)
        if existing:
            existing["aliases"] = list(dict.fromkeys([*existing["aliases"], *aliases]))[:8]
            existing["caseIds"] = list(dict.fromkeys([*existing["caseIds"], *case_ids]))
            for hint in locator_hints or []:
                if hint not in existing["locatorHints"]:
                    existing["locatorHints"].append(hint)
            existing["locatorHints"] = existing["locatorHints"][:6]
            if evidence_source == "preflight":
                existing["evidenceSource"] = evidence_source
            return existing
        target = {
            "targetId": f"target-{len(targets) + 1}",
            "kind": kind,
            "name": clean_name,
            "aliases": [alias for alias in dict.fromkeys(aliases) if alias and alias != clean_name][:8],
            "caseIds": list(dict.fromkeys(case_ids)),
            "stateKey": state_key,
            "required": True,
            "locatorHints": list(locator_hints or [])[:6],
            "evidenceSource": evidence_source,
        }
        target_by_key[key] = target
        targets.append(target)
        return target

    item_requirement = str(item["requirement"] or "")
    login_case_ids = [
        case["external_id"] for case in parsed_cases
        if exploration_case_requires_login(case, item_requirement)
    ]
    entry = exploration_login_entry(preflight)
    entry_target = None
    login_state = "login" if entry else "initial"
    if entry and login_case_ids:
        entry_target = add_target(
            str(entry.get("locatorRole") or "link").lower(),
            str(entry.get("name") or entry.get("locatorValue") or "登录"),
            [],
            login_case_ids,
            "initial",
            exploration_candidate_locator_hints(entry),
            "preflight",
        )
    combined_login_source = exploration_positive_login_source(
        "\n".join([
            item_requirement,
            *(exploration_case_source(case) for case in parsed_cases if case["external_id"] in login_case_ids),
        ])
    )
    username_target = None
    password_target = None
    submit_target = None
    if entry and login_case_ids and re.search(r"账号|用户名|username|account", combined_login_source, re.IGNORECASE):
        username_target = add_target("textbox", "账号", ["用户名", "用户账号", "username", "account"], login_case_ids, login_state, evidence_source="login-transition")
    if entry and login_case_ids and re.search(r"密码|password|pwd", combined_login_source, re.IGNORECASE):
        password_target = add_target("password", "密码", ["登录密码", "password", "pwd"], login_case_ids, login_state, evidence_source="login-transition")
    if entry and login_case_ids:
        submit_target = add_target("button", "登录", ["登录系统", "立即登录", "Sign in", "Log in"], login_case_ids, login_state, evidence_source="login-transition")

    for candidate in (preflight or {}).get("elements") or []:
        if not isinstance(candidate, dict):
            continue
        kind = exploration_preflight_candidate_kind(candidate)
        name = str(candidate.get("locatorValue") or candidate.get("name") or "").strip()
        if not kind or not name:
            continue
        mapped_case_ids = exploration_preflight_candidate_case_ids(candidate, parsed_cases, item_requirement)
        if not mapped_case_ids:
            continue
        aliases = [
            value for value in (
                str(candidate.get("name") or "").strip(),
                str(candidate.get("locatorValue") or "").strip(),
            )
            if value and value != name
        ]
        add_target(
            kind,
            name,
            aliases,
            mapped_case_ids,
            "initial",
            exploration_candidate_locator_hints(candidate),
            "preflight",
        )

    if not targets:
        return None
    if any(target["stateKey"] not in {"initial", "login"} for target in targets):
        return None
    journeys: list[dict[str, Any]] = []
    initial_targets = [target for target in targets if target["stateKey"] == "initial" and target is not entry_target]
    if initial_targets or (entry_target and login_state == "initial"):
        steps = [{"action": "navigate", "targetId": "", "value": "", "description": "打开需求指定目标页面"}]
        for target in initial_targets:
            steps.append({"action": "locate", "targetId": target["targetId"], "value": "", "description": f"确认交互控件：{target['name']}"})
        steps.append({"action": "snapshot", "targetId": "", "value": "", "description": "记录初始页面状态"})
        journeys.append({"journeyId": "initial-assets", "title": "初始页面交互控件", "stateKey": "initial", "caseIds": list(dict.fromkeys(case_id for target in initial_targets for case_id in target["caseIds"])), "steps": steps})
    login_targets = [target for target in targets if target["stateKey"] == "login"]
    if login_targets:
        steps = [{"action": "navigate", "targetId": "", "value": "", "description": "打开需求指定目标页面"}]
        if entry_target:
            steps.append({"action": "click", "targetId": entry_target["targetId"], "value": "", "description": "进入登录页面"})
        for target in login_targets:
            steps.append({"action": "locate", "targetId": target["targetId"], "value": "", "description": f"确认登录控件：{target['name']}"})
        steps.append({"action": "snapshot", "targetId": "", "value": "", "description": "记录登录页面状态"})
        journeys.append({"journeyId": "login-assets", "title": "登录页面交互控件", "stateKey": "login", "caseIds": login_case_ids, "steps": steps})
    if username_target and password_target and submit_target:
        item_keys = item.keys() if hasattr(item, "keys") else item
        item_test_data = str(item["test_data"] or "") if "test_data" in item_keys else ""
        shared_credentials = parse_test_data("\n".join([item_test_data, item_requirement]))
        for case in parsed_cases:
            case_id = case["external_id"]
            if case_id not in login_case_ids or not exploration_case_required_actions(case).intersection({"fill", "click"}):
                continue
            credentials = parse_test_data("\n".join([
                str(case.get("preconditions") or ""),
                str(case.get("steps") or ""),
                str(case.get("requirement") or ""),
            ]))
            negative_case = bool(re.search(
                r"(?:错误|失败|无效|不存在|为空|incorrect|invalid|missing|empty)",
                exploration_case_source(case),
                re.IGNORECASE,
            ))
            username = credentials.get("username") or ("" if negative_case else shared_credentials.get("username"))
            password = credentials.get("password") or ("" if negative_case else shared_credentials.get("password"))
            if not username or not password:
                continue
            steps = [{"action": "navigate", "targetId": "", "value": "", "description": "打开需求指定目标页面"}]
            if entry_target:
                steps.append({
                    "action": "click",
                    "targetId": entry_target["targetId"],
                    "value": "",
                    "description": "进入登录页面",
                    "expected": {"stateChanged": True},
                })
            steps.extend([
                {
                    "action": "fill",
                    "targetId": username_target["targetId"],
                    "value": username,
                    "description": "填写账号",
                    "expected": {"valueEquals": username},
                },
                {
                    "action": "fill",
                    "targetId": password_target["targetId"],
                    "value": password,
                    "description": "填写密码",
                    "expected": {"valueEquals": password},
                },
                {
                    "action": "click",
                    "targetId": submit_target["targetId"],
                    "value": "",
                    "description": "提交登录",
                    "expected": {"stateChanged": True},
                },
                {"action": "snapshot", "targetId": "", "value": "", "description": "记录登录结果状态"},
            ])
            journeys.append({
                "journeyId": f"login-{case_id.lower()}",
                "title": f"登录状态路径：{case_id}",
                "stateKey": f"login-result-{case_id.lower()}",
                "caseIds": [case_id],
                "steps": steps,
            })
    search_targets = [
        target for target in targets
        if target["stateKey"] == "initial"
        and target["kind"] == "textbox"
        and EXPLORATION_SEARCH_INTENT_PATTERN.search(" ".join([target["name"], *target["aliases"]]))
    ]
    if search_targets:
        search_target = search_targets[0]
        for case in parsed_cases:
            case_id = case["external_id"]
            if case_id not in search_target["caseIds"] or "fill" not in exploration_case_required_actions(case):
                continue
            values = exploration_case_input_values(case)
            if not values:
                return None
            steps = [{"action": "navigate", "targetId": "", "value": "", "description": "打开需求指定目标页面"}]
            for value in values:
                steps.append({
                    "action": "fill",
                    "targetId": search_target["targetId"],
                    "value": value,
                    "description": f"输入查询条件：{value}",
                    "expected": {"valueEquals": value, "stateChanged": True},
                })
            steps.append({"action": "snapshot", "targetId": "", "value": "", "description": "记录搜索结果状态"})
            journeys.append({
                "journeyId": f"search-{case_id.lower()}",
                "title": f"搜索状态路径：{case_id}",
                "stateKey": f"search-{case_id.lower()}",
                "caseIds": [case_id],
                "steps": steps,
            })
    if not journeys:
        return None
    return {"targets": targets, "journeys": journeys}


def validate_and_normalize_exploration_plan(
    raw_payload: dict[str, Any],
    item: sqlite3.Row,
    parsed_cases: list[dict[str, str]],
    preflight: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if not isinstance(raw_payload, dict):
        raise ExplorationPlanBuildError("empty_plan", "AI 未返回页面元素发现计划")
    if not raw_payload.get("targets") and isinstance(raw_payload.get("scenarios"), list):
        raw_payload = legacy_scenarios_to_asset_plan(raw_payload)
    raw_targets = raw_payload.get("targets")
    raw_journeys = raw_payload.get("journeys")
    if not isinstance(raw_targets, list):
        raise ExplorationPlanBuildError("empty_targets", "AI 未返回需求和用例所需的交互控件清单")
    if not isinstance(raw_journeys, list) or not raw_journeys:
        raise ExplorationPlanBuildError("empty_journeys", "AI 未返回用于暴露交互控件的最短状态路径")

    expected_ids = [case["external_id"] for case in parsed_cases]
    expected_id_set = set(expected_ids)
    blocked_cases = [item for item in raw_payload.get("blockedCases", []) if isinstance(item, dict)]
    blocked_case_ids = {
        str(item.get("caseId") or "")
        for item in blocked_cases
        if str(item.get("caseId") or "") in expected_id_set
    }

    def degrade_case(case_id: str, code: str, reason: str) -> None:
        if case_id in blocked_case_ids:
            return
        blocked_case_ids.add(case_id)
        blocked_cases.append({
            "caseId": case_id,
            "priority": next((case.get("priority") or "P1" for case in parsed_cases if case["external_id"] == case_id), "P1"),
            "code": code,
            "reason": reason,
            "missingTargets": [],
        })
    if not raw_targets and any(
        case["external_id"] not in blocked_case_ids
        and (exploration_case_requires_interaction(case) or exploration_case_requires_actionability(case))
        for case in parsed_cases
    ):
        raise ExplorationPlanBuildError("empty_targets", "探索计划没有返回交互用例所需的控件清单")
    item_keys = item.keys() if hasattr(item, "keys") else item
    all_case_source = "\n".join([
        str(item["requirement"] or ""),
        str(item["test_data"] or "") if "test_data" in item_keys else "",
        *(exploration_case_source(case) for case in parsed_cases),
    ])
    merged_targets: dict[tuple[str, str, str, str], dict[str, Any]] = {}
    target_aliases: dict[str, str] = {}
    used_target_ids: set[str] = set()

    for index, raw_target in enumerate(raw_targets):
        if not isinstance(raw_target, dict):
            raise ExplorationPlanBuildError("invalid_target", "元素清单包含非法目标")
        kind = str(raw_target.get("kind") or "").strip().lower()
        raw_name = str(raw_target.get("name") or "")
        name = sanitize_exploration_phrase(raw_name, max_length=120)
        aliases = [sanitize_exploration_phrase(value, max_length=120) for value in raw_target.get("aliases", [])]
        aliases = [value for value in aliases if value][:8]
        if kind not in EXPLORATION_TARGET_KINDS:
            raise ExplorationPlanBuildError("invalid_target_kind", f"不支持的交互控件类型：{kind or '空'}")
        if not name and not aliases:
            raise ExplorationPlanBuildError("empty_target", "交互控件缺少语义名称")
        quality_error = exploration_target_quality_error(raw_name or name or aliases[0])
        if quality_error:
            raise ExplorationPlanBuildError(
                "invalid_target_name",
                f"交互控件名称不可靠：{name or aliases[0]}",
                quality_error,
            )
        if kind == "selector" and name not in all_case_source:
            raise ExplorationPlanBuildError("invented_selector", f"selector 未出现在需求或测试用例中：{name}")
        raw_target_id = str(raw_target.get("targetId") or f"target-{index + 1}").strip()
        state_key = str(raw_target.get("stateKey") or "initial").strip() or "initial"
        if (
            state_key.lower() == "initial"
            and exploration_preflight_requires_entry(preflight)
            and kind in {"textbox", "password", "button"}
            and (
                kind == "password"
                or EXPLORATION_LOGIN_CONTROL_PATTERN.search(" ".join([name, *aliases]))
            )
        ):
            state_key = "login"
        locator_hints = exploration_candidate_locator_hints({"locatorHints": raw_target.get("locatorHints") or []})
        evidence_source = str(raw_target.get("evidenceSource") or "").strip()
        if not locator_hints:
            matched_candidate = exploration_preflight_target_candidate(kind, name, aliases, preflight)
            if matched_candidate:
                locator_hints = exploration_candidate_locator_hints(matched_candidate)
                evidence_source = "preflight"
        case_ids = [
            case_id for case_id in normalize_case_ids(raw_target.get("caseIds") or [])
            if case_id in expected_id_set
        ]
        if not case_ids:
            raise ExplorationPlanBuildError("target_case_mapping_missing", f"交互控件 {name or aliases[0]} 未关联任何当前测试用例")
        strong_evidence = bool(locator_hints) or state_key.lower() != "initial" or kind == "selector"
        target_required = bool(raw_target.get("required", True)) and strong_evidence
        raw_desired_option = raw_target.get("desiredOption") if isinstance(raw_target.get("desiredOption"), dict) else {}
        merge_key = (
            state_key.lower(),
            kind,
            (name or aliases[0]).lower(),
            str(raw_desired_option.get("value") or raw_desired_option.get("label") or ""),
        )
        existing = merged_targets.get(merge_key)
        if existing:
            existing["aliases"] = list(dict.fromkeys([*existing["aliases"], *aliases]))[:8]
            existing["caseIds"] = list(dict.fromkeys([*existing["caseIds"], *case_ids]))
            existing["required"] = bool(existing["required"] or target_required)
            for hint in locator_hints:
                if hint not in existing["locatorHints"]:
                    existing["locatorHints"].append(hint)
            existing["locatorHints"] = existing["locatorHints"][:6]
            if evidence_source == "preflight":
                existing["evidenceSource"] = evidence_source
            target_aliases[raw_target_id] = existing["targetId"]
            continue
        target_id = raw_target_id or f"target-{index + 1}"
        if target_id in used_target_ids:
            target_id = f"{target_id}-{index + 1}"
        used_target_ids.add(target_id)
        normalized_target = {
            "targetId": target_id,
            "kind": kind,
            "name": name or aliases[0],
            "aliases": aliases,
            "caseIds": case_ids,
            "stateKey": state_key,
            "required": target_required,
            "exact": bool(raw_target.get("exact", True)),
            "locatorHints": locator_hints,
            "evidenceSource": evidence_source or ("preflight" if locator_hints else "inferred"),
            "candidateId": str(raw_target.get("candidateId") or ""),
            "href": str(raw_target.get("href") or ""),
            "safety": raw_target.get("safety") if isinstance(raw_target.get("safety"), dict) else {},
            "controlType": str(raw_target.get("controlType") or kind),
            "desiredOption": raw_target.get("desiredOption") if isinstance(raw_target.get("desiredOption"), dict) else {},
            "regionName": str(raw_target.get("regionName") or ""),
            "regionAliases": [str(value) for value in raw_target.get("regionAliases") or [] if str(value)],
            "selectionPolicy": str(raw_target.get("selectionPolicy") or "best-match"),
            "selectionIndex": int(raw_target.get("selectionIndex") or 0),
            "stateEvidenceSource": str(raw_target.get("stateEvidenceSource") or ""),
            "stateRequestedUrl": str(raw_target.get("stateRequestedUrl") or ""),
            "stateFinalUrl": str(raw_target.get("stateFinalUrl") or ""),
            "stateAccessGate": raw_target.get("stateAccessGate") if isinstance(raw_target.get("stateAccessGate"), dict) else {},
            "destinationStateKey": str(raw_target.get("destinationStateKey") or ""),
            "destinationFinalUrl": str(raw_target.get("destinationFinalUrl") or ""),
            "destinationAccessGate": raw_target.get("destinationAccessGate") if isinstance(raw_target.get("destinationAccessGate"), dict) else {},
        }
        merged_targets[merge_key] = normalized_target
        target_aliases[raw_target_id] = target_id

    targets = list(merged_targets.values())
    target_by_id = {target["targetId"]: target for target in targets}
    recovery_policy = exploration_recovery_policy(preflight)
    journeys: list[dict[str, Any]] = []

    for journey_index, raw_journey in enumerate(raw_journeys):
        if not isinstance(raw_journey, dict):
            raise ExplorationPlanBuildError("invalid_journey", "最短状态路径包含非法记录")
        journey_id = str(raw_journey.get("journeyId") or f"journey-{journey_index + 1}").strip()
        state_key = str(raw_journey.get("stateKey") or "initial").strip() or "initial"
        raw_steps = raw_journey.get("steps")
        if not isinstance(raw_steps, list):
            raise ExplorationPlanBuildError("invalid_journey_steps", f"状态路径 {journey_id} 缺少步骤")
        journey_case_ids = [
            case_id for case_id in normalize_case_ids(raw_journey.get("caseIds") or [])
            if case_id in expected_id_set
        ]
        normalized_steps: list[dict[str, Any]] = []
        if not raw_steps or str((raw_steps[0] or {}).get("action") or "").strip().lower() != "navigate":
            raw_steps = [
                {"action": "navigate", "targetId": "", "value": "", "description": "打开需求指定目标页面"},
                *raw_steps,
            ]
        for raw_step in raw_steps:
            if not isinstance(raw_step, dict):
                raise ExplorationPlanBuildError("invalid_step", f"状态路径 {journey_id} 包含非法步骤")
            action = str(raw_step.get("action") or "").strip().lower()
            if action not in EXPLORATION_ACTIONS:
                raise ExplorationPlanBuildError("invalid_action", f"状态路径 {journey_id} 包含不支持的动作：{action or '空'}")
            raw_target_id = str(raw_step.get("targetId") or "").strip()
            target_id = target_aliases.get(raw_target_id, raw_target_id)
            target_meta: dict[str, Any]
            if action == "navigate":
                target = str(item["target_url"] or "")
                target_meta = {"kind": "url", "name": "targetUrl", "aliases": [], "exact": True}
            elif action == "snapshot":
                target = ""
                target_meta = {"kind": "state", "name": state_key, "aliases": [], "exact": True}
            else:
                target_record = target_by_id.get(target_id)
                if target_record is None:
                    raise ExplorationPlanBuildError("unknown_target", f"状态路径 {journey_id} 引用了不存在的目标：{raw_target_id or '空'}")
                target = target_record["name"]
                target_meta = {
                    "kind": target_record["kind"],
                    "name": target_record["name"],
                    "aliases": target_record["aliases"],
                    "exact": bool(target_record.get("exact", True)),
                    "targetId": target_record["targetId"],
                    "caseIds": target_record["caseIds"],
                    "stateKey": target_record["stateKey"],
                    "required": target_record["required"],
                    "locatorHints": target_record.get("locatorHints") or [],
                    "evidenceSource": target_record.get("evidenceSource") or "",
                    "candidateId": target_record.get("candidateId") or "",
                    "href": target_record.get("href") or "",
                    "safety": target_record.get("safety") or {},
                    "controlType": target_record.get("controlType") or target_record.get("kind") or "",
                    "desiredOption": target_record.get("desiredOption") or {},
                    "regionName": target_record.get("regionName") or "",
                    "regionAliases": target_record.get("regionAliases") or [],
                    "selectionPolicy": target_record.get("selectionPolicy") or "best-match",
                    "selectionIndex": int(target_record.get("selectionIndex") or 0),
                    "stateEvidenceSource": target_record.get("stateEvidenceSource") or "",
                    "stateRequestedUrl": target_record.get("stateRequestedUrl") or "",
                    "stateFinalUrl": target_record.get("stateFinalUrl") or "",
                    "stateAccessGate": target_record.get("stateAccessGate") or {},
                    "destinationStateKey": target_record.get("destinationStateKey") or "",
                    "destinationFinalUrl": target_record.get("destinationFinalUrl") or "",
                    "destinationAccessGate": target_record.get("destinationAccessGate") or {},
                }
                if not journey_case_ids:
                    journey_case_ids = list(dict.fromkeys(target_record["caseIds"]))
            value = str(raw_step.get("value") or "")
            description = sanitize_exploration_phrase(raw_step.get("description"), max_length=180) or f"{action} {target}".strip()
            desired_option = target_meta.get("desiredOption") if isinstance(target_meta.get("desiredOption"), dict) else {}
            select_value_from_evidence = action == "select" and value in {
                str(desired_option.get("value") or ""),
                str(desired_option.get("label") or ""),
            }
            if action in {"fill", "select"} and value and value not in all_case_source and not select_value_from_evidence:
                raise ExplorationPlanBuildError("invented_test_data", f"状态路径 {journey_id} 使用了需求和用例中不存在的测试数据")
            if exploration_step_is_dangerous(action, description, target, value, target_meta):
                raise ExplorationPlanBuildError("dangerous_action", f"状态路径 {journey_id} 包含不允许自动执行的危险动作：{description}")
            step = {
                "action": action,
                "target": target,
                "targetId": target_id,
                "targetMeta": target_meta,
                "value": value,
                "description": description,
                "critical": action != "snapshot",
                "expected": normalize_exploration_expected(raw_step.get("expected"), action, value),
                "journeyId": journey_id,
                "stateKey": state_key,
                "stateTransition": raw_step.get("stateTransition") if isinstance(raw_step.get("stateTransition"), dict) else {},
            }
            if (
                recovery_policy
                and action in {"locate", "fill"}
                and target_meta.get("stateKey") == "login"
                and target_meta.get("kind") in {"textbox", "password", "button"}
            ):
                step["recoveryPolicy"] = recovery_policy
            normalized_steps.append(step)
        if not any(step["action"] == "snapshot" for step in normalized_steps):
            normalized_steps.append({
                "action": "snapshot",
                "target": "",
                "targetId": "",
                "targetMeta": {"kind": "state", "name": state_key, "aliases": [], "exact": True},
                "value": "",
                "description": f"记录 {state_key} 页面状态证据",
                "critical": False,
                "expected": {},
                "journeyId": journey_id,
                "stateKey": state_key,
            })
        preflight_candidate_count = len((preflight or {}).get("elements") or [])
        for step_index, step in enumerate(normalized_steps):
            if step["action"] not in {"navigate", "click"}:
                continue
            next_target = next(
                (
                    candidate_step.get("targetMeta") or {}
                    for candidate_step in normalized_steps[step_index + 1:]
                    if candidate_step.get("action") in {"locate", "fill", "select", "click"}
                    and (candidate_step.get("targetMeta") or {}).get("locatorHints")
                ),
                {},
            )
            step["readinessHints"] = next_target.get("locatorHints") or []
            step["readiness"] = {
                "minInteractive": 1 if preflight_candidate_count else 0,
                "preflightCandidateCount": preflight_candidate_count,
                "timeoutMs": 8000,
            }
            if step["action"] == "click" and step["readinessHints"] and not step["expected"]:
                step["expected"] = {"targetVisible": step["readinessHints"][:6]}
            elif step["action"] in {"click", "select"} and not step["expected"]:
                step["expected"] = {"stateChanged": True}
        journeys.append({
            "journeyId": journey_id,
            "title": str(raw_journey.get("title") or state_key).strip() or state_key,
            "stateKey": state_key,
            "requiredState": str(raw_journey.get("requiredState") or state_key),
            "destinationState": str(raw_journey.get("destinationState") or ""),
            "entryPath": raw_journey.get("entryPath") if isinstance(raw_journey.get("entryPath"), list) else [],
            "caseIds": journey_case_ids,
            "steps": normalized_steps,
        })

    referenced_target_ids = {
        step["targetId"]
        for journey in journeys
        for step in journey["steps"]
        if step.get("targetId")
    }
    for target in targets:
        if target["targetId"] in referenced_target_ids:
            continue
        journey = next((item for item in journeys if item["stateKey"].lower() == target["stateKey"].lower()), journeys[0])
        locate_step = {
            "action": "locate",
            "target": target["name"],
            "targetId": target["targetId"],
            "targetMeta": {
                "kind": target["kind"],
                "name": target["name"],
                "aliases": target["aliases"],
                "exact": bool(target.get("exact", True)),
                "targetId": target["targetId"],
                "caseIds": target["caseIds"],
                "stateKey": target["stateKey"],
                "required": target["required"],
                "locatorHints": target.get("locatorHints") or [],
                "evidenceSource": target.get("evidenceSource") or "",
                "candidateId": target.get("candidateId") or "",
                "href": target.get("href") or "",
                "safety": target.get("safety") or {},
                "controlType": target.get("controlType") or target.get("kind") or "",
                "desiredOption": target.get("desiredOption") or {},
                "regionName": target.get("regionName") or "",
                "regionAliases": target.get("regionAliases") or [],
                "selectionPolicy": target.get("selectionPolicy") or "best-match",
                "selectionIndex": int(target.get("selectionIndex") or 0),
                "stateEvidenceSource": target.get("stateEvidenceSource") or "",
                "stateRequestedUrl": target.get("stateRequestedUrl") or "",
                "stateFinalUrl": target.get("stateFinalUrl") or "",
                "stateAccessGate": target.get("stateAccessGate") or {},
                "destinationStateKey": target.get("destinationStateKey") or "",
                "destinationFinalUrl": target.get("destinationFinalUrl") or "",
                "destinationAccessGate": target.get("destinationAccessGate") or {},
            },
            "value": "",
            "description": f"确认交互控件：{target['name']}",
            "critical": target["required"],
            "expected": {},
            "journeyId": journey["journeyId"],
            "stateKey": journey["stateKey"],
        }
        snapshot_index = next((index for index, step in enumerate(journey["steps"]) if step["action"] == "snapshot"), len(journey["steps"]))
        journey["steps"].insert(snapshot_index, locate_step)
        journey["caseIds"] = list(dict.fromkeys([*journey["caseIds"], *target["caseIds"]]))

    for case in parsed_cases:
        case_id = case["external_id"]
        if case_id in blocked_case_ids:
            continue
        related_steps = [
            step
            for journey in journeys
            if case_id in journey.get("caseIds", [])
            for step in journey.get("steps", [])
        ]
        actions = {str(step.get("action") or "") for step in related_steps}
        required_actions = exploration_case_required_actions(case)
        missing_actions = []
        if "fill" in required_actions and "fill" not in actions:
            missing_actions.append("fill")
        if "select" in required_actions and not actions.intersection({"select", "click"}):
            state_changing_fill = any(
                step.get("action") == "fill" and bool((step.get("expected") or {}).get("stateChanged"))
                for step in related_steps
            )
            if not state_changing_fill:
                missing_actions.append("select/click/stateChanged")
        if "click" in required_actions and "click" not in actions:
            state_changing_fill = any(
                step.get("action") in {"fill", "select"}
                and bool((step.get("expected") or {}).get("stateChanged"))
                for step in related_steps
            )
            if not state_changing_fill:
                missing_actions.append("click/stateChanged")
        if exploration_case_requires_interaction(case) and not actions.intersection({"click", "fill", "select"}):
            missing_actions.append("interaction")
        if missing_actions:
            degrade_case(
                case_id,
                "incomplete_case_journey",
                f"探索路径缺少必要动作：{', '.join(dict.fromkeys(missing_actions))}",
            )
            continue
        for step in related_steps:
            if step.get("action") in {"click", "select"} and not step.get("expected"):
                degrade_case(
                    case_id,
                    "missing_state_expectation",
                    f"状态变更步骤缺少后置校验：{step.get('description') or step.get('action')}",
                )
                break

    flattened: list[dict[str, Any]] = []
    for journey_index, journey in enumerate(journeys):
        for step_index, step in enumerate(journey["steps"]):
            step["targetMeta"].setdefault("stateKey", journey["stateKey"])
            step["targetMeta"].setdefault("caseIds", journey["caseIds"])
            step.update(
                index=len(flattened),
                caseId=(journey["caseIds"][0] if journey["caseIds"] else ""),
                caseIds=journey["caseIds"],
                scenarioIndex=journey_index,
                scenarioStepIndex=step_index,
            )
            flattened.append(step)
    return {
        "version": int(raw_payload.get("version") or 4),
        "plannerVersion": int(raw_payload.get("plannerVersion") or 0),
        "source": str(raw_payload.get("source") or "ai"),
        "preflight": preflight_run_payload(preflight),
        "caseContracts": raw_payload.get("caseContracts") if isinstance(raw_payload.get("caseContracts"), list) else [],
        "caseStateAssignments": raw_payload.get("caseStateAssignments") if isinstance(raw_payload.get("caseStateAssignments"), list) else [],
        "stateGraph": raw_payload.get("stateGraph") if isinstance(raw_payload.get("stateGraph"), dict) else {},
        "plannedCaseIds": [case_id for case_id in expected_ids if case_id not in blocked_case_ids],
        "blockedCases": blocked_cases,
        "targets": targets,
        "journeys": journeys,
        "scenarios": journeys,
        "steps": flattened,
    }


def normalize_exploration_semantic_name(value: Any) -> str:
    text = sanitize_exploration_phrase(value, max_length=160).lower()
    text = re.sub(r"[\s\-—_·:：/\\()（）\[\]【】'\"“”]+", "", text)
    text = re.sub(r"(?:按钮|链接|入口|控件|选项)$", "", text)
    text = re.sub(r"skill$", "", text, flags=re.IGNORECASE)
    return text


def exploration_ordinal_number(value: Any) -> int:
    token = str(value or "").strip()
    if not token:
        return 0
    if token.isdigit():
        return int(token)
    digits = {"零": 0, "〇": 0, "一": 1, "二": 2, "两": 2, "三": 3, "四": 4, "五": 5, "六": 6, "七": 7, "八": 8, "九": 9}
    if token == "十":
        return 10
    if "十" in token:
        tens, ones = token.split("十", 1)
        return (digits.get(tens, 1) if tens else 1) * 10 + digits.get(ones, 0)
    return digits.get(token, 0)


def exploration_ordinal_record_intent(source: str) -> tuple[int, list[str]]:
    if not re.search(r"(?:记录|排行|总榜|榜单|列表|表格|表内|table|row)", source, re.IGNORECASE):
        return 0, []
    match = re.search(
        r"第\s*([0-9]{1,3}|[零〇一二两三四五六七八九十]{1,4})\s*"
        r"(?:条|项|个|行)(?:记录|数据|结果|技能)?",
        source,
        re.IGNORECASE,
    )
    if match:
        ordinal = exploration_ordinal_number(match.group(1))
    else:
        match = re.search(r"首\s*(?:条|项|行)(?:记录|数据|结果|技能)?", source, re.IGNORECASE)
        ordinal = 1 if match else 0
    if not match or ordinal <= 0:
        return 0, []
    prefix = source[max(0, match.start() - 48):match.start()]
    regions = re.findall(
        r"([A-Za-z0-9\u4e00-\u9fff_-]{2,24}(?:总榜|排行榜|榜单|列表|表格))",
        prefix,
        re.IGNORECASE,
    )
    return ordinal, ([regions[-1]] if regions else [])


def exploration_candidate_record_ordinal(candidate: dict[str, Any]) -> int:
    match = re.match(r"^\s*([0-9]{1,3})(?:\s|[.、．)])", str(candidate.get("name") or ""))
    return int(match.group(1)) if match else 0


def exploration_candidate_is_list_record(candidate: dict[str, Any]) -> bool:
    name = str(candidate.get("name") or "").strip()
    if re.search(r"查看全部|完整排行榜|更多|上一页|下一页|more|previous|next", name, re.IGNORECASE):
        return False
    tag = str(candidate.get("tag") or candidate.get("tagName") or "").strip().lower()
    return bool(
        tag in {"tr", "li"}
        or exploration_candidate_record_ordinal(candidate)
        or re.search(r"查看(?:技能|详情)|打开(?:技能|详情)", name, re.IGNORECASE)
    )


def exploration_candidate_safety(candidate: dict[str, Any], target_url: str) -> dict[str, Any]:
    name = str(candidate.get("name") or candidate.get("locatorValue") or "").strip()
    kind = exploration_preflight_candidate_kind(candidate)
    href = str(candidate.get("href") or "").strip()
    resolved_href = ""
    same_origin: bool | None = None
    if href:
        with contextlib.suppress(ValueError):
            resolved_href = urllib.parse.urljoin(target_url, href)
            resolved_url = urllib.parse.urlparse(resolved_href)
            requested_url = urllib.parse.urlparse(target_url)
            same_origin = (resolved_url.scheme, resolved_url.netloc) == (requested_url.scheme, requested_url.netloc)
    button_type = str(candidate.get("buttonType") or candidate.get("type") or "").strip().lower()
    form_method = str(candidate.get("formMethod") or "").strip().upper()
    irreversible = bool(EXPLORATION_IRREVERSIBLE_PATTERN.search(name))
    if re.search(r"(?:确认|提交|立即).{0,8}发布|发布.{0,8}(?:确认|提交)", name, re.IGNORECASE):
        irreversible = True
    if kind == "button" and button_type == "submit" and form_method not in {"", "GET"} and "发布" in name:
        irreversible = True
    if irreversible:
        safety_class = "irreversible"
    elif kind in {"link", "menuitem", "tab"}:
        safety_class = "same-origin-navigation" if same_origin is not False else "external-navigation"
    elif kind in {"button", "combobox", "option", "checkbox", "radio", "switch"}:
        safety_class = "reversible-state-change"
    else:
        safety_class = "read-only"
    return {
        "class": safety_class,
        "sameOrigin": same_origin,
        "href": resolved_href or href,
        "buttonType": button_type,
        "formMethod": form_method,
        "formAction": str(candidate.get("formAction") or ""),
    }


def exploration_candidate_inventory(preflight: dict[str, Any] | None, target_url: str) -> list[dict[str, Any]]:
    inventory: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    raw_states = (preflight or {}).get("states") if isinstance((preflight or {}).get("states"), list) else []
    states = raw_states or [{
        "stateKey": "initial",
        "requested_url": target_url,
        "final_url": str((preflight or {}).get("final_url") or target_url),
        "elements": (preflight or {}).get("elements") or [],
        "accessGate": {},
    }]
    inventory_index = 0
    for state in states:
        if not isinstance(state, dict):
            continue
        state_key = str(state.get("stateKey") or "initial")
        state_url = str(state.get("requested_url") or state.get("requestedUrl") or target_url)
        final_url = str(state.get("final_url") or state.get("finalUrl") or state_url)
        access_gate = state.get("accessGate") if isinstance(state.get("accessGate"), dict) else {}
        for raw_candidate in state.get("elements") or []:
            if not isinstance(raw_candidate, dict):
                continue
            candidate = dict(raw_candidate)
            kind = exploration_preflight_candidate_kind(candidate)
            name = str(candidate.get("name") or candidate.get("locatorValue") or "").strip()
            if not kind or not name:
                continue
            seed = "|".join([
                state_key,
                kind,
                name,
                str(candidate.get("regionName") or candidate.get("area") or ""),
                str(candidate.get("locatorType") or ""),
                str(candidate.get("locatorRole") or ""),
                str(candidate.get("locatorValue") or ""),
            ])
            candidate_id = f"candidate-{hashlib.sha256(seed.encode('utf-8')).hexdigest()[:12]}"
            if candidate_id in seen_ids:
                candidate_id = f"{candidate_id}-{inventory_index + 1}"
            seen_ids.add(candidate_id)
            candidate.update(
                candidateId=candidate_id,
                inventoryIndex=inventory_index,
                kind=kind,
                name=name,
                normalizedName=normalize_exploration_semantic_name(name),
                stateKey=state_key,
                stateRequestedUrl=state_url,
                stateFinalUrl=final_url,
                stateAccessGate=access_gate,
                stateEvidenceSource="expanded-preflight" if state_key != "initial" else "initial-preflight",
                safety=exploration_candidate_safety(candidate, state_url),
            )
            inventory.append(candidate)
            inventory_index += 1
    state_by_requested_url = {
        str(state.get("requested_url") or state.get("requestedUrl") or ""): state
        for state in states
        if isinstance(state, dict) and str(state.get("requested_url") or state.get("requestedUrl") or "")
    }
    for candidate in inventory:
        href = str((candidate.get("safety") or {}).get("href") or "")
        destination_state = state_by_requested_url.get(href)
        if destination_state:
            candidate["destinationStateKey"] = str(destination_state.get("stateKey") or "")
            candidate["destinationFinalUrl"] = str(destination_state.get("final_url") or destination_state.get("finalUrl") or "")
            candidate["destinationAccessGate"] = destination_state.get("accessGate") if isinstance(destination_state.get("accessGate"), dict) else {}
    return inventory


def exploration_state_from_url(value: str) -> str:
    normalized = normalized_navigation_url(value)
    parsed = urllib.parse.urlsplit(normalized)
    route = f"#{parsed.fragment}" if parsed.fragment else parsed.path or "/"
    if re.search(r"(?:^|[/#?])login(?:[/#?=&]|$)", route, re.IGNORECASE):
        return "login"
    if re.search(r"(?:^|[/#?])skills?(?:[/#?=&]|$)", route, re.IGNORECASE):
        return "skills"
    if re.search(r"(?:^|[/#?])publish(?:[/#?=&]|$)", route, re.IGNORECASE):
        return "publish-gate"
    return "root"


def exploration_case_state_assignment(case: dict[str, str], item: sqlite3.Row | dict[str, Any] | None = None) -> dict[str, Any]:
    source = exploration_case_source(case)
    expected = str(case.get("expected") or "")
    steps = str(case.get("steps") or "")
    explicit_urls = re.findall(r"(?:https?://[^\s，。；;]+|#/[A-Za-z0-9_?=&./-]*)", expected)
    explicit_state = exploration_state_from_url(explicit_urls[-1]) if explicit_urls else ""
    publish_intent = bool(re.search(r"发布\s*skill|发布按钮|发布入口|点击.{0,12}发布", source, re.IGNORECASE))
    skill_intent = bool(re.search(r"技能库|全部技能|skills?", source, re.IGNORECASE))
    if explicit_state == "login" and publish_intent:
        required_state, destination_state = "skills", "publish-gate"
    elif explicit_state:
        required_state, destination_state = explicit_state, ""
    elif publish_intent or skill_intent:
        required_state = "skills"
        destination_state = "publish-gate" if publish_intent and re.search(
            r"点击.{0,20}发布|发布.{0,20}(?:跳转|进入)", source, re.IGNORECASE
        ) else ""
    elif exploration_case_requires_login(case):
        required_state, destination_state = "login", ""
    else:
        required_state, destination_state = "root", ""
    required_targets: list[str] = []
    if publish_intent and not re.search(r"提交发布|确认发布|立即发布", source, re.IGNORECASE):
        required_targets.append("发布 Skill")
    if re.search(r"分类", source):
        required_targets.append("分类")
    if re.search(r"部门", source):
        required_targets.append("所属部门")
    if re.search(r"排序", source):
        required_targets.append("排序方式")
    if re.search(r"搜索|查询", source):
        required_targets.append("搜索")
    return {
        "caseId": str(case.get("external_id") or ""),
        "requiredState": required_state,
        "destinationState": destination_state,
        "requiredTargets": list(dict.fromkeys(required_targets)),
        "explicitState": explicit_state,
        "sourceHash": hashlib.sha256(source.encode("utf-8")).hexdigest()[:16],
        "stepsHash": hashlib.sha256(steps.encode("utf-8")).hexdigest()[:16],
    }


def exploration_state_graph(item: sqlite3.Row | dict[str, Any], inventory: list[dict[str, Any]]) -> dict[str, Any]:
    keys = item.keys() if hasattr(item, "keys") else item
    target_url = str(item["target_url"] or "") if "target_url" in keys else ""
    nodes: dict[str, dict[str, Any]] = {"root": {"stateKey": "root", "url": target_url, "readiness": []}}
    edges: list[dict[str, Any]] = []
    for candidate in inventory:
        name = str(candidate.get("name") or "")
        href = str((candidate.get("safety") or {}).get("href") or candidate.get("href") or "")
        source_state = str(candidate.get("stateKey") or "initial")
        source_state = "root" if source_state == "initial" else source_state
        destination = exploration_state_from_url(str(candidate.get("destinationFinalUrl") or href))
        if destination == "root" and re.search(r"技能库|全部技能", name):
            destination = "skills"
        if destination == "root" and re.search(r"发布", name):
            destination = "publish-gate"
        if destination == source_state or not href:
            continue
        nodes.setdefault(destination, {"stateKey": destination, "url": str(candidate.get("destinationFinalUrl") or href), "readiness": []})
        edges.append({
            "from": source_state, "to": destination,
            "candidateId": str(candidate.get("candidateId") or ""),
            "name": name, "kind": str(candidate.get("kind") or "link"),
            "href": href, "safety": candidate.get("safety") or {},
        })
    if "skills" in nodes and not any(edge["from"] == "skills" and edge["to"] == "publish-gate" for edge in edges):
        publish = next((candidate for candidate in inventory if re.search(r"发布", str(candidate.get("name") or ""))), None)
        if publish:
            nodes.setdefault("publish-gate", {"stateKey": "publish-gate", "url": str(publish.get("destinationFinalUrl") or (publish.get("safety") or {}).get("href") or ""), "readiness": []})
            edges.append({
                "from": "skills", "to": "publish-gate", "candidateId": "",
                "name": "发布 Skill", "kind": "link",
                "href": str((publish.get("safety") or {}).get("href") or ""),
                "safety": {"class": "same-origin-navigation", "sameOrigin": True},
                "inferred": True,
            })
    return {"nodes": list(nodes.values()), "edges": edges}


def exploration_case_contract(case: dict[str, str], item: sqlite3.Row | dict[str, Any] | None = None) -> dict[str, Any]:
    case_id = str(case.get("external_id") or "")
    priority = str(case.get("priority") or "P1").upper()
    source = exploration_case_intent_source(case)
    required_actions = exploration_case_required_actions(case)
    state_assignment = exploration_case_state_assignment(case, item)
    required_state = state_assignment["requiredState"]
    concepts: list[dict[str, Any]] = []
    concept_keys: set[str] = set()

    def add_concept(
        key: str,
        name: str,
        aliases: list[str],
        kinds: set[str],
        action: str,
        *,
        intent: str = "generic",
        state_key: str = "initial",
        allow_inferred: bool = False,
        control_type: str = "",
        desired_option: dict[str, str] | None = None,
        region_aliases: list[str] | None = None,
        selection_policy: str = "best-match",
        selection_index: int = 0,
    ) -> None:
        if key in concept_keys:
            return
        concept_keys.add(key)
        concepts.append({
            "key": key,
            "name": name,
            "aliases": list(dict.fromkeys([name, *aliases])),
            "kinds": sorted(kinds),
            "action": action,
            "intent": intent,
            "stateKey": state_key,
            "allowInferred": allow_inferred,
            "controlType": control_type,
            "desiredOption": desired_option or {},
            "regionAliases": list(dict.fromkeys(region_aliases or [])),
            "selectionPolicy": selection_policy,
            "selectionIndex": selection_index,
        })

    quoted_targets = re.findall(r"[“\"']([^”\"'\n]{1,50})[”\"']", source)

    if re.search(r"发布", source, re.IGNORECASE):
        publish_action = "click" if "click" in required_actions else "locate"
        add_concept(
            "publish-entry",
            "发布 Skill" if required_state == "skills" else "发布",
            ["发布", "发布skill", "发布 Skill"],
            {"link", "menuitem", "tab", "button"},
            publish_action,
            intent="publish-navigation",
            state_key=required_state,
            allow_inferred=required_state != "root",
        )
    generic_skill_card = bool(re.search(
        r"(?:任一|任意|第一个|首个|第一张|目标).{0,12}(?:技能|skill)|"
        r"(?:技能|skill).{0,12}(?:任一|任意|第一个|首个|第一张|卡片?|card)",
        source,
        re.IGNORECASE,
    ))
    if "click" in required_actions and generic_skill_card and not quoted_targets:
        region_aliases = ["本周热门"] if re.search(r"本周热门|热门区|weekly\s*hot|trending", source, re.IGNORECASE) else []
        add_concept(
            "skill-detail-first",
            "查看技能",
            ["技能卡", "技能卡片", "目标技能卡", "查看技能"],
            {"button", "link"},
            "click",
            intent="skill-detail",
            region_aliases=region_aliases,
            selection_policy="first-safe",
        )
    elif "click" in required_actions and not quoted_targets and re.search(r"技能.{0,12}(?:卡片?|详情)|查看技能|skill.{0,12}(?:card|detail)", source, re.IGNORECASE):
        add_concept("skill-detail", "查看技能", ["技能卡", "技能卡片", "技能详情"], {"button", "link"}, "click", intent="skill-detail")
    ordinal_index, ordinal_regions = exploration_ordinal_record_intent(source)
    if "click" in required_actions and ordinal_index:
        region_name = ordinal_regions[0] if ordinal_regions else "列表"
        add_concept(
            f"ordinal-record-{ordinal_index}-{hashlib.sha256(region_name.encode('utf-8')).hexdigest()[:6]}",
            f"{region_name}第 {ordinal_index} 条记录",
            [f"第{ordinal_index}条记录", f"第 {ordinal_index} 条记录"],
            {"button", "link", "menuitem"},
            "click",
            intent="ordinal-record",
            region_aliases=ordinal_regions,
            selection_policy="nth-safe",
            selection_index=ordinal_index,
        )
    if re.search(r"分类", source) and required_actions.intersection({"click", "select"}):
        add_concept("category-filter", "浏览分类", ["分类"], {"button", "link", "tab", "option"}, "click", intent="category")
        if re.search(r"(?:全部|恢复全部)", source):
            add_concept("category-all", "全部", ["全部分类", "所有"], {"button", "link", "tab", "option"}, "click", intent="category-all", state_key="skills", allow_inferred=True)
    for key, label, value, pattern in [
        ("sort-install", "按安装量", "dl", r"安装量|downloadCount"),
        ("sort-week", "按本周热度", "wk", r"本周热度|weekCount"),
        ("sort-updated", "按更新时间", "upd", r"更新时间|updatedAt"),
    ]:
        if re.search(pattern, source, re.IGNORECASE) and required_actions.intersection({"click", "select"}):
            add_concept(
                key,
                "排序方式",
                ["排序", label],
                {"combobox"},
                "select",
                intent="sort",
                state_key="skills",
                allow_inferred=True,
                control_type="combobox",
                desired_option={"label": label, "value": value},
            )
    if "fill" in required_actions and EXPLORATION_SEARCH_INTENT_PATTERN.search(source):
        add_concept("search-input", "搜索技能、作者、标签", ["搜索技能", "搜索", "查询"], {"textbox"}, "fill", intent="search")
    if re.search(r"账号|用户名|username|account", source, re.IGNORECASE) and "fill" in required_actions:
        add_concept("login-username", "账号", ["用户名", "username", "account"], {"textbox"}, "fill", intent="login", state_key="login", allow_inferred=True)
    if re.search(r"密码|password|pwd", source, re.IGNORECASE) and "fill" in required_actions:
        add_concept("login-password", "密码", ["password", "pwd"], {"password"}, "fill", intent="login", state_key="login", allow_inferred=True)
    if exploration_case_requires_login(case) and "click" in required_actions and state_assignment["destinationState"] != "publish-gate":
        add_concept("login-submit", "登录", ["登录系统", "立即登录", "Sign in", "Log in"], {"button"}, "click", intent="login", state_key="login", allow_inferred=True)

    if not (exploration_case_requires_interaction(case) or exploration_case_requires_actionability(case)):
        quoted_targets = []
    for quoted in quoted_targets:
        clean = sanitize_exploration_phrase(quoted, max_length=50)
        normalized = normalize_exploration_semantic_name(clean)
        if not clean or len(normalized) < 2:
            continue
        if required_state == "skills" and re.fullmatch(r"(?:技能库|全部技能|skills?)", clean, re.IGNORECASE):
            continue
        if any(
            normalized == normalized_alias
            or (min(len(normalized), len(normalized_alias)) >= 2 and (normalized in normalized_alias or normalized_alias in normalized))
            for concept in concepts
            for alias in concept["aliases"]
            for normalized_alias in [normalize_exploration_semantic_name(alias)]
            if normalized_alias
        ):
            continue
        action = "click" if "click" in required_actions else "select" if "select" in required_actions else "locate"
        add_concept(
            f"quoted-{hashlib.sha256(clean.encode('utf-8')).hexdigest()[:8]}",
            clean,
            [],
            {"button", "link", "tab", "menuitem", "option"},
            action,
            intent="quoted",
            state_key=required_state,
            allow_inferred=action != "locate",
        )

    return {
        "caseId": case_id,
        "priority": priority if priority in EXPLORATION_PRIORITY_RANK else "P1",
        "title": str(case.get("title") or case_id),
        "requiredActions": sorted(required_actions),
        "requiresInteraction": exploration_case_requires_interaction(case),
        "requiresActionability": exploration_case_requires_actionability(case),
        "requiredState": required_state,
        "destinationState": state_assignment["destinationState"],
        "requiredTargets": state_assignment["requiredTargets"],
        "concepts": concepts,
        "inputValues": exploration_case_input_values(case),
        "sourceHash": hashlib.sha256(source.encode("utf-8")).hexdigest()[:16],
    }


def exploration_candidate_match_score(concept: dict[str, Any], candidate: dict[str, Any]) -> int:
    if candidate.get("kind") not in set(concept.get("kinds") or []):
        return 0
    desired_state = str(concept.get("stateKey") or "initial")
    candidate_state = str(candidate.get("stateKey") or "initial")
    desired_state = "initial" if desired_state == "root" else desired_state
    candidate_state = "initial" if candidate_state == "root" else candidate_state
    if desired_state != "initial" and candidate_state != desired_state:
        return 0
    region_aliases = [normalize_exploration_semantic_name(value) for value in concept.get("regionAliases") or []]
    region_aliases = [value for value in region_aliases if value]
    candidate_region = normalize_exploration_semantic_name(candidate.get("regionName") or candidate.get("area") or "")
    if region_aliases and not any(alias in candidate_region or candidate_region in alias for alias in region_aliases):
        return 0
    candidate_name = str(candidate.get("normalizedName") or "")
    aliases = [normalize_exploration_semantic_name(value) for value in concept.get("aliases") or []]
    aliases = [value for value in aliases if value]
    intent = concept.get("intent")
    raw_name = str(candidate.get("name") or "")
    if intent == "category-all" and not re.search(r"^(?:全部|所有)(?:分类)?$", raw_name.strip(), re.IGNORECASE):
        return 0
    score = 0
    if candidate_name in aliases:
        score = 100
    elif any(alias in candidate_name or candidate_name in alias for alias in aliases if min(len(alias), len(candidate_name)) >= 2):
        score = 88
    if intent == "publish-navigation" and "发布" in raw_name:
        score = max(score, 100 if candidate.get("kind") in {"link", "menuitem", "tab"} else 82)
    elif intent == "skill-detail" and re.search(r"查看技能|技能详情", raw_name):
        score = max(score, 94)
    elif intent == "ordinal-record" and exploration_candidate_is_list_record(candidate):
        score = max(score, 94)
        requested_index = int(concept.get("selectionIndex") or 0)
        if requested_index and exploration_candidate_record_ordinal(candidate) == requested_index:
            score = max(score, 108)
    elif intent == "category" and re.search(r"浏览分类", raw_name):
        score = max(score, 92)
    elif intent == "category-all" and re.search(r"^(?:全部|所有)", raw_name):
        score = max(score, 96)
    elif intent == "sort":
        desired_option = concept.get("desiredOption") if isinstance(concept.get("desiredOption"), dict) else {}
        desired_label = normalize_exploration_semantic_name(desired_option.get("label") or "")
        desired_value = str(desired_option.get("value") or "")
        options = candidate.get("options") if isinstance(candidate.get("options"), list) else []
        option_match = any(
            normalize_exploration_semantic_name(option.get("label") or option.get("text") or "") == desired_label
            or (desired_value and str(option.get("value") or "") == desired_value)
            for option in options
            if isinstance(option, dict)
        )
        if candidate.get("kind") == "combobox" and option_match:
            score = max(score, 105)
        elif candidate.get("kind") == "combobox" and any(alias and alias in candidate_name for alias in aliases):
            score = max(score, 92)
    elif intent == "search" and candidate.get("kind") == "textbox" and EXPLORATION_SEARCH_INTENT_PATTERN.search(raw_name):
        score = max(score, 96)
    elif intent == "login" and any(alias and alias in candidate_name for alias in aliases):
        score = max(score, 94)
    safety_class = str((candidate.get("safety") or {}).get("class") or "")
    if safety_class == "irreversible" or (safety_class == "external-navigation" and concept.get("action") != "locate"):
        return 0
    if score and desired_state == candidate_state:
        score += 3
    return score


def best_exploration_candidate(
    concept: dict[str, Any],
    inventory: list[dict[str, Any]],
    preferred_candidate_id: str = "",
) -> tuple[dict[str, Any] | None, int]:
    ranked = []
    for candidate in inventory:
        score = exploration_candidate_match_score(concept, candidate)
        if preferred_candidate_id and candidate.get("candidateId") == preferred_candidate_id:
            score = max(score, 110)
        if score:
            ranked.append((score, int(candidate.get("inventoryIndex") or 0), str(candidate.get("candidateId") or ""), candidate))
    if not ranked:
        return None, 0
    ranked.sort(key=lambda item: (-item[0], item[1], item[2]))
    if str(concept.get("selectionPolicy") or "") == "nth-safe":
        selection_index = int(concept.get("selectionIndex") or 0)
        exact_rank = [item for item in ranked if exploration_candidate_record_ordinal(item[3]) == selection_index]
        if exact_rank:
            return exact_rank[0][3], exact_rank[0][0]
        dom_order = sorted(ranked, key=lambda item: (item[1], item[2]))
        if 0 < selection_index <= len(dom_order):
            selected = dom_order[selection_index - 1]
            return selected[3], selected[0]
        return None, 0
    return ranked[0][3], ranked[0][0]


def exploration_expected_for_candidate(
    candidate: dict[str, Any] | None,
    action: str,
    value: str = "",
    *,
    behavior_policy: str = "enforce",
) -> dict[str, Any]:
    if action == "fill":
        return {"valueEquals": value}
    if action == "select":
        return {"valueEquals": value, "behaviorPolicy": behavior_policy}
    if action not in {"click", "select"}:
        return {}
    href = str(((candidate or {}).get("safety") or {}).get("href") or (candidate or {}).get("href") or "")
    if href:
        parsed = urllib.parse.urlparse(href)
        fragment = f"#{parsed.fragment}" if parsed.fragment else ""
        path = parsed.path if parsed.path and parsed.path != "/" else ""
        url_contains = fragment or path
        if url_contains:
            return {"urlContains": url_contains, "stateChanged": True, "behaviorPolicy": behavior_policy}
    return {"stateChanged": True, "behaviorPolicy": behavior_policy}


def exploration_transition_candidate(inventory: list[dict[str, Any]], state_key: str) -> dict[str, Any] | None:
    if state_key == "login":
        pattern = EXPLORATION_LOGIN_ENTRY_PATTERN
    elif state_key == "skills":
        pattern = re.compile(r"^(?:技能库|全部技能|skills)$", re.IGNORECASE)
    else:
        return None
    candidates = [
        candidate for candidate in inventory
        if str(candidate.get("stateKey") or "initial") == "initial"
        and candidate.get("kind") in {"link", "button", "menuitem", "tab"}
        and pattern.search(str(candidate.get("name") or ""))
        and str((candidate.get("safety") or {}).get("class") or "") != "irreversible"
    ]
    return sorted(candidates, key=lambda item: str(item.get("candidateId") or ""))[0] if candidates else None


def exploration_target_from_candidate(
    case_id: str,
    concept: dict[str, Any],
    candidate: dict[str, Any] | None,
) -> dict[str, Any]:
    candidate_id = str((candidate or {}).get("candidateId") or "")
    seed = f"{case_id}|{concept['key']}|{candidate_id or concept['name']}"
    kind = str((candidate or {}).get("kind") or (concept.get("kinds") or ["button"])[0])
    safety = (candidate or {}).get("safety") if isinstance((candidate or {}).get("safety"), dict) else {
        "class": "reversible-state-change" if kind not in {"link", "menuitem", "tab"} else "same-origin-navigation",
        "sameOrigin": None,
        "href": "",
    }
    desired_option = concept.get("desiredOption") if isinstance(concept.get("desiredOption"), dict) else {}
    resolved_option = dict(desired_option)
    if candidate and desired_option:
        desired_label = normalize_exploration_semantic_name(desired_option.get("label") or "")
        desired_value = str(desired_option.get("value") or "")
        matched_option = next((
            option for option in candidate.get("options") or []
            if isinstance(option, dict)
            and (
                (desired_value and str(option.get("value") or "") == desired_value)
                or normalize_exploration_semantic_name(option.get("label") or option.get("text") or "") == desired_label
            )
        ), None)
        if matched_option:
            resolved_option = {
                "label": str(matched_option.get("label") or matched_option.get("text") or desired_option.get("label") or ""),
                "value": str(matched_option.get("value") or desired_option.get("value") or ""),
            }
    return {
        "targetId": f"target-{hashlib.sha256(seed.encode('utf-8')).hexdigest()[:12]}",
        "candidateId": candidate_id,
        "kind": kind,
        "name": str((candidate or {}).get("name") or concept["name"]),
        "aliases": list(dict.fromkeys([*concept.get("aliases", []), str((candidate or {}).get("locatorValue") or "")])),
        "caseIds": [case_id],
        "stateKey": concept.get("stateKey") or "initial",
        "required": True,
        "exact": bool(candidate),
        "locatorHints": exploration_candidate_locator_hints(candidate or {}),
        "evidenceSource": "preflight" if candidate else "case-intent",
        "href": str(safety.get("href") or ""),
        "safety": safety,
        "controlType": str(concept.get("controlType") or kind),
        "desiredOption": resolved_option,
        "regionName": str((candidate or {}).get("regionName") or (candidate or {}).get("area") or ""),
        "regionAliases": list(concept.get("regionAliases") or []),
        "selectionPolicy": str(concept.get("selectionPolicy") or "best-match"),
        "selectionIndex": int(concept.get("selectionIndex") or 0),
        "stateEvidenceSource": str((candidate or {}).get("stateEvidenceSource") or ("case-intent" if not candidate else "preflight")),
        "stateRequestedUrl": str((candidate or {}).get("stateRequestedUrl") or ""),
        "stateFinalUrl": str((candidate or {}).get("stateFinalUrl") or ""),
        "stateAccessGate": (candidate or {}).get("stateAccessGate") if isinstance((candidate or {}).get("stateAccessGate"), dict) else {},
        "destinationStateKey": str((candidate or {}).get("destinationStateKey") or ""),
        "destinationFinalUrl": str((candidate or {}).get("destinationFinalUrl") or ""),
        "destinationAccessGate": (candidate or {}).get("destinationAccessGate") if isinstance((candidate or {}).get("destinationAccessGate"), dict) else {},
    }


def merge_read_only_state_journeys(journeys: list[dict[str, Any]]) -> list[dict[str, Any]]:
    merged: list[dict[str, Any]] = []
    grouped: dict[tuple[str, tuple[str, ...]], dict[str, Any]] = {}
    for journey in journeys:
        steps = journey.get("steps") or []
        unsafe_actions = [
            step for step in steps
            if step.get("action") not in {"navigate", "locate", "snapshot"}
            and not (step.get("action") == "click" and step.get("stateTransition"))
        ]
        transition_ids = tuple(
            str(step.get("targetId") or "")
            for step in steps
            if step.get("stateTransition")
        )
        if unsafe_actions:
            merged.append(journey)
            continue
        key = (str(journey.get("requiredState") or journey.get("stateKey") or "root"), transition_ids)
        existing = grouped.get(key)
        if existing is None:
            existing = {
                **journey,
                "caseIds": list(journey.get("caseIds") or []),
                "steps": [dict(step) for step in steps],
            }
            grouped[key] = existing
            merged.append(existing)
            continue
        existing["caseIds"] = list(dict.fromkeys([*existing.get("caseIds", []), *journey.get("caseIds", [])]))
        existing_locates = {str(step.get("targetId") or "") for step in existing["steps"] if step.get("action") == "locate"}
        snapshot_index = next((index for index, step in enumerate(existing["steps"]) if step.get("action") == "snapshot"), len(existing["steps"]))
        for step in steps:
            if step.get("action") != "locate" or str(step.get("targetId") or "") in existing_locates:
                continue
            existing["steps"].insert(snapshot_index, dict(step))
            snapshot_index += 1
            existing_locates.add(str(step.get("targetId") or ""))
        existing["title"] = f"{key[0]} 页面状态与控件证据"
    return merged


def saucedemo_case_scope(case: sqlite3.Row | dict[str, Any]) -> str:
    source = "\n".join(
        str(exploration_case_value(case, key) or "")
        for key in ("title", "requirement", "preconditions", "steps", "expected", "automation_notes")
    )
    if (
        re.search(r"(?:访问|打开|展示).{0,20}(?:登录页|登录页面|登录表单)|登录页.{0,12}(?:可访问|可见|展示)", source, re.IGNORECASE)
        and not re.search(r"(?:输入|填写).{0,16}(?:账号|用户名|密码)|点击\s*Login|登录成功|完成登录", source, re.IGNORECASE)
    ):
        return "login-page"
    if re.search(r"checkout-step-one|进入.{0,12}(?:结账|结算)|(?:结账|结算).{0,12}(?:信息页|流程)|点击\s*Checkout", source, re.IGNORECASE):
        return "checkout"
    if re.search(r"购物车(?:中|页面).{0,16}(?:展示|显示|商品)|已添加商品显示在购物车|读取购物车商品", source, re.IGNORECASE):
        return "cart"
    if re.search(r"添加.{0,12}(?:商品|产品)?.{0,8}购物车|加入购物车|加购|Add\s+to\s+cart|购物车角标", source, re.IGNORECASE):
        return "add"
    if re.search(
        r"(?:输入|填写).{0,16}(?:账号|用户名|密码)|点击\s*Login|使用.{0,24}(?:账号|用户名).{0,16}(?:登录成功|成功登录)",
        source,
        re.IGNORECASE,
    ):
        return "login"
    if re.search(r"商品列表|商品页面|商品页|可购买商品|inventory(?:\.html|\s+item)", source, re.IGNORECASE):
        return "inventory"
    if re.search(r"登录成功|完成登录|有效账号登录|成功登录|点击\s*Login|sign[ -]?in|log[ -]?in", source, re.IGNORECASE):
        return "login"
    return ""


def saucedemo_exploration_plan(
    item: sqlite3.Row | dict[str, Any],
    parsed_cases: list[dict[str, str]],
) -> dict[str, Any] | None:
    if not is_sauce_demo_item(item):
        return None
    item_keys = item.keys() if hasattr(item, "keys") else item
    credentials = parse_test_data(" ".join(
        str(item[key] or "")
        for key in ("test_data", "requirement")
        if key in item_keys
    ))
    if not credentials.get("username") or not credentials.get("password"):
        return None

    case_scopes = {
        case["external_id"]: scope
        for case in parsed_cases
        for scope in [saucedemo_case_scope(case)]
        if scope
    }

    p0_ids = {
        case["external_id"]
        for case in parsed_cases
        if str(case.get("priority") or "P1").upper() == "P0"
    }
    if not p0_ids or not p0_ids.issubset(case_scopes):
        return None

    target_specs = {
        "username": ("textbox", "用户名", "initial", [{"locatorType": "testid", "locatorValue": "username", "locatorRole": ""}], "read-only"),
        "password": ("password", "密码", "initial", [{"locatorType": "testid", "locatorValue": "password", "locatorRole": ""}], "read-only"),
        "login": ("button", "Login", "initial", [{"locatorType": "testid", "locatorValue": "login-button", "locatorRole": "button"}], "reversible-state-change"),
        "add": ("button", "Add to cart", "inventory", [{"locatorType": "css", "locatorValue": "[data-test^=\"add-to-cart-\"]", "locatorRole": "button"}], "reversible-state-change"),
        "cart": ("link", "购物车", "inventory-added", [{"locatorType": "testid", "locatorValue": "shopping-cart-link", "locatorRole": "link"}], "same-origin-navigation"),
        "checkout": ("button", "Checkout", "cart", [{"locatorType": "testid", "locatorValue": "checkout", "locatorRole": "button"}], "reversible-state-change"),
    }
    target_cases = {
        "username": list(case_scopes),
        "password": list(case_scopes),
        "login": list(case_scopes),
        "add": [case_id for case_id, scope in case_scopes.items() if scope in {"add", "cart", "checkout"}],
        "cart": [case_id for case_id, scope in case_scopes.items() if scope in {"cart", "checkout"}],
        "checkout": [case_id for case_id, scope in case_scopes.items() if scope == "checkout"],
    }
    targets = []
    for key, case_ids in target_cases.items():
        if not case_ids:
            continue
        kind, name, state_key, hints, safety_class = target_specs[key]
        targets.append({
            "targetId": f"sauce-{key}",
            "kind": kind,
            "name": name,
            "aliases": [name],
            "caseIds": case_ids,
            "stateKey": state_key,
            "required": True,
            "locatorHints": hints,
            "evidenceSource": "saucedemo-domain-contract",
            "safety": {"class": safety_class, "sameOrigin": True},
            "selectionPolicy": "first-safe" if key == "add" else "best-match",
        })

    target_ids = {target["targetId"] for target in targets}
    scope_destination_states = {
        "login-page": "login-page",
        "login": "inventory",
        "inventory": "inventory",
        "add": "inventory-added",
        "cart": "cart",
        "checkout": "checkout",
    }
    journeys = []
    for case in parsed_cases:
        case_id = case["external_id"]
        scope = case_scopes.get(case_id)
        if not scope:
            continue
        steps = [{"action": "navigate", "targetId": "", "value": "", "description": "打开 SauceDemo 登录页", "expected": {}}]
        if scope == "login-page":
            steps.extend([
                {"action": "locate", "targetId": "sauce-username", "value": "", "description": "确认用户名输入框可见", "expected": {}},
                {"action": "locate", "targetId": "sauce-password", "value": "", "description": "确认密码输入框可见", "expected": {}},
                {"action": "locate", "targetId": "sauce-login", "value": "", "description": "确认 Login 按钮可用", "expected": {}},
            ])
        else:
            steps.extend([
                {"action": "fill", "targetId": "sauce-username", "value": credentials["username"], "description": "填写需求提供的用户名", "expected": {"valueEquals": credentials["username"]}},
                {"action": "fill", "targetId": "sauce-password", "value": credentials["password"], "description": "填写需求提供的密码", "expected": {"valueEquals": credentials["password"]}},
                {"action": "click", "targetId": "sauce-login", "value": "", "description": "点击 Login 并进入商品列表", "expected": {"urlContains": "/inventory.html"}},
            ])
        if scope in {"add", "cart", "checkout"}:
            steps.append({"action": "click", "targetId": "sauce-add", "value": "", "description": "选择首个稳定、可见且启用的商品并加入购物车", "expected": {"stateChanged": True}})
        if scope in {"cart", "checkout"}:
            steps.extend([
                {"action": "click", "targetId": "sauce-cart", "value": "", "description": "进入购物车", "expected": {"urlContains": "/cart.html"}},
            ])
        if scope == "checkout":
            steps.append({
                "action": "click",
                "targetId": "sauce-checkout",
                "value": "",
                "description": "点击 Checkout 进入结账信息页",
                "expected": {"urlContains": "/checkout-step-one.html"},
            })
        steps.append({"action": "snapshot", "targetId": "", "value": "", "description": f"记录 {case['title']} 页面状态", "expected": {}})
        if any(step.get("targetId") and step["targetId"] not in target_ids for step in steps):
            return None
        semantic_destination_state = scope_destination_states[scope]
        evidence_state_key = f"{semantic_destination_state}-{hashlib.sha256(case_id.encode('utf-8')).hexdigest()[:8]}"
        journeys.append({
            "journeyId": f"sauce-{scope}-{hashlib.sha256(case_id.encode('utf-8')).hexdigest()[:8]}",
            "title": case["title"],
            "stateKey": evidence_state_key,
            "requiredState": "root",
            "destinationState": evidence_state_key,
            "semanticDestinationState": semantic_destination_state,
            "entryPath": [],
            "caseIds": [case_id],
            "steps": steps,
        })

    blocked_cases = [
        {
            "caseId": case["external_id"],
            "priority": str(case.get("priority") or "P1").upper(),
            "code": "non_core_saucedemo_scope",
            "reason": "该场景不属于登录、加购或进入结账信息页的本次核心安全范围",
            "missingTargets": [],
        }
        for case in parsed_cases
        if case["external_id"] not in case_scopes
    ]
    return {
        "version": EXPLORATION_PLANNER_VERSION,
        "plannerVersion": EXPLORATION_PLANNER_VERSION,
        "source": "saucedemo-domain-contract",
        "caseContracts": [],
        "caseStateAssignments": [
            {
                "caseId": case["external_id"],
                "requiredState": "root",
                "destinationState": f"{scope_destination_states[case_scopes[case['external_id']]]}-{hashlib.sha256(case['external_id'].encode('utf-8')).hexdigest()[:8]}",
                "semanticDestinationState": scope_destination_states[case_scopes[case["external_id"]]],
                "requiredTargets": [
                    target["name"]
                    for target in targets
                    if case["external_id"] in target.get("caseIds", [])
                ],
                "entryPath": [],
            }
            for case in parsed_cases
            if case["external_id"] in case_scopes
        ],
        "stateGraph": {},
        "plannedCaseIds": list(case_scopes),
        "blockedCases": blocked_cases,
        "targets": targets,
        "journeys": journeys,
    }


def compile_exploration_plan_v5(
    item: sqlite3.Row,
    parsed_cases: list[dict[str, str]],
    preflight: dict[str, Any] | None,
    mappings: dict[str, dict[str, str]] | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    started = time.monotonic()
    sauce_plan = saucedemo_exploration_plan(item, parsed_cases)
    if sauce_plan:
        return sauce_plan, {
            "plannerVersion": EXPLORATION_PLANNER_VERSION,
            "candidateCount": len((preflight or {}).get("elements") or []),
            "caseCount": len(parsed_cases),
            "plannedCaseCount": len(sauce_plan["plannedCaseIds"]),
            "blockedCaseCount": len(sauce_plan["blockedCases"]),
            "localMatchedTargetCount": len(sauce_plan["targets"]),
            "inferredTargetCount": 0,
            "repairActions": [],
            "blockedCases": sauce_plan["blockedCases"],
            "localCompileMs": int((time.monotonic() - started) * 1000),
            "domainContract": "saucedemo",
        }
    target_url = str(item["target_url"] or "")
    inventory = exploration_candidate_inventory(preflight, target_url)
    contracts = [exploration_case_contract(case, item) for case in parsed_cases]
    state_graph = exploration_state_graph(item, inventory)
    case_source_by_id = {case["external_id"]: exploration_case_intent_source(case) for case in parsed_cases}
    mappings = mappings or {}
    targets: list[dict[str, Any]] = []
    journeys: list[dict[str, Any]] = []
    blocked_cases: list[dict[str, Any]] = []
    planned_case_ids: list[str] = []
    matched_count = 0
    inferred_count = 0
    repair_actions: list[dict[str, Any]] = []

    def append_target(target: dict[str, Any]) -> dict[str, Any]:
        existing = next((
            value for value in targets
            if value["targetId"] == target["targetId"]
            or (
                str(value.get("stateKey") or "") == str(target.get("stateKey") or "")
                and str(value.get("kind") or "") == str(target.get("kind") or "")
                and normalize_exploration_semantic_name(value.get("name")) == normalize_exploration_semantic_name(target.get("name"))
            )
        ), None)
        if existing:
            existing["caseIds"] = list(dict.fromkeys([*existing.get("caseIds", []), *target.get("caseIds", [])]))
            existing["aliases"] = list(dict.fromkeys([*existing.get("aliases", []), *target.get("aliases", [])]))[:8]
            return existing
        targets.append(target)
        return target

    for contract in sorted(contracts, key=lambda value: (EXPLORATION_PRIORITY_RANK.get(value["priority"], 1), value["caseId"])):
        case_id = contract["caseId"]
        case_mapping = mappings.get(case_id) or {}
        unresolved: list[dict[str, Any]] = []
        resolved_concepts: list[tuple[dict[str, Any], dict[str, Any], dict[str, Any] | None]] = []
        if contract["requiredActions"] and not contract["concepts"]:
            blocked_cases.append({
                "caseId": case_id,
                "priority": contract["priority"],
                "code": "missing_target_concept",
                "reason": "交互用例没有描述可定位的目标控件",
                "missingTargets": [contract["title"]],
                "missingActions": list(contract["requiredActions"]),
                "unresolvedConcepts": [],
            })
            continue
        for concept in contract["concepts"]:
            preferred_id = str(case_mapping.get(concept["key"]) or "")
            candidate, score = best_exploration_candidate(concept, inventory, preferred_id)
            if candidate:
                matched_count += 1
                resolved_concepts.append((concept, exploration_target_from_candidate(case_id, concept, candidate), candidate))
                continue
            transition = exploration_transition_candidate(inventory, str(concept.get("stateKey") or "initial"))
            semantic_name = str(case_mapping.get(f"{concept['key']}:semanticName") or concept["name"])
            semantic_allowed = normalize_exploration_semantic_name(semantic_name) in normalize_exploration_semantic_name(case_source_by_id.get(case_id, ""))
            if concept.get("allowInferred") and transition and (semantic_allowed or concept.get("intent") in {"sort", "category-all", "login"}):
                inferred_concept = {**concept, "name": semantic_name, "aliases": list(dict.fromkeys([semantic_name, *concept.get("aliases", [])]))}
                inferred_count += 1
                resolved_concepts.append((inferred_concept, exploration_target_from_candidate(case_id, inferred_concept, None), None))
                continue
            unresolved.append({
                "conceptKey": concept["key"],
                "name": concept["name"],
                "requiredAction": concept["action"],
                "stateKey": concept.get("stateKey") or "initial",
            })

        if unresolved:
            blocked_cases.append({
                "caseId": case_id,
                "priority": contract["priority"],
                "code": "unresolved_target",
                "reason": "缺少可安全执行的真实控件或状态入口",
                "missingTargets": [item["name"] for item in unresolved],
                "missingActions": list(dict.fromkeys(item["requiredAction"] for item in unresolved)),
                "unresolvedConcepts": unresolved,
            })
            continue

        required_state = str(contract.get("requiredState") or "root")
        steps: list[dict[str, Any]] = [{
            "action": "navigate",
            "targetId": "",
            "value": "",
            "description": "打开需求指定目标页面",
            "expected": {},
            "safety": {"class": "read-only"},
        }]
        used_transitions: set[str] = set()
        entry_path: list[dict[str, Any]] = []
        if required_state != "root":
            transition_candidate = exploration_transition_candidate(inventory, required_state)
            if transition_candidate is None:
                blocked_cases.append({
                    "caseId": case_id,
                    "priority": contract["priority"],
                    "code": "required_state_unreachable",
                    "reason": f"无法从根页面进入 {required_state} 页面状态",
                    "missingTargets": [required_state],
                    "missingActions": ["state-transition"],
                    "expectedState": required_state,
                })
                continue
            transition_concept = {
                "key": f"transition-{required_state}",
                "name": str(transition_candidate.get("name") or required_state),
                "aliases": [str(transition_candidate.get("name") or required_state)],
                "kinds": [str(transition_candidate.get("kind") or "link")],
                "action": "click",
                "intent": "transition",
                "stateKey": "initial",
            }
            transition_target = append_target(exploration_target_from_candidate(case_id, transition_concept, transition_candidate))
            transition_step = {
                "action": "click",
                "targetId": transition_target["targetId"],
                "value": "",
                "description": f"进入 {required_state} 页面状态",
                "expected": exploration_expected_for_candidate(transition_candidate, "click"),
                "safety": transition_target["safety"],
                "stateTransition": {"from": "root", "to": required_state},
            }
            steps.append(transition_step)
            entry_path.append({"from": "root", "to": required_state, "targetId": transition_target["targetId"], "name": transition_target["name"]})
            used_transitions.add(required_state)
        input_values = list(contract.get("inputValues") or [])
        credentials = parse_test_data(case_source_by_id.get(case_id, ""))
        for concept, target, candidate in resolved_concepts:
            state_key = str(concept.get("stateKey") or "initial")
            if state_key != "initial" and state_key not in used_transitions:
                transition_candidate = exploration_transition_candidate(inventory, state_key)
                if transition_candidate:
                    transition_concept = {
                        "key": f"transition-{state_key}",
                        "name": str(transition_candidate.get("name") or state_key),
                        "aliases": [str(transition_candidate.get("name") or state_key)],
                        "kinds": [str(transition_candidate.get("kind") or "link")],
                        "action": "click",
                        "intent": "transition",
                        "stateKey": "initial",
                    }
                    transition_target = append_target(exploration_target_from_candidate(case_id, transition_concept, transition_candidate))
                    steps.append({
                        "action": "click",
                        "targetId": transition_target["targetId"],
                        "value": "",
                        "description": f"进入 {state_key} 页面状态",
                        "expected": exploration_expected_for_candidate(transition_candidate, "click"),
                        "safety": transition_target["safety"],
                    })
                    used_transitions.add(state_key)
            target = append_target(target)
            action = str(concept.get("action") or "locate")
            if action == "select" and target["kind"] not in {"combobox", "option"}:
                action = "click"
                repair_actions.append({"caseId": case_id, "type": "action-normalized", "from": "select", "to": "click", "target": target["name"]})
            value = ""
            if action == "fill":
                if concept["key"] == "login-username":
                    value = credentials.get("username", "")
                elif concept["key"] == "login-password":
                    value = credentials.get("password", "")
                elif input_values:
                    value = input_values[0]
                if not value:
                    unresolved.append({"conceptKey": concept["key"], "name": target["name"], "requiredAction": "fill", "stateKey": state_key})
                    break
            elif action == "select":
                desired_option = target.get("desiredOption") if isinstance(target.get("desiredOption"), dict) else {}
                value = str(desired_option.get("value") or desired_option.get("label") or "")
                if not value:
                    unresolved.append({"conceptKey": concept["key"], "name": target["name"], "requiredAction": "select", "stateKey": state_key})
                    break
            steps.append({
                "action": action,
                "targetId": target["targetId"],
                "value": value,
                "description": f"{action} {target['name']}",
                "expected": exploration_expected_for_candidate(candidate, action, value, behavior_policy="record"),
                "safety": target["safety"],
            })
            if concept.get("intent") == "category" and action in {"click", "select"}:
                used_transitions.add("skills")
        if unresolved:
            blocked_cases.append({
                "caseId": case_id,
                "priority": contract["priority"],
                "code": "missing_test_data",
                "reason": "交互动作缺少可追溯测试数据",
                "missingTargets": [item["name"] for item in unresolved],
                "missingActions": ["fill"],
                "unresolvedConcepts": unresolved,
            })
            targets = [target for target in targets if case_id not in target.get("caseIds", [])]
            continue
        steps.append({
            "action": "snapshot",
            "targetId": "",
            "value": "",
            "description": f"记录 {contract['title']} 页面状态证据",
            "expected": {},
            "safety": {"class": "read-only"},
        })
        destination_state = str(contract.get("destinationState") or "")
        journeys.append({
            "journeyId": f"journey-{hashlib.sha256(case_id.encode('utf-8')).hexdigest()[:12]}",
            "title": contract["title"],
            "stateKey": destination_state or required_state,
            "requiredState": required_state,
            "destinationState": destination_state,
            "entryPath": entry_path,
            "caseIds": [case_id],
            "priority": contract["priority"],
            "steps": steps,
        })
        planned_case_ids.append(case_id)

    journeys = merge_read_only_state_journeys(journeys)
    draft = {
        "version": EXPLORATION_PLANNER_VERSION,
        "plannerVersion": EXPLORATION_PLANNER_VERSION,
        "source": "system",
        "caseContracts": contracts,
        "caseStateAssignments": [
            {
                "caseId": contract["caseId"],
                "requiredState": contract.get("requiredState") or "root",
                "destinationState": contract.get("destinationState") or "",
                "requiredTargets": contract.get("requiredTargets") or [],
                "entryPath": next((
                    journey.get("entryPath") or []
                    for journey in journeys
                    if contract["caseId"] in (journey.get("caseIds") or [])
                ), []),
            }
            for contract in contracts
        ],
        "stateGraph": state_graph,
        "plannedCaseIds": planned_case_ids,
        "blockedCases": blocked_cases,
        "targets": targets,
        "journeys": journeys,
    }
    diagnostics = {
        "plannerVersion": EXPLORATION_PLANNER_VERSION,
        "candidateCount": len(inventory),
        "caseCount": len(contracts),
        "plannedCaseCount": len(planned_case_ids),
        "blockedCaseCount": len(blocked_cases),
        "localMatchedTargetCount": matched_count,
        "inferredTargetCount": inferred_count,
        "repairActions": repair_actions,
        "blockedCases": blocked_cases,
        "localCompileMs": int((time.monotonic() - started) * 1000),
    }
    return draft, diagnostics


def ai_exploration_plan(item: sqlite3.Row, cases_markdown: str, preflight: dict[str, Any] | None = None) -> dict[str, Any]:
    parsed_cases = parse_cases_markdown(cases_markdown)
    if not parsed_cases:
        raise ExplorationPlanBuildError("cases_unavailable", "当前没有可用于页面探索的结构化测试用例")
    deterministic_plan = deterministic_exploration_asset_plan(item, parsed_cases, preflight)
    deterministic_error: ExplorationPlanBuildError | None = None
    if deterministic_plan:
        try:
            result = validate_and_normalize_exploration_plan(deterministic_plan, item, parsed_cases, preflight)
            result["source"] = "system"
            return result
        except ExplorationPlanBuildError as exc:
            deterministic_error = exc
            log_event(
                logging.INFO,
                "deterministic_exploration_plan_incomplete",
                component="exploration",
                work_item_id=item["id"],
                error_code=exc.code,
                message=exc.technical_message,
            )
    api_key = get_openai_api_key()
    if not api_key:
        if deterministic_error is not None:
            raise ExplorationPlanBuildError(
                "deterministic_plan_incomplete",
                "本地页面证据不足以覆盖 P0 交互流程，请配置 AI 或进入探索实验室人工接管",
                deterministic_error.technical_message,
                {"deterministicErrorCode": deterministic_error.code},
            )
        raise ExplorationPlanBuildError("ai_not_configured", "AI 未配置且本地规则无法完整提取交互控件，请补充更明确的用例步骤或配置 AI")
    model = get_openai_model()
    base_url = get_openai_base_url()
    schema = {
        "type": "object",
        "additionalProperties": False,
        "properties": {
            "targets": {
                "type": "array",
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "properties": {
                        "targetId": {"type": "string"},
                        "kind": {"type": "string", "enum": sorted(EXPLORATION_TARGET_KINDS)},
                        "name": {"type": "string"},
                        "aliases": {"type": "array", "items": {"type": "string"}},
                        "caseIds": {"type": "array", "items": {"type": "string"}},
                        "stateKey": {"type": "string"},
                        "required": {"type": "boolean"},
                    },
                    "required": ["targetId", "kind", "name", "aliases", "caseIds", "stateKey", "required"],
                },
            },
            "journeys": {
                "type": "array",
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "properties": {
                        "journeyId": {"type": "string"},
                        "title": {"type": "string"},
                        "stateKey": {"type": "string"},
                        "caseIds": {"type": "array", "items": {"type": "string"}},
                        "steps": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "additionalProperties": False,
                                "properties": {
                                    "action": {"type": "string", "enum": sorted(EXPLORATION_ACTIONS)},
                                    "targetId": {"type": "string"},
                                    "value": {"type": "string"},
                                    "description": {"type": "string"},
                                    "expected": {
                                        "type": "object",
                                        "additionalProperties": False,
                                        "properties": {
                                            "urlContains": {"type": "string"},
                                            "urlNotContains": {"type": "string"},
                                            "textAny": {"type": "array", "items": {"type": "string"}},
                                            "textAbsent": {"type": "array", "items": {"type": "string"}},
                                            "stateChanged": {"type": "boolean"},
                                        },
                                        "required": ["urlContains", "urlNotContains", "textAny", "textAbsent", "stateChanged"],
                                    },
                                },
                                "required": ["action", "targetId", "value", "description", "expected"],
                            },
                        },
                    },
                    "required": ["journeyId", "title", "stateKey", "caseIds", "steps"],
                },
            },
        },
        "required": ["targets", "journeys"],
    }
    preflight_prompt = json.dumps(preflight_prompt_payload(preflight), ensure_ascii=False)
    prompt = f"""仅根据目标 URL、页面预探索证据、需求和当前测试用例，生成页面交互控件资产发现计划。
页面探索不是完整测试执行，但必须证明动作抵达了正确页面状态；不要生成 assert action。
先生成 targets，列出后续 Playwright 脚本真正需要操作的输入框、密码框、按钮、链接、选择框等交互控件；不要把成功提示、错误提示、标题或普通文本列为 target。
每个 target 必须关联使用它的全部 caseIds，并用 stateKey 描述控件所在页面状态。相同状态、类型和语义名称的控件必须跨用例合并。
再生成 journeys：每个 journey 是暴露一组 target 的最短状态路径，只允许必要的 navigate、fill、click、select、locate、snapshot。
locate 用于只确认控件存在且可操作；fill/click/select 只用于抵达后续控件所在状态；每个状态最多一个 snapshot。
每个 click/select 必须提供 expected 后置证据：优先 URL 片段或真实可见文本；无法预知文案时设置 stateChanged=true。fill 的值必须来自需求或用例。
包含进入、搜索、切换、提交、登录等交互的用例，journey 不能只有 navigate、locate、snapshot。
journey 不需要覆盖每条用例，只需让每个 required target 至少被 locate、fill、click 或 select 一次。
页面预探索证据是目标 URL 当前真实 DOM 摘要。若登录控件位于唯一登录入口之后，只生成一次点击入口的最短路径。
页面预探索证据提供 locatorRole 时，target kind 必须匹配该真实角色，不要因为需求把链接口语化称为按钮就改成 button。
只有需求或测试用例明确给出 selector 时才使用 selector 类型；填写或选择值只能来自需求和测试用例。
不得执行删除、支付、下单、确认发布、提交发布等不可逆动作；不要为最终提交控件生成可执行路径。
仅用于进入发布页面的 link、menuitem 或 tab 属于安全导航，可以 click 并用 stateChanged 或 URL 变化证明跳转，但进入后不得提交。
不得引用站点模板、历史脚本、历史 selector 或需求之外的业务流程。

目标 URL：{item['target_url']}
页面预探索证据：
{preflight_prompt}

需求原文：
{item['requirement']}

当前测试用例：
{cases_markdown}
"""
    payload = {
        "model": model,
        "input": prompt,
        "max_output_tokens": 8192,
        "text": {
            "verbosity": "low",
            "format": {
                "type": "json_schema",
                "name": "exploration_plan",
                "schema": schema,
                "strict": True,
            }
        },
    }
    if model.lower().startswith("gpt-5"):
        payload["reasoning"] = {"effort": "low"}
    config = ai_runtime_config()
    capability = resolve_ai_capability(api_key, model, base_url, config["provider"])
    raw_text = ""
    validation_error: ExplorationPlanBuildError | None = None
    for attempt in range(2):
        request_payload = payload
        if attempt:
            correction_reason = validation_error.technical_message if validation_error else "返回内容不是有效 JSON"
            request_payload = {
                **payload,
                "input": (
                    f"{prompt}\n\n上一次输出未通过页面探索计划校验：{correction_reason}\n"
                    f"上一次输出摘要：{raw_text[:4000]}\n"
                    f"请重新返回完全符合以下 JSON Schema 的单个 JSON 对象，不要使用 Markdown 代码块：\n"
                    f"{json.dumps(schema, ensure_ascii=False)}"
                ),
            }
        request_completed = False
        request_error: Exception | None = None
        for request_attempt in range(2):
            try:
                raw_text = call_openai_responses_stream(
                    api_key,
                    model,
                    base_url,
                    request_payload,
                    "",
                    timeout=EXPLORATION_PLAN_TIMEOUT_SECONDS,
                    provider=config["provider"],
                )
                request_completed = True
                break
            except Exception as exc:
                request_error = exc
                if request_attempt == 0 and not isinstance(exc, TimeoutError) and ai_error_details(exc).get("retryable"):
                    continue
                details = ai_error_details(exc)
                details.update(
                    provider=config["provider"],
                    model=model,
                    apiProtocol=capability.get("api_protocol", ""),
                    structuredOutputMode=capability.get("structured_output_mode", ""),
                    requestRetries=request_attempt,
                )
                raise ExplorationPlanBuildError(
                    "ai_request_failed",
                    (
                        "AI 页面探索计划生成超时，请检查 AI 服务响应速度后重试"
                        if isinstance(exc, TimeoutError)
                        else "AI 页面探索计划生成失败，请检查 AI 服务后重试"
                    ),
                    openai_error_message(exc),
                    details,
                ) from exc
        if not request_completed:
            raise ExplorationPlanBuildError(
                "ai_request_failed",
                "AI 页面探索计划生成失败，请检查 AI 服务后重试",
                openai_error_message(request_error or RuntimeError("AI 请求失败")),
            )
        try:
            parsed = json.loads(raw_text)
        except (json.JSONDecodeError, TypeError) as exc:
            validation_error = ExplorationPlanBuildError(
                "invalid_ai_response",
                "AI 返回的页面探索计划不是有效 JSON",
                str(exc),
            )
            continue
        try:
            return validate_and_normalize_exploration_plan(parsed, item, parsed_cases, preflight)
        except ExplorationPlanBuildError as exc:
            validation_error = exc
            continue
    if validation_error:
        validation_error.details.update(
            provider=config["provider"],
            model=model,
            apiProtocol=capability.get("api_protocol", ""),
            structuredOutputMode=capability.get("structured_output_mode", ""),
            correctionAttempts=1,
        )
        raise validation_error
    raise ExplorationPlanBuildError("invalid_ai_response", "AI 返回的页面探索计划不是有效 JSON")


def exploration_plan_fingerprint(item: sqlite3.Row, cases_markdown: str, preflight: dict[str, Any] | None) -> str:
    keys = item.keys() if hasattr(item, "keys") else item
    runtime = ai_runtime_config()
    payload = {
        "plannerVersion": EXPLORATION_PLANNER_VERSION,
        "workItemId": str(item["id"] or ""),
        "requirementRevision": int(item["requirement_revision"] or 1) if "requirement_revision" in keys else 1,
        "targetUrl": str(item["target_url"] or ""),
        "casesHash": hashlib.sha256(cases_markdown.encode("utf-8")).hexdigest(),
        "preflightHash": hashlib.sha256(
            json.dumps(preflight_prompt_payload(preflight), ensure_ascii=False, sort_keys=True).encode("utf-8")
        ).hexdigest(),
        "profileId": runtime.get("profile_id", ""),
        "model": runtime.get("model", ""),
        "baseUrl": runtime.get("base_url", ""),
    }
    return hashlib.sha256(json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()


def cached_exploration_plan(work_item_id: str, fingerprint: str) -> tuple[dict[str, Any], dict[str, Any]] | None:
    with get_db() as conn:
        row = conn.execute(
            """
            SELECT plan_json, plan_diagnostics_json
            FROM exploration_runs
            WHERE work_item_id = ?
              AND plan_fingerprint = ?
              AND COALESCE(plan_error_code, '') = ''
              AND COALESCE(plan_json, '') NOT IN ('', '[]')
            ORDER BY started_at DESC
            LIMIT 1
            """,
            (work_item_id, fingerprint),
        ).fetchone()
    if row is None:
        return None
    plan = safe_json_loads(row["plan_json"], {})
    if not isinstance(plan, dict) or int(plan.get("plannerVersion") or 0) != EXPLORATION_PLANNER_VERSION:
        return None
    first_safe_cases = {
        str(contract.get("caseId") or "")
        for contract in plan.get("caseContracts") or []
        if isinstance(contract, dict)
        and any(
            isinstance(concept, dict)
            and concept.get("selectionPolicy") == "first-safe"
            and concept.get("regionAliases")
            for concept in contract.get("concepts") or []
        )
    }
    if first_safe_cases:
        complete_first_safe_cases = {
            str(case_id)
            for target in plan.get("targets") or []
            if isinstance(target, dict)
            and target.get("selectionPolicy") == "first-safe"
            and str(target.get("regionName") or "")
            for case_id in target.get("caseIds") or []
        }
        if not first_safe_cases.issubset(complete_first_safe_cases):
            return None
    diagnostics = safe_json_loads(row["plan_diagnostics_json"], {})
    if not isinstance(diagnostics, dict):
        diagnostics = {}
    diagnostics.update(cacheHit=True, aiUsed=False, plannerVersion=EXPLORATION_PLANNER_VERSION)
    plan = {**plan, "source": "cache", "planFingerprint": fingerprint, "planDiagnostics": diagnostics}
    return plan, diagnostics


def ai_exploration_gap_mappings(
    item: sqlite3.Row,
    blocked_cases: list[dict[str, Any]],
    contracts: list[dict[str, Any]],
    inventory: list[dict[str, Any]],
) -> tuple[dict[str, dict[str, str]], dict[str, Any]]:
    api_key = get_openai_api_key()
    if not api_key or not blocked_cases:
        return {}, {"aiUsed": False, "aiMappingCount": 0}
    blocked_ids = {str(case.get("caseId") or "") for case in blocked_cases}
    contract_payload = [
        {
            "caseId": contract["caseId"],
            "priority": contract["priority"],
            "title": contract["title"],
            "concepts": [
                {
                    "conceptKey": concept["key"],
                    "name": concept["name"],
                    "aliases": concept["aliases"],
                    "kinds": concept["kinds"],
                    "action": concept["action"],
                    "stateKey": concept["stateKey"],
                }
                for concept in contract["concepts"]
            ],
        }
        for contract in contracts
        if contract["caseId"] in blocked_ids
    ]
    candidate_payload = [
        {
            "candidateId": candidate["candidateId"],
            "kind": candidate["kind"],
            "name": candidate["name"],
            "safetyClass": (candidate.get("safety") or {}).get("class", ""),
        }
        for candidate in inventory
        if str((candidate.get("safety") or {}).get("class") or "") not in {"irreversible", "external-navigation"}
    ]
    schema = {
        "type": "object",
        "additionalProperties": False,
        "properties": {
            "mappings": {
                "type": "array",
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "properties": {
                        "caseId": {"type": "string"},
                        "conceptKey": {"type": "string"},
                        "candidateId": {"type": "string"},
                        "semanticName": {"type": "string"},
                    },
                    "required": ["caseId", "conceptKey", "candidateId", "semanticName"],
                },
            },
        },
        "required": ["mappings"],
    }
    prompt = f"""你只负责把未解析的测试用例目标概念映射到真实 DOM 候选，不生成执行步骤、journey、selector 或测试数据。
优先选择 candidateId；只有目标明确位于候选页面之后的新状态时，candidateId 留空并填写测试用例概念中已有的 semanticName。
不得返回候选清单之外的 candidateId，不得映射 irreversible 或 external-navigation 候选。

目标 URL：{item['target_url']}
未解析用例合同：
{json.dumps(contract_payload, ensure_ascii=False)}

安全候选：
{json.dumps(candidate_payload, ensure_ascii=False)}
"""
    config = ai_runtime_config()
    payload = {
        "model": config["model"],
        "input": prompt,
        "max_output_tokens": 2048,
        "text": {
            "verbosity": "low",
            "format": {
                "type": "json_schema",
                "name": "exploration_gap_mappings",
                "schema": schema,
                "strict": True,
            },
        },
    }
    if config["model"].lower().startswith("gpt-5"):
        payload["reasoning"] = {"effort": "low"}
    started = time.monotonic()
    try:
        raw_text = call_openai_responses_stream(
            api_key,
            config["model"],
            config["base_url"],
            payload,
            "",
            timeout=EXPLORATION_PLAN_TIMEOUT_SECONDS,
            provider=config["provider"],
        )
        decoded = json.loads(raw_text)
    except Exception as exc:
        return {}, {
            "aiUsed": True,
            "aiMappingCount": 0,
            "aiElapsedMs": int((time.monotonic() - started) * 1000),
            "aiError": openai_error_message(exc),
        }
    valid_candidates = {candidate["candidateId"] for candidate in inventory}
    valid_contracts = {
        contract["caseId"]: {concept["key"] for concept in contract["concepts"]}
        for contract in contracts
        if contract["caseId"] in blocked_ids
    }
    mappings: dict[str, dict[str, str]] = {}
    accepted = 0
    rejected = 0
    for mapping in decoded.get("mappings") or []:
        if not isinstance(mapping, dict):
            rejected += 1
            continue
        case_id = str(mapping.get("caseId") or "")
        concept_key = str(mapping.get("conceptKey") or "")
        candidate_id = str(mapping.get("candidateId") or "")
        semantic_name = sanitize_exploration_phrase(mapping.get("semanticName"), max_length=80)
        if case_id not in valid_contracts or concept_key not in valid_contracts[case_id]:
            rejected += 1
            continue
        if candidate_id and candidate_id not in valid_candidates:
            rejected += 1
            continue
        if not candidate_id and not semantic_name:
            rejected += 1
            continue
        case_mapping = mappings.setdefault(case_id, {})
        if candidate_id:
            case_mapping[concept_key] = candidate_id
        if semantic_name:
            case_mapping[f"{concept_key}:semanticName"] = semantic_name
        accepted += 1
    return mappings, {
        "aiUsed": True,
        "aiMappingCount": accepted,
        "aiRejectedMappingCount": rejected,
        "aiElapsedMs": int((time.monotonic() - started) * 1000),
    }


def planner_v5_exploration_plan(item: sqlite3.Row, cases_markdown: str, preflight: dict[str, Any] | None = None) -> dict[str, Any]:
    parsed_cases = parse_cases_markdown(cases_markdown)
    if not parsed_cases:
        raise ExplorationPlanBuildError("cases_unavailable", "当前没有可用于页面探索的结构化测试用例")
    fingerprint = exploration_plan_fingerprint(item, cases_markdown, preflight)
    cached = cached_exploration_plan(str(item["id"]), fingerprint)
    if cached:
        return cached[0]

    draft, diagnostics = compile_exploration_plan_v5(item, parsed_cases, preflight)
    inventory = exploration_candidate_inventory(preflight, str(item["target_url"] or ""))
    if draft.get("blockedCases"):
        mappings, ai_diagnostics = ai_exploration_gap_mappings(
            item,
            draft.get("blockedCases") or [],
            draft.get("caseContracts") or [],
            inventory,
        )
    else:
        mappings, ai_diagnostics = {}, {"aiUsed": False, "aiMappingCount": 0}
    diagnostics.update(ai_diagnostics)
    if mappings:
        draft, repaired_diagnostics = compile_exploration_plan_v5(item, parsed_cases, preflight, mappings)
        diagnostics.update({
            "plannedCaseCount": repaired_diagnostics["plannedCaseCount"],
            "blockedCaseCount": repaired_diagnostics["blockedCaseCount"],
            "localMatchedTargetCount": repaired_diagnostics["localMatchedTargetCount"],
            "inferredTargetCount": repaired_diagnostics["inferredTargetCount"],
            "repairActions": repaired_diagnostics["repairActions"],
            "blockedCases": repaired_diagnostics["blockedCases"],
            "recompiledAfterAi": True,
        })
        draft["source"] = "hybrid"

    blocked_cases = draft.get("blockedCases") or []
    blocked_p0 = [case for case in blocked_cases if str(case.get("priority") or "").upper() == "P0"]
    planned_case_ids = {str(case_id) for case_id in draft.get("plannedCaseIds") or [] if str(case_id)}
    planned_p0_case_ids = [
        case["external_id"]
        for case in parsed_cases
        if str(case.get("priority") or "").upper() == "P0" and case["external_id"] in planned_case_ids
    ]
    diagnostics.update(
        cacheHit=False,
        planFingerprint=fingerprint,
        blockedP0CaseIds=[str(case.get("caseId") or "") for case in blocked_p0],
        plannedP0CaseIds=planned_p0_case_ids,
    )
    if not planned_p0_case_ids or not planned_case_ids:
        blocked_scope = blocked_p0 or blocked_cases
        summary = "；".join(
            f"{case.get('caseId')}：{case.get('reason')}（{', '.join(case.get('missingTargets') or []) or '未知目标'}）"
            for case in blocked_scope
        )
        error_code = "missing_target_concept" if any(case.get("code") == "missing_target_concept" for case in blocked_scope) else "planner_contract_unresolved"
        raise ExplorationPlanBuildError(
            error_code,
            f"页面探索计划没有任何可执行 P0 用例：{summary}",
            summary,
            {
                "planFingerprint": fingerprint,
                "planDiagnostics": diagnostics,
                "draftPlan": draft,
            },
        )
    try:
        result = validate_and_normalize_exploration_plan(draft, item, parsed_cases, preflight)
    except ExplorationPlanBuildError as exc:
        exc.details.update(
            planFingerprint=fingerprint,
            planDiagnostics=diagnostics,
            draftPlan=draft,
        )
        raise
    result.update(
        version=EXPLORATION_PLANNER_VERSION,
        plannerVersion=EXPLORATION_PLANNER_VERSION,
        source=draft.get("source") or "system",
        planFingerprint=fingerprint,
        planDiagnostics=diagnostics,
    )
    return result


def sanitize_exploration_plan_draft(plan: Any) -> dict[str, Any]:
    if not isinstance(plan, dict):
        return {}
    sanitized = safe_json_loads(json.dumps(plan, ensure_ascii=False), {})
    if not isinstance(sanitized, dict):
        return {}
    for journey in sanitized.get("journeys") or []:
        if not isinstance(journey, dict):
            continue
        for step in journey.get("steps") or []:
            if not isinstance(step, dict):
                continue
            if str(step.get("action") or "") == "fill" and step.get("value"):
                step["value"] = "[REDACTED]"
            expected = step.get("expected") if isinstance(step.get("expected"), dict) else {}
            if "valueEquals" in expected:
                expected["valueEquals"] = "[REDACTED]"
    for step in sanitized.get("steps") or []:
        if isinstance(step, dict) and str(step.get("action") or "") == "fill" and step.get("value"):
            step["value"] = "[REDACTED]"
    return sanitized


async def build_exploration_plan(item: sqlite3.Row, cases_markdown: str, preflight: dict[str, Any] | None = None) -> dict[str, Any]:
    started_at = time.monotonic()
    try:
        result = await asyncio.to_thread(planner_v5_exploration_plan, item, cases_markdown, preflight)
    except ExplorationPlanBuildError as exc:
        exc.details["elapsedMs"] = int((time.monotonic() - started_at) * 1000)
        log_event(
            logging.ERROR,
            "exploration_plan_failed",
            component="exploration",
            work_item_id=item["id"],
            provider=ai_runtime_config()["provider"],
            model=get_openai_model(),
            error_code=exc.code,
            message=exc.technical_message,
            elapsed_ms=int((time.monotonic() - started_at) * 1000),
        )
        raise
    result["elapsedMs"] = int((time.monotonic() - started_at) * 1000)
    return result


def stored_exploration_plan(value: Any) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    if isinstance(value, list):
        return value, []
    if not isinstance(value, dict):
        return [], []
    scenarios = value.get("journeys") if isinstance(value.get("journeys"), list) else []
    if not scenarios:
        scenarios = value.get("scenarios") if isinstance(value.get("scenarios"), list) else []
    steps = value.get("steps") if isinstance(value.get("steps"), list) else []
    if not steps and scenarios:
        steps = [step for scenario in scenarios for step in scenario.get("steps", []) if isinstance(step, dict)]
    return steps, scenarios


def insert_exploration_step(exploration_run_id: str, work_item_id: str, step: dict[str, Any]) -> None:
    with get_db() as conn:
        conn.execute(
            """
            INSERT INTO exploration_steps (
                exploration_run_id, work_item_id, step_index, action, target, value,
                description, status, case_id, scenario_index, scenario_step_index,
                critical, target_json, expected_json
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                exploration_run_id,
                work_item_id,
                step["index"],
                step["action"],
                step.get("target", ""),
                step.get("value", ""),
                step.get("description", ""),
                "pending",
                step.get("caseId", ""),
                int(step.get("scenarioIndex", 0)),
                int(step.get("scenarioStepIndex", 0)),
                1 if step.get("critical", step.get("action") != "snapshot") else 0,
                json.dumps(step.get("targetMeta") or {}, ensure_ascii=False),
                json.dumps(step.get("expected") or {}, ensure_ascii=False),
            ),
        )


def update_exploration_step(exploration_run_id: str, step_index: int, **fields: Any) -> None:
    if not fields:
        return
    keys = ", ".join(f"{key} = ?" for key in fields)
    with get_db() as conn:
        conn.execute(
            f"UPDATE exploration_steps SET {keys} WHERE exploration_run_id = ? AND step_index = ?",
            [*fields.values(), exploration_run_id, step_index],
        )


CASE_PLACEHOLDER_PATTERNS = (
    re.compile(r"冒烟主流程满足已明确验收标准"),
    re.compile(r"按需求完成核心操作"),
    re.compile(r"观察结果"),
    re.compile(r"页面出现与明确验收标准对应的核心成功状态"),
    re.compile(r"核心流程符合预期"),
    re.compile(r"^(?:测试|验证|检查|校验)(?:\s|[:：]|页面|功能|流程|链接|按钮)"),
)


def acceptance_items_for_item(item: sqlite3.Row | dict[str, Any]) -> list[dict[str, Any]]:
    keys = item.keys() if hasattr(item, "keys") else item
    stored = safe_json_loads(item["analysis_json"] if "analysis_json" in keys else None, {})
    acceptance = str(item["acceptance"] or "") if "acceptance" in keys else ""
    requirement = str(item["requirement"] or "") if "requirement" in keys else ""
    return normalize_acceptance_items(stored.get("acceptanceItems") or stored.get("acceptance_items"), requirement, acceptance)


def normalized_target_words(value: str) -> list[str]:
    text = re.sub(r"(?:页面|按钮|链接|入口|功能|相关|skill)", " ", str(value or ""), flags=re.IGNORECASE)
    return [part.casefold() for part in re.findall(r"[A-Za-z0-9]+|[\u4e00-\u9fff]{2,}", text) if len(part) >= 2]


def matching_navigation_target(data_context: dict[str, Any], target: str) -> dict[str, str]:
    targets = [item for item in data_context.get("navigationTargets") or [] if isinstance(item, dict)]
    words = normalized_target_words(target)
    for candidate in targets:
        name = str(candidate.get("name") or "")
        candidate_text = name.casefold()
        if words and any(word in candidate_text or candidate_text in word for word in words):
            return {"name": name, "href": str(candidate.get("href") or ""), "role": str(candidate.get("role") or "link")}
    return {}


def hash_route(value: str) -> str:
    parsed = urllib.parse.urlsplit(str(value or ""))
    return f"#{parsed.fragment}" if parsed.fragment else parsed.path or str(value or "")


