def row_to_global_assistant_message(row: sqlite3.Row, actions: list[sqlite3.Row] | None = None) -> dict[str, Any]:
    return {
        "id": row["id"],
        "conversationId": row["conversation_id"],
        "role": row["role"],
        "content": row["content"],
        "status": row["status"],
        "modelProfileId": row["model_profile_id"] or "",
        "provider": row["provider"] or "",
        "model": row["model"] or "",
        "errorCode": row["error_code"] or "",
        "createdAt": row["created_at"],
        "updatedAt": row["updated_at"],
        "actions": [row_to_global_assistant_action(action) for action in (actions or [])],
    }


def require_global_assistant_conversation(conn: sqlite3.Connection, conversation_id: str, owner_user_id: str) -> sqlite3.Row:
    row = conn.execute(
        "SELECT * FROM global_assistant_conversations WHERE id = ? AND owner_user_id = ?",
        (conversation_id, owner_user_id),
    ).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail="全局 AI 助手会话不存在")
    return row


def get_global_assistant_conversations(request: Request, page: int = 1, page_size: int = 30) -> dict[str, Any]:
    actor = require_current_user(request)
    normalized_page = max(1, int(page or 1))
    normalized_page_size = min(100, max(1, int(page_size or 30)))
    with get_db() as conn:
        total = conn.execute(
            "SELECT COUNT(*) AS total FROM global_assistant_conversations WHERE owner_user_id = ?",
            (actor["id"],),
        ).fetchone()["total"]
        rows = conn.execute(
            "SELECT * FROM global_assistant_conversations WHERE owner_user_id = ? ORDER BY last_message_at DESC LIMIT ? OFFSET ?",
            (actor["id"], normalized_page_size, (normalized_page - 1) * normalized_page_size),
        ).fetchall()
    return {"items": [row_to_global_assistant_conversation(row) for row in rows], "total": total, "page": normalized_page, "pageSize": normalized_page_size}


def create_global_assistant_conversation(payload: GlobalAssistantConversationCreateRequest, request: Request) -> dict[str, Any]:
    actor = require_current_user(request)
    timestamp = now_iso()
    conversation_id = uuid.uuid4().hex[:16]
    title = payload.title.strip()[:80] or "新对话"
    with get_db() as conn:
        conn.execute(
            "INSERT INTO global_assistant_conversations (id, owner_user_id, title, created_at, updated_at, last_message_at) VALUES (?, ?, ?, ?, ?, ?)",
            (conversation_id, actor["id"], title, timestamp, timestamp, timestamp),
        )
        row = conn.execute("SELECT * FROM global_assistant_conversations WHERE id = ?", (conversation_id,)).fetchone()
    return row_to_global_assistant_conversation(row)


def update_global_assistant_conversation(conversation_id: str, payload: GlobalAssistantConversationPatchRequest, request: Request) -> dict[str, Any]:
    actor = require_current_user(request)
    title = payload.title.strip()
    if not title:
        raise HTTPException(status_code=400, detail="会话名称不能为空")
    if len(title) > 80:
        raise HTTPException(status_code=400, detail="会话名称不能超过 80 个字符")
    with get_db() as conn:
        require_global_assistant_conversation(conn, conversation_id, actor["id"])
        conn.execute("UPDATE global_assistant_conversations SET title = ?, updated_at = ? WHERE id = ?", (title, now_iso(), conversation_id))
        row = conn.execute("SELECT * FROM global_assistant_conversations WHERE id = ?", (conversation_id,)).fetchone()
    return row_to_global_assistant_conversation(row)


def delete_global_assistant_conversation(conversation_id: str, request: Request) -> dict[str, str]:
    actor = require_current_user(request)
    with get_db() as conn:
        require_global_assistant_conversation(conn, conversation_id, actor["id"])
        conn.execute("DELETE FROM global_assistant_actions WHERE conversation_id = ?", (conversation_id,))
        conn.execute("DELETE FROM global_assistant_messages WHERE conversation_id = ?", (conversation_id,))
        conn.execute("DELETE FROM global_assistant_conversations WHERE id = ?", (conversation_id,))
    write_audit_log("global_assistant_conversation_deleted", "全局 AI 助手会话已删除", actor_user_id=actor["id"], metadata={"conversationId": conversation_id})
    return {"status": "deleted"}


def get_global_assistant_messages(conversation_id: str, request: Request, before: str = "", limit: int = 50) -> dict[str, Any]:
    actor = require_current_user(request)
    normalized_limit = min(100, max(1, int(limit or 50)))
    with get_db() as conn:
        require_global_assistant_conversation(conn, conversation_id, actor["id"])
        params: list[Any] = [conversation_id]
        before_clause = ""
        if before:
            before_row = conn.execute(
                "SELECT created_at FROM global_assistant_messages WHERE id = ? AND conversation_id = ?",
                (before, conversation_id),
            ).fetchone()
            if before_row is not None:
                before_clause = " AND created_at < ?"
                params.append(before_row["created_at"])
        rows = conn.execute(
            f"SELECT * FROM global_assistant_messages WHERE conversation_id = ?{before_clause} ORDER BY created_at DESC LIMIT ?",
            (*params, normalized_limit + 1),
        ).fetchall()
    has_more = len(rows) > normalized_limit
    rows = list(reversed(rows[:normalized_limit]))
    actions_by_message: dict[str, list[sqlite3.Row]] = {}
    if rows:
        message_ids = [row["id"] for row in rows]
        placeholders = ",".join("?" for _ in message_ids)
        with get_db() as conn:
            action_rows = conn.execute(
                f"SELECT * FROM global_assistant_actions WHERE message_id IN ({placeholders}) ORDER BY created_at ASC",
                message_ids,
            ).fetchall()
        for action in action_rows:
            actions_by_message.setdefault(action["message_id"], []).append(action)
    return {
        "items": [row_to_global_assistant_message(row, actions_by_message.get(row["id"], [])) for row in rows],
        "hasMore": has_more,
        "nextBefore": rows[0]["id"] if has_more and rows else "",
    }


def truncate_global_assistant_text(value: str, budget: int) -> tuple[str, bool]:
    text = str(value or "")
    if len(text) <= budget:
        return text, False
    marker = "\n\n[中间内容已因模型上下文预算被裁剪，请在需要时要求用户分段提供]\n\n"
    available = max(2, budget - len(marker))
    head = available // 2
    tail = available - head
    return f"{text[:head]}{marker}{text[-tail:]}", True


def global_assistant_history_prompt(rows: list[sqlite3.Row], message: str) -> str:
    current_message, current_truncated = truncate_global_assistant_text(message, GLOBAL_ASSISTANT_CURRENT_MESSAGE_BUDGET)
    system_reserve = 4_000
    remaining_history_budget = max(0, GLOBAL_ASSISTANT_MODEL_INPUT_BUDGET - len(current_message) - system_reserve)
    selected: list[str] = []
    total = 0
    for row in reversed(rows[-20:]):
        line = f"{row['role']}: {row['content']}"
        if total + len(line) > remaining_history_budget:
            break
        selected.append(line)
        total += len(line)
    history = "\n".join(reversed(selected)) or "无"
    truncation_notice = (
        "当前用户消息过长，已仅向模型提供开头和结尾。你必须明确说明未完整读取中间内容，并建议用户分段。"
        if current_truncated else
        "当前用户消息已完整提供。"
    )
    return f"""你是 Web 智能测试平台中的全局 AI 助手，请使用中文，给出准确、清晰、可执行的回答。
你可以解释概念、分析报错、提供排查步骤、测试建议和示例代码。
你可以说明全局助手支持查询项目、功能、用例和脚本；创建调试会话、页面探索和脚本草稿必须经过用户逐步确认。
除非服务端工具结果明确返回成功，否则不能声称已经执行平台操作、运行测试或操作浏览器。
不得建议全局助手执行测试、自愈、同步、发布、删除或修改正式用例与正式脚本。
请从用户的文字描述中识别所在页面、操作步骤、实际现象和预期结果。
如果这些信息不足以定位问题，请先明确追问缺少的信息，不要猜测用户当前所在页面。
不要编造当前平台状态、业务规则或执行结果。
输出使用适合阅读的 Markdown。涉及危险或破坏性操作时必须先提醒风险。
输入完整性：{truncation_notice}

最近对话：
{history}

用户问题：
{current_message}
"""


GLOBAL_ASSISTANT_WRITE_TOOLS = {
    "create_case_debug_session",
    "run_case_page_exploration",
    "generate_case_script_draft",
}


def global_assistant_case_summary(row: sqlite3.Row) -> dict[str, Any]:
    return {
        "id": row["id"],
        "externalId": row["external_id"],
        "title": row["title"],
        "projectId": row["project_id"],
        "featureId": row["feature_id"] or "",
        "priority": row["priority"],
        "status": row["library_status"],
        "updatedAt": row["updated_at"],
    }


def search_global_assistant_cases(query: str, project_id: str = "", feature_id: str = "") -> list[dict[str, Any]]:
    keyword = str(query or "").strip()
    clauses = ["library_status = 'published'"]
    params: list[Any] = []
    if project_id:
        clauses.append("project_id = ?")
        params.append(project_id)
    if feature_id:
        clauses.append("feature_id = ?")
        params.append(feature_id)
    if keyword:
        clauses.append("(id = ? OR external_id = ? OR title LIKE ? OR requirement LIKE ? OR steps LIKE ? OR expected LIKE ?)")
        params.extend([keyword, keyword, f"%{keyword}%", f"%{keyword}%", f"%{keyword}%", f"%{keyword}%"])
    with get_db() as conn:
        rows = conn.execute(
            f"SELECT * FROM test_cases WHERE {' AND '.join(clauses)} ORDER BY updated_at DESC LIMIT 20",
            params,
        ).fetchall()
    return [global_assistant_case_summary(row) for row in rows]


def global_assistant_read_tool(message: str) -> tuple[str, dict[str, Any]] | None:
    text = message.strip()
    case_match = re.search(r"(?:用例(?:ID|编号)?|case)\s*[:：#]?\s*([A-Za-z0-9_-]+)", text, re.I)
    query = case_match.group(1) if case_match else ""
    if not query:
        keyword_match = re.search(r"(?:查询|搜索|查找|获取|查看)用例\s+(.+)$", text)
        query = keyword_match.group(1).strip() if keyword_match else ""
    if any(token in text for token in ("项目列表", "有哪些项目", "查询项目")):
        with get_db() as conn:
            rows = conn.execute("SELECT id, name, project_code, status FROM projects ORDER BY updated_at DESC LIMIT 50").fetchall()
        return "list_projects", {"items": [dict(row) for row in rows]}
    if "功能" in text and any(token in text for token in ("列表", "功能树", "有哪些", "查询")):
        project_match = re.search(r"项目(?:ID)?\s*[:：#]?\s*([A-Za-z0-9_-]+)", text, re.I)
        if not project_match:
            return "list_features", {"needsProjectId": True, "message": "请提供项目 ID 后查询功能树。"}
        project_id = project_match.group(1)
        with get_db() as conn:
            rows = conn.execute(
                "SELECT id, project_id, parent_id, name, description FROM feature_menus WHERE project_id = ? ORDER BY sort_order, created_at LIMIT 200",
                (project_id,),
            ).fetchall()
        return "list_features", {"projectId": project_id, "items": [dict(row) for row in rows]}
    if "脚本" in text and any(token in text for token in ("获取", "查看", "读取", "当前", "绑定")):
        cases = search_global_assistant_cases(query)
        if len(cases) != 1:
            return "get_case_script", {"candidates": cases, "ambiguous": len(cases) > 1, "message": "请提供唯一的用例 ID 或编号。"}
        with get_db() as conn:
            binding = case_debug_source_binding_for_case(conn, cases[0]["id"])
            if binding.get("scriptVersionId"):
                version_row = conn.execute("SELECT * FROM test_script_versions WHERE id = ?", (binding["scriptVersionId"],)).fetchone()
                if version_row is not None:
                    binding = {**binding, **row_to_script_version_detail(conn, version_row)}
        return "get_case_script", {"case": cases[0], "script": binding}
    if "用例" in text and any(token in text for token in ("获取", "查看", "查询", "搜索", "查找", "有哪些", "详情")):
        cases = search_global_assistant_cases(query)
        if any(token in text for token in ("详情", "完整")) and len(cases) == 1:
            with get_db() as conn:
                row = conn.execute("SELECT * FROM test_cases WHERE id = ?", (cases[0]["id"],)).fetchone()
            return "get_test_case", {"case": row_to_test_case(row)}
        return "search_test_cases", {"items": cases, "ambiguous": len(cases) > 1 and bool(query)}
    return None


def global_assistant_write_intent(message: str) -> tuple[str, dict[str, Any]] | None:
    text = message.strip()
    session_match = re.search(r"(?:调试会话|session)(?:ID)?\s*[:：#]?\s*([A-Za-z0-9_-]+)", text, re.I)
    if session_match and "探索" in text:
        return "run_case_page_exploration", {"debugSessionId": session_match.group(1)}
    if session_match and "脚本" in text and any(token in text for token in ("生成", "草稿")):
        return "generate_case_script_draft", {"debugSessionId": session_match.group(1)}
    if "用例" in text and any(token in text for token in ("调试", "页面探索", "探索页面", "生成新脚本", "生成脚本草稿")):
        match = re.search(r"(?:用例(?:ID|编号)?|case)\s*[:：#]?\s*([A-Za-z0-9_-]+)", text, re.I)
        cases = search_global_assistant_cases(match.group(1) if match else "")
        if len(cases) == 1:
            return "create_case_debug_session", {"caseId": cases[0]["id"], "case": cases[0]}
        return "create_case_debug_session", {"candidates": cases, "ambiguous": True}
    return None


def create_global_assistant_action(
    actor: dict[str, Any], conversation_id: str, message_id: str, tool_name: str, arguments: dict[str, Any],
) -> dict[str, Any]:
    if tool_name not in GLOBAL_ASSISTANT_WRITE_TOOLS:
        raise HTTPException(status_code=400, detail="不支持的全局助手操作")
    action_id = uuid.uuid4().hex[:16]
    timestamp = now_iso()
    expires_at = (datetime.now(timezone.utc) + timedelta(minutes=GLOBAL_ASSISTANT_ACTION_TTL_MINUTES)).isoformat()
    args_json = json.dumps(arguments, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    args_hash = hashlib.sha256(args_json.encode("utf-8")).hexdigest()
    labels = {
        "create_case_debug_session": ("创建单用例调试会话", "创建隔离调试空间，不修改正式用例或脚本"),
        "run_case_page_exploration": ("执行单用例页面探索", "在隔离调试会话中访问页面并保存探索结果"),
        "generate_case_script_draft": ("生成单用例脚本草稿", "生成隔离草稿，不覆盖或发布正式脚本"),
    }
    summary, effect = labels[tool_name]
    with get_db() as conn:
        require_global_assistant_conversation(conn, conversation_id, actor["id"])
        conn.execute(
            """INSERT INTO global_assistant_actions
            (id, owner_user_id, conversation_id, message_id, tool_name, args_json, args_hash, summary, effect,
             risk_level, status, result_json, error, expires_at, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'confirm', 'proposed', '{}', '', ?, ?, ?)""",
            (action_id, actor["id"], conversation_id, message_id, tool_name, args_json, args_hash, summary, effect, expires_at, timestamp, timestamp),
        )
        row = conn.execute("SELECT * FROM global_assistant_actions WHERE id = ?", (action_id,)).fetchone()
    return row_to_global_assistant_action(row)


def global_assistant_tool_markdown(tool_name: str, result: dict[str, Any]) -> str:
    if result.get("message") and not result.get("items") and not result.get("candidates"):
        return str(result["message"])
    items = result.get("items") or result.get("candidates") or []
    if tool_name == "list_projects":
        lines = ["| 项目 ID | 项目名称 | 编码 | 状态 |", "| --- | --- | --- | --- |"]
        lines.extend(f"| {item['id']} | {item['name']} | {item.get('project_code') or '-'} | {item.get('status') or '-'} |" for item in items)
        return "查询到以下项目：\n\n" + "\n".join(lines) if items else "当前没有可访问的项目。"
    if tool_name == "list_features":
        lines = ["| 功能 ID | 功能名称 | 父级 ID |", "| --- | --- | --- |"]
        lines.extend(f"| {item['id']} | {item['name']} | {item.get('parent_id') or '-'} |" for item in items)
        return "查询到以下功能：\n\n" + "\n".join(lines) if items else str(result.get("message") or "该项目暂无功能。")
    if tool_name in {"search_test_cases", "get_case_script"} and items:
        lines = ["找到多个候选用例，请使用唯一的用例 ID 或编号重新提问：", "", "| 用例 ID | 编号 | 标题 |", "| --- | --- | --- |"]
        lines.extend(f"| {item['id']} | {item['externalId']} | {item['title']} |" for item in items)
        return "\n".join(lines)
    if tool_name == "search_test_cases":
        return "没有找到匹配的已发布用例。"
    if tool_name == "get_test_case":
        case = result.get("case") or {}
        return f"### {case.get('externalId', '')} {case.get('title', '')}\n\n- 优先级：{case.get('priority') or '-'}\n- 前置条件：{case.get('preconditions') or '-'}\n- 操作步骤：{case.get('steps') or '-'}\n- 预期结果：{case.get('expected') or '-'}"
    if tool_name == "get_case_script":
        case = result.get("case") or {}
        script = result.get("script") or {}
        content = script.get("content") or ""
        return f"### {case.get('externalId')} {case.get('title')}\n\n- 脚本版本：{script.get('version') or '-'}\n- 状态：{script.get('status') or '未绑定'}\n- 路径：{script.get('specPath') or '-'}\n\n```typescript\n{content[:30000]}\n```" if content else "该用例当前没有绑定脚本。"
    return json.dumps(result, ensure_ascii=False, indent=2)[:30000]


def require_global_assistant_action(conn: sqlite3.Connection, action_id: str, owner_user_id: str) -> sqlite3.Row:
    row = conn.execute(
        "SELECT * FROM global_assistant_actions WHERE id = ? AND owner_user_id = ?",
        (action_id, owner_user_id),
    ).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail="全局助手操作不存在")
    return row


def get_global_assistant_action(action_id: str, request: Request) -> dict[str, Any]:
    actor = require_current_user(request)
    with get_db() as conn:
        return row_to_global_assistant_action(require_global_assistant_action(conn, action_id, actor["id"]))


def reject_global_assistant_action(action_id: str, request: Request) -> dict[str, Any]:
    actor = require_current_user(request)
    with get_db() as conn:
        row = require_global_assistant_action(conn, action_id, actor["id"])
        if row["status"] == "rejected":
            return row_to_global_assistant_action(row)
        if row["status"] != "proposed":
            raise HTTPException(status_code=409, detail="当前操作已处理，不能拒绝")
        conn.execute("UPDATE global_assistant_actions SET status = 'rejected', updated_at = ? WHERE id = ?", (now_iso(), action_id))
        updated = conn.execute("SELECT * FROM global_assistant_actions WHERE id = ?", (action_id,)).fetchone()
    return row_to_global_assistant_action(updated)


async def approve_global_assistant_action(action_id: str, request: Request) -> dict[str, Any]:
    actor = require_role_user(request, {"admin", "lead", "executor"})
    with get_db() as conn:
        row = require_global_assistant_action(conn, action_id, actor["id"])
        if row["status"] == "completed":
            return row_to_global_assistant_action(row)
        if row["status"] != "proposed":
            raise HTTPException(status_code=409, detail="当前操作已处理或正在执行")
        if datetime.fromisoformat(row["expires_at"]) <= datetime.now(timezone.utc):
            conn.execute("UPDATE global_assistant_actions SET status = 'expired', updated_at = ? WHERE id = ?", (now_iso(), action_id))
            raise HTTPException(status_code=409, detail="操作确认已过期，请重新发起")
        args_json = row["args_json"]
        if hashlib.sha256(args_json.encode("utf-8")).hexdigest() != row["args_hash"]:
            raise HTTPException(status_code=409, detail="操作参数校验失败")
        with GLOBAL_ASSISTANT_GENERATIONS_LOCK:
            if actor["id"] in GLOBAL_ASSISTANT_ACTION_USERS:
                raise HTTPException(status_code=429, detail="当前已有一项全局助手操作正在执行")
            GLOBAL_ASSISTANT_ACTION_USERS.add(actor["id"])
        conn.execute("UPDATE global_assistant_actions SET status = 'running', updated_at = ? WHERE id = ?", (now_iso(), action_id))
        tool_name = row["tool_name"]
        arguments = safe_json_loads(args_json, {})
    try:
        if tool_name == "create_case_debug_session":
            case_id = str(arguments.get("caseId") or "")
            with get_db() as conn:
                case_row = require_published_test_case(conn.execute("SELECT * FROM test_cases WHERE id = ?", (case_id,)).fetchone())
                active = conn.execute(
                    "SELECT created_by FROM case_debug_sessions WHERE case_id = ? AND status IN ('draft','running','failed','healing','passed','stale') ORDER BY updated_at DESC LIMIT 1",
                    (case_id,),
                ).fetchone()
                if active is not None and active["created_by"] not in {"", actor["id"]}:
                    raise HTTPException(status_code=409, detail="该用例已有其他用户的活动调试会话")
            result = create_case_debug_session(case_id, CaseDebugSessionCreateRequest(expected_case_updated_at=case_row["updated_at"]))
            result = {"debugSessionId": result["id"], "caseId": case_id, "status": result["status"]}
        elif tool_name in {"run_case_page_exploration", "generate_case_script_draft"}:
            session_id = str(arguments.get("debugSessionId") or "")
            with get_db() as conn:
                session = get_case_debug_row(conn, session_id)
                if session["created_by"] != actor["id"]:
                    raise HTTPException(status_code=403, detail="只能操作本人创建的调试会话")
            if tool_name == "run_case_page_exploration":
                exploration = await run_case_debug_exploration(session_id)
                result = {"debugSessionId": session_id, "explorationRunId": exploration.get("id") or exploration.get("runId") or "", "status": exploration.get("status") or "running"}
            else:
                session = get_case_debug_session(session_id)
                if not session.get("latestExplorationRunId"):
                    raise HTTPException(status_code=409, detail="请先完成页面探索，再生成脚本草稿")
                generated = generate_script_set(
                    session["workItemId"],
                    ContentRequest(asset_mode="refresh", case_ids=[session["caseId"]], debug_session_id=session_id),
                )
                version = next((item for item in generated.get("scriptVersions", []) if item.get("caseId") == session["caseId"]), None)
                if version is None:
                    version = next((item for item in (generated.get("scriptSet") or {}).get("scriptVersions", []) if item.get("caseId") == session["caseId"]), None)
                if version is None:
                    raise HTTPException(status_code=400, detail="未生成当前用例脚本草稿")
                with get_db() as conn:
                    conn.execute("UPDATE case_debug_sessions SET current_script_version_id = ?, status = 'draft', updated_at = ? WHERE id = ?", (version["id"], now_iso(), session_id))
                result = {"debugSessionId": session_id, "scriptVersionId": version["id"], "status": "draft"}
        else:
            raise HTTPException(status_code=400, detail="不支持的全局助手操作")
        with get_db() as conn:
            conn.execute("UPDATE global_assistant_actions SET status = 'completed', result_json = ?, error = '', updated_at = ? WHERE id = ?", (json.dumps(result, ensure_ascii=False), now_iso(), action_id))
            updated = conn.execute("SELECT * FROM global_assistant_actions WHERE id = ?", (action_id,)).fetchone()
        write_audit_log("global_assistant_action_completed", "全局 AI 助手操作已完成", actor_user_id=actor["id"], metadata={"actionId": action_id, "tool": tool_name})
        return row_to_global_assistant_action(updated)
    except Exception as exc:
        detail = str(exc.detail) if isinstance(exc, HTTPException) else str(exc)
        with get_db() as conn:
            conn.execute("UPDATE global_assistant_actions SET status = 'failed', error = ?, updated_at = ? WHERE id = ?", (detail[:1000], now_iso(), action_id))
        raise
    finally:
        with GLOBAL_ASSISTANT_GENERATIONS_LOCK:
            GLOBAL_ASSISTANT_ACTION_USERS.discard(actor["id"])


def normalize_global_assistant_request_id(value: str = "") -> str:
    request_id = value.strip() or uuid.uuid4().hex
    if not re.fullmatch(r"[A-Za-z0-9_-]{8,100}", request_id):
        raise HTTPException(status_code=400, detail="无效的 AI 生成请求 ID")
    return request_id


def persist_cancelled_global_assistant_generation(generation: dict[str, Any]) -> None:
    content = "".join(generation.get("chunks") or []).strip()
    with get_db() as conn:
        conn.execute(
            "UPDATE global_assistant_messages SET content = ?, status = 'cancelled', error_code = 'cancelled', updated_at = ? WHERE id = ? AND status = 'streaming'",
            (content, now_iso(), generation["assistant_message_id"]),
        )
        conn.execute(
            "UPDATE global_assistant_conversations SET updated_at = ?, last_message_at = ? WHERE id = ?",
            (now_iso(), now_iso(), generation["conversation_id"]),
        )


def reserve_global_assistant_generation(user_id: str, generation: dict[str, Any]) -> None:
    stale_generation: dict[str, Any] | None = None
    with GLOBAL_ASSISTANT_GENERATIONS_LOCK:
        now = time.monotonic()
        expired_keys = [
            key for key, cancelled_at in GLOBAL_ASSISTANT_CANCELLED_REQUESTS.items()
            if now - cancelled_at > GLOBAL_ASSISTANT_GENERATION_STALE_SECONDS
        ]
        for key in expired_keys:
            GLOBAL_ASSISTANT_CANCELLED_REQUESTS.pop(key, None)
        cancellation_key = (user_id, generation["request_id"])
        if cancellation_key in GLOBAL_ASSISTANT_CANCELLED_REQUESTS:
            GLOBAL_ASSISTANT_CANCELLED_REQUESTS.pop(cancellation_key, None)
            generation["cancelled"] = True
            return
        active = GLOBAL_ASSISTANT_GENERATIONS.get(user_id)
        if active is not None:
            elapsed = now - float(active.get("started_at") or 0)
            if not active.get("cancelled") and elapsed <= GLOBAL_ASSISTANT_GENERATION_STALE_SECONDS:
                raise HTTPException(status_code=429, detail="当前已有一条 AI 回复正在生成，请稍后再试")
            active["cancelled"] = True
            stale_generation = active
        GLOBAL_ASSISTANT_GENERATIONS[user_id] = generation
    if stale_generation is not None:
        with contextlib.suppress(Exception):
            persist_cancelled_global_assistant_generation(stale_generation)


def release_global_assistant_generation(user_id: str, generation: dict[str, Any]) -> None:
    with GLOBAL_ASSISTANT_GENERATIONS_LOCK:
        if GLOBAL_ASSISTANT_GENERATIONS.get(user_id) is generation:
            GLOBAL_ASSISTANT_GENERATIONS.pop(user_id, None)


def cancel_global_assistant_generation(request_id: str, request: Request) -> dict[str, str]:
    actor = require_current_user(request)
    normalized_request_id = normalize_global_assistant_request_id(request_id)
    with GLOBAL_ASSISTANT_GENERATIONS_LOCK:
        generation = GLOBAL_ASSISTANT_GENERATIONS.get(actor["id"])
        if generation is None or generation.get("request_id") != normalized_request_id:
            GLOBAL_ASSISTANT_CANCELLED_REQUESTS[(actor["id"], normalized_request_id)] = time.monotonic()
            return {"status": "not-active", "requestId": normalized_request_id}
        generation["cancelled"] = True
        GLOBAL_ASSISTANT_GENERATIONS.pop(actor["id"], None)
    persist_cancelled_global_assistant_generation(generation)
    write_audit_log(
        "global_assistant_generation_cancelled",
        "全局 AI 助手生成已停止",
        actor_user_id=actor["id"],
        metadata={
            "conversationId": generation["conversation_id"],
            "requestId": normalized_request_id,
            "messageId": generation["assistant_message_id"],
            "outputLength": len("".join(generation.get("chunks") or [])),
        },
    )
    return {
        "status": "cancelled",
        "requestId": normalized_request_id,
        "messageId": generation["assistant_message_id"],
    }


def stream_global_assistant_message(conversation_id: str, payload: GlobalAssistantMessageRequest, request: Request) -> StreamingResponse:
    actor = require_current_user(request)
    message = payload.message.strip()
    if not message:
        raise HTTPException(status_code=400, detail="请输入要发送给全局 AI 助手的内容")
    if len(message) > GLOBAL_ASSISTANT_MAX_MESSAGE_CHARS:
        raise HTTPException(status_code=400, detail="单条消息不能超过 200,000 个字符，请分段发送")
    request_id = normalize_global_assistant_request_id(payload.request_id)
    config = ai_runtime_config()
    if not config["api_key"] or os.environ.get("QA_DISABLE_AI") == "1":
        raise HTTPException(status_code=409, detail="AI 未配置，请先在 AI 配置中启用可用模型")
    timestamp = now_iso()
    user_message_id = uuid.uuid4().hex[:16]
    assistant_message_id = uuid.uuid4().hex[:16]
    with get_db() as conn:
        conversation = require_global_assistant_conversation(conn, conversation_id, actor["id"])
        history = conn.execute(
            "SELECT role, content FROM global_assistant_messages WHERE conversation_id = ? AND status = 'completed' ORDER BY created_at DESC LIMIT 20",
            (conversation_id,),
        ).fetchall()
    generation = {
        "request_id": request_id,
        "user_id": actor["id"],
        "conversation_id": conversation_id,
        "user_message_id": user_message_id,
        "assistant_message_id": assistant_message_id,
        "started_at": time.monotonic(),
        "cancelled": False,
        "chunks": [],
    }
    reserve_global_assistant_generation(actor["id"], generation)
    try:
        with get_db() as conn:
            conversation = require_global_assistant_conversation(conn, conversation_id, actor["id"])
            conn.execute(
                "INSERT INTO global_assistant_messages (id, conversation_id, role, content, status, context_json, model_profile_id, provider, model, error_code, created_at, updated_at) VALUES (?, ?, 'user', ?, 'completed', ?, '', '', '', '', ?, ?)",
                (user_message_id, conversation_id, message, "{}", timestamp, timestamp),
            )
            conn.execute(
                "INSERT INTO global_assistant_messages (id, conversation_id, role, content, status, context_json, model_profile_id, provider, model, error_code, created_at, updated_at) VALUES (?, ?, 'assistant', '', ?, '{}', ?, ?, ?, ?, ?, ?)",
                (
                    assistant_message_id,
                    conversation_id,
                    "cancelled" if generation["cancelled"] else "streaming",
                    config["profile_id"],
                    config["provider"],
                    config["model"],
                    "cancelled" if generation["cancelled"] else "",
                    timestamp,
                    timestamp,
                ),
            )
            next_title = conversation["title"]
            if next_title == "新对话":
                next_title = re.sub(r"\s+", " ", message)[:36]
            conn.execute(
                "UPDATE global_assistant_conversations SET title = ?, updated_at = ?, last_message_at = ? WHERE id = ?",
                (next_title, timestamp, timestamp, conversation_id),
            )
    except Exception:
        release_global_assistant_generation(actor["id"], generation)
        raise
    read_tool = global_assistant_read_tool(message)
    write_intent = global_assistant_write_intent(message) if read_tool is None else None
    action: dict[str, Any] | None = None
    tool_name = ""
    tool_result: dict[str, Any] | None = None
    direct_content = ""
    if read_tool is not None:
        tool_name, tool_result = read_tool
        direct_content = global_assistant_tool_markdown(tool_name, tool_result)
    elif write_intent is not None:
        tool_name, arguments = write_intent
        if arguments.get("ambiguous"):
            tool_result = {"candidates": arguments.get("candidates") or [], "ambiguous": True}
            direct_content = global_assistant_tool_markdown("search_test_cases", tool_result)
        else:
            action = create_global_assistant_action(actor, conversation_id, assistant_message_id, tool_name, arguments)
            direct_content = f"我已准备操作：**{action['summary']}**。\n\n{action['effect']}。请确认后执行；确认将在 {GLOBAL_ASSISTANT_ACTION_TTL_MINUTES} 分钟后过期。"
    prompt = global_assistant_history_prompt(list(reversed(history)), message)
    request_payload = {"model": config["model"], "input": prompt, "max_output_tokens": 4_000}

    def events() -> Iterator[str]:
        chunks = generation["chunks"]
        status = "cancelled"
        error_code = "cancelled"
        started = time.monotonic()
        try:
            yield ndjson_event("started", requestId=request_id, conversationId=conversation_id, userMessageId=user_message_id, assistantMessageId=assistant_message_id, model=config["model"])
            if generation["cancelled"]:
                yield ndjson_event("cancelled", requestId=request_id, messageId=assistant_message_id, content="")
                return
            if direct_content:
                if tool_name:
                    yield ndjson_event("tool_started", requestId=request_id, messageId=assistant_message_id, toolName=tool_name)
                if tool_result is not None:
                    yield ndjson_event("tool_result", requestId=request_id, messageId=assistant_message_id, toolName=tool_name, result=tool_result)
                if action is not None:
                    yield ndjson_event("action_proposed", requestId=request_id, messageId=assistant_message_id, action=action)
                chunks.append(direct_content)
                status = "completed"
                error_code = ""
                yield ndjson_event("completed", messageId=assistant_message_id, content=direct_content)
                return
            for delta in iter_openai_stream_deltas(
                config["api_key"], config["model"], config["base_url"], request_payload,
                timeout=60, provider=config["provider"],
            ):
                if generation["cancelled"]:
                    yield ndjson_event("cancelled", requestId=request_id, messageId=assistant_message_id, content="".join(chunks).strip())
                    return
                chunks.append(delta)
                yield ndjson_event("delta", messageId=assistant_message_id, delta=delta)
            if generation["cancelled"]:
                yield ndjson_event("cancelled", requestId=request_id, messageId=assistant_message_id, content="".join(chunks).strip())
                return
            content = "".join(chunks).strip()
            if not content:
                raise AIRequestError("AI 返回了空回复")
            status = "completed"
            error_code = ""
            yield ndjson_event("completed", messageId=assistant_message_id, content=content)
        except GeneratorExit:
            generation["cancelled"] = True
            raise
        except Exception as exc:
            if generation["cancelled"]:
                status = "cancelled"
                error_code = "cancelled"
            else:
                status = "failed"
                error_code = getattr(exc, "provider_code", "") or ("timeout" if isinstance(exc, TimeoutError) else "provider_error")
                yield ndjson_event("error", messageId=assistant_message_id, code=error_code, message=openai_error_message(exc) or "AI 回复生成失败")
        finally:
            if generation["cancelled"]:
                status = "cancelled"
                error_code = "cancelled"
            content = "".join(chunks).strip()
            with contextlib.suppress(Exception):
                with get_db() as conn:
                    conn.execute(
                        "UPDATE global_assistant_messages SET content = ?, status = ?, error_code = ?, updated_at = ? WHERE id = ?",
                        (content, status, error_code, now_iso(), assistant_message_id),
                    )
                    conn.execute(
                        "UPDATE global_assistant_conversations SET updated_at = ?, last_message_at = ? WHERE id = ?",
                        (now_iso(), now_iso(), conversation_id),
                    )
            release_global_assistant_generation(actor["id"], generation)
            write_audit_log(
                "global_assistant_message_completed",
                "全局 AI 助手请求已结束",
                actor_user_id=actor["id"],
                metadata={
                    "conversationId": conversation_id,
                    "provider": config["provider"],
                    "model": config["model"],
                    "status": status,
                    "inputLength": len(message),
                    "outputLength": len(content),
                    "elapsedMs": int((time.monotonic() - started) * 1000),
                },
            )

    return manual_generation_stream_response(events())


def commit_case_assistant_proposals(
    conn: sqlite3.Connection,
    work_item_id: str,
    final_content: str,
    proposal_commits: list[dict[str, Any]],
) -> None:
    if not proposal_commits:
        return
    final_rows = {row["externalId"]: row for row in (case_assistant_api_row(item) for item in parse_cases_markdown(final_content))}
    for commit in proposal_commits:
        proposal_id = str(commit.get("proposal_id") or commit.get("proposalId") or "").strip()
        requested_ids = {
            str(item).strip()
            for item in (commit.get("operation_ids") or commit.get("operationIds") or [])
            if str(item).strip()
        }
        if not proposal_id or not requested_ids:
            continue
        proposal_row = get_case_assistant_proposal_row(conn, work_item_id, proposal_id)
        if proposal_row["status"] == "rejected":
            raise HTTPException(status_code=409, detail="已拒绝的 AI 提案不能提交")
        operations = safe_json_loads(proposal_row["operations_json"], [])
        operations_by_id = {operation.get("id"): operation for operation in operations}
        unknown_ids = sorted(requested_ids.difference(operations_by_id))
        if unknown_ids:
            raise HTTPException(status_code=400, detail=f"提交的 AI 提案操作不存在：{', '.join(unknown_ids)}")
        committed_ids: list[str] = []
        for operation_id in requested_ids:
            operation = operations_by_id[operation_id]
            target_id = operation["targetExternalId"]
            final_row = final_rows.get(target_id)
            if operation["type"] == "delete":
                reflected = final_row is None
            elif operation["type"] == "add":
                expected = operation.get("after") or {}
                reflected = final_row is not None and all(final_row.get(field, "") == value for field, value in expected.items())
            else:
                expected = operation.get("after") or {}
                reflected = final_row is not None and all(final_row.get(field, "") == value for field, value in expected.items())
            if reflected:
                committed_ids.append(operation_id)
        status = "committed" if len(committed_ids) == len(requested_ids) else "partially_committed"
        conn.execute(
            "UPDATE case_assistant_proposals SET status = ?, committed_operation_ids_json = ?, updated_at = ? WHERE id = ?",
            (status, json.dumps(committed_ids, ensure_ascii=False), now_iso(), proposal_id),
        )


def extract_playwright_script(content: str) -> str:
    text = content.strip()
    fenced = re.search(r"```(?:ts|typescript)?\s*([\s\S]+?)```", text)
    if fenced:
        return fenced.group(1).strip()
    return text


def basic_typescript_shape_valid(script: str) -> bool:
    stripped = script.lstrip()
    if not stripped.startswith("import "):
        return False
    if re.search(r"^[\u4e00-\u9fff].*?\bimport\s+", script[:300], re.DOTALL):
        return False
    if re.search(r"(?m)^(我会|接下来|以下是|说明|修复思路|诊断)", stripped):
        return False
    code = typescript_code_without_literals(script)
    if code.count("(") != code.count(")") or code.count("{") != code.count("}") or code.count("[") != code.count("]"):
        return False
    return True


def stream_ai_test_cases_sync(item: sqlite3.Row, artifact_id: str, data_context: dict[str, Any] | None = None) -> dict[str, Any]:
    api_key = get_openai_api_key()
    if not api_key:
        return {"content": "", "source": "fallback", "reasonCode": "ai-not-configured", "reason": "AI 未配置", "quality": {}}
    payload = {
        "model": get_openai_model(),
        "input": test_cases_prompt(item, data_context),
    }
    try:
        content = call_openai_responses_stream(api_key, get_openai_model(), get_openai_base_url(), payload, artifact_id, timeout=18).strip()
    except (AIRequestError, urllib.error.URLError, TimeoutError, json.JSONDecodeError) as exc:
        return {
            "content": "",
            "source": "fallback",
            "reasonCode": "ai-request-failed",
            "reason": f"AI 生成测试用例失败：{openai_error_message(exc)}",
            "quality": {},
        }
    if not content:
        return {"content": "", "source": "fallback", "reasonCode": "ai-empty", "reason": "AI 未返回测试用例内容", "quality": {}}
    validation_error = generated_cases_expectation_error(content)
    if validation_error:
        log_event(
            logging.WARNING,
            "ai_test_cases_rejected",
            component="workflow",
            work_item_id=item["id"],
            reason=validation_error,
            stream=True,
        )
        return {
            "content": "",
            "source": "fallback",
            "reasonCode": "ai-format-invalid",
            "reason": f"AI 返回测试用例校验失败：{validation_error}",
            "quality": {},
        }
    quality = case_quality_report(content, requirement_analysis(item), allow_pending_evidence=True)
    if not quality["valid"]:
        reason = "AI 返回测试用例质量不合格：" + "；".join(quality["errors"])
        log_event(
            logging.WARNING,
            "ai_test_cases_rejected",
            component="workflow",
            work_item_id=item["id"],
            reason=reason,
            stream=True,
        )
        return {"content": "", "source": "fallback", "reasonCode": "ai-quality-invalid", "reason": reason, "quality": quality}
    return {"content": content, "source": "ai", "reasonCode": "", "reason": "", "quality": quality}


async def stream_ai_test_cases(item: sqlite3.Row, artifact_id: str, data_context: dict[str, Any] | None = None) -> dict[str, Any]:
    return await asyncio.to_thread(stream_ai_test_cases_sync, item, artifact_id, data_context)


def ai_playwright_script(
    item: sqlite3.Row,
    elements: list[sqlite3.Row],
    cases_markdown: str,
    fixture_import: str = "",
    state_evidence: list[dict[str, Any]] | None = None,
    generation_mode: str = "interaction",
    datasets: list[dict[str, Any]] | None = None,
    readiness: dict[str, str] | None = None,
) -> str:
    api_key = get_openai_api_key()
    if not api_key:
        return ""
    prompt = playwright_script_prompt(
        item,
        elements,
        cases_markdown,
        fixture_import,
        state_evidence or [],
        generation_mode=generation_mode,
        datasets=datasets or [],
        readiness=readiness or {},
    )
    payload = {
        "model": get_openai_model(),
        "input": prompt,
    }
    try:
        body = call_openai_responses(api_key, get_openai_model(), get_openai_base_url(), payload, timeout=60)
        content = parse_openai_text_response(body).strip()
    except (AIRequestError, urllib.error.URLError, TimeoutError, json.JSONDecodeError):
        return ""
    script = ensure_verbose_playwright_logging(extract_playwright_script(content))
    cases = parse_cases_markdown(cases_markdown)
    if not valid_playwright_script(script, elements) or len(cases) != 1:
        log_event(
            logging.WARNING,
            "ai_playwright_script_rejected",
            component="workflow",
            work_item_id=item["id"],
            reason="脚本结构无效或单用例上下文缺失",
        )
        return ""
    validation_error = single_primary_assertion_error(script, cases[0]["expected"])
    if validation_error:
        log_event(
            logging.WARNING,
            "ai_playwright_script_rejected",
            component="workflow",
            work_item_id=item["id"],
            case_external_id=cases[0]["external_id"],
            reason=validation_error,
        )
        return ""
    return script


def playwright_script_prompt(
    item: sqlite3.Row,
    elements: list[sqlite3.Row],
    cases_markdown: str,
    fixture_import: str = "",
    state_evidence: list[dict[str, Any]] | None = None,
    *,
    generation_mode: str = "interaction",
    datasets: list[dict[str, Any]] | None = None,
    readiness: dict[str, str] | None = None,
) -> str:
    data_context = latest_automation_data_context(item["id"])
    element_lines = "\n".join(
        f"- {element['area']} / {element['name']}: {element['locator_type']}{f'({element['locator_role']})' if 'locator_role' in element.keys() and element['locator_role'] else ''}={element['locator_value']} ({element['source']})；状态={element['state_key'] if 'state_key' in element.keys() and element['state_key'] else '未标注'}；来源 URL={element['source_url'] if 'source_url' in element.keys() and element['source_url'] else '-'}；备用={element['fallbacks_json'] if 'fallbacks_json' in element.keys() and element['fallbacks_json'] else '[]'}"
        for element in elements[:24]
    )
    state_lines = "\n".join(
        f"- {evidence.get('stateKey') or 'state'}: URL={evidence.get('url') or '-'}；标题={evidence.get('title') or '-'}；关键文本={', '.join(str(text) for text in (evidence.get('texts') or [])[:8]) or '-'}"
        for evidence in (state_evidence or [])[:12]
    )
    dataset_lines = "\n".join(
        f"- GET {dataset.get('url') or '-'}；字段={', '.join(str(value) for value in dataset.get('fields') or []) or '-'}；来源={dataset.get('source') or '-'}"
        for dataset in (datasets or [])[:12]
    )
    readiness = readiness or {}
    generation_mode_guidance = {
        "interaction": "当前用例是交互用例，所有操作 locator 必须来自已确认元素。",
        "static-page": "当前用例是静态页面用例，不要求交互控件；使用探索确认的 readiness heading/text 打开页面并断言。",
        "static-api": "当前用例是静态/API 对比用例，不要求交互控件；必须使用下方同源 GET dataset 获取实时真值，并与页面可见数据做一次整体断言。",
    }.get(generation_mode, "")
    login_entry_elements = [
        element
        for element in elements
        if str(element["locator_type"] or "").lower() == "role"
        and str(element["locator_role"] or "").lower() in {"link", "button"}
        and EXPLORATION_LOGIN_ENTRY_PATTERN.fullmatch(str(element["locator_value"] or element["name"] or "").strip())
    ]
    login_entry_guidance = ""
    if len(login_entry_elements) == 1:
        entry = login_entry_elements[0]
        login_entry_guidance = f"""
- 页面探索确认目标 URL 首屏存在登录入口：`role={entry['locator_role']}`、`name={entry['locator_value']}`、来源 URL `{entry['source_url'] or item['target_url']}`。
- 对账号、密码、登录表单或登录成功相关用例，必须在 `page.goto` 后先精确点击该入口，再定位登录表单；不得直接在首屏 fill 账号或密码。
"""
    domain_guidance = ""
    if is_zzpss_item(item):
        domain_guidance = """
ZZPSS 登录成功判定：
- 登录按钮必须优先使用 `page.locator('.login-button').filter({ hasText: /^登录$/ }).first()` 或 `.login-button:has-text("登录")`；禁止使用 `page.locator('text=登录').first()`，因为会误点“用户登录”标题。
- 登录成功后 URL 应进入 `#/home`。
- 首页真实稳定信号包括 `欢迎您，李宁`、活跃菜单 `.menu-item.menu-active` 包含 `首页`、以及 `基本情况`、`电能质量` 等首页看板标题。
- 不要使用 `navigation`、`menu`、`main`、`aside`、`.el-menu`、`.layout` 等未被页面证据确认的通用 layout selector 作为唯一登录态断言。
"""
    elif "saucedemo" in str(item["target_url"]).lower() or "sauce demo" in str(item["title"]).lower():
        domain_guidance = """
SauceDemo 稳定化要求：
- 测试用例表中每个 `ID` 必须各自生成一个 Playwright `test(...)`；不要把多条用例合并成一个主流程测试。
- 抽出 `openSauceLogin(page)`：`page.goto(BASE_URL, { waitUntil: 'commit', timeout: 15_000 })` 后等待 `[data-test="username"]`、`[data-test="password"]`、`[data-test="login-button"]` 可见/可用；不要把 `[data-test="login-container"]` 或 `Swag Labs` 文本作为必需就绪信号。
- 抽出 `loginAs(page, username, password)`：使用 `[data-test="username"]`、`[data-test="password"]`、`[data-test="login-button"]`，登录后等待 `/inventory.html` 和 `[data-test="title"]` 文本 `Products`。
- 抽出 `logout(page)`：点击 `getByRole('button', { name: 'Open Menu' })` 后，等待 `[data-test="logout-sidebar-link"]` 的 `tabindex` 不再是 `-1`，并确认 bounding box 已完整进入 viewport 后再点击。
- 需要加长单用例预算时，在测试体内调用 `test.setTimeout(60_000)`；禁止生成 `test('...', { timeout: 60000 }, async (...) => ...)`。
"""
    fixture_guidance = ""
    if fixture_import:
        fixture_guidance = f"""
- 当前输入只包含一条测试用例，必须且只能生成一个 test(...)。
- 必须使用 `import {{ openTargetPage, runStep }} from '{fixture_import}';` 引入共享 Fixture，并在第一个业务步骤中调用 `await openTargetPage(page)`。
- 禁止在 spec 内重新定义 TARGET_URL 或 runStep；打开目标页面时使用 TARGET_URL。
- 不得导入任何其他 `.spec.ts` 文件。
"""
    return f"""你是资深 Playwright 自动化工程师。请基于已确认页面元素和测试用例生成 TypeScript Playwright spec。
要求：
- 使用 import {{ expect, test }} from '@playwright/test';
- 测试用例表中的每个 `ID` 必须原样出现在至少一个 Playwright `test('ID 标题', ...)` 标题中。
- 每个 Playwright `test(...)` 标题必须严格等于测试用例表中的“ID + 单个空格 + 标题”，不得改写、缩短或追加说明。
- 不得删除、改写、缩短、重编号、合并或遗漏任何测试用例 ID；有多条用例时必须生成多条 `test(...)`，不能只生成一个“主流程”测试。
- 每个测试步骤都在相邻位置写中文注释。
- 每个业务步骤必须使用 `await test.step('中文步骤名', async () => {{ ... }})` 包裹，并在步骤开始、成功、失败时分别打印 `console.log('[步骤开始] ...')`、`console.log('[步骤通过] ...')`、`console.log('[步骤失败] ...')`。
- 不允许只写注释代替运行时日志；执行日志必须能逐步看到打开页面、输入、点击、断言、截图/证据等关键动作。
- 可以定义 `runStep(title, action)` helper 统一封装 `console.log` 与 `test.step`，但每个关键动作都必须调用它。
- locator 只能来自已确认元素、页面可见文案、ARIA role/name、label、placeholder、稳定 data-test/data-testid 或项目已有约定。
- 当前用例没有已确认交互控件时，只能从“真实页面状态证据”的 headings/texts 选择精确可见断言；禁止退化为 `body`、通用容器或猜测 selector。
- 生成模式：`{generation_mode}`。{generation_mode_guidance}
- 已确认 readiness：{readiness.get('kind') or '-'}={readiness.get('value') or '-'}。
- 对“登录”、“关闭”、“确定”等短且容易成为其他可访问名子串的 role/name locator，优先使用 `exact: true`，避免 Playwright strict mode 歧义。
- 使用 web-first assertions；不要使用固定 waitForTimeout。
- 当前输入中的每条用例只有一个主期望结果。每个单用例 spec 必须且只能调用一次 `expect(...)`、`expect.poll(...)` 或 `expect.soft(...)`。
- 唯一 `expect` 的上一行必须写 `// 主断言：<期望结果>`，其中内容必须与用例表“期望结果”完全一致，末尾句号可以省略。
- 页面打开、控件可见/可用、接口返回和操作前提使用 `locator.waitFor`、`page.waitForURL`、`page.waitForResponse` 或显式数据准备；禁止为这些前提追加辅助 `expect`。
- 如果用例需要比较多个字段，先将实际值和期望值归一化为对象或数组，最后只执行一次 `expect(actual).toEqual(expected)`。
- 第三方/外部页面导航优先使用 `waitUntil: 'commit'`，随后等待真实页面可操作信号；不要把 `domcontentloaded` 或 `load` 当作核心就绪条件。
- 不要使用 `waitUntil: 'networkidle'`，因为第三方站点可能有持续后台请求导致永不 idle。
- 需要加长单用例预算时使用 `test.setTimeout(...)`；禁止生成 `test('...', {{ timeout: ... }}, async (...) => ...)`。
- 必要 timeout 必须有上限。
- 不要为“需业务规则确认/可选人工验证”的账号锁定、验证码、风控或限流场景生成强制 Playwright 断言；这些内容只允许保留为注释或人工验证说明。
- 只读数据预探索上下文中的同源 GET/JSON 接口可以作为数据结构和端点证据；动态列表、榜单和统计必须在同一次测试运行中通过 `page.waitForResponse` 获取实时响应后再与页面比较，禁止硬编码预探索样本值。
- 排名校验将名次、名称、主排序值和页面顺序归一化为一个记录序列，再通过唯一一次整体 `toEqual` 与同次接口序列比较；数值并列时保持接口顺序，不推断需求未说明的并列规则。
- 若用例标记 `blocked-by-data` 且运行时仍未获得真值，只跳过该用例并说明原因，不得降低其他展示、切换或跳转用例的断言。
- 如果某个流程已经进入目标成功状态，例如登录后出现首页 URL、欢迎语或业务看板，后续不得再追加“仍停留在登录页”等相反断言。
{login_entry_guidance}
{fixture_guidance}
返回完整 TypeScript spec，不要解释。
{domain_guidance}

标题：{item['title']}
需求：{item['requirement']}
目标 URL：{item['target_url']}
角色：{item['role']}
测试数据：{item['test_data']}
验收标准：{item['acceptance']}
只读数据预探索上下文：
{data_context_prompt_text(data_context)}
测试用例：
{cases_markdown}

已确认元素：
{element_lines}

真实页面状态证据（只用于选择断言，不是可交互 locator）：
{state_lines or '-'}

当前用例可信同源 GET datasets：
{dataset_lines or '-'}
"""


def valid_playwright_script(script: str, elements: list[sqlite3.Row] | list[dict[str, Any]]) -> bool:
    if not basic_typescript_shape_valid(script):
        return False
    if "test(" not in script or "expect(" not in script:
        return False
    if "waitForTimeout" in script:
        return False
    if re.search(r"""\btest(?:\.(?:only|skip|fixme))?\s*\(\s*(?:"(?:\\.|[^"])*"|'(?:\\.|[^'])*'|`(?:\\.|[^`])*`)\s*,\s*\{[^{}]*\btimeout\s*:""", script, re.DOTALL):
        return False
    semantic_markers = ["getByRole", "getByLabel", "getByPlaceholder", "getByText", "data-test", "data-testid", "locator("]
    return any(marker in script for marker in semantic_markers)


def valid_case_playwright_script(
    script: str,
    case_row: sqlite3.Row,
    elements: list[sqlite3.Row] | list[dict[str, Any]],
    fixture_import: str,
    *,
    enforce_single_primary: bool = False,
    navigation_target: dict[str, Any] | None = None,
) -> str:
    if not valid_playwright_script(script, elements):
        return "脚本未通过 Playwright 结构或 locator 校验"
    titles = extract_playwright_test_titles(script)
    if len(titles) != 1:
        return f"单用例脚本必须且只能包含一个 test(...)，当前检测到 {len(titles)} 个"
    external_id = case_row["external_id"]
    expected_title = script_name_for_case(case_row)
    if titles[0] != expected_title:
        return f"测试标题不匹配：当前为“{titles[0]}”；必须严格等于：{expected_title}"
    if fixture_import and fixture_import not in script:
        return "脚本未引用当前生成批次的共享 Fixture"
    if re.search(r"from\s+['\"][^'\"]+\.spec(?:\.ts)?['\"]", script):
        return "单用例脚本不能导入其他 spec 文件"
    if navigation_target and navigation_target.get("evidenceConfirmed"):
        if not navigation_target.get("readinessSignals"):
            return "navigation-precondition：缺少目标页面 readiness signal，禁止生成脚本"
        if not navigation_target.get("navigationPathConfirmed"):
            return "navigation-precondition：缺少可重复导航路径或已确认的直接访问证据"
        required_mode = navigation_target.get("requiredAccessMode") or "unknown"
        explored_mode = navigation_target.get("accessMode") or "unknown"
        if required_mode != "unknown" and explored_mode != required_mode:
            return f"navigation-precondition：需求访问模式 {required_mode} 与探索结果 {explored_mode} 不一致"
        if "openTargetPage(" not in script:
            return "navigation-precondition：脚本必须通过共享 openTargetPage 回放已确认导航路径"
        if re.search(r"\bpage\.goto\s*\(", script):
            return "navigation-precondition：脚本不得绕过共享导航 helper 直接调用 page.goto"
    if enforce_single_primary:
        primary_error = single_primary_assertion_error(script, str(case_row["expected"] or ""))
        if primary_error:
            return primary_error
    return ""


def valid_shared_spec_debug_script(
    script: str,
    case_row: sqlite3.Row,
    elements: list[sqlite3.Row] | list[dict[str, Any]],
) -> str:
    return valid_shared_spec_scope_script(script, [case_row], elements)


def valid_shared_spec_scope_script(
    script: str,
    case_rows: list[sqlite3.Row],
    elements: list[sqlite3.Row] | list[dict[str, Any]],
) -> str:
    if not valid_playwright_script(script, elements):
        return "脚本未通过 Playwright 结构或 locator 校验"
    missing = [
        str(case_row["external_id"] or "")
        for case_row in case_rows
        if not re.search(case_external_id_grep_pattern(str(case_row["external_id"] or "")), script)
    ]
    if missing:
        return f"共享 spec 必须保留执行范围内的用例 ID：{', '.join(missing)}"
    return ""


def typescript_call_end(code: str, open_parenthesis: int) -> int:
    depth = 0
    for index in range(open_parenthesis, len(code)):
        char = code[index]
        if char == "(":
            depth += 1
        elif char == ")":
            depth -= 1
            if depth == 0:
                return index
    return -1


def migrate_confirmed_target_navigation(script: str) -> str:
    code = typescript_code_without_literals(script)
    if re.search(r"\bopenTargetPage\s*\(", code):
        return script
    for match in re.finditer(r"\bawait\s+page\s*\.\s*goto\s*\(", code):
        open_parenthesis = code.find("(", match.start(), match.end())
        call_end = typescript_call_end(code, open_parenthesis)
        if call_end < 0:
            continue
        arguments = code[open_parenthesis + 1 : call_end]
        if not re.match(r"\s*(?:TARGET_URL|WORK_ITEM_TARGET_URL)\s*(?:,|$)", arguments):
            continue
        replacement_end = call_end + 1
        while replacement_end < len(code) and code[replacement_end] in {" ", "\t"}:
            replacement_end += 1
        if replacement_end < len(code) and code[replacement_end] == ";":
            replacement_end += 1
        return script[: match.start()] + "await openTargetPage(page);" + script[replacement_end:]
    return script


def upsert_case_fixture_import(
    script: str,
    fixture_import: str,
    previous_fixture_import: str = "",
) -> str:
    if not fixture_import:
        return script
    import_pattern = re.compile(
        r"import\s*\{(?P<names>[\s\S]*?)\}\s*from\s*(?P<quote>['\"])(?P<path>[^'\"]+)(?P=quote)\s*;"
    )
    fixture_paths = {path for path in (fixture_import, previous_fixture_import) if path}
    candidates = [
        match
        for match in import_pattern.finditer(script)
        if match.group("path") in fixture_paths or "/fixtures/" in match.group("path")
    ]
    if candidates:
        names: list[str] = []
        for match in candidates:
            for name in (part.strip() for part in match.group("names").split(",")):
                if name and name not in names:
                    names.append(name)
        if not any(re.match(r"openTargetPage(?:\s+as\s+\w+)?$", name) for name in names):
            names.append("openTargetPage")
        replacement = f"import {{ {', '.join(names)} }} from '{fixture_import}';"
        parts: list[str] = []
        cursor = 0
        for index, match in enumerate(candidates):
            parts.append(script[cursor : match.start()])
            if index == 0:
                parts.append(replacement)
            cursor = match.end()
        parts.append(script[cursor:])
        return "".join(parts)
    import_match = re.search(r"import[^\n]+from\s+['\"](?:@playwright/test|playwright/test)['\"]\s*;", script)
    dependency = f"\nimport {{ TARGET_URL as WORK_ITEM_TARGET_URL, openTargetPage, runStep }} from '{fixture_import}';"
    if import_match:
        return script[: import_match.end()] + dependency + script[import_match.end() :]
    return script


def ensure_case_fixture_dependency(
    script: str,
    fixture_import: str,
    *,
    migrate_navigation: bool = False,
    previous_fixture_import: str = "",
) -> str:
    normalized = upsert_case_fixture_import(script, fixture_import, previous_fixture_import)
    return migrate_confirmed_target_navigation(normalized) if migrate_navigation else normalized


def fallback_locator_expression(elements: list[sqlite3.Row]) -> str:
    first_element = elements[0] if elements else None
    if first_element is None:
        return "page.locator('body')"
    locator_type = str(first_element["locator_type"] or "text").lower()
    value = str(first_element["locator_value"] or first_element["name"] or "").replace("\\", "\\\\").replace("'", "\\'")
    if locator_type == "role":
        role = (first_element["locator_role"] if "locator_role" in first_element.keys() else "") or ("button" if "button" in str(first_element["source"] or "").lower() else "generic")
        return f"page.getByRole('{role}', {{ name: /{value}/ }}).first()"
    if locator_type == "label":
        return f"page.getByLabel('{value}').first()"
    if locator_type == "placeholder":
        return f"page.getByPlaceholder('{value}').first()"
    if locator_type in {"testid", "data-test", "data-testid"}:
        return f"page.locator('[data-test=\"{value}\"], [data-testid=\"{value}\"]').first()"
    if locator_type == "css":
        return f"page.locator('{value}').first()"
    return f"page.getByText('{value}').first()"


def static_case_locator_from_evidence(
    case_row: sqlite3.Row | dict[str, Any],
    state_evidence: list[dict[str, Any]],
    *,
    allow_proven_fallback: bool = False,
) -> dict[str, str]:
    case_source = exploration_case_source(case_row).lower()
    for evidence in state_evidence:
        for kind, values in (
            ("heading", evidence.get("headings") or []),
            ("text", evidence.get("texts") or []),
        ):
            for raw_value in values:
                value = sanitize_exploration_phrase(raw_value, max_length=120)
                if len(value) < 3:
                    continue
                if value.lower() in case_source:
                    return {"kind": kind, "value": value}
    if allow_proven_fallback:
        for evidence in state_evidence:
            readiness = evidence.get("readinessLocator") if isinstance(evidence.get("readinessLocator"), dict) else {}
            kind = str(readiness.get("kind") or "")
            value = sanitize_exploration_phrase(readiness.get("value"), max_length=160)
            if kind in {"heading", "text"} and len(value) >= 3:
                return {"kind": kind, "value": value, "source": "exploration-readiness"}
            headings = [sanitize_exploration_phrase(item, max_length=160) for item in evidence.get("headings") or []]
            heading = next((item for item in headings if len(item) >= 3), "")
            if heading:
                return {"kind": "heading", "value": heading, "source": "exploration-heading"}
    return {}


def case_read_only_datasets(
    item: sqlite3.Row,
    case_row: sqlite3.Row,
    state_evidence: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    source = exploration_case_source(case_row)
    datasets: list[dict[str, Any]] = []
    seen_urls: set[str] = set()

    def add_dataset(url: str, *, fields: list[str] | None = None, item_count: int = 0, source_label: str) -> None:
        normalized = str(url or "").strip()
        if not normalized:
            return
        absolute = urllib.parse.urljoin(str(item["target_url"] or ""), normalized)
        expected_origin = urllib.parse.urlparse(str(item["target_url"] or ""))
        actual_origin = urllib.parse.urlparse(absolute)
        if (expected_origin.scheme, expected_origin.netloc) != (actual_origin.scheme, actual_origin.netloc):
            return
        if absolute in seen_urls:
            return
        seen_urls.add(absolute)
        datasets.append({
            "method": "GET",
            "url": absolute,
            "fields": list(fields or []),
            "itemCount": int(item_count or 0),
            "source": source_label,
        })

    for evidence in state_evidence:
        for response in evidence.get("readOnlyResponses") or []:
            if not isinstance(response, dict) or str(response.get("method") or "GET").upper() != "GET":
                continue
            response_url = str(response.get("url") or "")
            parsed = urllib.parse.urlparse(response_url)
            path_with_query = parsed.path + (f"?{parsed.query}" if parsed.query else "")
            if path_with_query and path_with_query not in source and parsed.path not in source:
                continue
            add_dataset(
                response_url,
                fields=[str(value) for value in response.get("fields") or []],
                item_count=int(response.get("itemCount") or 0),
                source_label="exploration-response",
            )
    for match in re.finditer(r"\bGET\s+((?:https?://[^\s；;，,<]+)|(?:/[^\s；;，,<]+))", source, re.IGNORECASE):
        add_dataset(match.group(1).rstrip("。.)）"), source_label="case-explicit-get")
    return datasets[:12]


def fallback_login_entry(elements: list[sqlite3.Row], case_row: sqlite3.Row) -> sqlite3.Row | None:
    case_source = " ".join(
        str(case_row[key] or "")
        for key in ("title", "requirement", "preconditions", "steps", "expected", "automation_notes")
        if key in case_row.keys()
    )
    if not EXPLORATION_LOGIN_CONTROL_PATTERN.search(case_source):
        return None
    entries = [
        element
        for element in elements
        if str(element["locator_type"] or "").lower() == "role"
        and str(element["locator_role"] or "").lower() in {"link", "button"}
        and EXPLORATION_LOGIN_ENTRY_PATTERN.fullmatch(str(element["locator_value"] or element["name"] or "").strip())
    ]
    return entries[0] if len(entries) == 1 else None


def ranking_case_script(item: sqlite3.Row, case_row: sqlite3.Row, fixture_import: str) -> str | None:
    item_source = automation_item_text(item)
    if not re.search(r"排行榜|榜单|排名", item_source):
        return None
    case_source = " ".join(
        str(case_row[key] or "")
        for key in ("title", "requirement", "steps", "expected", "automation_notes")
        if key in case_row.keys()
    )
    common = """import { expect, test, type Locator, type Page } from '@playwright/test';
import { openTargetPage, runStep } from '__FIXTURE__';

type ApiEnvelope<T> = { data: T };
type RankRecord = { rank: number; slug: string; name: string; value: number };
type ContributorRecord = { rank: number; name: string; installTotal: number; skillCount: number };
type DepartmentRecord = { dept: string; installTotal: number; skillCount: number };

async function gotoRankPage(page: Page) {
  await openTargetPage(page);
  await page.getByRole('heading', { name: '排行榜', exact: true }).first().waitFor({ state: 'visible', timeout: 10_000 });
}

async function apiData<T>(response: import('@playwright/test').Response): Promise<T> {
  const payload = await response.json() as ApiEnvelope<T>;
  return payload.data;
}

async function skillRows(table: Locator) {
  return await table.locator('tbody tr').evaluateAll((rows) => rows.map((row) => {
    const cells = Array.from(row.querySelectorAll('td'));
    return {
      rank: Number(cells[0]?.textContent?.trim() || 0),
      name: row.querySelector('.lnk')?.textContent?.trim() || '',
      value: Number(cells[4]?.textContent?.trim() || 0),
    };
  }));
}

test(__TEST_NAME__, async ({ page }) => {
__TEST_BODY__
});
"""
    if re.search(r"三类|完整展示|页面展示|部门分布.*贡献者", case_source):
        body = """  await runStep('打开排行榜并验证三部分展示', async () => {
    await gotoRankPage(page);
    await page.getByRole('heading', { name: '贡献者榜', exact: true }).waitFor({ state: 'visible' });
    await page.getByRole('heading', { name: '部门分布', exact: true }).waitFor({ state: 'visible' });
    __PRIMARY_ASSERTION__
    await expect(page.locator('table')).toHaveCount(3);
  });"""
    elif re.search(r"累计安装", case_source):
        body = """  await runStep('捕获累计安装接口并打开排行榜', async () => {
    const responsePromise = page.waitForResponse((response) => response.request().method() === 'GET' && response.url().includes('/api/stats/rank?mode=dl'));
    await gotoRankPage(page);
    const expected = await apiData<RankRecord[]>(await responsePromise);
    const actual = await skillRows(page.locator('table').first());
    __PRIMARY_ASSERTION__
    expect(actual).toEqual(expected.map(({ rank, name, value }) => ({ rank, name, value })));
  });"""
    elif re.search(r"本周|热度", case_source):
        body = """  await runStep('切换本周热度并与实时接口比较', async () => {
    await gotoRankPage(page);
    const responsePromise = page.waitForResponse((response) => response.request().method() === 'GET' && response.url().includes('/api/stats/rank?mode=wk'));
    await page.getByRole('button', { name: '本周热度', exact: true }).click();
    const expected = await apiData<RankRecord[]>(await responsePromise);
    await page.getByText('技能排行榜，按本周安装排序', { exact: true }).waitFor({ state: 'visible' });
    const actual = await skillRows(page.locator('table').first());
    __PRIMARY_ASSERTION__
    expect(actual).toEqual(expected.map(({ rank, name, value }) => ({ rank, name, value })));
  });"""
    elif re.search(r"贡献者", case_source) and not re.search(r"部门", case_source):
        body = """  await runStep('捕获贡献者接口并比较表格', async () => {
    const responsePromise = page.waitForResponse((response) => response.request().method() === 'GET' && response.url().includes('/api/stats/contributors'));
    await gotoRankPage(page);
    const expected = await apiData<ContributorRecord[]>(await responsePromise);
    const actual = await page.locator('table').nth(1).locator('tbody tr').evaluateAll((rows) => rows.map((row) => {
      const cells = Array.from(row.querySelectorAll('td'));
      return { rank: Number(cells[0]?.textContent?.trim() || 0), name: row.querySelector('.lnk')?.textContent?.trim() || '', installTotal: Number(cells[3]?.textContent?.trim() || 0), skillCount: Number(cells[4]?.textContent?.trim() || 0) };
    }));
    __PRIMARY_ASSERTION__
    expect(actual).toEqual(expected.map(({ rank, name, installTotal, skillCount }) => ({ rank, name, installTotal, skillCount })));
  });"""
    elif re.search(r"部门", case_source) and not re.search(r"贡献者", case_source):
        body = """  await runStep('捕获部门接口并比较表格', async () => {
    const responsePromise = page.waitForResponse((response) => response.request().method() === 'GET' && response.url().includes('/api/stats/depts'));
    await gotoRankPage(page);
    const expected = await apiData<DepartmentRecord[]>(await responsePromise);
    const actual = await page.locator('table').nth(2).locator('tbody tr').evaluateAll((rows) => rows.map((row) => {
      const cells = Array.from(row.querySelectorAll('td'));
      return { dept: cells[0]?.textContent?.trim() || '', skillCount: Number(cells[2]?.textContent?.trim() || 0), installTotal: Number(cells[3]?.textContent?.trim() || 0) };
    }));
    __PRIMARY_ASSERTION__
    expect(actual).toEqual(expected.map(({ dept, skillCount, installTotal }) => ({ dept, skillCount, installTotal })));
  });"""
    elif re.search(r"贡献者|部门", case_source):
        body = """  await runStep('捕获贡献者和部门接口并比较表格', async () => {
    const contributorsPromise = page.waitForResponse((response) => response.request().method() === 'GET' && response.url().includes('/api/stats/contributors'));
    const departmentsPromise = page.waitForResponse((response) => response.request().method() === 'GET' && response.url().includes('/api/stats/depts'));
    await gotoRankPage(page);
    const contributors = await apiData<ContributorRecord[]>(await contributorsPromise);
    const departments = await apiData<DepartmentRecord[]>(await departmentsPromise);
    const tables = page.locator('table');
    const contributorRows = await tables.nth(1).locator('tbody tr').evaluateAll((rows) => rows.map((row) => {
      const cells = Array.from(row.querySelectorAll('td'));
      return { rank: Number(cells[0]?.textContent?.trim() || 0), name: row.querySelector('.lnk')?.textContent?.trim() || '', installTotal: Number(cells[3]?.textContent?.trim() || 0), skillCount: Number(cells[4]?.textContent?.trim() || 0) };
    }));
    const departmentRows = await tables.nth(2).locator('tbody tr').evaluateAll((rows) => rows.map((row) => {
      const cells = Array.from(row.querySelectorAll('td'));
      return { dept: cells[0]?.textContent?.trim() || '', skillCount: Number(cells[2]?.textContent?.trim() || 0), installTotal: Number(cells[3]?.textContent?.trim() || 0) };
    }));
    __PRIMARY_ASSERTION__
    expect({ contributorRows, departmentRows }).toEqual({
      contributorRows: contributors.map(({ rank, name, installTotal, skillCount }) => ({ rank, name, installTotal, skillCount })),
      departmentRows: departments.map(({ dept, skillCount, installTotal }) => ({ dept, skillCount, installTotal })),
    });
  });"""
    elif re.search(r"跳转|详情|skill", case_source, re.IGNORECASE):
        body = """  await runStep('从排行榜记录跳转到对应技能详情', async () => {
    const responsePromise = page.waitForResponse((response) => response.request().method() === 'GET' && response.url().includes('/api/stats/rank?mode=dl'));
    await gotoRankPage(page);
    const records = await apiData<RankRecord[]>(await responsePromise);
    test.skip(!records.length, '排行榜没有可用于跳转的技能记录');
    const record = records[0];
    await page.locator('table').first().locator('tbody tr').first().click();
    await page.waitForURL((url) => url.hash.includes(`/s/${record.slug}`), { timeout: 10_000 });
    await page.getByRole('heading', { name: new RegExp(record.name) }).first().waitFor({ state: 'visible' });
    __PRIMARY_ASSERTION__
    expect(page.url()).toContain(`/s/${record.slug}`);
  });"""
    else:
        return None
    return common.replace("__FIXTURE__", fixture_import).replace(
        "__TEST_NAME__",
        json.dumps(script_name_for_case(case_row), ensure_ascii=False),
    ).replace("__TEST_BODY__", body).replace(
        "__PRIMARY_ASSERTION__",
        primary_assertion_comment(str(case_row["expected"] or "")),
    )


def readiness_locator_expression(readiness: dict[str, str]) -> str:
    kind = str(readiness.get("kind") or "")
    value = str(readiness.get("value") or "").replace("\\", "\\\\").replace("'", "\\'")
    if kind == "heading" and value:
        return f"page.getByRole('heading', {{ name: '{value}', exact: true }}).first()"
    if kind == "text" and value:
        return f"page.getByText('{value}', {{ exact: true }}).first()"
    return "page.locator('main').first()"


def static_api_case_script(
    case_row: sqlite3.Row,
    fixture_import: str,
    datasets: list[dict[str, Any]],
    readiness: dict[str, str],
) -> str | None:
    case_source = exploration_case_source(case_row)
    dataset = datasets[0] if datasets else None
    if not dataset:
        return None
    parsed = urllib.parse.urlparse(str(dataset.get("url") or ""))
    relative_url = parsed.path + (f"?{parsed.query}" if parsed.query else "")
    if not relative_url:
        return None
    external_id = str(case_row["external_id"]).replace("'", "\\'")
    title = str(case_row["title"] or "静态数据验证").replace("'", "\\'")
    expected_text = str(case_row["expected"] or "页面数据与接口一致")
    readiness_locator = readiness_locator_expression(readiness)
    common_header = f"""import {{ expect, test }} from '@playwright/test';
import {{ openTargetPage, runStep }} from '{fixture_import}';

test('{external_id} {title}', async ({{ page }}) => {{
  await runStep('打开需求指定目标页面', async () => {{
    await openTargetPage(page);
    await {readiness_locator}.waitFor({{ state: 'visible', timeout: 10_000 }});
  }});
"""
    if re.search(r"概览|统计|overview|skillCount|installTotal|contributorCount|deptCount", case_source, re.IGNORECASE):
        return common_header + f"""
  await runStep('读取同源概览接口并核对页面数字', async () => {{
    const response = await page.context().request.get(new URL('{relative_url}', page.url()).href);
    if (!response.ok()) throw new Error(`概览接口返回 ${{response.status()}}`);
    const payload = await response.json();
    const data = payload?.data ?? payload;
    const fields = ['skillCount', 'installTotal', 'contributorCount', 'deptCount', 'monthNew', 'weekInstall']
      .filter((field) => data?.[field] !== undefined);
    const actual = Object.fromEntries(await Promise.all(fields.map(async (field) => [
      field,
      await page.getByText(String(data[field]), {{ exact: true }}).count() > 0,
    ])));
    const expected = Object.fromEntries(fields.map((field) => [field, true]));
    // 主断言：{expected_text}
    expect(actual).toEqual(expected);
  }});
}});
"""
    if re.search(r"技能.*列表|列表.*技能|/api/skills", case_source, re.IGNORECASE):
        return common_header + f"""
  await runStep('读取同源技能接口并核对可见技能', async () => {{
    const response = await page.context().request.get(new URL('{relative_url}', page.url()).href);
    if (!response.ok()) throw new Error(`技能接口返回 ${{response.status()}}`);
    const payload = await response.json();
    const data = payload?.data ?? payload;
    const records = Array.isArray(data) ? data : Array.isArray(data?.list) ? data.list : [];
    const expectedNames = new Set(records.map((record) => String(record?.name || '').trim()).filter(Boolean));
    const visibleNames = await page.getByRole('button', {{ name: /^查看技能 / }}).evaluateAll((buttons) =>
      buttons.map((button) => String(button.getAttribute('aria-label') || button.textContent || '').replace(/^查看技能\\s*/, '').trim()).filter(Boolean)
    );
    const actual = {{ hasVisibleSkills: visibleNames.length > 0, allVisibleSkillsExistInApi: visibleNames.every((name) => expectedNames.has(name)) }};
    const expected = {{ hasVisibleSkills: true, allVisibleSkillsExistInApi: true }};
    // 主断言：{expected_text}
    expect(actual).toEqual(expected);
  }});
}});
"""
    return None


def saucedemo_case_script(
    item: sqlite3.Row,
    case_row: sqlite3.Row,
    fixture_import: str,
) -> str | None:
    if not is_sauce_demo_item(item):
        return None
    credentials = parse_test_data(" ".join([
        str(item["test_data"] or ""),
        str(item["requirement"] or ""),
    ]))
    missing_fields = [field for field in ("username", "password") if not credentials.get(field)]
    if missing_fields:
        raise HTTPException(
            status_code=400,
            detail="SauceDemo 脚本生成缺少" + "、".join(credential_field_label(field) for field in missing_fields) + "，禁止使用内置默认账号",
        )

    scope = saucedemo_case_scope(case_row)
    if not scope:
        return None
    expected = str(case_row["expected"] or "")
    primary_marker = primary_assertion_comment(expected)
    product = json.dumps(credentials.get("product", ""), ensure_ascii=False)
    header = f"""import {{ expect, test, type Page }} from '@playwright/test';
import {{ openTargetPage, runStep }} from '{fixture_import}';

{PLAYWRIGHT_REQUIRED_CREDENTIAL_HELPER}

const username = requiredCredential('QA_USERNAME');
const password = requiredCredential('QA_PASSWORD');
const requestedProduct = {product};

function sauce(page: Page, testId: string) {{
  return page.locator(`[data-test="${{testId}}"]`);
}}

async function login(page: Page) {{
  await sauce(page, 'username').fill(username);
  await sauce(page, 'password').fill(password);
  await sauce(page, 'login-button').click();
  await page.waitForURL(/\\/inventory\\.html$/, {{ timeout: 15_000 }});
}}

async function addSelectedProduct(page: Page) {{
  const products = sauce(page, 'inventory-item');
  const productCard = requestedProduct ? products.filter({{ hasText: requestedProduct }}).first() : products.first();
  await productCard.waitFor({{ state: 'visible', timeout: 10_000 }});
  const selectedProduct = (await productCard.locator('[data-test="inventory-item-name"]').innerText()).trim();
  await productCard.locator('button[data-test^="add-to-cart-"]').click();
  return selectedProduct;
}}

test({json.dumps(script_name_for_case(case_row), ensure_ascii=False)}, async ({{ page }}) => {{
"""
    if scope == "checkout":
        body = f"""  await runStep('登录并添加一个真实可用商品', async () => {{
    await openTargetPage(page);
    await login(page);
    await addSelectedProduct(page);
  }});
  await runStep('从购物车进入结账信息页', async () => {{
    await sauce(page, 'shopping-cart-link').click();
    await sauce(page, 'checkout').click();
    await page.waitForURL(/\\/checkout-step-one\\.html$/, {{ timeout: 10_000 }});
    {primary_marker}
    await expect(page).toHaveURL(/\\/checkout-step-one\\.html$/);
  }});
}});
"""
    elif scope == "cart":
        body = f"""  let selectedProduct = '';
  await runStep('登录并选择真实可用商品', async () => {{
    await openTargetPage(page);
    await login(page);
    selectedProduct = await addSelectedProduct(page);
  }});
  await runStep('进入购物车核对所选商品', async () => {{
    await sauce(page, 'shopping-cart-link').click();
    {primary_marker}
    await expect(sauce(page, 'inventory-item-name')).toHaveText(selectedProduct);
  }});
}});
"""
    elif scope == "add":
        body = f"""  await runStep('登录并添加首个真实可用商品', async () => {{
    await openTargetPage(page);
    await login(page);
    await addSelectedProduct(page);
    {primary_marker}
    await expect(sauce(page, 'shopping-cart-badge')).toHaveText('1');
  }});
}});
"""
    elif scope == "inventory":
        body = f"""  await runStep('登录并确认商品列表存在可购买商品', async () => {{
    await openTargetPage(page);
    await login(page);
    const productCount = await sauce(page, 'inventory-item').count();
    {primary_marker}
    expect(productCount).toBeGreaterThan(0);
  }});
}});
"""
    elif scope == "login-page":
        body = f"""  await runStep('打开 SauceDemo 登录页并检查表单', async () => {{
    await openTargetPage(page);
    const actual = {{
      pathname: new URL(page.url()).pathname,
      username: await sauce(page, 'username').isVisible(),
      password: await sauce(page, 'password').isVisible(),
      loginEnabled: await sauce(page, 'login-button').isEnabled(),
    }};
    {primary_marker}
    await expect(actual).toEqual({{ pathname: '/', username: true, password: true, loginEnabled: true }});
  }});
}});
"""
    elif scope == "login":
        body = f"""  await runStep('使用需求提供的凭据登录 SauceDemo', async () => {{
    await openTargetPage(page);
    await login(page);
    {primary_marker}
    await expect(page).toHaveURL(/\\/inventory\\.html$/);
  }});
}});
"""
    else:
        return None
    return header + body


def default_case_script(
    item: sqlite3.Row,
    case_row: sqlite3.Row,
    elements: list[sqlite3.Row],
    fixture_import: str,
    state_evidence: list[dict[str, Any]] | None = None,
    generation_mode: str = "interaction",
    datasets: list[dict[str, Any]] | None = None,
    readiness: dict[str, str] | None = None,
) -> str:
    sauce_script = saucedemo_case_script(item, case_row, fixture_import)
    if sauce_script:
        return sauce_script
    ranking_script = ranking_case_script(item, case_row, fixture_import)
    if ranking_script:
        return ranking_script
    if generation_mode == "static-api":
        static_api_script = static_api_case_script(case_row, fixture_import, datasets or [], readiness or {})
        if static_api_script:
            return static_api_script
    external_id = str(case_row["external_id"]).replace("'", "\\'")
    title = str(case_row["title"] or "自动化测试").replace("'", "\\'")
    login_entry = fallback_login_entry(elements, case_row)
    assertion_elements = [element for element in elements if login_entry is None or element["id"] != login_entry["id"]]
    static_locator = (
        readiness
        or static_case_locator_from_evidence(case_row, state_evidence or [], allow_proven_fallback=generation_mode in {"static-page", "static-api"})
        if not assertion_elements
        else {}
    )
    if static_locator.get("kind") == "heading":
        static_value = str(static_locator["value"]).replace("\\", "\\\\").replace("'", "\\'")
        locator = f"page.getByRole('heading', {{ name: '{static_value}', exact: true }}).first()"
    elif static_locator.get("kind") == "text":
        static_value = str(static_locator["value"]).replace("\\", "\\\\").replace("'", "\\'")
        locator = f"page.getByText('{static_value}', {{ exact: true }}).first()"
    else:
        locator = fallback_locator_expression(assertion_elements or elements)
    login_entry_step = ""
    if login_entry is not None:
        role = str(login_entry["locator_role"] or "link").replace("'", "\\'")
        name = str(login_entry["locator_value"] or login_entry["name"] or "登录").replace("\\", "\\\\").replace("'", "\\'")
        login_entry_step = f"""
  await runStep('进入登录页面', async () => {{
    await page.getByRole('{role}', {{ name: '{name}', exact: true }}).click();
  }});

"""
    return f"""import {{ expect, test }} from '@playwright/test';
import {{ openTargetPage, runStep }} from '{fixture_import}';

test('{external_id} {title}', async ({{ page }}) => {{
  await runStep('打开需求指定目标页面', async () => {{
    await openTargetPage(page);
  }});

{login_entry_step}  
  await runStep('验证探索阶段确认的关键元素可见', async () => {{
    await {locator}.waitFor({{ state: 'visible', timeout: 10_000 }});
    {primary_assertion_comment(str(case_row['expected'] or ''))}
    await expect({locator}).toBeVisible({{ timeout: 10_000 }});
  }});
}});
"""


def stream_ai_playwright_script_sync(item: sqlite3.Row, elements: list[sqlite3.Row], cases_markdown: str, artifact_id: str) -> str:
    api_key = get_openai_api_key()
    if not api_key:
        return ""
    payload = {
        "model": get_openai_model(),
        "input": playwright_script_prompt(item, elements, cases_markdown),
    }
    try:
        content = call_openai_responses_stream(api_key, get_openai_model(), get_openai_base_url(), payload, artifact_id, timeout=24).strip()
    except (AIRequestError, urllib.error.URLError, TimeoutError, json.JSONDecodeError):
        return ""
    script = ensure_verbose_playwright_logging(extract_playwright_script(content))
    if script != content:
        update_flow_artifact(artifact_id, content=script)
    cases = parse_cases_markdown(cases_markdown)
    if not valid_playwright_script(script, elements):
        return ""
    if len(cases) == 1 and single_primary_assertion_error(script, cases[0]["expected"]):
        return ""
    return script


async def stream_ai_playwright_script(item: sqlite3.Row, elements: list[sqlite3.Row], cases_markdown: str, artifact_id: str) -> str:
    return await asyncio.to_thread(stream_ai_playwright_script_sync, item, elements, cases_markdown, artifact_id)


def failure_evidence_summary(failure_log: str) -> str:
    evidence_lines: list[str] = []
    seen_paths: set[str] = set()
    path_pattern = re.compile(r"((?:test-results|playwright-report)/[^\s`]+(?:error-context\.md|test-failed-\d+\.png|video\.webm|\.png|\.webm))")
    for match in path_pattern.finditer(failure_log):
        path_text = match.group(1).rstrip(".,)")
        if path_text in seen_paths:
            continue
        seen_paths.add(path_text)
        path = resolve_workspace_path(path_text)
        evidence_lines.append(f"- 证据路径：`{relative_or_absolute(path)}`")
        if path.name == "error-context.md" and path.exists():
            excerpt = path.read_text(encoding="utf-8", errors="replace")[:4000].strip()
            if excerpt:
                evidence_lines.append(f"```text\n{excerpt}\n```")
    return "\n".join(evidence_lines) if evidence_lines else "未找到 Playwright error-context、截图或视频路径。"


AUTH_REJECTION_PATTERN = re.compile(
    r"用户名或密码错误|账号或密码错误|用户名密码错误|密码不正确|账号不存在|用户不存在|invalid\s+(?:username|credentials)|incorrect\s+(?:username|password|credentials)",
    re.IGNORECASE,
)
LOGIN_ROUTE_PATTERN = re.compile(
    r"(?:received string|current url|page url|actual url)[^\n]*#/login|停留在[^\n]*登录页",
    re.IGNORECASE,
)
LOGIN_HEADING_PATTERN = re.compile(r"heading\s+['\"][^'\"\n]*登录|\bheading\b[^\n]*\blog\s*in\b", re.IGNORECASE)
LOGIN_USERNAME_FIELD_PATTERN = re.compile(r"(?:textbox|input|label)[^\n]*(?:用户名|账号|username)", re.IGNORECASE)
LOGIN_PASSWORD_FIELD_PATTERN = re.compile(r"(?:textbox|input|label)[^\n]*(?:密码|password)", re.IGNORECASE)
STRICT_MODE_FAILURE_PATTERN = re.compile(r"strict mode violation", re.IGNORECASE)
LOCATOR_FAILURE_PATTERN = re.compile(
    r"element\(s\) not found|waiting for (?:getBy|locator)|expect\(locator\)|Locator:\s*",
    re.IGNORECASE,
)
ENVIRONMENT_FAILURE_PATTERN = re.compile(
    r"page\.goto\s*:\s*[^\n]*(?:timeout\b|timed out|exceeded)|net::ERR_|ECONNREFUSED|ENOTFOUND|ERR_CONNECTION|目标 URL 探测.*(?:失败|错误)",
    re.IGNORECASE,
)
CSS_LOCATOR_LITERAL_PATTERN = re.compile(r"\.locator\(\s*(['\"])([^'\"]+)\1\s*\)")
CREDENTIAL_OVERRIDE_PATTERNS = (
    re.compile(r"\bfunction\s+normalize(?:credential|username|password)\b", re.IGNORECASE),
    re.compile(r"\b(?:const|let|var)\s+(?:username|password)\s*=\s*['\"`]", re.IGNORECASE),
    re.compile(r"\b(?:username|password|credential|value)\s*={2,3}\s*['\"`][^'\"`]+", re.IGNORECASE),
    re.compile(r"\b(?:username|password)\s*\.\s*(?:replace|trim|toLowerCase|toUpperCase)\s*\(", re.IGNORECASE),
)


def playwright_report_section(failure_log: str, heading: str) -> str:
    match = re.search(
        rf"(?ms)^# {re.escape(heading)}\s*\n(.*?)(?=^# [^\n]+\s*$|\Z)",
        failure_log or "",
    )
    return match.group(1).strip() if match else ""


def playwright_diagnostic_evidence(failure_log: str) -> tuple[str, str]:
    error_details = playwright_report_section(failure_log, "Error details")
    page_snapshot = playwright_report_section(failure_log, "Page snapshot")
    if not error_details and not page_snapshot:
        text = failure_log or ""
        return text, text
    observed_parts = [part for part in (error_details, page_snapshot) if part]
    return error_details or "\n".join(observed_parts), "\n".join(observed_parts)


def observed_login_page(evidence: str) -> bool:
    if LOGIN_ROUTE_PATTERN.search(evidence):
        return True
    return bool(
        LOGIN_HEADING_PATTERN.search(evidence)
        and LOGIN_USERNAME_FIELD_PATTERN.search(evidence)
        and LOGIN_PASSWORD_FIELD_PATTERN.search(evidence)
    )


def compact_failure_prompt_context(failure_log: str) -> str:
    error_details = playwright_report_section(failure_log, "Error details")
    page_snapshot = playwright_report_section(failure_log, "Page snapshot")
    if not error_details and not page_snapshot:
        return (failure_log or "")[-6000:]
    parts: list[str] = []
    if error_details:
        parts.append(f"## 错误详情\n{error_details[:5000]}")
    if page_snapshot:
        parts.append(f"## 页面快照\n{page_snapshot[:6000]}")
    return "\n\n".join(parts)


def failure_context_from_archived_report(
    run: sqlite3.Row | dict[str, Any],
    target_version: sqlite3.Row | dict[str, Any],
    target_case: sqlite3.Row | dict[str, Any] | None,
) -> str:
    report_path = str(run["report_path"] or "") if "report_path" in run.keys() else ""
    if not report_path:
        return ""
    data_dir = resolve_workspace_path(report_path).parent / "data"
    if not data_dir.exists():
        return ""
    identifiers = {
        Path(str(target_version["spec_path"] or "")).name,
        str(target_case["external_id"] or "") if target_case is not None else "",
    }
    identifiers.discard("")
    markdown_files = sorted(data_dir.glob("*.md"))
    for path in markdown_files:
        content = path.read_text(encoding="utf-8", errors="replace")
        if any(identifier in content for identifier in identifiers):
            return content[:16000]
    if len(markdown_files) == 1:
        return markdown_files[0].read_text(encoding="utf-8", errors="replace")[:16000]
    return ""


def failure_log_for_target(
    run: sqlite3.Row | dict[str, Any],
    full_failure_log: str,
    target_version: sqlite3.Row | dict[str, Any],
    target_case: sqlite3.Row | dict[str, Any] | None,
) -> str:
    archived_context = failure_context_from_archived_report(run, target_version, target_case)
    if archived_context:
        return archived_context
    identifiers = [
        Path(str(target_version["spec_path"] or "")).name,
        str(target_case["external_id"] or "") if target_case is not None else "",
    ]
    identifiers = [value for value in identifiers if value]
    lines = full_failure_log.splitlines()
    matched_indexes = [index for index, line in enumerate(lines) if any(value in line for value in identifiers)]
    if not matched_indexes:
        return full_failure_log if len(identifiers) <= 1 else "\n".join(lines[-160:])
    selected: set[int] = set()
    for index in matched_indexes:
        selected.update(range(max(0, index - 45), min(len(lines), index + 45)))
    return "\n".join(lines[index] for index in sorted(selected))[-12000:]


def successful_login_case(target_case: sqlite3.Row | dict[str, Any] | None, cases_markdown: str) -> bool:
    if target_case is None:
        text = cases_markdown
    else:
        text = " ".join(
            str(target_case[key] or "")
            for key in ("title", "requirement", "preconditions", "steps", "expected")
            if key in target_case.keys()
        )
    return bool(re.search(r"登录|sign\s*in|log\s*in", text, re.IGNORECASE)) and bool(
        re.search(r"有效|正确|成功|进入.*(?:首页|主页|业务页)|success", text, re.IGNORECASE)
    )


def diagnosis_signature(target_name: str, category: str, markers: list[str]) -> str:
    normalized = "|".join([target_name, category, *sorted(set(markers))]).lower()
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()[:16]


def diagnose_healing_target(
    item: sqlite3.Row | dict[str, Any],
    target_version: sqlite3.Row | dict[str, Any],
    target_case: sqlite3.Row | dict[str, Any] | None,
    cases_markdown: str,
    failure_log: str,
) -> dict[str, Any]:
    target_name = (
        str(target_case["external_id"] or "")
        if target_case is not None
        else Path(str(target_version["spec_path"] or "unknown.spec.ts")).name
    )
    markers: list[str] = []
    evidence: list[str] = []
    error_details, observed_evidence = playwright_diagnostic_evidence(failure_log)
    auth_match = AUTH_REJECTION_PATTERN.search(observed_evidence)
    on_login_route = observed_login_page(observed_evidence)
    if auth_match:
        markers.append("auth-rejected")
        evidence.append("应用明确返回登录凭据无效")
    if on_login_route:
        markers.append("login-route-retained")
        evidence.append("提交后仍停留在登录页")
    if STRICT_MODE_FAILURE_PATTERN.search(error_details):
        category = "test-code"
        confidence = "high"
        action = "repair"
        summary = "失败证据明确为 Playwright strict mode locator 歧义，应修复精确匹配或定位范围。"
        markers.append("strict-mode-violation")
    elif successful_login_case(target_case, cases_markdown) and auth_match and on_login_route:
        category = "test-data-environment"
        confidence = "high"
        action = "block"
        summary = "登录接口明确拒绝当前凭据；请检查所选运行环境的 QA_USERNAME/QA_PASSWORD 后重新执行，测试侧自愈不会改写凭据。"
    else:
        policy_reason = expectation_policy_mismatch_reason(item, observed_evidence, cases_markdown)
        if policy_reason:
            category = "product-expectation"
            confidence = "high"
            action = "block"
            summary = policy_reason
            markers.append("expectation-policy-mismatch")
        elif ENVIRONMENT_FAILURE_PATTERN.search(error_details):
            category = "test-data-environment"
            confidence = "medium"
            action = "confirm"
            summary = "失败证据指向目标站点或网络环境异常，先使用原脚本确认一次。"
            markers.append("environment-failure")
        elif LOCATOR_FAILURE_PATTERN.search(error_details):
            category = "test-code"
            confidence = "high"
            action = "repair"
            summary = "失败证据指向 locator、页面进入步骤或等待策略，可进行测试侧自愈。"
            markers.append("locator-or-wait-failure")
        else:
            category = "unknown"
            confidence = "low"
            action = "repair"
            summary = "暂未识别为高置信业务、数据或环境问题，保留现有测试侧自愈策略。"
            markers.append("unknown-failure")
    safe_evidence = [redact_sensitive_log_text(value)[:240] for value in evidence[:4]]
    return {
        "category": category,
        "confidence": confidence,
        "signature": diagnosis_signature(target_name, category, markers),
        "summary": redact_sensitive_log_text(summary),
        "evidence": safe_evidence,
        "action": action,
        "target": target_name,
    }


def aggregate_healing_diagnoses(diagnoses: list[dict[str, Any]]) -> dict[str, Any]:
    if not diagnoses:
        return {}
    action_priority = {"block": 3, "confirm": 2, "repair": 1}
    primary = max(diagnoses, key=lambda value: action_priority.get(str(value.get("action")), 0))
    signatures = [str(value.get("signature") or "") for value in diagnoses if value.get("signature")]
    return {
        "category": primary.get("category", "unknown"),
        "confidence": primary.get("confidence", "low"),
        "signature": hashlib.sha256("|".join(sorted(signatures)).encode("utf-8")).hexdigest()[:16],
        "summary": primary.get("summary", ""),
        "evidence": primary.get("evidence", []),
        "action": primary.get("action", "repair"),
        "targets": {str(value.get("target") or index): value for index, value in enumerate(diagnoses, start=1)},
    }


def diagnosis_json(diagnosis: dict[str, Any]) -> str:
    return json.dumps(sanitize_flow_log_details(diagnosis), ensure_ascii=False)


def unsupported_new_css_locator(
    current_script: str,
    healed_script: str,
    failure_log: str,
) -> str:
    current_locators = {match.group(2) for match in CSS_LOCATOR_LITERAL_PATTERN.finditer(current_script)}
    for match in CSS_LOCATOR_LITERAL_PATTERN.finditer(healed_script):
        locator = match.group(2).strip()
        if locator in current_locators or locator in failure_log:
            continue
        if locator.startswith(".") or (locator.startswith("#") and not locator.startswith("#/")):
            return locator
    return ""


def added_credential_override_reason(current_script: str, healed_script: str) -> str:
    added_lines = [
        line[1:].strip()
        for line in script_unified_diff(current_script, healed_script).splitlines()
        if line.startswith("+") and not line.startswith("+++")
    ]
    if any(pattern.search(line) for line in added_lines for pattern in CREDENTIAL_OVERRIDE_PATTERNS):
        return "自愈脚本不得硬编码、纠正或归一化 QA_USERNAME/QA_PASSWORD；请修正所选运行环境的凭据配置"
    return ""


def confirmed_non_script_failure_summary(diagnosis: dict[str, Any]) -> str:
    evidence = " ".join(str(value) for value in diagnosis.get("evidence") or [])
    if diagnosis.get("category") == "test-data-environment" and re.search(
        r"凭据|用户名|密码|credential|username|password",
        evidence,
        re.IGNORECASE,
    ):
        return "登录接口确认复跑仍拒绝当前凭据；请修正所选运行环境的 QA_USERNAME/QA_PASSWORD 后重新执行，测试侧自愈不会改写凭据。"
    return "原脚本确认复跑再次出现相同账号、环境或产品失败，停止测试侧自愈。"


def normalized_script_body(script: str) -> str:
    return re.sub(r"\s+", "", script or "")


class HealingScriptGenerationError(RuntimeError):
    """A user-actionable failure while asking AI for a healed script."""


def failed_locator_still_present(failure_log: str, script: str) -> bool:
    locator_match = re.search(r"Locator:\s*(.+)", failure_log)
    if not locator_match:
        return False
    locator = locator_match.group(1).strip()
    if not locator:
        return False
    fragments = [
        "getByRole('navigation')",
        'getByRole("navigation")',
        "getByRole('menu')",
        'getByRole("menu")',
        ".el-menu",
        ".layout",
        ".app-main",
        ".navbar",
        ".sidebar-container",
    ]
    return any(fragment in locator and fragment in script for fragment in fragments)


def strict_mode_locator_expression(failure_log: str) -> str:
    error_details, _ = playwright_diagnostic_evidence(failure_log)
    match = re.search(
        r"strict mode violation:\s*(.+?)\s+resolved to\s+\d+\s+elements?",
        error_details,
        re.IGNORECASE,
    )
    return match.group(1).strip() if match else ""


def strict_mode_locator_still_present(failure_log: str, script: str) -> bool:
    locator = strict_mode_locator_expression(failure_log)
    if not locator:
        return False
    normalized_locator = re.sub(r"\s+", "", locator)
    normalized_script = re.sub(r"\s+", "", script or "")
    return bool(normalized_locator and normalized_locator in normalized_script)


def script_changed_enough(current_script: str, healed_script: str, failure_log: str) -> bool:
    if not healed_script:
        return False
    if normalized_script_body(current_script) == normalized_script_body(healed_script):
        return False
    if strict_mode_locator_still_present(failure_log, healed_script):
        return False
    if failed_locator_still_present(failure_log, healed_script):
        return False
    return True


def failure_log_shows_success_state(failure_log: str) -> bool:
    text = failure_log or ""
    lowered = text.lower()
    success_markers = (
        "#/home",
        "/home",
        "欢迎您",
        "基本情况",
        "电能质量",
        "business homepage",
        "target success state",
    )
    return any(marker.lower() in lowered for marker in success_markers)


def failure_log_mentions_login_security_policy(failure_log: str) -> bool:
    lowered = (failure_log or "").lower()
    return any(keyword.lower() in lowered for keyword in LOGIN_SECURITY_POLICY_KEYWORDS)


def expectation_policy_mismatch_reason(item: sqlite3.Row, failure_log: str, cases_markdown: str) -> str:
    if not is_login_like_item(item):
        return ""
    if has_explicit_login_security_policy(item):
        return ""
    if not failure_log_shows_success_state(failure_log):
        return ""
    if not (failure_log_mentions_login_security_policy(failure_log) or any(is_login_security_policy_case(row) for row in parse_cases_markdown(cases_markdown))):
        return ""
    return "需求/验收标准未明确账号锁定、验证码、风控或限流规则，但失败上下文显示系统已进入登录成功状态；该失败属于用例预期与实际产品策略不一致，不应继续测试侧自愈。"


def ai_healed_script(
    item: sqlite3.Row,
    current_script: str,
    run: sqlite3.Row,
    failure_log: str,
    elements: list[sqlite3.Row],
    operator_guidance: str = "",
    cases_markdown: str = "",
    fixture_import: str = "",
    navigation_target: dict[str, Any] | None = None,
) -> str:
    api_key = get_openai_api_key()
    if not api_key:
        return ""
    prompt = healed_script_prompt(
        item,
        current_script,
        run,
        failure_log,
        elements,
        operator_guidance,
        cases_markdown,
        fixture_import,
        navigation_target=navigation_target,
    )
    payload = {
        "model": get_openai_model(),
        "input": prompt,
    }
    try:
        body = call_openai_responses(api_key, get_openai_model(), get_openai_base_url(), payload, timeout=60)
        content = parse_openai_text_response(body).strip()
    except (AIRequestError, urllib.error.URLError, TimeoutError, json.JSONDecodeError) as exc:
        raise HealingScriptGenerationError(f"AI 生成修复脚本失败：{openai_error_message(exc)}") from exc
    if not content:
        raise HealingScriptGenerationError("AI 未返回修复脚本内容")
    script = ensure_verbose_playwright_logging(extract_playwright_script(content))
    if not valid_playwright_script(script, elements):
        raise HealingScriptGenerationError("AI 返回的修复脚本未通过 Playwright 结构或 locator 校验")
    return script


def healed_script_prompt(
    item: sqlite3.Row,
    current_script: str,
    run: sqlite3.Row,
    failure_log: str,
    elements: list[sqlite3.Row],
    operator_guidance: str = "",
    cases_markdown: str = "",
    fixture_import: str = "",
    script_layout: str = "single-case",
    navigation_target: dict[str, Any] | None = None,
) -> str:
    element_lines = "\n".join(
        f"- {element['locator_type']}{f'({element['locator_role']})' if 'locator_role' in element.keys() and element['locator_role'] else ''}={element['locator_value']} ({element['name']})"
        for element in elements[:24]
    )
    evidence = failure_evidence_summary(failure_log)
    diagnostic_context = compact_failure_prompt_context(failure_log)
    error_details, _ = playwright_diagnostic_evidence(failure_log)
    item_id = ""
    with contextlib.suppress(Exception):
        item_id = item["id"]
    scoped_cases_markdown = cases_markdown or (latest_cases_for_work_item(item_id) if item_id else "")
    scoped_cases = parse_cases_markdown(scoped_cases_markdown)
    single_case_guidance = ""
    if len(scoped_cases) == 1 and script_layout != "shared-spec":
        external_id = scoped_cases[0]["external_id"]
        fixture_guidance = (
            f"- 必须保留并继续使用共享 Fixture 引用 `{fixture_import}`，不得内联或改成其他路径。\n"
            if fixture_import
            else ""
        )
        single_case_guidance = f"""
当前是逐用例脚本自愈，只允许修复用例 `{external_id}`：
- 返回脚本必须且只能包含一个 Playwright `test(...)`，测试标题必须严格等于 `{external_id} {scoped_cases[0]['title']}`。
- 返回脚本必须继续且只能包含一个业务 `expect(...)`，其上一行必须保留 `// 主断言：{normalize_primary_expectation(scoped_cases[0]['expected'])}`。
- 页面就绪、控件可操作、接口返回和数据准备只能使用 waitFor 系列或显式前置处理，不得新增辅助 expect。
- 不得新增、复制或补齐其他用例的 `test(...)`，即使失败 Run 同时执行了多个 spec。
- 保留当前 spec 中与该用例相关的辅助函数、常量、步骤日志和 import，除非修复失败原因确实需要调整。
{fixture_guidance}"""
    elif len(scoped_cases) == 1 and script_layout == "shared-spec":
        external_id = scoped_cases[0]["external_id"]
        single_case_guidance = f"""
当前是共享 spec 的单用例私有分支自愈，执行范围仅限 `{external_id}`：
- 必须返回完整共享 TypeScript spec，保留其中所有 import、公共 helper、hook、describe、循环数据和其他用例 ID。
- 只修改修复 `{external_id}` 所必需的代码，不得删除、拆分或改写其他共享测试。
- `{external_id}` 必须继续以边界清晰的完整 ID 出现在源码中，运行时将通过 grep 只执行当前用例。
"""
    sauce_guidance = ""
    if is_sauce_demo_item(item):
        sauce_guidance = """
SauceDemo 自愈约束：
- 登录页就绪优先等待 `[data-test="username"]`、`[data-test="password"]`、`[data-test="login-button"]`，不要等待 `Swag Labs` 文本作为必需信号。
- 如果多个用例集中失败在 `page.goto` timeout 或登录页就绪等待，应优先标记为目标站点/网络响应不稳定；只修正明显错误的等待或 selector，不要为了掩盖环境问题削弱断言。
"""
    zzpss_guidance = ""
    if is_zzpss_item(item):
        zzpss_guidance = """
ZZPSS 自愈约束：
- 登录用例停留在登录页且证据显示按钮 class 为 `.login-button` 时，使用 `.login-button` 精确点击；禁止使用 `page.locator('text=登录').first()`。
- `.login-button` 仅适用于 ZZPSS，其他站点不得凭空引入该 selector。
"""
    environment_risk = navigation_environment_risk(error_details)
    operator_section = f"\n人工补充的诊断与修复约束：\n{operator_guidance.strip()}\n" if operator_guidance.strip() else ""
    confirmed_navigation = bool(navigation_target and navigation_target.get("evidenceConfirmed"))
    if confirmed_navigation:
        navigation_steps = []
        for index, step in enumerate((navigation_target or {}).get("navigationSteps") or [], start=1):
            action = str(step.get("action") or "操作")
            target = str(step.get("target") or (step.get("resolvedTarget") or {}).get("name") or "目标控件")
            url_after = str(step.get("urlAfter") or "")
            suffix = f"，完成后 URL={url_after}" if url_after else ""
            navigation_steps.append(f"  {index}. {action} {target}{suffix}")
        navigation_step_text = "\n".join(navigation_steps) or "  - 无额外交互步骤，helper 负责已确认的直接访问"
        navigation_guidance = f"""
当前运行存在已确认的共享导航契约：
- requested URL：{navigation_target.get('requestedUrl') or '-'}
- resolved URL：{navigation_target.get('resolvedUrl') or '-'}
- `openTargetPage(page)` 已负责打开 requested URL、回放以下步骤并最终到达 resolved URL：
{navigation_step_text}
- 测试脚本必须保留并调用 `openTargetPage(page)`，不得直接调用 `page.goto(...)` 绕过共享 helper。
- `openTargetPage(page)` 已执行的点击、填写、选择或定位动作不得在测试体中重复执行；如果失败 locator 对应上述步骤，应删除重复动作并直接验证 helper 到达后的业务结果。
- 即使失败表现为导航或 locator 超时，也不得通过直跳 requested/resolved URL 修复。
"""
    else:
        navigation_guidance = """
第三方/外部页面出现 `page.goto` timeout 时，优先把导航改为 `waitUntil: 'commit'`，随后等待真实页面可操作信号，不要只加长 timeout，也不要依赖 `domcontentloaded` 或 `load` 作为核心就绪条件。
"""
    return f"""你是资深 Playwright 测试自愈工程师。请只修复测试脚本，不修改产品代码。
允许修改：测试数据、等待策略、selector、断言、Playwright 测试代码。
不得硬编码、替换、纠正、trim 或归一化 `QA_USERNAME`、`QA_PASSWORD` 及其读取结果；认证失败必须保留原凭据并交由运行环境配置处理。
测试用例表中的每个 `ID` 必须原样出现在至少一个 Playwright `test('ID 标题', ...)` 标题中；不得删除、改写、缩短、重编号、合并或遗漏任何已有用例 ID。
如果当前脚本已包含测试用例 ID，自愈时必须完整保留这些 ID；如果当前脚本缺失测试用例表中的 ID，返回脚本必须补齐对应 `test(...)`。
{single_case_guidance}
禁止使用 `waitUntil: 'networkidle'`，因为第三方站点可能有持续后台请求导致永不 idle。
{navigation_guidance}
如果失败日志包含 `outside of the viewport`、`element is not stable`、`#logout_sidebar_link` 或 `logout-sidebar-link`，必须修复为：点击 Open Menu 后等待 `[data-test="logout-sidebar-link"]` 的 `tabindex` 不再是 `-1`，并确认 bounding box 已完整进入 viewport，再点击 Logout。
需要加长单用例预算时使用 `test.setTimeout(...)`；禁止生成 `test('...', {{ timeout: ... }}, async (...) => ...)`。
禁止削弱核心验收断言来掩盖产品问题。返回完整 TypeScript spec，不要解释。
自愈只能修复 selector、等待策略和数据归一化，必须保持用例“期望结果”和 `// 主断言：...` 的文本及业务含义不变。
如果需要比较多个字段，先归一化为一个对象或数组，最后仍只允许一次整体 expect。
如果错误为 `strict mode violation`，必须修复报错 locator 本身；报告中出现 Playwright `aka ... exact: true` 建议时，优先在对应 role/name locator 上增加 `exact: true`，不得只修改无关代码。
对“登录”、“关闭”、“确定”等短且容易成为其他可访问名子串的 role/name locator，优先使用 `exact: true`。
如果 Playwright error-context 显示业务首页、欢迎语或目标成功状态已经出现，应优先用这些真实可见文本、URL 或稳定 CSS 作为断言，而不是继续等待不存在的通用 layout/navigation selector。
如果失败来自账号锁定、验证码、风控、限流等策略类断言，但需求/验收标准没有明确规则，不要继续强化该断言；应移除相反断言或把该场景改为需业务规则确认。
如果当前脚本在同一测试中已经把 `#/home`、欢迎语、业务首页等成功状态视为可接受结果，后续不得再追加 `#/login`、登录输入框可见等相反断言。
必须保留或补齐详细步骤日志：每个业务步骤使用 test.step 或 runStep 包裹。共享 `runStep` 已包含开始、通过和失败日志时，禁止再增加外层 loggedStep/step 包装器重复打印同一组日志。
修复 selector、等待或断言时，不得删除现有 `test.step`、`runStep` 或 `console.log` 步骤日志；如果当前脚本缺少这些日志，返回的修复脚本必须补齐。
{sauce_guidance}
{zzpss_guidance}
环境风险提示：{environment_risk or '暂无'}
{operator_section}

需求：{item['requirement']}
目标 URL：{item['target_url']}
测试用例：
{scoped_cases_markdown}

失败 spec：{run['spec']}
结构化失败证据（已排除测试源码）：
{diagnostic_context}

Playwright 失败上下文与页面快照摘录：
{evidence}

已确认元素：
{element_lines}

当前脚本：
{current_script}
"""


def stream_ai_healed_script_sync(
    item: sqlite3.Row,
    current_script: str,
    run: sqlite3.Row,
    failure_log: str,
    elements: list[sqlite3.Row],
    artifact_id: str,
    operator_guidance: str = "",
    cases_markdown: str = "",
    fixture_import: str = "",
    script_layout: str = "single-case",
    navigation_target: dict[str, Any] | None = None,
) -> str:
    api_key = get_openai_api_key()
    if not api_key:
        return ""
    payload = {
        "model": get_openai_model(),
        "input": healed_script_prompt(
            item,
            current_script,
            run,
            failure_log,
            elements,
            operator_guidance,
            cases_markdown,
            fixture_import,
            script_layout,
            navigation_target,
        ),
    }
    try:
        content = call_openai_responses_stream(api_key, get_openai_model(), get_openai_base_url(), payload, artifact_id, timeout=60).strip()
    except (AIRequestError, urllib.error.URLError, TimeoutError, json.JSONDecodeError) as exc:
        raise HealingScriptGenerationError(f"AI 生成修复脚本失败：{openai_error_message(exc)}") from exc
    if not content:
        raise HealingScriptGenerationError("AI 未返回修复脚本内容")
    script = ensure_verbose_playwright_logging(extract_playwright_script(content))
    if artifact_id and script != content:
        update_flow_artifact(artifact_id, content=script)
    if not valid_playwright_script(script, elements):
        raise HealingScriptGenerationError("AI 返回的修复脚本未通过 Playwright 结构或 locator 校验")
    return script


async def stream_ai_healed_script(
    item: sqlite3.Row,
    current_script: str,
    run: sqlite3.Row,
    failure_log: str,
    elements: list[sqlite3.Row],
    artifact_id: str,
    operator_guidance: str = "",
    cases_markdown: str = "",
    fixture_import: str = "",
    script_layout: str = "single-case",
    navigation_target: dict[str, Any] | None = None,
) -> str:
    return await asyncio.to_thread(
        stream_ai_healed_script_sync,
        item,
        current_script,
        run,
        failure_log,
        elements,
        artifact_id,
        operator_guidance,
        cases_markdown,
        fixture_import,
        script_layout,
        navigation_target,
    )


async def generate_healed_script(
    item: sqlite3.Row,
    current_script: str,
    run: sqlite3.Row,
    failure_log: str,
    elements: list[sqlite3.Row],
    *,
    artifact_id: str = "",
    operator_guidance: str = "",
    cases_markdown: str = "",
    fixture_import: str = "",
    script_layout: str = "single-case",
    navigation_target: dict[str, Any] | None = None,
) -> str:
    return await stream_ai_healed_script(
        item,
        current_script,
        run,
        failure_log,
        elements,
        artifact_id,
        operator_guidance,
        cases_markdown,
        fixture_import,
        script_layout,
        navigation_target,
    )


def latest_run_for_work_item(work_item_id: str, latest_run_id: str = "") -> sqlite3.Row | None:
    with get_db() as conn:
        if latest_run_id:
            return conn.execute(
                "SELECT * FROM runs WHERE id = ? AND work_item_id = ?",
                (latest_run_id, work_item_id),
            ).fetchone()
        return conn.execute(
            "SELECT * FROM runs WHERE work_item_id = ? ORDER BY started_at DESC LIMIT 1",
            (work_item_id,),
        ).fetchone()


def write_draft_spec(item: sqlite3.Row, script: str) -> str:
    WORK_ITEM_DRAFT_DIR.mkdir(parents=True, exist_ok=True)
    spec_path = WORK_ITEM_DRAFT_DIR / f"{item['slug']}.draft.spec.ts"
    spec_path.write_text(script, encoding="utf-8")
    return str(spec_path.relative_to(ROOT_DIR))


def report_cell(value: Any, fallback: str = "-") -> str:
    text = str(value or fallback).replace("\n", "<br>").replace("|", "\\|").strip()
    return text or fallback


def report_time(value: str | None) -> str:
    parsed = parse_iso_datetime(value)
    if parsed is None:
        return value or "无"
    return parsed.astimezone(timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")


def report_duration(started_at: str | None, ended_at: str | None) -> str:
    started = parse_iso_datetime(started_at)
    ended = parse_iso_datetime(ended_at)
    if started is None or ended is None:
        return "无"
    seconds = max(0, int((ended - started).total_seconds()))
    minutes, remaining = divmod(seconds, 60)
    if minutes:
        return f"{minutes}分{remaining}秒"
    return f"{remaining}秒"


def report_run_status(run: sqlite3.Row | None) -> str:
    if run is None:
        return "未执行"
    return {"passed": "通过", "failed": "失败", "running": "执行中"}.get(run["status"], run["status"] or "未知")


def report_case_statistics(cases_markdown: str) -> tuple[list[dict[str, str]], str, str]:
    parsed_cases = parse_cases_markdown(cases_markdown)
    if not parsed_cases:
        return [], "- 用例总数：0\n- P0：0；P1：0；P2：0；其他：0", "未解析到结构化 Markdown 用例；请检查用例表头是否包含 ID、优先级、标题等字段。"
    priority_counts: dict[str, int] = {}
    for case in parsed_cases:
        priority = case.get("priority") or "未标注"
        priority_counts[priority] = priority_counts.get(priority, 0) + 1
    ordered_priorities = ["P0", "P1", "P2"]
    priority_summary = "；".join(
        [f"{priority}：{priority_counts.get(priority, 0)}" for priority in ordered_priorities]
        + [f"{priority}：{count}" for priority, count in sorted(priority_counts.items()) if priority not in ordered_priorities]
    )
    stats = f"- 用例总数：{len(parsed_cases)}\n- 优先级分布：{priority_summary}"
    rows = [
        "| 用例 ID | 优先级 | 标题 | 覆盖需求 | 前置条件/数据 | 期望结果 | 自动化说明 |",
        "| --- | --- | --- | --- | --- | --- | --- |",
    ]
    for case in parsed_cases:
        rows.append(
            "| {external_id} | {priority} | {title} | {requirement} | {preconditions} | {expected} | {automation_notes} |".format(
                external_id=report_cell(case.get("external_id")),
                priority=report_cell(case.get("priority")),
                title=report_cell(case.get("title")),
                requirement=report_cell(case.get("requirement")),
                preconditions=report_cell(case.get("preconditions")),
                expected=report_cell(case.get("expected")),
                automation_notes=report_cell(case.get("automation_notes")),
            )
        )
    return parsed_cases, stats, "\n".join(rows)


def report_log_excerpt(run_id: str, limit: int = 8000) -> str:
    if not run_id:
        return "无运行日志。"
    logs = run_log_text(run_id)
    if not logs:
        return "无运行日志。"
    if len(logs) <= limit:
        return logs
    return f"...（已截断前 {len(logs) - limit} 字符，仅保留最近日志）\n{logs[-limit:]}"


def report_failure_analysis(run: sqlite3.Row | None, reason: str = "") -> str:
    if run is None:
        return "- 当前尚无 Playwright 运行记录，无法判定失败原因。\n- 建议先完成草稿 spec 运行，再结合 HTML report、截图和日志复盘。"
    if run["status"] == "passed":
        return "- 本次 Playwright 运行通过，未发现阻塞性失败。\n- 仍建议结合业务验收标准人工复核关键路径和测试数据有效性。"
    return f"""- 失败结论：{reason or 'Playwright 运行未通过，需结合证据继续定位。'}
- 优先检查：HTML report 中的失败用例、trace/video/screenshot、控制台与网络错误、测试数据和环境可用性。
- 归因建议：先区分产品缺陷、环境/账号/数据问题、selector 失效、等待时序、断言口径不一致，再决定是否进入自愈或提缺陷。"""


def report_quality_risks(run: sqlite3.Row | None) -> str:
    delivery_note = "最终保存的 spec 来自已运行验证后的草稿版本。" if run is not None else "当前报告尚未绑定已完成运行，不能作为最终验证结论。"
    return f"""- selector 风险：未人工确认的候选元素不得作为最终 selector；若页面结构频繁变化，应优先使用稳定语义属性或业务可见文本。
- 环境与数据风险：目标环境、账号权限、测试数据、第三方依赖不可用时，自动化结果可能不能代表产品真实质量。
- 覆盖风险：默认不覆盖未声明的跨浏览器兼容、性能、安全、无障碍、视觉细节和第三方链路。
- 交付风险：{delivery_note}
- 后续建议：失败时优先补充缺陷单、证据截图、复现步骤和影响范围；通过时建议纳入回归套件并持续观察稳定性。"""


def default_report(item: sqlite3.Row, cases: str = "", run: sqlite3.Row | None = None) -> str:
    generated_at = report_time(now_iso())
    run_status = report_run_status(run)
    exit_code = "无"
    run_id = "无"
    spec = f"tests/e2e/{item['slug']}.spec.ts"
    command = f"npx playwright test {spec} --project=chromium --reporter=list,html"
    html_report = relative_or_absolute(REPORT_INDEX)
    screenshot = relative_or_absolute(SCREENSHOT_PATH)
    started_at = "无"
    ended_at = "无"
    duration = "无"
    deliverable_readiness = "否，尚未执行验证。"
    failure_reason = "无"
    parsed_cases, case_stats, coverage_matrix = report_case_statistics(cases)
    log_excerpt = "无运行日志。"
    if run is not None:
        exit_code = str(run["exit_code"])
        run_id = run["id"]
        spec = run["spec"]
        command = f"npx playwright test {spec} --project=chromium --reporter=list,html"
        html_report = relative_or_absolute(run["report_path"] or REPORT_INDEX)
        screenshot = relative_or_absolute(run["screenshot_path"] or SCREENSHOT_PATH)
        started_at = report_time(run["started_at"])
        ended_at = report_time(run["ended_at"])
        duration = report_duration(run["started_at"], run["ended_at"])
        deliverable_readiness = "是，已完成运行验证。" if run["status"] in {"passed", "failed"} else "否，运行尚未完成。"
        failure_reason = "应用或环境问题已记录，详见 HTML report 和日志" if run["status"] == "failed" else "无"
        log_excerpt = report_log_excerpt(run["id"])
    conclusion = (
        "本次自动化验证通过，可作为当前范围内的回归参考。"
        if run is not None and run["status"] == "passed"
        else "本次自动化验证失败，需要结合证据继续定位后再关闭风险。"
        if run is not None and run["status"] == "failed"
        else "尚未执行 Playwright 验证，报告仅描述测试设计与计划。"
    )
    raw_cases = cases or "已保存测试用例见同名 *-test-cases.md 文件。"
    return f"""# {item['title']} 测试报告

## 1. 报告元信息

| 项目 | 内容 |
| --- | --- |
| 报告生成时间 | {report_cell(generated_at)} |
| 工单 ID | {report_cell(item['id'])} |
| 任务标题 | {report_cell(item['title'])} |
| 运行 ID | {report_cell(run_id)} |
| 执行状态 | {report_cell(run_status)} |
| 开始时间 | {report_cell(started_at)} |
| 结束时间 | {report_cell(ended_at)} |
| 执行耗时 | {report_cell(duration)} |

## 2. 测试结论摘要

- 结论：{conclusion}
- 执行状态：{run_status}
- 退出码：{exit_code}
- 是否可作为最终交付物：{deliverable_readiness}
- 证据完整性：已记录测试用例、执行命令、Playwright HTML report、截图/预览路径和运行日志摘录。

## 3. 测试范围与输入

- 需求：{item['requirement']}
- 目标 URL：{item['target_url'] or '未提供'}
- 验收标准：{item['acceptance'] or '未提供'}
- 角色/账号：{item['role'] or '未提供'}
- 测试数据：{item['test_data'] or '未提供'}
- 排除项：{item['exclusions'] or '未明确要求的视觉细节、非目标浏览器和无关业务流程默认范围外'}

## 4. 测试用例统计

{case_stats}

## 5. 覆盖矩阵

{coverage_matrix}

## 6. 原始测试用例

{raw_cases}

## 7. 执行数据支撑

- Spec 路径：`{spec}`
- Playwright HTML report：`{html_report}`
- 截图/预览路径：`{screenshot}`
- 运行用例数：{len(parsed_cases) if parsed_cases else '未解析'}

### 执行命令

```bash
{command}
```

### 运行日志摘录

```text
{log_excerpt}
```

## 8. 失败分析与证据索引

- 失败原因：{failure_reason}
- HTML report：`{html_report}`
- 截图/预览：`{screenshot}`
- 日志来源：`runs/{run_id}/logs`

{report_failure_analysis(run, failure_reason)}

## 9. 质量风险与后续建议

{report_quality_risks(run)}
"""


def svg_escape(value: str) -> str:
    return (
        value.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
    )


def file_data_url(path_value: str | None) -> str:
    if not path_value:
        return ""
    path = Path(path_value)
    if not path.exists():
        return ""
    mime = "image/png" if path.suffix.lower() == ".png" else "image/svg+xml"
    encoded = base64.b64encode(path.read_bytes()).decode("ascii")
    return f"data:{mime};base64,{encoded}"


def image_frame_payload(path_value: str | None, reason: str = "step-result") -> dict[str, Any] | None:
    if not path_value:
        return None
    path = Path(path_value)
    if not path.exists() or path.suffix.lower() not in {".png", ".jpg", ".jpeg"}:
        return None
    return {
        "type": "frame",
        "data": base64.b64encode(path.read_bytes()).decode("ascii"),
        "format": "jpeg" if path.suffix.lower() in {".jpg", ".jpeg"} else "png",
        "width": DEFAULT_VIEWPORT["width"],
        "height": DEFAULT_VIEWPORT["height"],
        "reason": reason,
    }


