def report_delete_target(path_value: str) -> Path | None:
    if not path_value:
        return None
    with contextlib.suppress(Exception):
        target = resolve_workspace_path(path_value).resolve()
        if target == REPORT_INDEX.resolve():
            return None
        allowed_roots = (PROJECT_ARTIFACT_DIR.resolve(), ARTIFACT_DIR.resolve())
        if any(target.is_relative_to(root) for root in allowed_roots):
            run_reports_root = (PLAYWRIGHT_REPORT_ARCHIVE_DIR / "runs").resolve()
            if target.is_relative_to(run_reports_root):
                relative_parts = target.relative_to(run_reports_root).parts
                if relative_parts:
                    return run_reports_root / relative_parts[0]
            return target
    return None


def bulk_delete_report_records(payload: ReportRecordBulkDeleteRequest) -> dict[str, Any]:
    report_ids = list(dict.fromkeys(report_id.strip() for report_id in payload.report_ids if report_id.strip()))
    if not report_ids:
        raise HTTPException(status_code=400, detail="请选择至少一条报告删除")
    if len(report_ids) > MAX_REPORT_DELETE_ITEMS:
        raise HTTPException(status_code=400, detail=f"单次最多删除 {MAX_REPORT_DELETE_ITEMS} 条报告")
    deletion_targets: set[Path] = set()
    affected_work_items: set[str] = set()
    with get_db() as conn:
        placeholders = ",".join("?" for _ in report_ids)
        rows = conn.execute(f"SELECT * FROM report_records WHERE id IN ({placeholders})", report_ids).fetchall()
        if len(rows) != len(report_ids):
            raise HTTPException(status_code=404, detail="选中的报告不存在或已变化，请刷新后重试")
        if any(row["status"] in ACTIVE_REPORT_RUN_STATUSES for row in rows):
            raise HTTPException(status_code=409, detail="运行中或排队中的报告不能删除")
        artifact_rows = conn.execute(
            f"SELECT * FROM report_artifacts WHERE report_id IN ({placeholders})",
            report_ids,
        ).fetchall()
        report_rows_by_id = {row["id"]: row for row in rows}
        paths = {row["file_path"] for row in artifact_rows if row["file_path"]}
        affected_work_items.update(row["work_item_id"] for row in rows if row["work_item_id"])
        conn.execute(f"DELETE FROM report_artifacts WHERE report_id IN ({placeholders})", report_ids)
        conn.execute(f"DELETE FROM report_records WHERE id IN ({placeholders})", report_ids)
        for path_value in paths:
            remaining = conn.execute(
                "SELECT 1 FROM report_artifacts WHERE file_path = ? LIMIT 1",
                (path_value,),
            ).fetchone()
            if remaining is not None:
                continue
            target = report_delete_target(path_value)
            if target is not None:
                deletion_targets.add(target)
            for artifact_row in artifact_rows:
                if artifact_row["file_path"] != path_value:
                    continue
                report_row = report_rows_by_id[artifact_row["report_id"]]
                if artifact_row["artifact_type"] == "markdown" and report_row["report_type"] == "work-item-summary":
                    conn.execute(
                        """
                        DELETE FROM deliverables
                        WHERE type = 'manual-report' AND file_path = ?
                          AND COALESCE(work_item_id, '') = ? AND COALESCE(run_id, '') = ?
                        """,
                        (path_value, report_row["work_item_id"] or "", report_row["run_id"] or ""),
                    )
                elif artifact_row["artifact_type"] == "html-report":
                    conn.execute(
                        """
                        DELETE FROM deliverables
                        WHERE type = 'html-report' AND file_path = ? AND COALESCE(run_id, '') = ?
                          AND (COALESCE(case_id, '') = ? OR COALESCE(case_id, '') = '')
                        """,
                        (path_value, report_row["run_id"] or "", report_row["case_id"] or ""),
                    )
            conn.execute("UPDATE runs SET report_path = '' WHERE report_path = ?", (path_value,))
        for work_item_id in affected_work_items:
            latest = conn.execute(
                """
                SELECT ra.file_path
                FROM report_records rr
                JOIN report_artifacts ra ON ra.report_id = rr.id AND ra.artifact_type = 'markdown'
                WHERE rr.report_type = 'work-item-summary' AND rr.work_item_id = ?
                ORDER BY rr.version DESC LIMIT 1
                """,
                (work_item_id,),
            ).fetchone()
            conn.execute(
                "UPDATE work_items SET report_path = ?, updated_at = ? WHERE id = ?",
                (latest["file_path"] if latest else "", now_iso(), work_item_id),
            )
        remaining_references = referenced_report_paths(conn)
        for target in deletion_targets:
            if not report_target_is_referenced(target, remaining_references):
                remove_report_target(target)
    write_audit_log("report_records_bulk_deleted", f"永久删除报告：{len(report_ids)} 条", metadata={"reportIds": report_ids})
    return {"status": "deleted", "deleted": len(report_ids)}


def bulk_delete_case_reports(payload: CaseReportBulkDeleteRequest) -> dict[str, Any]:
    report_ids: list[str] = []
    with get_db() as conn:
        for item in payload.items:
            row = conn.execute(
                """
                SELECT id FROM report_records
                WHERE report_type = 'case-execution' AND case_id = ? AND run_id = ?
                """,
                (item.case_id.strip(), item.run_id.strip()),
            ).fetchone()
            if row is not None:
                report_ids.append(row["id"])
    if report_ids:
        return bulk_delete_report_records(ReportRecordBulkDeleteRequest(report_ids=report_ids))
    return _bulk_delete_legacy_case_reports(payload)


def bulk_delete_manual_reports(payload: ManualReportBulkDeleteRequest) -> dict[str, Any]:
    new_report_ids: list[str] = []
    legacy_report_ids: list[str] = []
    with get_db() as conn:
        for report_id in dict.fromkeys(value.strip() for value in payload.report_ids if value.strip()):
            if conn.execute("SELECT 1 FROM report_records WHERE id = ?", (report_id,)).fetchone() is not None:
                new_report_ids.append(report_id)
            else:
                legacy_report_ids.append(report_id)
    deleted = 0
    if new_report_ids:
        deleted += bulk_delete_report_records(ReportRecordBulkDeleteRequest(report_ids=new_report_ids))["deleted"]
    if legacy_report_ids:
        deleted += _bulk_delete_legacy_manual_reports(ManualReportBulkDeleteRequest(report_ids=legacy_report_ids))["deleted"]
    if not deleted:
        raise HTTPException(status_code=404, detail="选中的工单总结报告不存在")
    return {"status": "deleted", "deleted": deleted}


def create_deliverable(payload: DeliverableRequest) -> dict[str, Any]:
    with get_db() as conn:
        project_id = validate_project_id(conn, payload.project_id)
        feature_id = validate_project_feature(conn, project_id, payload.feature_id)
    file_path = payload.file_path.strip()
    content = payload.content
    if not file_path:
        safe_name = slugify(payload.name or payload.type)
        file_path = str(PROJECT_ARTIFACT_DIR / project_id / "deliverables" / "manual" / f"{safe_name}.md")
    path = resolve_workspace_path(file_path)
    if content:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
    if not path.exists():
        raise HTTPException(status_code=400, detail="交付物文件不存在，请提供 content 或有效 file_path")
    with get_db() as conn:
        deliverable_id = register_deliverable(
            conn,
            project_id,
            payload.type.strip(),
            payload.name.strip() or path.name,
            path,
            work_item_id=payload.work_item_id.strip(),
            case_id=payload.case_id.strip(),
            run_id=payload.run_id.strip(),
            feature_id=feature_id,
            status=payload.status.strip() or "ready",
            summary=payload.summary.strip() or summarize_content(content, "手工登记交付物"),
        )
        row = conn.execute("SELECT * FROM deliverables WHERE id = ?", (deliverable_id,)).fetchone()
    result = row_to_deliverable(row, include_content=True)
    log_event(logging.INFO, "deliverable_created", component="assets", deliverable_id=deliverable_id, project_id=project_id, feature_id=feature_id, work_item_id=payload.work_item_id.strip(), run_id=payload.run_id.strip(), deliverable_type=payload.type.strip(), file_path=path)
    return result


def create_test_suite(payload: SuiteRequest) -> dict[str, Any]:
    name = payload.name.strip()
    if not name:
        raise HTTPException(status_code=400, detail="套件名称不能为空")
    suite_id = uuid.uuid4().hex[:12]
    timestamp = now_iso()
    with get_db() as conn:
        project_id = validate_project_id(conn, payload.project_id)
        conn.execute(
            """
            INSERT INTO test_suites (
                id, project_id, name, description, filter_json, status,
                run_config_json, schedule_config_json, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                suite_id,
                project_id,
                name,
                payload.description.strip(),
                json.dumps(payload.filter, ensure_ascii=False),
                "disabled" if payload.status == "disabled" else "active",
                json.dumps(validate_suite_environment_config(conn, project_id, payload.run_config), ensure_ascii=False),
                json.dumps(normalize_suite_schedule_config(payload.schedule_config), ensure_ascii=False),
                timestamp,
                timestamp,
            ),
        )
        row = conn.execute("SELECT * FROM test_suites WHERE id = ?", (suite_id,)).fetchone()
    result = row_to_test_suite(row)
    log_event(logging.INFO, "test_suite_created", component="assets", suite_id=suite_id, project_id=project_id, status=result["status"])
    return result


def get_test_suite(suite_id: str) -> dict[str, Any]:
    with get_db() as conn:
        row = conn.execute("SELECT * FROM test_suites WHERE id = ?", (suite_id,)).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Test suite not found")
        return row_to_test_suite(row, conn)


def update_test_suite(suite_id: str, payload: SuitePatchRequest) -> dict[str, Any]:
    fields: dict[str, Any] = {}
    if payload.name is not None:
        name = payload.name.strip()
        if not name:
            raise HTTPException(status_code=400, detail="套件名称不能为空")
        fields["name"] = name
    if payload.description is not None:
        fields["description"] = payload.description.strip()
    if payload.filter is not None:
        fields["filter_json"] = json.dumps(payload.filter, ensure_ascii=False)
    if payload.status is not None:
        fields["status"] = "disabled" if payload.status == "disabled" else "active"
    if payload.schedule_config is not None:
        fields["schedule_config_json"] = json.dumps(normalize_suite_schedule_config(payload.schedule_config), ensure_ascii=False)
    with get_db() as conn:
        suite = conn.execute("SELECT * FROM test_suites WHERE id = ?", (suite_id,)).fetchone()
        if suite is None:
            raise HTTPException(status_code=404, detail="Test suite not found")
        if payload.run_config is not None:
            fields["run_config_json"] = json.dumps(
                validate_suite_environment_config(conn, suite["project_id"], payload.run_config),
                ensure_ascii=False,
            )
        if fields:
            fields["updated_at"] = now_iso()
            keys = ", ".join(f"{key} = ?" for key in fields)
            conn.execute(f"UPDATE test_suites SET {keys} WHERE id = ?", [*fields.values(), suite_id])
        row = conn.execute("SELECT * FROM test_suites WHERE id = ?", (suite_id,)).fetchone()
        result = row_to_test_suite(row, conn)
    log_event(logging.INFO, "test_suite_updated", component="assets", suite_id=suite_id, project_id=suite["project_id"], changed_fields=",".join(key for key in fields if key != "updated_at"))
    return result


def delete_test_suite(suite_id: str) -> dict[str, Any]:
    with get_db() as conn:
        suite = conn.execute("SELECT * FROM test_suites WHERE id = ?", (suite_id,)).fetchone()
        if suite is None:
            raise HTTPException(status_code=404, detail="Test suite not found")
        conn.execute("DELETE FROM test_suite_cases WHERE suite_id = ?", (suite_id,))
        conn.execute("DELETE FROM test_suites WHERE id = ?", (suite_id,))
    write_audit_log("test_suite_deleted", f"套件已删除：{suite['name']}", metadata={"suiteId": suite_id})
    log_event(logging.INFO, "test_suite_deleted", component="assets", suite_id=suite_id, project_id=suite["project_id"])
    return {"ok": True, "id": suite_id}


def update_test_suite_cases(suite_id: str, payload: SuiteCaseUpdateRequest) -> dict[str, Any]:
    case_ids = list(dict.fromkeys(payload.case_ids))
    with get_db() as conn:
        suite = conn.execute("SELECT * FROM test_suites WHERE id = ?", (suite_id,)).fetchone()
        if suite is None:
            raise HTTPException(status_code=404, detail="Test suite not found")
        existing_cases = {
            row["id"]
            for row in conn.execute(
                f"SELECT id FROM test_cases WHERE id IN ({','.join('?' for _ in case_ids)}) AND library_status = 'published'",
                case_ids,
            ).fetchall()
        } if case_ids else set()
        if len(existing_cases) != len(case_ids):
            raise HTTPException(status_code=400, detail="存在无效用例，不能加入套件")
        cross_project = [
            row["id"]
            for row in conn.execute(
                f"SELECT id FROM test_cases WHERE id IN ({','.join('?' for _ in case_ids)}) AND project_id != ?",
                [*case_ids, suite["project_id"]],
            ).fetchall()
        ] if case_ids else []
        if cross_project:
            raise HTTPException(status_code=400, detail="存在跨项目用例，不能加入套件")
        conn.execute("DELETE FROM test_suite_cases WHERE suite_id = ?", (suite_id,))
        timestamp = now_iso()
        for case_id in case_ids:
            conn.execute(
                "INSERT INTO test_suite_cases (suite_id, case_id, created_at) VALUES (?, ?, ?)",
                (suite_id, case_id, timestamp),
            )
        conn.execute("UPDATE test_suites SET updated_at = ? WHERE id = ?", (timestamp, suite_id))
        row = conn.execute("SELECT * FROM test_suites WHERE id = ?", (suite_id,)).fetchone()
    result = row_to_test_suite(row)
    log_event(logging.INFO, "test_suite_cases_updated", component="assets", suite_id=suite_id, project_id=suite["project_id"], case_count=len(case_ids))
    return result


def selected_suite_cases(conn: sqlite3.Connection, payload: SuiteRunRequest) -> tuple[str, str, list[sqlite3.Row]]:
    if payload.case_ids:
        placeholders = ",".join("?" for _ in payload.case_ids)
        rows = conn.execute(
            f"SELECT * FROM test_cases WHERE id IN ({placeholders}) AND library_status = 'published' ORDER BY priority ASC, external_id ASC",
            payload.case_ids,
        ).fetchall()
        if len(rows) != len(set(payload.case_ids)):
            raise HTTPException(status_code=400, detail="存在无效用例，不能执行")
        project_id = rows[0]["project_id"] if rows else ""
        return "", project_id, rows
    if payload.suite_id:
        suite = conn.execute("SELECT * FROM test_suites WHERE id = ?", (payload.suite_id,)).fetchone()
        if suite is None:
            raise HTTPException(status_code=404, detail="Test suite not found")
        rows = conn.execute(
            """
            SELECT tc.*
            FROM test_cases tc
            JOIN test_suite_cases tsc ON tsc.case_id = tc.id
            WHERE tsc.suite_id = ? AND tc.library_status = 'published'
            ORDER BY tc.priority ASC, tc.external_id ASC
            """,
            (payload.suite_id,),
        ).fetchall()
        return suite["id"], suite["project_id"], rows
    raise HTTPException(status_code=400, detail="请选择套件或至少一个用例")


async def execute_suite_run(suite_run_id: str) -> None:
    suite_started = time.monotonic()
    with get_db() as conn:
        suite_run = conn.execute("SELECT * FROM suite_runs WHERE id = ?", (suite_run_id,)).fetchone()
        case_links = conn.execute(
            "SELECT * FROM suite_run_cases WHERE suite_run_id = ? ORDER BY id ASC",
            (suite_run_id,),
        ).fetchall()
    if suite_run is None:
        log_event(logging.WARNING, "suite_run_missing", component="execution", suite_run_id=suite_run_id)
        return
    if not case_links:
        update_suite_run(suite_run_id, status="skipped", progress=100, ended_at=now_iso())
        log_event(logging.WARNING, "suite_run_skipped", component="execution", suite_run_id=suite_run_id, project_id=suite_run["project_id"], reason="no_cases")
        return

    update_suite_run(suite_run_id, status="running")
    suite_run_keys = set(suite_run.keys())
    suite_environment = {
        "id": (suite_run["environment_id"] or "") if "environment_id" in suite_run_keys else "",
        "name": (suite_run["environment_name"] or "") if "environment_name" in suite_run_keys else "",
        "url": (suite_run["environment_url"] or "") if "environment_url" in suite_run_keys else "",
    }
    log_event(logging.INFO, "suite_run_started", component="execution", suite_run_id=suite_run_id, suite_id=suite_run["suite_id"], project_id=suite_run["project_id"], total_cases=len(case_links))
    blob_dir = suite_blob_report_dir(suite_run_id)
    with contextlib.suppress(FileNotFoundError):
        shutil.rmtree(blob_dir)
    for index, link in enumerate(case_links, start=1):
        with get_db() as conn:
            case_row = conn.execute("SELECT * FROM test_cases WHERE id = ?", (link["case_id"],)).fetchone()
        if case_row is None:
            with get_db() as conn:
                report_row = conn.execute(
                    """
                    SELECT id FROM report_records
                    WHERE report_type = 'case-execution' AND suite_run_id = ? AND case_id = ?
                    """,
                    (suite_run_id, link["case_id"]),
                ).fetchone()
                conn.execute(
                    "UPDATE suite_run_cases SET status = 'skipped', ended_at = ?, error = ? WHERE id = ?",
                    (now_iso(), "用例不存在", link["id"]),
                )
                if report_row is not None:
                    conn.execute(
                        """
                        UPDATE report_records
                        SET status = 'skipped', failure_reason = ?, ended_at = ?, updated_at = ?
                        WHERE id = ?
                        """,
                        ("源用例在执行前已删除", now_iso(), now_iso(), report_row["id"]),
                    )
            refresh_suite_run_counts(suite_run_id)
            continue

        with get_db() as conn:
            spec_path, grep_pattern, script_version_id = active_spec_for_case(conn, case_row)
            work_item_row = conn.execute(
                "SELECT target_url FROM work_items WHERE id = ?",
                (case_row["work_item_id"] or "",),
            ).fetchone()
            source_target_url = str(work_item_row["target_url"] or "") if work_item_row is not None else str(suite_run["source_target_url"] or "")
            selected_environment = (
                suite_environment
                if suite_environment.get("url")
                else resolve_project_environment(
                    conn,
                    suite_run["project_id"],
                    fallback_url=source_target_url,
                )
            )
        if not spec_path or not resolve_workspace_path(spec_path).exists():
            with get_db() as conn:
                report_id = ensure_case_execution_report(
                    conn,
                    case_row,
                    suite_run_id=suite_run_id,
                    status="skipped",
                    started_at=now_iso(),
                )
                conn.execute(
                    """
                    UPDATE suite_run_cases
                    SET status = 'skipped', started_at = ?, ended_at = ?, error = ?
                    WHERE id = ?
                    """,
                    (now_iso(), now_iso(), "用例尚未绑定可执行 spec", link["id"]),
                )
                conn.execute(
                    "UPDATE test_cases SET latest_status = 'skipped', updated_at = ? WHERE id = ?",
                    (now_iso(), case_row["id"]),
                )
                conn.execute(
                    """
                    UPDATE report_records
                    SET status = 'skipped', failure_reason = ?, ended_at = ?, updated_at = ?
                    WHERE id = ?
                    """,
                    ("用例尚未绑定可执行 spec", now_iso(), now_iso(), report_id),
                )
            refresh_suite_run_counts(suite_run_id)
            continue

        run_id = uuid.uuid4().hex[:12]
        html_report = run_html_report_index(run_id)
        suite = {
            "id": case_row["external_id"],
            "name": case_row["title"],
            "spec": spec_path,
            "priority": case_row["priority"] or "P1",
            "cases": 1,
            "description": case_row["requirement"] or case_row["title"],
            "grep": grep_pattern,
            "case_id": case_row["id"],
            "script_version_id": script_version_id,
            "html_report_path": html_report,
            "blob_report_dir": blob_dir,
            "environment": selected_environment,
            "source_target_url": source_target_url,
        }
        with get_db() as conn:
            conn.execute(
                """
                INSERT INTO runs (
                    id, suite_id, suite_name, spec, status, stage_key, stage_label,
                    progress, started_at, report_path, screenshot_path, work_item_id,
                    environment_id, environment_name, environment_url, source_target_url
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    run_id,
                    suite["id"],
                    suite["name"],
                    suite["spec"],
                    "queued",
                    "prepare",
                    "等待浏览器资源",
                    6,
                    now_iso(),
                    relative_or_absolute(html_report),
                    str(run_preview_path(run_id)),
                    case_row["work_item_id"],
                    selected_environment.get("id", ""),
                    selected_environment.get("name", ""),
                    selected_environment.get("url", ""),
                    source_target_url,
                ),
            )
            conn.execute(
                """
                UPDATE suite_run_cases
                SET status = 'running', started_at = ?, run_id = ?
                WHERE id = ?
                """,
                (now_iso(), run_id, link["id"]),
            )
            ensure_case_execution_report(
                conn,
                case_row,
                run_id=run_id,
                suite_run_id=suite_run_id,
                status="queued",
                started_at=now_iso(),
            )
        if case_row["work_item_id"]:
            update_work_item(case_row["work_item_id"], stage="运行验证", status="running", latest_run_id=run_id)
        write_log(run_id, "info", f"套件 {suite_run['name']} 执行用例 {index}/{suite_run['total_cases']}: {case_row['external_id']}")
        if selected_environment.get("url"):
            write_log(run_id, "info", f"运行环境: {selected_environment.get('name') or '当前环境'} · {selected_environment['url']}")
        render_preview(run_id, "running", "准备环境", 6, [])
        await run_playwright(run_id, suite, case_row["work_item_id"])
        with get_db() as conn:
            run_row = conn.execute("SELECT status FROM runs WHERE id = ?", (run_id,)).fetchone()
            status = run_row["status"] if run_row else "failed"
            conn.execute(
                """
                UPDATE suite_run_cases
                SET status = ?, ended_at = ?, error = ?
                WHERE id = ?
                """,
                (status, now_iso(), "" if status == "passed" else "详见单用例执行日志和 HTML report", link["id"]),
            )
        refresh_suite_run_counts(suite_run_id)

    refresh_suite_run_counts(suite_run_id)
    with get_db() as conn:
        summary = conn.execute("SELECT * FROM suite_runs WHERE id = ?", (suite_run_id,)).fetchone()
    final_status = "failed" if summary["failed_cases"] else "passed" if summary["passed_cases"] else "skipped"
    suite_report_path = ""
    try:
        suite_report = await merge_suite_html_report(suite_run_id)
        if suite_report is not None:
            suite_report_path = relative_or_absolute(suite_report)
            publish_latest_playwright_report(suite_report)
    except Exception as exc:
        log_event(
            logging.WARNING,
            "suite_report_merge_failed",
            component="execution",
            suite_run_id=suite_run_id,
            error=str(exc),
        )
        with get_db() as conn:
            run_ids = [
                row["run_id"]
                for row in conn.execute(
                    "SELECT run_id FROM suite_run_cases WHERE suite_run_id = ? AND run_id IS NOT NULL AND run_id != ''",
                    (suite_run_id,),
                ).fetchall()
            ]
        for run_id in run_ids:
            write_log(run_id, "warning", f"套件 HTML report 聚合失败，已保留单用例报告: {exc}")
    update_suite_run(
        suite_run_id,
        status=final_status,
        progress=100,
        ended_at=now_iso(),
        report_path=suite_report_path or relative_or_absolute(REPORT_INDEX),
    )
    log_event(
        logging.INFO if final_status == "passed" else logging.ERROR,
        "suite_run_completed",
        component="execution",
        suite_run_id=suite_run_id,
        suite_id=suite_run["suite_id"],
        project_id=suite_run["project_id"],
        status=final_status,
        total_cases=summary["total_cases"],
        passed_cases=summary["passed_cases"],
        failed_cases=summary["failed_cases"],
        skipped_cases=summary["skipped_cases"],
        elapsed_ms=int((time.monotonic() - suite_started) * 1000),
    )


async def create_suite_run(payload: SuiteRunRequest) -> dict[str, Any]:
    with get_db() as conn:
        suite_id, project_id, rows = selected_suite_cases(conn, payload)
        if not rows:
            raise HTTPException(status_code=400, detail="请至少选择一个用例执行")
        suite_name = "临时用例执行"
        suite_environment_id = ""
        if suite_id:
            suite_row = conn.execute("SELECT name, run_config_json FROM test_suites WHERE id = ?", (suite_id,)).fetchone()
            suite_name = suite_row["name"] if suite_row else suite_name
            suite_config = normalize_suite_run_config(safe_json_loads(suite_row["run_config_json"], {})) if suite_row else default_suite_run_config()
            suite_environment_id = suite_config.get("environmentId", "")
        selected_environment = resolve_project_environment(
            conn,
            project_id,
            payload.environment_id.strip() or suite_environment_id,
            use_project_default=True,
        )
        project_row = conn.execute("SELECT target_url FROM projects WHERE id = ?", (project_id,)).fetchone()
        source_target_url = str(project_row["target_url"] or "") if project_row is not None else ""
        suite_run_id = uuid.uuid4().hex[:12]
        timestamp = now_iso()
        conn.execute(
            """
            INSERT INTO suite_runs (
                id, suite_id, project_id, name, status, progress, total_cases,
                passed_cases, failed_cases, skipped_cases, started_at, environment_id,
                environment_name, environment_url, source_target_url
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                suite_run_id,
                suite_id,
                project_id,
                suite_name,
                "queued",
                0,
                len(rows),
                0,
                0,
                0,
                timestamp,
                selected_environment.get("id", ""),
                selected_environment.get("name", ""),
                selected_environment.get("url", ""),
                source_target_url,
            ),
        )
        for case_row in rows:
            conn.execute(
                """
                INSERT INTO suite_run_cases (
                    suite_run_id, case_id, status
                ) VALUES (?, ?, ?)
                """,
                (suite_run_id, case_row["id"], "queued"),
            )
            ensure_case_execution_report(
                conn,
                case_row,
                suite_run_id=suite_run_id,
                status="queued",
                started_at=timestamp,
            )
        row = conn.execute("SELECT * FROM suite_runs WHERE id = ?", (suite_run_id,)).fetchone()
    task = asyncio.create_task(execute_suite_run(suite_run_id))
    task.add_done_callback(lambda done: log_background_task_result(done, "suite_run", suite_run_id))
    write_audit_log("suite_run_started", f"测试执行已启动：{suite_name}", metadata={"suiteRunId": suite_run_id, "totalCases": len(rows)})
    log_event(logging.INFO, "suite_run_queued", component="execution", suite_run_id=suite_run_id, suite_id=suite_id, project_id=project_id, total_cases=len(rows))
    return row_to_suite_run(row)


def suite_runs(project_id: str = "", suite_name: str = "") -> list[dict[str, Any]]:
    normalized_project_id = normalize_project_id(project_id)
    if not normalized_project_id:
        return []
    clauses: list[str] = []
    params: list[Any] = []
    if normalized_project_id != "all":
        clauses.append("project_id = ?")
        params.append(normalized_project_id)
    normalized_suite_name = suite_name.strip().lower()
    if normalized_suite_name:
        clauses.append("instr(lower(name), ?) > 0")
        params.append(normalized_suite_name)
    where_sql = f"WHERE {' AND '.join(clauses)}" if clauses else ""
    with get_db() as conn:
        rows = conn.execute(
            f"SELECT * FROM suite_runs {where_sql} ORDER BY started_at DESC LIMIT 20",
            params,
        ).fetchall()
    return [row_to_suite_run(row, include_cases=False) for row in rows]


def get_suite_run(suite_run_id: str) -> dict[str, Any]:
    with get_db() as conn:
        row = conn.execute("SELECT * FROM suite_runs WHERE id = ?", (suite_run_id,)).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail="Suite run not found")
    return row_to_suite_run(row)


def delete_suite_run(suite_run_id: str) -> dict[str, str]:
    with get_db() as conn:
        row = conn.execute("SELECT * FROM suite_runs WHERE id = ?", (suite_run_id,)).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Suite run not found")
        if row["status"] in {"queued", "running"}:
            raise HTTPException(status_code=400, detail="运行中或排队中的执行记录不能删除")
        conn.execute("DELETE FROM suite_run_cases WHERE suite_run_id = ?", (suite_run_id,))
        conn.execute("DELETE FROM suite_runs WHERE id = ?", (suite_run_id,))
    write_audit_log(
        "suite_run_deleted",
        f"执行记录已从监控列表移除：{row['name']}",
        metadata={"suiteRunId": suite_run_id, "status": row["status"], "projectId": row["project_id"]},
    )
    return {"status": "deleted", "id": suite_run_id}


def suite_run_logs(suite_run_id: str) -> dict[str, Any]:
    with get_db() as conn:
        rows = conn.execute(
            """
            SELECT logs.*
            FROM logs
            JOIN suite_run_cases src ON src.run_id = logs.run_id
            WHERE src.suite_run_id = ?
            ORDER BY logs.id ASC
            """,
            (suite_run_id,),
        ).fetchall()
    return {
        "items": [
            {
                "id": row["id"],
                "createdAt": row["created_at"],
                "level": row["level"],
                "message": row["message"],
            }
            for row in rows
        ]
    }


def work_items() -> list[dict[str, Any]]:
    with get_db() as conn:
        rows = conn.execute("SELECT * FROM work_items WHERE COALESCE(is_system_import, 0) = 0 ORDER BY updated_at DESC LIMIT 50").fetchall()
    return [row_to_work_item(row) for row in rows]


def insert_work_item_record(
    conn: sqlite3.Connection,
    payload: WorkItemRequest,
    analysis: dict[str, Any],
    project_id: str,
    feature_id: str,
    feature_name: str,
) -> str:
    requirement = payload.requirement.strip()
    analysis = dict(analysis)
    suggested_title = title_from_analysis(requirement, analysis, feature_name)
    analysis["suggestedTitle"] = suggested_title
    explicit_title = payload.title.strip()
    title_source = normalize_title_source(payload.title_mode, has_explicit_title=bool(explicit_title))
    title = explicit_title if title_source == "manual" else suggested_title
    if not title:
        raise HTTPException(status_code=400, detail="人工工单标题不能为空")
    target_url = resolve_work_item_target_url(
        conn,
        project_id,
        requirement,
        explicit_url=payload.target_url,
        ai_environment=str(analysis.get("environment") or ""),
    )
    role = payload.role.strip() or analysis.get("role", "")
    test_data = payload.test_data.strip() or usable_test_data(str(analysis.get("testData", ""))) or extract_test_data(requirement)
    acceptance = payload.acceptance.strip() or analysis.get("acceptance", "")
    exclusions = payload.exclusions.strip() or analysis.get("exclusions", "")
    analysis.update({
        "environment": target_url or "未提供目标 URL",
        "role": role,
        "testData": test_data,
        "acceptance": acceptance,
        "exclusions": exclusions,
    })
    work_item_id = uuid.uuid4().hex[:12]
    slug = slug_for_work_item(title, work_item_id)
    timestamp = now_iso()
    asset_mode = normalize_asset_mode(payload.asset_mode or ("refresh" if payload.case_ids else "create"))
    case_ids = validate_case_ids_for_project(conn, project_id, normalize_case_ids(payload.case_ids))
    existing = conn.execute("SELECT id FROM work_items WHERE slug = ?", (slug,)).fetchone()
    if existing:
        slug = slug_for_work_item(title, work_item_id)
    conn.execute(
        """
        INSERT INTO work_items (
            id, slug, title, title_source, suggested_title, requirement, target_url, role, test_data, acceptance,
            exclusions, stage, status, created_at, updated_at, analysis_json, project_id,
            feature_id, asset_mode, case_ids_json, requirement_revision,
            requirement_updated_at, downstream_review_required
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            work_item_id,
            slug,
            title,
            title_source,
            suggested_title,
            requirement,
            target_url,
            role,
            test_data,
            acceptance,
            exclusions,
            "需求分析",
            "draft",
            timestamp,
            timestamp,
            json.dumps(analysis, ensure_ascii=False),
            project_id,
            feature_id,
            asset_mode,
            json_case_ids(case_ids),
            1,
            timestamp,
            0,
        ),
    )
    return work_item_id


def create_work_item(payload: WorkItemRequest) -> dict[str, Any]:
    requirement = payload.requirement.strip()
    if not requirement:
        raise HTTPException(status_code=400, detail="需求内容不能为空")
    with get_db() as conn:
        project_id = validate_project_id(conn, payload.project_id)
        feature_id = validate_project_feature(conn, project_id, payload.feature_id, required=True)
        feature_name = get_feature_row(conn, feature_id)["name"]
    analysis = analyze_requirement_with_ai(requirement)
    with get_db() as conn:
        project_id = validate_project_id(conn, project_id)
        feature_id = validate_project_feature(conn, project_id, feature_id, required=True)
        work_item_id = insert_work_item_record(conn, payload, analysis, project_id, feature_id, feature_name)
    result = get_work_item(work_item_id)
    log_event(
        logging.INFO,
        "work_item_created",
        component="workflow",
        work_item_id=work_item_id,
        project_id=project_id,
        feature_id=feature_id,
        asset_mode=result.get("assetMode", ""),
        linked_case_count=len(result.get("caseIds") or []),
        analysis_source=analysis.get("source", ""),
        target_url=result.get("targetUrl", ""),
    )
    return result


def update_work_item_details(work_item_id: str, payload: WorkItemPatchRequest) -> dict[str, Any]:
    item = get_work_item_row(work_item_id)
    project_id = require_work_item_project_id(item)
    with get_db() as conn:
        active_flow = conn.execute(
            "SELECT id FROM automation_flow_runs WHERE work_item_id = ? AND status IN ('queued', 'running', 'healing') LIMIT 1",
            (work_item_id,),
        ).fetchone()
        if active_flow is not None:
            raise HTTPException(status_code=409, detail="一键自动化流程正在运行，完成或停止后才能修改需求")
        guard_no_active_manual_data(conn, work_item_id, {"exploration", "execution", "healing"})

    requirement = (payload.requirement if payload.requirement is not None else item["requirement"]).strip()
    if not requirement:
        raise HTTPException(status_code=400, detail="需求内容不能为空")
    current_feature_id = item["feature_id"] or ""
    with get_db() as conn:
        requested_feature_id = payload.feature_id.strip() if payload.feature_id is not None else current_feature_id
        feature_id = current_feature_id if requested_feature_id == current_feature_id else validate_project_feature(conn, project_id, requested_feature_id, required=True)
        feature_row = get_feature_row(conn, feature_id)
    analysis = analyze_requirement_with_ai(requirement)
    suggested_title = title_from_analysis(requirement, analysis, feature_row["name"])
    analysis["suggestedTitle"] = suggested_title
    existing_title_source = item["title_source"] if "title_source" in item.keys() and item["title_source"] in TITLE_SOURCE_VALUES else "manual"
    submitted_title = (payload.title if payload.title is not None else item["title"] or "").strip()
    if payload.title_mode is None:
        title_source = "manual" if payload.title is not None and submitted_title != item["title"] else existing_title_source
    else:
        title_source = normalize_title_source(payload.title_mode, has_explicit_title=bool(submitted_title), default=existing_title_source)
    title = submitted_title if title_source == "manual" else suggested_title
    if not title:
        raise HTTPException(status_code=400, detail="人工工单标题不能为空")
    submitted_target_url = payload.target_url.strip() if payload.target_url is not None else ""
    existing_target_url = str(item["target_url"] or "") if payload.target_url is None else ""
    with get_db() as conn:
        target_url = resolve_work_item_target_url(
            conn,
            project_id,
            requirement,
            explicit_url=submitted_target_url,
            existing_url=existing_target_url,
            ai_environment=str(analysis.get("environment") or ""),
        )
    role = (payload.role if payload.role is not None else item["role"] or "").strip() or str(analysis.get("role", ""))
    test_data = (payload.test_data if payload.test_data is not None else item["test_data"] or "").strip() or usable_test_data(str(analysis.get("testData", ""))) or extract_test_data(requirement)
    acceptance = (payload.acceptance if payload.acceptance is not None else item["acceptance"] or "").strip() or str(analysis.get("acceptance", ""))
    exclusions = (payload.exclusions if payload.exclusions is not None else item["exclusions"] or "").strip() or str(analysis.get("exclusions", ""))
    analysis.update({
        "role": role,
        "testData": test_data,
        "acceptance": acceptance,
        "exclusions": exclusions,
        "environment": target_url or analyzed_environment,
    })
    timestamp = now_iso()

    with get_db() as conn:
        has_downstream = any(
            conn.execute(f"SELECT 1 FROM {table} WHERE work_item_id = ? LIMIT 1", (work_item_id,)).fetchone() is not None
            for table in ("generated_cases", "test_cases", "explorations", "generated_scripts", "runs", "healing_runs", "deliverables")
        )
        revision = max(1, int(item["requirement_revision"] or 1)) + 1
        conn.execute(
            """
            UPDATE work_items
            SET title = ?, title_source = ?, suggested_title = ?, requirement = ?, target_url = ?, role = ?, test_data = ?,
                acceptance = ?, exclusions = ?, analysis_json = ?, feature_id = ?,
                requirement_revision = ?, requirement_updated_at = ?,
                downstream_review_required = ?, stage = ?, status = ?, updated_at = ?
            WHERE id = ?
            """,
            (
                title, title_source, suggested_title, requirement, target_url, role, test_data, acceptance, exclusions,
                json.dumps(analysis, ensure_ascii=False), feature_id, revision, timestamp,
                int(has_downstream), "用例设计" if has_downstream else "需求分析",
                "review-required" if has_downstream else "draft", timestamp, work_item_id,
            ),
        )
        if feature_id != current_feature_id:
            conn.execute("UPDATE test_cases SET feature_id = ?, updated_at = ? WHERE work_item_id = ?", (feature_id, timestamp, work_item_id))
            conn.execute("UPDATE deliverables SET feature_id = ?, updated_at = ? WHERE work_item_id = ?", (feature_id, timestamp, work_item_id))
            conn.execute("UPDATE automation_flow_runs SET feature_id = ? WHERE work_item_id = ?", (feature_id, work_item_id))

    write_audit_log(
        "work_item_requirement_updated",
        f"需求工单已更新并重新分析：{title}",
        metadata={"workItemId": work_item_id, "projectId": project_id, "featureId": feature_id, "revision": revision, "downstreamReviewRequired": has_downstream},
    )
    log_event(
        logging.INFO,
        "work_item_requirement_updated",
        component="workflow",
        work_item_id=work_item_id,
        project_id=project_id,
        feature_id=feature_id,
        revision=revision,
        downstream_review_required=has_downstream,
    )
    return get_work_item(work_item_id)


def get_work_item(work_item_id: str) -> dict[str, Any]:
    return row_to_work_item(get_work_item_row(work_item_id), include_detail=True)


